Method là hàm nằm trong class. static method gọi qua tên class, không cần tạo đối tượng.

public class MathUtil {
    public static int add(int a, int b) {
        return a + b;
    }

    // Overloading: cùng tên, khác tham số
    public static double add(double a, double b) {
        return a + b;
    }

    // Varargs: số lượng tham số tùy ý
    public static int sum(int... nums) {
        int total = 0;
        for (int n : nums) total += n;
        return total;
    }
}

MathUtil.add(2, 3);      // -> 5
MathUtil.add(1.5, 2.5);  // -> 4.0
MathUtil.sum(1, 2, 3);   // -> 6

