Class là khuôn mẫu, object là thực thể tạo từ class bằng new.

public class Student {
    private String name;           // private: chỉ dùng trong class
    private int age;
    private static int count = 0;  // dùng chung cho mọi object

    public Student(String name, int age) {   // constructor
        this.name = name;
        this.age = age;
        count++;
    }

    public String getName() { return name; }      // getter
    public void setAge(int age) {                 // setter có kiểm tra
        if (age > 0) this.age = age;
    }

    @Override
    public String toString() {
        return name + " (" + age + ")";
    }
}

Student s = new Student("An", 20);
System.out.println(s);   // -> An (20)

