Một class chỉ kế thừa (extends) một class cha nhưng cài đặt (implements) được nhiều interface.

abstract class Animal {
    protected String name;
    Animal(String name) { this.name = name; }
    abstract String sound();                 // lớp con phải cài đặt
    void speak() { System.out.println(name + ": " + sound()); }
}

interface Pet {
    void play();
    default void sleep() { System.out.println("Zzz"); } // method mặc định
}

class Dog extends Animal implements Pet {
    Dog(String name) { super(name); }        // gọi constructor lớp cha
    @Override String sound() { return "Gâu"; }
    @Override public void play() { System.out.println("Chạy nhảy"); }
}

Animal a = new Dog("Milu");   // đa hình: biến kiểu cha, đối tượng lớp con
