Coroutine là cách chạy tác vụ bất đồng bộ nhẹ hơn thread. Hàm suspend có thể tạm dừng mà không chặn thread. Cần thư viện kotlinx-coroutines.

import kotlinx.coroutines.*

suspend fun fetchUser(): String {
    delay(1000)              // tạm dừng, không chặn thread
    return "An"
}

fun main() = runBlocking {
    launch {                 // chạy song song, không trả kết quả
        println("Đang tải...")
    }
    val user = async { fetchUser() }   // chạy song song, có kết quả
    println("User: ${user.await()}")
}

