Hàm phải được khai báo (prototype) trước khi dùng. Tham số truyền theo giá trị (bản sao).

#include <stdio.h>

int add(int a, int b);            // prototype
void swap(int *a, int *b);

int main(void) {
    printf("%d\n", add(2, 3));    // -> 5
    int x = 1, y = 2;
    swap(&x, &y);                 // truyền địa chỉ để hàm sửa được biến
    printf("%d %d\n", x, y);      // -> 2 1
    return 0;
}

int add(int a, int b) {
    return a + b;
}

void swap(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

int factorial(int n) {            // đệ quy
    return n <= 1 ? 1 : n * factorial(n - 1);
}

Cấp phát bộ nhớ lúc chạy trên heap bằng các hàm trong <stdlib.h>. Mọi vùng đã cấp phát phải được free, nếu không sẽ rò rỉ bộ nhớ (memory leak).

malloc(size): cấp phát size byte (chưa khởi tạo)
calloc(n, size): cấp phát n phần tử, gán về 0
realloc(p, size): đổi kích thước vùng nhớ
free(p): giải phóng

#include <stdlib.h>

int n = 5;
int *arr = malloc(n * sizeof(int));
if (arr == NULL) {
    return 1;                  // cấp phát thất bại
}
for (int i = 0; i < n; i++) arr[i] = i * i;

arr = realloc(arr, 10 * sizeof(int));   // mở rộng lên 10 phần tử
free(arr);
arr = NULL;                             // tránh dùng lại con trỏ đã free

struct gom nhiều biến khác kiểu thành một kiểu dữ liệu mới.

#include <stdio.h>
#include <string.h>

typedef struct {
    char name[50];
    int age;
    float gpa;
} Student;

int main(void) {
    Student s = {"An", 20, 3.5f};
    s.age = 21;                       // truy cập bằng dấu chấm

    Student *p = &s;
    p->gpa = 3.8f;                    // qua con trỏ dùng ->
    strcpy(p->name, "Bình");

    printf("%s %d %.1f\n", s.name, s.age, s.gpa);
    return 0;
}

