#include <iostream>
#include <string>

class Animal {
protected:
    std::string name;
public:
    Animal(const std::string &n) : name(n) {}     // constructor + initializer list
    virtual ~Animal() = default;                  // destructor ảo cho lớp cơ sở
    virtual std::string sound() const = 0;        // hàm thuần ảo -> lớp trừu tượng
    void speak() const {
        std::cout << name << ": " << sound() << "\n";
    }
};

class Dog : public Animal {
public:
    Dog(const std::string &n) : Animal(n) {}
    std::string sound() const override { return "Gâu"; }
};

int main() {
    Dog d("Milu");
    Animal &a = d;      // đa hình qua tham chiếu
    a.speak();          // -> Milu: Gâu
}

