Goroutine là luồng nhẹ, tạo bằng từ khóa go. Channel dùng để truyền dữ liệu giữa các goroutine an toàn.

func worker(id int, jobs <-chan int, results chan<- int) {
    for j := range jobs {
        results <- j * 2
    }
}

func main() {
    jobs := make(chan int, 5)
    results := make(chan int, 5)

    for w := 1; w <= 3; w++ {
        go worker(w, jobs, results)   // chạy 3 goroutine song song
    }
    for j := 1; j <= 5; j++ {
        jobs <- j
    }
    close(jobs)

    for i := 0; i < 5; i++ {
        fmt.Println(<-results)
    }
}

var wg sync.WaitGroup
for i := 0; i < 3; i++ {
    wg.Add(1)
    go func(n int) {
        defer wg.Done()
        fmt.Println(n)
    }(i)
}
wg.Wait()   // chờ tất cả goroutine xong

select {    // chờ channel nào có dữ liệu trước
case msg := <-ch:
    fmt.Println(msg)
case <-time.After(time.Second):
    fmt.Println("Hết thời gian chờ")
}

