Trait định nghĩa hành vi chung (giống interface), kiểu nào cài đặt trait thì có hành vi đó.

trait Describe {
    fn describe(&self) -> String;
    fn hello(&self) -> String {          // method mặc định
        format!("Xin chào, {}", self.describe())
    }
}

struct Dog;
impl Describe for Dog {
    fn describe(&self) -> String {
        "chú chó".to_string()
    }
}

fn print_it(item: &impl Describe) {      // nhận mọi kiểu có trait Describe
    println!("{}", item.hello());
}

fn largest<T: PartialOrd + Copy>(list: &[T]) -> T {   // generic + trait bound
    let mut max = list[0];
    for &x in list {
        if x > max { max = x; }
    }
    max
}

#[derive(Debug, Clone, PartialEq)]       // tự cài đặt trait có sẵn
