}

class Student: Person {              // chỉ class mới kế thừa được
    override func greet() -> String { super.greet() + ", sinh viên" }
}

Protocol định nghĩa các yêu cầu (giống interface); extension thêm chức năng cho kiểu có sẵn.

protocol Describable {
    var description: String { get }
    func describe() -> String
}

extension Describable {                // cài đặt mặc định
    func describe() -> String { "Mô tả: \(description)" }
}

struct Car: Describable {
    let brand: String
    var description: String { brand }  // computed property
}

extension Int {
    var squared: Int { self * self }
    func times(_ action: () -> Void) {
        for _ in 0..<self { action() }
    }
}
5.squared           // -> 25
3.times { print("Hi") }

Các protocol có sẵn hay dùng: Equatable (so sánh ==), Hashable (dùng làm key), Codable (chuyển JSON), Comparable.

Hàm có thể ném lỗi được đánh dấu throws; gọi bằng try bên trong do / catch.

enum LoginError: Error {
    case emptyPassword
    case wrongPassword(attempts: Int)
}

func login(password: String) throws -> String {
    if password.isEmpty { throw LoginError.emptyPassword }
    if password != "123" { throw LoginError.wrongPassword(attempts: 1) }
    return "Đăng nhập thành công"
}

do {
    let msg = try login(password: "")
    print(msg)
} catch LoginError.emptyPassword {
    print("Chưa nhập mật khẩu")
} catch {
    print("Lỗi: \(error)")
}

let result = try? login(password: "abc")   // lỗi thì nil

Đơn vị

px: điểm ảnh, cố định
%: theo phần tử cha
em: theo font-size của phần tử cha
rem: theo font-size của thẻ html (thường 16px) — nên dùng cho font và khoảng cách
vw, vh: 1% chiều rộng / cao màn hình
fr: phần chia trong CSS Grid

html { font-size: 16px; }
h1 { font-size: 2rem; }          /* 32px */
.hero { height: 100vh; }
.col { width: 50%; }

Màu

color: red;
color: #00ff66;                  /* hex */
color: rgb(0, 255, 102);
color: rgba(0, 0, 0, 0.5);       /* có độ trong suốt */
color: hsl(145, 100%, 50%);

Biến CSS (custom properties)

:root {
  --primary: #00ff66;
  --space: 16px;
}
.btn {
  color: var(--primary);
  padding: var(--space);
}

Kết quả

h1         font-size 2rem = 32px
.hero      cao bằng màn hình
.col       rộng nửa cha
rgba(0, 0, 0, 0.5) -> đen trong suốt 50%
hsl(145, 100%, 50%) -> xanh neon
.btn       chữ #00ff66, padding 16px

Flexbox sắp xếp các phần tử con theo một hàng hoặc một cột.

.container {
  display: flex;
  flex-direction: row;          /* row | column */
  justify-content: space-between; /* căn theo trục chính */
  align-items: center;          /* căn theo trục phụ */
  flex-wrap: wrap;              /* cho phép xuống dòng */
  gap: 16px;                    /* khoảng cách giữa các phần tử */
}

.item {
  flex: 1;                      /* chia đều phần còn trống */
}
.sidebar {
  flex: 0 0 250px;              /* grow shrink basis: cố định 250px */
}

Giá trị hay dùng

justify-content: flex-start, center, flex-end, space-between, space-around, space-evenly
align-items: stretch, flex-start, center, flex-end, baseline
align-self: căn riêng cho một phần tử con
order: đổi thứ tự hiển thị

.center {                       /* căn giữa tuyệt đối */
  display: flex;
  justify-content: center;
  align-items: center;
}

Kết quả

.container:   [A]      [B]      [C]      <- dàn đều, căn giữa dọc, cách 16px, hết chỗ thì xuống dòng
.item flex:1  mỗi item chia đều phần trống
.sidebar      cố định 250px, không co không giãn
.center       con nằm chính giữa cả ngang lẫn dọc

CSS Grid chia bố cục theo cả hàng và cột.

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);   /* 3 cột bằng nhau */
  grid-template-rows: auto 1fr auto;
  gap: 20px;
}

.cards {                                    /* tự co số cột theo màn hình */
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
}

.item-wide {
  grid-column: span 2;                      /* chiếm 2 cột */
}

grid-template-areas

.layout {
  display: grid;
  grid-template-columns: 250px 1fr;
  grid-template-areas:
    "header header"
    "sidebar main"
    "footer footer";
}
header { grid-area: header; }
aside  { grid-area: sidebar; }
main   { grid-area: main; }
footer { grid-area: footer; }

Kết quả

.grid:  [1][2][3]        3 cột bằng nhau, khe 20px
        [4][5][6]
.cards: màn 1000px -> 5 cột; màn 450px -> 2 cột (mỗi cột >= 200px)
.item-wide: một ô rộng bằng 2 cột
.layout:
+----------------------+
|        header        |
+--------+-------------+
| sidebar|    main     |
| 250px  |             |
+--------+-------------+
|        footer        |
+----------------------+

Flexbox hợp cho bố cục một chiều (thanh menu, hàng nút); Grid hợp cho bố cục hai chiều (cả trang, lưới thẻ).

static: mặc định, theo dòng chảy bình thường
relative: dịch so với vị trí gốc, vẫn giữ chỗ cũ
absolute: định vị theo tổ tiên gần nhất có position khác static
fixed: định vị theo màn hình, không cuộn theo trang
sticky: bình thường cho tới khi cuộn tới ngưỡng thì dính lại

.card {
  position: relative;          /* làm mốc cho phần tử con absolute */
}
.badge {
  position: absolute;
  top: 8px;
  right: 8px;
}
.navbar {
  position: sticky;
  top: 0;
  z-index: 10;                 /* lớp chồng: số lớn nằm trên */
}
.chat-button {
  position: fixed;
  bottom: 20px;
  right: 20px;
}

Kết quả

- .badge nằm góc trên phải của .card (cách 8px), không phải góc trang
- .navbar dính đỉnh màn hình khi cuộn qua, nằm trên nội dung khác (z-index 10)
- .chat-button luôn ở góc dưới phải màn hình dù cuộn tới đâu

Responsive: giao diện tự thích nghi với mọi kích thước màn hình. Cách phổ biến là mobile-first: viết CSS cho điện thoại trước, rồi dùng media query mở rộng cho màn hình lớn.

.grid {
  display: grid;
  grid-template-columns: 1fr;          /* điện thoại: 1 cột */
}

@media (min-width: 768px) {            /* máy tính bảng trở lên */
  .grid { grid-template-columns: 1fr 1fr; }
}

@media (min-width: 1200px) {           /* màn hình lớn */
  .grid { grid-template-columns: repeat(4, 1fr); }
}

@media (prefers-color-scheme: dark) {  /* theo chế độ tối của hệ thống */
  body { background: #000; color: #0f6; }
}

h1 { font-size: clamp(1.5rem, 4vw, 3rem); }   /* co giãn trong khoảng */
img { max-width: 100%; height: auto; }

Kết quả

Điện thoại (< 768px):  1 cột
Tablet (>= 768px):     2 cột
Màn lớn (>= 1200px):   4 cột
Chế độ tối:            nền đen, chữ xanh neon
h1 co giãn 24px - 48px; ảnh không bao giờ tràn khỏi màn hình

Transition

Chuyển đổi mượt giữa hai trạng thái (ví dụ khi hover).

.btn {
  background: #00ff66;
  transition: background 0.3s ease, transform 0.2s;
}
.btn:hover {
  background: #00cc52;
  transform: scale(1.05);
}

Animation với @keyframes

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

.card {
  animation: fadeIn 0.5s ease-out forwards;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}
.loader { animation: spin 1s linear infinite; }

Kết quả

- Rê chuột lên .btn: nền đậm dần trong 0.3s, nút phóng 105% trong 0.2s
- .card xuất hiện: mờ dần hiện ra và trượt lên 20px trong 0.5s, giữ trạng thái cuối
- .loader quay tròn đều mỗi vòng 1 giây, không ngừng

transform (translate, scale, rotate) và opacity cho hiệu ứng mượt nhất vì không làm trình duyệt tính lại bố cục.

Subquery là câu truy vấn lồng trong câu truy vấn khác. CTE (WITH) đặt tên cho kết quả trung gian, giúp truy vấn dài dễ đọc.

-- Sản phẩm đắt hơn giá trung bình
SELECT name, price FROM products
WHERE price > (SELECT AVG(price) FROM products);

-- Người dùng có ít nhất một đơn hàng
SELECT name FROM users u
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);

-- Subquery trong FROM
SELECT city, max_age FROM (
  SELECT city, MAX(age) AS max_age FROM users GROUP BY city
) t WHERE max_age > 50;

WITH monthly AS (
  SELECT strftime('%Y-%m', created_at) AS thang, SUM(total) AS doanh_thu
  FROM orders
  GROUP BY thang
)
SELECT thang, doanh_thu
FROM monthly
WHERE doanh_thu > 10000000
ORDER BY thang;

Index

Index giúp tìm kiếm nhanh hơn trên cột hay dùng trong WHERE / JOIN / ORDER BY, đổi lại tốn thêm bộ nhớ và làm INSERT / UPDATE chậm hơn một chút.

CREATE INDEX idx_users_email ON users(email);
CREATE UNIQUE INDEX idx_products_sku ON products(sku);
CREATE INDEX idx_orders_user_date ON orders(user_id, created_at);  -- index nhiều cột
DROP INDEX idx_users_email;

EXPLAIN QUERY PLAN SELECT * FROM users WHERE email = 'an@mail.com';  -- xem có dùng index không

Transaction

Transaction gom nhiều câu lệnh thành một khối: hoặc thành công tất cả (COMMIT), hoặc hủy tất cả (ROLLBACK).

BEGIN TRANSACTION;
UPDATE accounts SET balance = balance - 500000 WHERE id = 1;
UPDATE accounts SET balance = balance + 500000 WHERE id = 2;
COMMIT;          -- lưu thay đổi
-- ROLLBACK;     -- hoặc hủy nếu có lỗi

Tính chất ACID

Atomicity: làm trọn vẹn hoặc không làm gì
Consistency: dữ liệu luôn thỏa mọi ràng buộc
Isolation: các transaction chạy đồng thời không làm hỏng nhau
Durability: đã COMMIT thì không mất kể cả khi sập nguồn

PHP là ngôn ngữ kịch bản (scripting) chạy phía server, ra đời để làm web động — vẫn là nền tảng của một phần lớn web hiện nay (WordPress, một phần Facebook cũ) dù không còn "hot" như trước.

<?php
$name = "An";
echo "Xin chào, $name!";      // chuỗi trong nháy kép cho phép chèn biến trực tiếp

function tinhTong($a, $b) {
    return $a + $b;
}
echo tinhTong(2, 3);           // -> 5

$users = ["An", "Bình", "Chi"];
foreach ($users as $u) {
    echo $u . "\n";
}
?>

PHP trộn lẫn được với HTML ngay trong cùng file (`<?php ... ?>`), là lý do nó phổ biến cho web truyền thống; framework Laravel là lựa chọn hiện đại phổ biến nhất để viết PHP có cấu trúc, giống Django/Rails.

C# (đọc là "C-sharp") là ngôn ngữ hướng đối tượng của Microsoft, chạy trên nền tảng .NET — dùng nhiều để viết backend, ứng dụng Windows, và làm game với Unity.

using System;

class Program {
    static void Main() {
        string name = "An";
        Console.WriteLine($"Xin chào, {name}!");   // string interpolation

        var numbers = new List<int> { 1, 2, 3 };
        var doubled = numbers.Select(n => n * 2);   // LINQ, giống map() của JS
        foreach (var n in doubled) Console.WriteLine(n);
    }
}

.NET (nền tảng chạy C#) giờ đã mã nguồn mở và chạy được trên Windows/Linux/macOS, không còn giới hạn trong hệ sinh thái Microsoft như trước; cú pháp C# khá gần với Java, ai biết một trong hai học ngôn ngữ còn lại sẽ nhanh.

Dart là ngôn ngữ của Google, gần như chỉ được biết đến nhờ Flutter — framework viết MỘT code chạy được trên cả iOS, Android, web và desktop.

void main() {
  String name = 'An';
  print('Xin chào, $name!');       // string interpolation

  final numbers = [1, 2, 3];
  final doubled = numbers.map((n) => n * 2).toList();
  print(doubled);                   // -> [2, 4, 6]
}

Dart biên dịch theo 2 chế độ: JIT (Just-In-Time) lúc phát triển để có hot reload cực nhanh, và AOT (Ahead-Of-Time) lúc build ra ứng dụng thật để chạy nhanh như code native — đây là lý do Flutter vừa phát triển nhanh vừa chạy mượt.

CORS (Cross-Origin Resource Sharing) là cơ chế bảo mật của trình duyệt chặn một trang web gọi API tới một domain KHÁC domain của chính nó, trừ khi server đó cho phép rõ ràng — đây là lỗi rất hay gặp khi mới làm frontend gọi API.

// Server phải trả về header này để trình duyệt CHO PHÉP frontend ở domain khác gọi tới
Access-Control-Allow-Origin: https://myapp.com
Access-Control-Allow-Methods: GET, POST, PUT, DELETE

// Lỗi CORS chỉ xảy ra khi gọi TỪ trình duyệt — gọi từ Node.js/Postman/server khác
// thì không bị chặn, vì CORS là quy tắc trình duyệt tự áp đặt để bảo vệ người dùng.
fetch('https://api.example.com/data')  // sẽ lỗi nếu api.example.com không cấu hình CORS cho domain của bạn

CORS không phải là lỗ hổng bảo mật của server — ngược lại, nó là lớp bảo vệ; thấy lỗi "blocked by CORS policy" nghĩa là trình duyệt đang làm đúng việc của nó, cần server (không phải frontend) cấu hình cho phép.

XSS (Cross-Site Scripting) là lỗ hổng cho phép kẻ tấn công CHÈN được đoạn JavaScript độc hại vào trang web mà người dùng khác sẽ xem — script đó chạy như thể nó thuộc về trang thật, đọc được cookie, giả mạo hành động của người dùng.

// NGUY HIỂM: hiển thị thẳng nội dung người dùng nhập mà không lọc
element.innerHTML = userComment;   // nếu userComment = "<script>đánh cắp cookie</script>"

// AN TOÀN HƠN: dùng textContent (trình duyệt không chạy nó như HTML)
element.textContent = userComment;

Nguyên tắc phòng chống: KHÔNG BAO GIỜ tin dữ liệu từ người dùng, luôn "escape" hoặc lọc trước khi hiển thị ra HTML; hầu hết framework hiện đại (React, Vue) tự động escape khi render `{value}`, chỉ nguy hiểm khi cố tình dùng `dangerouslySetInnerHTML` hay `v-html`.

Sass (Syntactically Awesome StyleSheets) là ngôn ngữ mở rộng CSS, thêm các tính năng lập trình (biến, hàm, lồng selector, import) rồi biên dịch ra CSS thuần mà trình duyệt hiểu được.

$primary: #00ff66;          // biến

.card {
  border: 1px solid $primary;
  .title {                   // lồng selector — biên dịch ra .card .title
    font-weight: bold;
  }
  &:hover { opacity: 0.8; }  // & đại diện cho chính .card
}

@mixin center {              // mixin: khối CSS tái sử dụng được
  display: flex;
  justify-content: center;
}
.box { @include center; }

Kết quả

.card { border: 1px solid #00ff66; }
.card .title { font-weight: bold; }
.card:hover { opacity: 0.8; }
.box { display: flex; justify-content: center; }

Nhiều tính năng của Sass (biến CSS `--x`, lồng selector qua CSS Nesting) giờ đã có sẵn trong CSS thuần ở trình duyệt hiện đại, nhưng Sass vẫn phổ biến nhờ mixin, hàm và các tính năng nâng cao chưa có trong CSS gốc.

Web Components là tập hợp API có sẵn của trình duyệt (Custom Elements, Shadow DOM, HTML Templates) cho phép tạo ra thẻ HTML TỰ ĐỊNH NGHĨA, tái sử dụng được ở bất kỳ dự án nào — không cần React, Vue hay framework nào khác.

class MyCounter extends HTMLElement {
  connectedCallback() {
    this.innerHTML = `<button>Đã bấm 0 lần</button>`;
    let count = 0;
    this.querySelector('button').onclick = (e) => {
      e.target.textContent = `Đã bấm ${++count} lần`;
    };
  }
}
customElements.define('my-counter', MyCounter);

<my-counter></my-counter>   <!-- dùng như một thẻ HTML bình thường -->

Shadow DOM cho phép CSS/JS bên trong component được CÔ LẬP, không bị ảnh hưởng bởi CSS của trang bên ngoài và ngược lại — đây là điểm khác biệt lớn nhất so với chỉ viết component bằng framework thông thường.

Serverless là mô hình triển khai trong đó bạn chỉ viết CODE XỬ LÝ (function), còn việc quản lý server, tự động mở rộng, và tính phí theo đúng thời gian chạy đều do nhà cung cấp cloud lo — không có nghĩa là "không có server", chỉ là bạn không phải quản lý nó.

// AWS Lambda — chỉ viết hàm xử lý, không cần cấu hình server
exports.handler = async (event) => {
  return { statusCode: 200, body: JSON.stringify({ message: 'Xin chào!' }) };
};

Trả phí theo số lần gọi và thời gian chạy thực tế (không tốn tiền lúc không có ai gọi) là ưu điểm lớn nhất; nhược điểm là "cold start" (lần gọi đầu sau một thời gian nghỉ chạy chậm hơn vì phải khởi động lại) và khó debug/theo dõi hơn so với server truyền thống.

Webhook là cách một hệ thống CHỦ ĐỘNG gọi tới URL của bạn ngay khi có sự kiện xảy ra (ví dụ: thanh toán thành công, có commit mới trên GitHub) — ngược với việc bạn phải liên tục hỏi (poll) "có gì mới chưa?".

// Server của bạn expose 1 endpoint để nhận webhook
app.post('/webhooks/payment', (req, res) => {
  const event = req.body;
  if (event.type === 'payment.success') {
    // xử lý: cập nhật đơn hàng đã thanh toán
  }
  res.sendStatus(200);   // luôn phản hồi nhanh để bên gửi biết đã nhận
});

Webhook về bản chất chỉ là một HTTP POST bình thường được gửi TỪ hệ thống khác TỚI server của bạn — nên gọi là "API ngược": thay vì bạn gọi họ, họ gọi bạn khi có chuyện xảy ra.

Index (chỉ mục) trong database là cấu trúc dữ liệu phụ giúp TÌM KIẾM nhanh hơn trên một cột, giống mục lục cuối sách — không cần index vẫn tra cứu được, nhưng phải "đọc từng trang" (quét toàn bộ bảng, rất chậm với bảng lớn).

CREATE INDEX idx_users_email ON users(email);

-- Truy vấn này giờ sẽ dùng index thay vì quét toàn bộ bảng
SELECT * FROM users WHERE email = 'an@mail.com';

EXPLAIN SELECT * FROM users WHERE email = 'an@mail.com'; -- xem có dùng index không

Đánh đổi: index giúp SELECT nhanh hơn nhiều nhưng làm INSERT/UPDATE/DELETE chậm đi một chút (vì phải cập nhật cả index) và tốn thêm bộ nhớ — nên chỉ đánh index trên các cột thực sự hay dùng để tìm kiếm/lọc/sắp xếp (WHERE, JOIN, ORDER BY), không nên đánh index tràn lan.

TDD (Test-Driven Development) là cách phát triển phần mềm trong đó bạn VIẾT TEST TRƯỚC KHI viết code thật — theo chu trình "Red - Green - Refactor": viết test (chưa có code nên test FAIL, đỏ), viết code tối thiểu để test PASS (xanh), rồi dọn dẹp lại code (refactor) mà không làm hỏng test.

// 1. RED: viết test trước, chạy sẽ fail vì cong() chưa tồn tại
test('cộng 2 số', () => {
  expect(cong(2, 3)).toBe(5);
});

// 2. GREEN: viết code tối thiểu để test pass
function cong(a, b) { return a + b; }

// 3. REFACTOR: cải thiện code (nếu cần) mà test vẫn pass

TDD ép buộc bạn nghĩ rõ ĐẦU VÀO/ĐẦU RA mong muốn trước khi viết logic, và đảm bảo mọi dòng code đều có test đi kèm — không phải lúc nào cũng cần áp dụng TDD nghiêm ngặt, nhưng tư duy "viết test sớm" luôn hữu ích.

Mocking là kỹ thuật THAY THẾ một phần phụ thuộc thật (gọi API, database, gửi email...) bằng một phiên bản GIẢ LẬP trong lúc test — giúp test chạy nhanh, ổn định, và không phụ thuộc vào hệ thống bên ngoài (mạng, server thật).

// Giả lập hàm gọi API thay vì gọi thật
jest.mock('./api');
import { fetchUser } from './api';

fetchUser.mockResolvedValue({ id: 1, name: 'An' }); // giả lập kết quả trả về

test('hiển thị tên user', async () => {
  const user = await fetchUser(1);
  expect(user.name).toBe('An');   // test chạy nhanh, không gọi API thật
});

Không mock thì test sẽ chậm (chờ mạng thật), không ổn định (server có thể đang bảo trì), và tốn tài nguyên thật (gửi email thật, trừ tiền thật) — mock giúp test chỉ tập trung kiểm tra LOGIC của chính đoạn code đang test.

E2E Testing (End-to-End Testing) là kiểm thử MÔ PHỎNG THAO TÁC THẬT của người dùng trên toàn bộ ứng dụng đã chạy đầy đủ (giao diện, backend, database) — ví dụ tự động mở trình duyệt, gõ vào ô tìm kiếm, bấm nút, kiểm tra kết quả hiển thị đúng.

// Ví dụ dùng Playwright/Cypress
test('đăng nhập thành công', async ({ page }) => {
  await page.goto('/login');
  await page.fill('#email', 'an@mail.com');
  await page.fill('#password', '123456');
  await page.click('button[type="submit"]');
  await expect(page.locator('.welcome')).toHaveText('Chào An!');
});

E2E test chậm hơn và dễ "flaky" (thỉnh thoảng fail dù code đúng, do mạng chậm/animation) hơn unit test rất nhiều, nên thường chỉ viết cho các luồng QUAN TRỌNG NHẤT (đăng nhập, thanh toán) — không nên viết E2E cho mọi trường hợp nhỏ nhặt như unit test.

Singleton là pattern đảm bảo một class CHỈ CÓ ĐÚNG MỘT thực thể (instance) tồn tại trong suốt chương trình, và cung cấp một điểm truy cập chung tới nó — thường dùng cho thứ chỉ nên có một bản (kết nối database, cấu hình toàn cục, logger).

class Logger {
  static #instance;                       // # = private field trong JS

  static getInstance() {
    if (!Logger.#instance) {
      Logger.#instance = new Logger();    // chỉ tạo 1 lần duy nhất
    }
    return Logger.#instance;
  }

  log(msg) { console.log(`[LOG] ${msg}`); }
}

Logger.getInstance().log('Xin chào');     // luôn trả về cùng 1 instance

Singleton hay bị lạm dụng và biến thành "biến toàn cục có vỏ bọc class" — làm code khó test hơn (vì trạng thái dùng chung ẩn ở mọi nơi) và khó chạy song song đúng cách, nên chỉ dùng khi thực sự chỉ nên có một thực thể.

Factory là pattern trong đó bạn gọi một HÀM để tạo đối tượng, thay vì gọi `new` trực tiếp — hàm đó quyết định TẠO LOẠI ĐỐI TƯỢNG NÀO dựa trên tham số đầu vào, giúp code gọi không cần biết chi tiết class cụ thể nào được tạo ra.

class Cho { keu() { return 'Gâu!'; } }
class Meo { keu() { return 'Meo!'; } }

function taoDongVat(loai) {              // factory function
  if (loai === 'cho') return new Cho();
  if (loai === 'meo') return new Meo();
  throw new Error('Không rõ loại');
}

const vatNuoi = taoDongVat('cho');
console.log(vatNuoi.keu());              // -> 'Gâu!' — nơi gọi không cần biết class Cho

Factory hữu ích khi việc tạo đối tượng phức tạp (cần chọn 1 trong nhiều class con, hoặc cần thiết lập nhiều bước) — tách logic "tạo cái gì" ra khỏi logic "dùng nó thế nào" giúp thêm loại mới sau này không phải sửa code nơi gọi.

Observer là pattern trong đó một đối tượng (subject) giữ danh sách những "người quan sát" (observer) và TỰ ĐỘNG BÁO cho tất cả khi có thay đổi — nền tảng của rất nhiều thứ quen thuộc: sự kiện DOM, React re-render, RxJS.

class Subject {
  #observers = [];
  subscribe(fn) { this.#observers.push(fn); }          // đăng ký lắng nghe
  notify(data) { this.#observers.forEach(fn => fn(data)); }  // báo cho tất cả
}

const tinTuc = new Subject();
tinTuc.subscribe(bai => console.log('Người đọc A thấy:', bai));
tinTuc.subscribe(bai => console.log('Người đọc B thấy:', bai));

tinTuc.notify('Có bài viết mới!');   // cả 2 observer cùng nhận được

`addEventListener` của DOM, hệ thống state của React, và các thư viện quản lý state (Redux) đều là biến thể của Observer — hiểu pattern này giúp hiểu TẠI SAO các API đó được thiết kế theo kiểu "đăng ký rồi được gọi lại" thay vì hỏi liên tục (polling).

SOLID là 5 nguyên tắc thiết kế hướng đối tượng giúp code dễ bảo trì, mở rộng hơn — viết tắt của: Single Responsibility (một class chỉ nên làm một việc), Open/Closed (mở để mở rộng, đóng để sửa đổi), Liskov Substitution, Interface Segregation, Dependency Inversion.

// VI PHẠM Single Responsibility: 1 class làm quá nhiều việc
class NguoiDung {
  luuVaoDatabase() { /* ... */ }
  guiEmail() { /* ... */ }         // không liên quan tới việc "là người dùng"
}

// TUÂN THỦ: tách trách nhiệm ra riêng
class NguoiDung { /* chỉ giữ dữ liệu người dùng */ }
class NguoiDungRepository { luu(nguoiDung) { /* ... */ } }
class EmailService { gui(nguoiDung) { /* ... */ } }

SOLID không phải luật bắt buộc tuân theo tuyệt đối trong mọi dòng code, mà là NGUYÊN TẮC ĐỊNH HƯỚNG — vi phạm một chút ở code nhỏ, ít thay đổi thường không sao, nhưng áp dụng SOLID rất đáng giá ở phần code lớn, phức tạp, hay phải sửa đổi.

DRY (Don't Repeat Yourself) là nguyên tắc: MỖI kiến thức/logic trong hệ thống chỉ nên xuất hiện ở ĐÚNG MỘT NƠI — nếu cùng một logic bị copy-paste ở nhiều chỗ, sửa lỗi ở một nơi rồi quên sửa nơi khác là nguồn bug rất phổ biến.

// VI PHẠM DRY: cùng công thức tính giảm giá lặp lại 2 nơi
function giaGioHang(gia) { return gia * 0.9; }
function giaCheckout(gia) { return gia * 0.9; }   // lặp lại — sửa 1 chỗ dễ quên chỗ kia

// TUÂN THỦ DRY: chỉ định nghĩa một lần, tái sử dụng
function apDungGiamGia(gia) { return gia * 0.9; }

DRY không có nghĩa là "không bao giờ lặp lại bất kỳ dòng code nào" — 2 đoạn code TRÙNG HỢP NGẪU NHIÊN giống nhau nhưng đại diện cho 2 KHÁI NIỆM khác nhau thì không cần gộp, gộp sai sẽ tạo ra sự phụ thuộc giả tạo giữa hai thứ không thực sự liên quan.

Technical Debt (nợ kỹ thuật) là các đánh đổi trong code — làm nhanh, làm tắt, bỏ qua thiết kế tốt để kịp deadline — giống như "vay nợ": có thể hữu ích ngắn hạn, nhưng nếu không "trả" (refactor sau) sẽ ngày càng khó sửa và chậm phát triển hơn.

// Comment TODO là dấu hiệu nợ kỹ thuật được ghi nhận rõ ràng
// TODO: hàm này copy-paste tạm để kịp release, cần refactor lại chung với tinhGia()
function tinhGiaKhuyenMai(gia) {
  return gia * 0.85;   // logic gần giống tinhGia(), nên gộp lại sau
}

Nợ kỹ thuật không phải lúc nào cũng xấu — đôi khi CHỦ ĐỘNG chấp nhận nợ để kịp ra mắt sản phẩm là quyết định đúng, miễn là được GHI NHẬN rõ ràng (TODO, ticket) và có kế hoạch trả sau, thay vì âm thầm tích tụ không ai biết tới khi code trở nên không thể bảo trì.

`useState(giaTriBanDau)` trả về mảng gồm giá trị hiện tại và hàm cập nhật. Gọi hàm cập nhật làm React lên lịch vẽ lại. Cập nhật không xảy ra ngay trong cùng lần render, và nhiều lệnh `set` trong một sự kiện được gộp. Khi giá trị mới phụ thuộc giá trị cũ, truyền hàm `(cu) => moi` để tránh dùng giá trị lỗi thời. State kiểu object/mảng phải được thay bằng bản sao mới, không sửa tại chỗ. Giá trị khởi tạo tốn kém nên truyền dưới dạng hàm: `useState(() => tinhToan())`.

import { useState } from 'react';

function GioHang() {
  const [ds, setDs] = useState([]);
  const them = (ten) => setDs((cu) => [...cu, ten]);
  const xoa = (ten) => setDs((cu) => cu.filter((x) => x !== ten));
  return (
    <div>
      <button onClick={() => them('Sách')}>Thêm</button>
      <p>{ds.length} món: {ds.join(', ')}</p>
      <button onClick={() => xoa('Sách')}>Xóa</button>
    </div>
  );
}

Kết quả

- Ban đầu hiện `0 món:` (mảng rỗng)
- Bấm "Thêm" hai lần: dạng hàm `(cu) => [...cu, ten]` cộng dồn đúng, hiện `2 món: Sách, Sách`
- Bấm "Xóa" lọc bỏ mọi phần tử `Sách` và về lại `0 món:`

Lưu ý

- Không viết `ds.push(...)` rồi `setDs(ds)`: cùng tham chiếu nên React không thấy thay đổi
- State đổi thì component vẽ lại, còn biến thường (`let`) thì mất sau mỗi lần render

Một component trải qua ba giai đoạn: mount (hiện lần đầu), update (vẽ lại khi state, props hoặc context đổi) và unmount (bị gỡ). Với component hàm, mỗi lần "render" là một lần React gọi lại chính hàm đó; biến cục bộ được tính lại, còn state được React giữ giúp. Phần việc phụ (gọi API, đăng ký sự kiện) đặt trong `useEffect`, chạy SAU khi giao diện được vẽ. Ở chế độ phát triển, `<StrictMode>` cố ý gọi render và effect hai lần để lộ lỗi side effect.

import { useState, useEffect } from 'react';

function DongHo() {
  const [giay, setGiay] = useState(0);
  console.log('render', giay);
  useEffect(() => {
    console.log('mount');
    const id = setInterval(() => setGiay((g) => g + 1), 1000);
    return () => {
      clearInterval(id);
      console.log('unmount');
    };
  }, []);
  return <p>{giay} giây</p>;
}

Kết quả

- Console in `render 0` rồi `mount` ngay khi component xuất hiện
- Mỗi giây state đổi nên in tiếp `render 1`, `render 2`... và giao diện cập nhật
- Khi `DongHo` bị gỡ khỏi trang, hàm dọn dẹp chạy: `clearInterval` và in `unmount`
- Trong StrictMode khi dev, `mount` rồi `unmount` rồi `mount` có thể hiện hai lần: đó là cố ý

Lưu ý

- Giữ hàm render "thuần": cùng props và state phải ra cùng JSX, không gọi API trong thân hàm
- Luôn trả hàm dọn dẹp từ effect khi đã đăng ký thứ gì đó

Context API giải quyết "prop drilling": thay vì truyền props qua từng tầng, bạn tạo context bằng `createContext`, bọc cây con bằng `Provider` có `value`, rồi bất kỳ component nào bên dưới đọc bằng `useContext`. Phù hợp với dữ liệu ít đổi và dùng khắp nơi: giao diện sáng tối, người dùng đăng nhập, ngôn ngữ. Khi `value` đổi, mọi component đọc context đó vẽ lại; vì vậy với state đổi liên tục nên dùng Zustand hoặc Redux, hoặc tách context nhỏ.

import { createContext, useContext, useState } from 'react';

const NguoiDungCtx = createContext(null);

function NguoiDungProvider({ children }) {
  const [nguoiDung, setNguoiDung] = useState({ ten: 'An' });
  return (
    <NguoiDungCtx.Provider value={{ nguoiDung, setNguoiDung }}>{children}</NguoiDungCtx.Provider>
  );
}

function LoiChao() {
  const { nguoiDung } = useContext(NguoiDungCtx);
  return <p>Xin chào, {nguoiDung.ten}</p>;
}

Kết quả

- `LoiChao` đặt bên trong `NguoiDungProvider` hiển thị `Xin chào, An` mà không cần nhận props
- Gọi `setNguoiDung({ ten: 'Bình' })` ở bất kỳ nơi nào trong cây thì `LoiChao` tự vẽ lại thành `Xin chào, Bình`
- Component nằm ngoài Provider nhận `null` (giá trị mặc định)

Lưu ý

- Bọc `value` bằng `useMemo` nếu là object tạo mới mỗi lần để tránh vẽ lại thừa
- Tạo hook `useNguoiDung()` bọc `useContext` và báo lỗi nếu thiếu Provider

`entry` và `output` là hai cấu hình BẮT BUỘC của mọi webpack config: `entry` cho biết webpack nên BẮT ĐẦU phân tích quan hệ import từ file nào, `output` cho biết kết quả đóng gói cuối cùng nên LƯU Ở ĐÂU và đặt tên gì.

module.exports = {
  entry: './src/index.js',                 // điểm bắt đầu — webpack đi theo mọi import từ đây
  output: {
    filename: 'bundle.[contenthash].js',   // [contenthash] đổi tên file khi nội dung đổi, giúp cache trình duyệt đúng
    path: __dirname + '/dist',
  },
};

`[contenthash]` trong tên file output là kỹ thuật "cache busting" — khi nội dung file thay đổi, tên file cũng đổi theo, buộc trình duyệt tải bản mới thay vì dùng bản cũ đã cache; nếu nội dung không đổi, tên file giữ nguyên và trình duyệt tiếp tục dùng cache hiệu quả.

Loader dạy cho webpack cách xử lý các LOẠI FILE KHÔNG PHẢI JavaScript thuần (CSS, hình ảnh, TypeScript, Sass...) — về bản chất, webpack chỉ hiểu JavaScript, loader "dịch" các file khác thành thứ webpack có thể đưa vào bundle.

module.exports = {
  module: {
    rules: [
      { test: /\.css$/, use: ['style-loader', 'css-loader'] },     // đọc CSS rồi tự chèn vào <style>
      { test: /\.png$/, type: 'asset/resource' },                  // xử lý ảnh (webpack 5 trở lên có sẵn)
      { test: /\.tsx?$/, use: 'ts-loader' },                        // biên dịch TypeScript
    ],
  },
};

Nhiều loader có thể áp dụng NỐI TIẾP cho cùng một loại file, chạy theo thứ tự TỪ PHẢI SANG TRÁI trong mảng `use` — ví dụ `['style-loader', 'css-loader']` nghĩa là `css-loader` chạy TRƯỚC (đọc nội dung CSS), rồi kết quả mới được đưa cho `style-loader` (chèn vào trang).

Plugin can thiệp vào TOÀN BỘ quá trình build (không chỉ xử lý từng file như loader) — có thể sinh thêm file, tối ưu bundle, hoặc thay đổi cách webpack hoạt động ở bất kỳ giai đoạn nào của quá trình đóng gói.

const HtmlWebpackPlugin = require('html-webpack-plugin');

module.exports = {
  plugins: [
    new HtmlWebpackPlugin({ template: './src/index.html' }),  // tự sinh file HTML, tự chèn thẻ <script> tới bundle
  ],
};

Phân biệt Loader và Plugin: Loader trả lời câu hỏi "làm sao ĐỌC file này", còn Plugin trả lời câu hỏi "làm gì THÊM với toàn bộ quá trình build" — một dự án thường dùng nhiều loader (một loại cho mỗi kiểu file) và một vài plugin (cho các tác vụ toàn cục như sinh HTML, dọn dẹp thư mục dist trước khi build).

Code Splitting là kỹ thuật chia bundle THÀNH NHIỀU FILE NHỎ thay vì một file khổng lồ duy nhất — trình duyệt chỉ cần tải phần code CẦN THIẾT cho trang hiện tại, các phần khác (trang khác, tính năng ít dùng) được tải SAU khi thực sự cần tới.

// Dynamic import — webpack tự động tách phần này thành một file riêng
button.addEventListener('click', async () => {
  const { default: bieuDo } = await import('./BieuDoNangCao.js');
  bieuDo.render();
});

Không có Code Splitting, một ứng dụng lớn có thể tạo ra một file JavaScript hàng MB mà người dùng phải tải hết trước khi trang chạy được, dù chỉ dùng một phần nhỏ ngay từ đầu — React cũng hỗ trợ pattern này qua `React.lazy()` để "tải lười" (lazy load) từng phần giao diện.

Store là nơi duy nhất giữ state của Redux. Nó có ba phương thức: `getState()` đọc state hiện tại, `dispatch(action)` gửi action cho reducer, `subscribe(listener)` đăng ký hàm được gọi sau mỗi thay đổi. Trong thực tế bạn tạo store bằng `configureStore` của Redux Toolkit. Ví dụ dưới đây tự cài một store thu nhỏ để thấy cơ chế bên trong.

function createStore(reducer) {
  let state = reducer(undefined, { type: '@@init' });
  const listeners = new Set();
  return {
    getState: () => state,
    dispatch(action) {
      state = reducer(state, action);
      listeners.forEach((f) => f());
    },
    subscribe(f) {
      listeners.add(f);
      return () => listeners.delete(f);
    },
  };
}
const store = createStore((s = 0, a) => (a.type === 'checkIn' ? s + 1 : s));
const unsubscribe = store.subscribe(() => console.log('sĩ số mới:', store.getState()));
store.dispatch({ type: 'checkIn' });
store.dispatch({ type: 'checkIn' });
unsubscribe();
store.dispatch({ type: 'checkIn' });
console.log(store.getState());

Kết quả

sĩ số mới: 1
sĩ số mới: 2
store.getState() → 3

Lưu ý

- Mỗi ứng dụng chỉ một store; chia nhỏ state bằng nhiều reducer (slice)
- Hàm `subscribe` trả về hàm hủy đăng ký

Action là object thuần có trường `type` (và dữ liệu đi kèm, thường là `payload`) mô tả "chuyện gì đã xảy ra". Action creator là hàm sinh action. Reducer là hàm thuần `(state, action) => stateMoi`: không sửa state cũ (luôn trả bản sao), không gọi API, không dùng ngẫu nhiên hay thời gian. Nhờ thuần nên cùng đầu vào luôn ra cùng kết quả và dễ kiểm thử.

const addHomework = (title) => ({ type: 'homework/add', payload: title });
const finish = (id) => ({ type: 'homework/finish', payload: id });

function homework(state = [], action) {
  switch (action.type) {
    case 'homework/add':
      return [...state, { id: state.length + 1, title: action.payload, done: false }];
    case 'homework/finish':
      return state.map((h) => (h.id === action.payload ? { ...h, done: true } : h));
    default:
      return state;
  }
}
const a = homework(undefined, addHomework('Bài tập Toán'));
const b = homework(a, addHomework('Bài tập Văn'));
const c = homework(b, finish(1));
console.log(c);
console.log(a === b, b[0] === c[0], b[1] === c[1]);

Kết quả

c → [ { id: 1, title: 'Bài tập Toán', done: true }, { id: 2, title: 'Bài tập Văn', done: false } ]
a === b, b[0] === c[0], b[1] === c[1] → false false true

Lưu ý

- Không viết `state.push(...)` trong reducer; Redux Toolkit cho phép viết như vậy nhờ Immer
- Đặt tên `type` theo dạng `lĩnh vực/sự kiện` để dễ đọc

`useSelector(state => ...)` của `react-redux` đọc MỘT PHẦN state từ store và đăng ký component với phần đó: component chỉ vẽ lại khi giá trị mà selector trả về thay đổi (so sánh bằng `===`). Bọc ứng dụng bằng `<Provider store={store}>` một lần. Selector nên trả về giá trị nhỏ nhất đủ dùng và không tạo object/mảng mới mỗi lần gọi (nếu không component vẽ lại mãi); dữ liệu suy ra nên dùng `createSelector` (reselect) để ghi nhớ.

import { useSelector } from 'react-redux';

function SoMon() {
  const soMon = useSelector((s) => s.gio.ds.length);
  const tongTien = useSelector((s) => s.gio.ds.reduce((t, m) => t + m.gia, 0));
  return <p>{soMon} món, tổng {tongTien}đ</p>;
}

Kết quả

- Giỏ có hai món giá 50000 và 10000: hiện `2 món, tổng 60000đ`
- Khi một phần khác của store thay đổi (ví dụ `s.nguoiDung`), `SoMon` KHÔNG vẽ lại vì hai selector vẫn trả cùng giá trị
- Thêm món vào giỏ: cả hai giá trị đổi nên component vẽ lại một lần

Lưu ý

- Chọn từng giá trị thay vì cả `state` để tránh vẽ lại thừa
- Selector trả `s.gio.ds.filter(...)` tạo mảng mới mỗi lần nên gây vẽ lại; dùng `createSelector`

Middleware là lớp nằm giữa `dispatch` và reducer, có thể ghi log, chặn, đổi hoặc trì hoãn action. Thunk là middleware phổ biến nhất: cho phép `dispatch` một HÀM thay vì object; hàm đó nhận `dispatch` và `getState` nên chạy được logic bất đồng bộ (gọi API) rồi dispatch các action `đang tải`, `thành công`, `thất bại`. Redux Toolkit đã bật sẵn thunk.

const loadStudent = (id) => async (dispatch, getState) => {
  dispatch({ type: 'student/loading' });
  try {
    const student = await Promise.resolve({ id, name: 'An' });
    dispatch({ type: 'student/done', payload: student });
  } catch (error) {
    dispatch({ type: 'student/error', error: error.message });
  }
};
const log = [];
const dispatch = (a) => (typeof a === 'function' ? a(dispatch, () => ({})) : log.push(a.type));
await dispatch(loadStudent(1));
console.log(log);

Kết quả

log → [ 'student/loading', 'student/done' ]

Lưu ý

- Với Redux Toolkit dùng `createAsyncThunk` thay vì tự viết ba loại action
- Middleware khác hay gặp: redux-saga, redux-observable, redux-logger

Nhóm phương thức làm thay đổi nội dung mảng: thêm (`push` cuối, `unshift` đầu), xóa (`pop` cuối, `shift` đầu), chèn hoặc xóa ở giữa (`splice`), ghi đè (`fill`, `copyWithin`). Chúng SỬA TẠI CHỖ mảng gốc. Từ ES2023 có phiên bản không đổi mảng gốc, trả về bản sao đã đổi: `toSpliced()` và `with()`; dùng chúng khi làm việc với state bất biến (React, Redux).

const roll = ['An', 'Bình', 'Chi'];
roll.push('Dũng');
roll.unshift('Mai');
console.log([...roll]);
console.log(roll.pop(), roll.shift(), roll);
const updated = roll.toSpliced(1, 1, 'Em', 'Phúc');
console.log(updated, roll);
console.log(roll.with(0, 'Khoa'), roll);

Kết quả

[...roll] → [ 'Mai', 'An', 'Bình', 'Chi', 'Dũng' ]
roll.pop(), roll.shift(), roll → 'Dũng' 'Mai' [ 'An', 'Bình', 'Chi' ]
updated, roll → [ 'An', 'Em', 'Phúc', 'Chi' ] [ 'An', 'Bình', 'Chi' ]
roll.with(0, 'Khoa'), roll → [ 'Khoa', 'Bình', 'Chi' ] [ 'An', 'Bình', 'Chi' ]

Lưu ý

- `push`, `pop`, `splice` đổi mảng gốc; `toSpliced`, `with` thì không
- Với state React luôn dùng bản trả về bản sao

Nhóm phương thức duyệt mảng bằng hàm callback: `forEach` (làm việc với từng phần tử, không trả gì), `map` (biến đổi thành mảng mới cùng độ dài), `filter` (giữ phần tử thỏa điều kiện), `reduce` (gom thành một giá trị), `flat` và `flatMap` (làm phẳng), `entries` (cặp chỉ số–giá trị). `map`, `filter`, `reduce` KHÔNG sửa mảng gốc và nối chuỗi được, nên là nền tảng của lập trình hàm.

const scores = [6, 7, 8, 9];
const bonus = scores.filter((x) => x >= 7).map((x) => x + 1).reduce((t, x) => t + x, 0);
console.log(bonus);
scores.forEach((x, i) => i < 2 && console.log(i, x));
console.log([['An', 'Bình'], ['Chi', ['Dũng']]].flat(2), ['An', 'Bình'].flatMap((n) => [n, n.length]));
console.log([...['An', 'Bình'].entries()]);

Kết quả

bonus → 27
i, x → 0 6
i, x → 1 7
[['An', 'Bình'], ['Chi', ['Dũng']]].flat(2), ['An', 'Bình'].flatMap((n) => [n, n.length]) →
  [ 'An', 'Bình', 'Chi', 'Dũng' ] [ 'An', 2, 'Bình', 4 ]
[...['An', 'Bình'].entries()] → [ [ 0, 'An' ], [ 1, 'Bình' ] ]

Lưu ý

- `forEach` không dừng được bằng `break`; dùng `for...of` hoặc `some`/`every`
- Callback của `reduce` nhận `(tong, phanTu)`; luôn đưa giá trị khởi đầu

Nhóm sắp xếp mảng: `sort()` và `reverse()` đổi mảng gốc, còn `toSorted()` và `toReversed()` (ES2023) trả về bản sao đã sắp, không đụng mảng gốc. `sort()` mặc định so sánh như CHUỖI (nên `[10, 9, 1]` ra `[1, 10, 9]`); muốn sắp số hay theo trường phải truyền hàm so sánh `(a, b) => a - b`. Thuật toán ổn định (phần tử bằng nhau giữ thứ tự cũ).

console.log([10, 9, 1].sort(), [10, 9, 1].sort((a, b) => a - b));
const students = [{ name: 'Bình', age: 16 }, { name: 'An', age: 15 }];
console.log(students.toSorted((a, b) => a.age - b.age).map((x) => x.name), students.map((x) => x.name));
console.log(['Đào', 'Anh', 'Ân'].sort(), ['Đào', 'Anh', 'Ân'].sort((a, b) => a.localeCompare(b, 'vi')));
const roll = ['An', 'Bình', 'Chi'];
console.log(roll.toReversed(), roll);

Kết quả

[10, 9, 1].sort(), [10, 9, 1].sort((a, b) => a - b) → [ 1, 10, 9 ] [ 1, 9, 10 ]
students.toSorted((a, b) => a.age - b.age).map((x) => x.name), students.map((x) => x.name) →
  [ 'An', 'Bình' ] [ 'Bình', 'An' ]
['Đào', 'Anh', 'Ân'].sort(), ['Đào', 'Anh', 'Ân'].sort((a, b) => a.localeCompare(b, 'vi')) →
  [ 'Anh', 'Ân', 'Đào' ] [ 'Anh', 'Ân', 'Đào' ]
roll.toReversed(), roll → [ 'Chi', 'Bình', 'An' ] [ 'An', 'Bình', 'Chi' ]

Lưu ý

- Luôn truyền hàm so sánh khi sắp số
- Dùng `localeCompare` để sắp chuỗi có dấu đúng thứ tự ngôn ngữ

`arr.shift()` xóa phần tử đầu tiên và trả về nó, dồn các phần tử còn lại lên một vị trí. Kết hợp với `push()` tạo thành hàng đợi (queue) vào trước ra trước. Trên mảng rất lớn `shift` chậm hơn `pop` vì phải dịch chuyển mọi phần tử.

const queue = ['An', 'Bình', 'Chi'];
console.log(queue.shift());
console.log(queue);
queue.push('Dũng');
console.log(queue.shift(), queue.shift());
console.log(queue);
console.log([].shift());

Kết quả

queue.shift() → 'An'
queue → [ 'Bình', 'Chi' ]
queue.shift(), queue.shift() → 'Bình' 'Chi'
queue → [ 'Dũng' ]
[].shift() → undefined

Tham số & trả về

Không có tham số
Trả về: phần tử đầu bị xóa, hoặc `undefined` nếu mảng rỗng

Lưu ý

- Hàng đợi lớn nên dùng cấu trúc chuyên dụng thay vì `shift()` lặp lại nhiều lần
- Xử lý lần lượt từng phần tử đầu: `while (queue.length) { const x = queue.shift(); ... }`

`arr.unshift(...cacPhanTu)` thêm phần tử vào đầu mảng, đẩy các phần tử cũ lùi về sau, sửa mảng gốc và trả về độ dài mới. Nếu thêm nhiều phần tử trong một lần gọi thì giữ nguyên thứ tự truyền vào.

const roll = ['Chi', 'Dũng'];
console.log(roll.unshift('Bình'));
console.log(roll);
console.log(roll.unshift('An', 'Ái'));
console.log(roll);
console.log(['Lớp trưởng', ...roll]);
console.log(roll.length);

Kết quả

roll.unshift('Bình') → 3
roll → [ 'Bình', 'Chi', 'Dũng' ]
roll.unshift('An', 'Ái') → 5
roll → [ 'An', 'Ái', 'Bình', 'Chi', 'Dũng' ]
['Lớp trưởng', ...roll] → [ 'Lớp trưởng', 'An', 'Ái', 'Bình', 'Chi', 'Dũng' ]
roll.length → 5

Tham số & trả về

cacPhanTu: một hoặc nhiều giá trị
Trả về: độ dài mới của mảng

Lưu ý

- Cũng chậm với mảng lớn như `shift()`
- Cách không sửa mảng gốc: `[moi, ...arr]`

`arr.flat(doSau)` trải phẳng các mảng lồng nhau thành một mảng mới, theo độ sâu chỉ định (mặc định 1 cấp). Dùng `Infinity` để làm phẳng mọi tầng. Đồng thời loại bỏ các ô trống.

const groups = ['An', ['Bình', ['Chi', ['Dũng']]]];
console.log(groups.flat());
console.log(groups.flat(2));
console.log(groups.flat(Infinity));
console.log(['An', , 'Chi'].flat());
console.log([['An', 'Bình'], ['Chi', 'Dũng']].flat());
console.log(groups);

Kết quả

groups.flat() → [ 'An', 'Bình', [ 'Chi', [ 'Dũng' ] ] ]
groups.flat(2) → [ 'An', 'Bình', 'Chi', [ 'Dũng' ] ]
groups.flat(Infinity) → [ 'An', 'Bình', 'Chi', 'Dũng' ]
['An', , 'Chi'].flat() → [ 'An', 'Chi' ]
[['An', 'Bình'], ['Chi', 'Dũng']].flat() → [ 'An', 'Bình', 'Chi', 'Dũng' ]
groups → [ 'An', [ 'Bình', [ 'Chi', [ 'Dũng' ] ] ] ]

Tham số & trả về

doSau: số tầng cần làm phẳng, mặc định 1
Trả về: mảng mới

Lưu ý

- Chỉ làm phẳng mảng, không chạm vào object bên trong
- Vừa `map` vừa làm phẳng một tầng: dùng `flatMap()`

`arr.find(callback)` trả về phần tử ĐẦU TIÊN khiến callback trả về truthy, hoặc `undefined` nếu không có. Dừng ngay khi tìm thấy nên nhanh hơn `filter()[0]`. Dùng để lấy một đối tượng theo điều kiện, ví dụ theo `id`.

const students = [
  { id: 1, name: 'An', score: 9 },
  { id: 2, name: 'Bình', score: 4 },
  { id: 3, name: 'Chi', score: 7 },
];
console.log(students.find((s) => s.id === 2));
console.log(students.find((s) => s.score < 3));
console.log(students.find((s) => s.score < 8)?.name);
console.log([4, 9, 6].find((s) => s >= 8));
console.log(students.filter((s) => s.score < 8).length);

Kết quả

students.find((s) => s.id === 2) → { id: 2, name: 'Bình', score: 4 }
students.find((s) => s.score < 3) → undefined
students.find((s) => s.score < 8)?.name → 'Bình'
[4, 9, 6].find((s) => s >= 8) → 9
students.filter((s) => s.score < 8).length → 2

Tham số & trả về

callback(phanTu, chiSo, mang): điều kiện cần thỏa
Trả về: phần tử đầu tiên khớp, hoặc `undefined`

Lưu ý

- Kiểm tra kết quả trước khi dùng, hoặc dùng `?.`, vì có thể là `undefined`
- Cần biết vị trí dùng `findIndex()`; chỉ cần biết có hay không dùng `some()`

`arr.findIndex(callback)` trả về chỉ số của phần tử đầu tiên khiến callback trả về truthy, hoặc `-1` nếu không có. Khác `indexOf()` ở chỗ nhận một điều kiện thay vì một giá trị, nên dùng được với object. Thường dùng để tìm vị trí cần cập nhật hoặc xóa.

const students = [{ id: 7 }, { id: 9 }, { id: 4 }];
console.log(students.findIndex((s) => s.id === 9));
console.log(students.findIndex((s) => s.id === 100));
console.log([4, 9, 6].findIndex((s) => s >= 8));
const i = students.findIndex((s) => s.id === 7);
if (i !== -1) students.splice(i, 1);
console.log(students);

Kết quả

students.findIndex((s) => s.id === 9) → 1
students.findIndex((s) => s.id === 100) → -1
[4, 9, 6].findIndex((s) => s >= 8) → 1
students → [ { id: 9 }, { id: 4 } ]

Tham số & trả về

callback: điều kiện cần thỏa
Trả về: chỉ số hoặc `-1`

Lưu ý

- Luôn kiểm tra `-1` trước khi dùng chỉ số
- Tìm từ cuối về đầu dùng `findLastIndex()`

`arr.indexOf(giaTri, tuViTri)` trả về chỉ số của lần xuất hiện đầu tiên của giá trị (so sánh nghiêm ngặt `===`), hoặc `-1`. Với object chỉ so sánh tham chiếu. Có `lastIndexOf()` tìm từ cuối. Không tìm được `NaN`; dùng `includes()` cho trường hợp đó.

const roll = ['An', 'Bình', 'Chi', 'Bình'];
console.log(roll.indexOf('Bình'));
console.log(roll.indexOf('Bình', 2));
console.log(roll.lastIndexOf('Bình'));
console.log(roll.indexOf('Dũng'));
console.log([NaN].indexOf(NaN));
console.log([8, 9, 7].indexOf('9'));
const an = { name: 'An' };
console.log([an].indexOf({ name: 'An' }), [an].indexOf(an));

Kết quả

roll.indexOf('Bình') → 1
roll.indexOf('Bình', 2) → 3
roll.lastIndexOf('Bình') → 3
roll.indexOf('Dũng') → -1
[NaN].indexOf(NaN) → -1
[8, 9, 7].indexOf('9') → -1
[an].indexOf({ name: 'An' }), [an].indexOf(an) → -1 0

Tham số & trả về

giaTri: giá trị cần tìm (so sánh `===`)
tuViTri: chỉ số bắt đầu tìm
Trả về: chỉ số hoặc `-1`

Lưu ý

- Chỉ cần biết có hay không thì dùng `includes()` rõ ý hơn
- Tìm object theo thuộc tính cần `findIndex()`

`arr.includes(giaTri, tuViTri)` trả về `true` nếu mảng chứa giá trị, dùng so sánh "SameValueZero" nên tìm được cả `NaN` (khác `indexOf`). Cách chuẩn để kiểm tra phần tử có trong danh sách, ví dụ `['a','b'].includes(x)` thay cho chuỗi `x === 'a' || x === 'b'`.

const clubs = ['robot', 'chess', 'music'];
console.log(clubs.includes('chess'));
console.log(clubs.includes('art'));
console.log([NaN].includes(NaN));
console.log([8, 9, 7].includes('9'));
console.log(clubs.includes('chess', 2));
const permissions = ['view', 'edit'];
const isAllowed = (action) => permissions.includes(action);
console.log(isAllowed('edit'), isAllowed('delete'));

Kết quả

clubs.includes('chess') → true
clubs.includes('art') → false
[NaN].includes(NaN) → true
[8, 9, 7].includes('9') → false
clubs.includes('chess', 2) → false
isAllowed('edit'), isAllowed('delete') → true false

Tham số & trả về

giaTri: giá trị cần tìm
tuViTri: chỉ số bắt đầu tìm
Trả về: `true` hoặc `false`

Lưu ý

- Với object chỉ so sánh tham chiếu; kiểm tra theo điều kiện dùng `some()`
- Tìm trong tập hợp lớn nhiều lần nên đổi sang `Set` để tra cứu nhanh hơn

`arr.some(callback)` trả về `true` ngay khi có ít nhất một phần tử khiến callback trả về truthy, và dừng duyệt luôn (đoản mạch). Trên mảng rỗng luôn trả về `false`. Là cách ngắn gọn để hỏi "có phần tử nào thỏa không".

const scores = [4, 6, 9, 3];
console.log(scores.some((s) => s >= 9));
console.log(scores.some((s) => s > 10));
console.log([].some((s) => true));
const members = [{ name: 'An', monitor: false }, { name: 'Bình', monitor: true }];
console.log(members.some((m) => m.monitor));
let calls = 0;
[1, 2, 3, 4].some((n) => {
  calls++;
  return n === 2;
});
console.log(calls);

Kết quả

scores.some((s) => s >= 9) → true
scores.some((s) => s > 10) → false
[].some((s) => true) → false
members.some((m) => m.monitor) → true
calls → 2

Tham số & trả về

callback: điều kiện cần thỏa
Trả về: `true` nếu có ít nhất một phần tử thỏa, ngược lại `false`

Lưu ý

- Dừng sớm khi tìm thấy, nên dùng được thay `forEach` khi cần thoát sớm
- Hỏi "tất cả đều thỏa không" dùng `every()`

`arr.every(callback)` trả về `true` nếu MỌI phần tử đều khiến callback trả về truthy, và dừng ngay khi gặp phần tử đầu tiên không đạt. Trên mảng rỗng trả về `true` (đúng với mọi phần tử vì không có phần tử nào vi phạm).

console.log([8, 9, 7].every((s) => s >= 5));
console.log([8, 9, 4].every((s) => s >= 5));
console.log([].every((s) => false));
const form = [{ name: 'fullName', valid: true }, { name: 'age', valid: false }];
console.log(form.every((field) => field.valid));
console.log(['An', 'Bình'].every((n) => typeof n === 'string'));

Kết quả

[8, 9, 7].every((s) => s >= 5) → true
[8, 9, 4].every((s) => s >= 5) → false
[].every((s) => false) → true
form.every((field) => field.valid) → false
['An', 'Bình'].every((n) => typeof n === 'string') → true

Tham số & trả về

callback: điều kiện cần thỏa
Trả về: `true` nếu mọi phần tử thỏa, ngược lại `false`

Lưu ý

- Mảng rỗng cho `true`: nhớ kiểm tra riêng trường hợp mảng rỗng nếu cần
- Phủ định của `every(p)` là `some(!p)`

`arr.sort(soSanh)` sắp xếp mảng TẠI CHỖ và trả về chính mảng đó. Không truyền hàm so sánh thì mọi phần tử bị chuyển thành chuỗi rồi so theo thứ tự mã, nên `[10, 9, 1].sort()` ra `[1, 10, 9]`. Với số và object luôn cần hàm so sánh `(a, b) => ...` trả về số âm (a đứng trước), 0 (giữ nguyên) hoặc dương (b đứng trước). Thuật toán ổn định (giữ thứ tự tương đối của phần tử bằng nhau).

const absences = [10, 9, 1, 100];
console.log([...absences].sort());
console.log([...absences].sort((a, b) => a - b));
console.log([...absences].sort((a, b) => b - a));
const students = [{ name: 'Chi', age: 16 }, { name: 'An', age: 15 }, { name: 'Bình', age: 16 }];
const byAge = students.sort((x, y) => x.age - y.age || x.name.localeCompare(y.name));
console.log(byAge.map((s) => s.name));
console.log(['Đào', 'Anh', 'Ân'].sort((a, b) => a.localeCompare(b, 'vi')));
const original = [3, 1, 2];
const sorted = original.sort();
console.log(original === sorted);

Kết quả

[...absences].sort() → [ 1, 10, 100, 9 ]
[...absences].sort((a, b) => a - b) → [ 1, 9, 10, 100 ]
[...absences].sort((a, b) => b - a) → [ 100, 10, 9, 1 ]
byAge.map((s) => s.name) → [ 'An', 'Bình', 'Chi' ]
['Đào', 'Anh', 'Ân'].sort((a, b) => a.localeCompare(b, 'vi')) → [ 'Anh', 'Ân', 'Đào' ]
original === sorted → true

Tham số & trả về

soSanh(a, b): số âm nếu `a` đứng trước, dương nếu `b` đứng trước, 0 nếu bằng nhau
Trả về: chính mảng đã sắp xếp (cùng tham chiếu)

Lưu ý

- `sort` sửa mảng gốc; để giữ gốc dùng `toSorted()` hoặc `[...arr].sort()`
- Sắp xếp chuỗi có dấu dùng `localeCompare`, không dùng `<`
- Đừng dùng `sort(() => Math.random() - 0.5)` để xáo trộn: kết quả không đều

`arr.concat(...cacGiaTri)` tạo mảng mới bằng cách nối mảng hiện tại với các mảng hoặc giá trị truyền vào; mảng đối số được trải ra một tầng. Ngày nay cú pháp spread `[...a, ...b]` thường được ưa chuộng hơn vì linh hoạt và dễ đọc.

console.log(['An', 'Bình'].concat(['Chi', 'Dũng']));
console.log(['An'].concat('Bình', ['Chi'], [['Dũng']]));
console.log(['An', 'Bình'].concat('Chi', { club: 'robot' }));
console.log([...['An', 'Bình'], ...['Chi', 'Dũng'], 'Em']);
const roll = ['An'];
console.log(roll.concat(['Bình']) === roll);

Kết quả

['An', 'Bình'].concat(['Chi', 'Dũng']) → [ 'An', 'Bình', 'Chi', 'Dũng' ]
['An'].concat('Bình', ['Chi'], [['Dũng']]) → [ 'An', 'Bình', 'Chi', [ 'Dũng' ] ]
['An', 'Bình'].concat('Chi', { club: 'robot' }) → [ 'An', 'Bình', 'Chi', { club: 'robot' } ]
[...['An', 'Bình'], ...['Chi', 'Dũng'], 'Em'] → [ 'An', 'Bình', 'Chi', 'Dũng', 'Em' ]
roll.concat(['Bình']) === roll → false

Tham số & trả về

cacGiaTri: mảng hoặc giá trị cần nối
Trả về: mảng mới

Lưu ý

- Mảng lồng bên trong không bị trải thêm; dùng `flat()` nếu cần
- Không đổi mảng gốc

`arr.join(phanCach)` nối các phần tử thành một chuỗi, ngăn cách bằng `phanCach` (mặc định dấu phẩy). Phần tử `null` và `undefined` thành chuỗi rỗng. Là phép ngược của `str.split()`; dùng để dựng CSV, đường dẫn, câu liệt kê.

console.log(['An', 'Bình', 'Chi'].join());
console.log(['An', 'Bình', 'Chi'].join(''));
console.log(['An', 'Bình', 'Chi'].join(' - '));
console.log([8, null, undefined, 9].join('|'));
console.log([[1, 2], [3]].join(';'));
console.log(['2025', '09', '05'].join('-'));
console.log([].join(','));

Kết quả

['An', 'Bình', 'Chi'].join() → 'An,Bình,Chi'
['An', 'Bình', 'Chi'].join('') → 'AnBìnhChi'
['An', 'Bình', 'Chi'].join(' - ') → 'An - Bình - Chi'
[8, null, undefined, 9].join('|') → '8|||9'
[[1, 2], [3]].join(';') → '1,2;3'
['2025', '09', '05'].join('-') → '2025-09-05'
[].join(',') → ''

Tham số & trả về

phanCach: chuỗi ngăn cách, mặc định `','`
Trả về: chuỗi

Lưu ý

- Mảng lồng được chuyển thành chuỗi bằng `toString()` nên cho kết quả phẳng
- Ghép nhiều mảnh chuỗi trong vòng lặp nhanh hơn dùng `+=` lặp lại

`arr.reverse()` đảo ngược thứ tự phần tử TẠI CHỖ và trả về chính mảng đó. Muốn giữ nguyên mảng gốc dùng `toReversed()` (ES2023) hoặc sao chép trước bằng `[...arr].reverse()`.

const queue = ['An', 'Bình', 'Chi'];
console.log(queue.reverse());
console.log(queue);
console.log(['An', 'Bình', 'Chi'].toReversed());
const roll = ['An', 'Bình', 'Chi'];
console.log([...roll].reverse());
console.log(roll);
console.log('lớp'.split('').reverse().join(''));

Kết quả

queue.reverse() → [ 'Chi', 'Bình', 'An' ]
queue → [ 'Chi', 'Bình', 'An' ]
['An', 'Bình', 'Chi'].toReversed() → [ 'Chi', 'Bình', 'An' ]
[...roll].reverse() → [ 'Chi', 'Bình', 'An' ]
roll → [ 'An', 'Bình', 'Chi' ]
'lớp'.split('').reverse().join('') → 'pớl'

Tham số & trả về

Không có tham số
Trả về: chính mảng đã đảo

Lưu ý

- Đảo chuỗi: `split('').reverse().join('')` (không đúng với ký tự gồm nhiều đơn vị)
- `toReversed()` có từ ES2023

`Array.isArray(giaTri)` trả về `true` nếu giá trị là mảng. Đây là cách kiểm tra đáng tin cậy vì `typeof` trả về `'object'` cho mảng, còn `instanceof Array` sai khi mảng đến từ iframe hoặc realm khác. Object "giống mảng" (có `length`, `arguments`, `NodeList`) không phải mảng thật.

console.log(Array.isArray([]));
console.log(Array.isArray(['An', 'Bình']));
console.log(Array.isArray({ length: 0 }));
console.log(Array.isArray('An'));
console.log(Array.isArray(new Array(3)));
console.log(Array.isArray(Array.prototype));
console.log(typeof []);
console.log(Array.isArray(undefined));

Kết quả

Array.isArray([]) → true
Array.isArray(['An', 'Bình']) → true
Array.isArray({ length: 0 }) → false
Array.isArray('An') → false
Array.isArray(new Array(3)) → true
Array.isArray(Array.prototype) → true
typeof [] → 'object'
Array.isArray(undefined) → false

Tham số & trả về

giaTri: giá trị cần kiểm tra
Trả về: `true` hoặc `false`

Lưu ý

- Chuyển object giống mảng thành mảng thật bằng `Array.from()`
- Typed array (`Uint8Array`...) không phải mảng: `Array.isArray` trả về `false`

Nhóm lấy phần của chuỗi (chuỗi là bất biến nên luôn trả chuỗi hoặc mảng mới): `slice(batDau, ketThuc)` (hỗ trợ chỉ số âm), `substring(batDau, ketThuc)` (tự hoán đổi nếu đảo ngược, không nhận số âm), `split(ngan)` (cắt thành mảng theo dấu phân cách). Ưu tiên `slice` vì hành vi dễ đoán hơn.

const s = 'Chào mừng lớp 10A1 đến trường';
console.log(s.slice(0, 5), s.slice(-8), s.slice(6, -10));
console.log(s.substring(8, 4), s.slice(8, 4));
console.log(s.split(' '), 'An,Bình,,Chi'.split(','), 'An'.split(''));
console.log('2025-09-05'.split('-', 2));

Kết quả

s.slice(0, 5), s.slice(-8), s.slice(6, -10) → 'Chào ' 'n trường' 'ừng lớp 10A1 '
s.substring(8, 4), s.slice(8, 4) → ' mừn' ''
s.split(' '), 'An,Bình,,Chi'.split(','), 'An'.split('') →
  [ 'Chào', 'mừng', 'lớp', '10A1', 'đến', 'trường' ] [ 'An', 'Bình', '', 'Chi' ] [ 'A', 'n' ]
'2025-09-05'.split('-', 2) → [ '2025', '09' ]

Lưu ý

- `slice(8, 4)` cho chuỗi rỗng, còn `substring(8, 4)` tự đổi chỗ thành `substring(4, 8)`
- `split` nhận thêm giới hạn số phần tử

`chuoi.slice(batDau, ketThuc)` trả về chuỗi con từ vị trí `batDau` đến trước `ketThuc` (không lấy ký tự tại `ketThuc`). Hỗ trợ chỉ số âm đếm từ cuối chuỗi, bỏ qua `ketThuc` thì cắt đến hết. Là phương thức cắt chuỗi nên dùng mặc định thay cho `substring()` và `substr()`.

const fullName = 'Nguyễn Văn An';
console.log(fullName.slice(0, 6));
console.log(fullName.slice(7));
console.log(fullName.slice(-6));
console.log(fullName.slice(-6, -3));
console.log(fullName.slice(5, 2));
console.log(fullName);

Kết quả

fullName.slice(0, 6) → 'Nguyễn'
fullName.slice(7) → 'Văn An'
fullName.slice(-6) → 'Văn An'
fullName.slice(-6, -3) → 'Văn'
fullName.slice(5, 2) → ''
fullName → 'Nguyễn Văn An'

Tham số & trả về

batDau: vị trí bắt đầu (lấy); số âm đếm từ cuối
ketThuc: vị trí kết thúc (không lấy), mặc định hết chuỗi
Trả về: chuỗi con mới; chuỗi gốc không đổi

Lưu ý

- Nếu `batDau` lớn hơn hoặc bằng `ketThuc`, kết quả là chuỗi rỗng (khác `substring()`, vốn tự hoán đổi)
- Cũng có `arr.slice()` cho mảng với cùng quy tắc

`chuoi.substring(batDau, ketThuc)` giống `slice()` nhưng quy tắc khác ở hai điểm: số âm được coi là 0 và nếu `batDau` lớn hơn `ketThuc` thì hai giá trị tự hoán đổi. Vì hành vi dễ gây bất ngờ, đa số hướng dẫn khuyên dùng `slice()`. Phương thức `substr(batDau, doDai)` cũ nhận độ dài thay vì vị trí cuối và đã bị coi là lỗi thời.

const fullName = 'Nguyễn Văn An';
console.log(fullName.substring(0, 6));
console.log(fullName.substring(5, 2));
console.log(fullName.slice(5, 2));
console.log(fullName.substring(-3, 6));
console.log(fullName.slice(-3, 6));

Kết quả

fullName.substring(0, 6) → 'Nguyễn'
fullName.substring(5, 2) → 'uyễ'
fullName.slice(5, 2) → ''
fullName.substring(-3, 6) → 'Nguyễn'
fullName.slice(-3, 6) → ''

Tham số & trả về

batDau, ketThuc: vị trí; số âm và `NaN` thành 0, số lớn hơn độ dài thành độ dài
Trả về: chuỗi con mới

Lưu ý

- Tránh `substr()`; nó nằm trong phần "legacy" của đặc tả
- Dùng `slice()` để có hành vi nhất quán với mảng

`chuoi.split(phanCach, gioiHan)` tách chuỗi thành mảng các chuỗi con tại mỗi vị trí gặp dấu phân cách. Dấu phân cách có thể là chuỗi hoặc biểu thức chính quy; phân cách rỗng `''` tách từng đơn vị UTF-16. Là phép ngược của `arr.join()`, rất hay dùng để xử lý CSV đơn giản, đường dẫn và từ trong câu.

console.log('An,Bình,Chi'.split(','));
console.log('An Bình  Chi'.split(' '));
console.log('An Bình  Chi'.split(/\s+/));
console.log('An'.split(''));
console.log('An,Bình,Chi,Dũng'.split(',', 2));
console.log('Chi'.split(','));
console.log(''.split(','));
console.log('Toán-Văn_Anh'.split(/[-_]/));
console.log('Lớp10Phòng2'.split(/(\d+)/));

Kết quả

'An,Bình,Chi'.split(',') → [ 'An', 'Bình', 'Chi' ]
'An Bình  Chi'.split(' ') → [ 'An', 'Bình', '', 'Chi' ]
'An Bình  Chi'.split(/\s+/) → [ 'An', 'Bình', 'Chi' ]
'An'.split('') → [ 'A', 'n' ]
'An,Bình,Chi,Dũng'.split(',', 2) → [ 'An', 'Bình' ]
'Chi'.split(',') → [ 'Chi' ]
''.split(',') → [ '' ]
'Toán-Văn_Anh'.split(/[-_]/) → [ 'Toán', 'Văn', 'Anh' ]
'Lớp10Phòng2'.split(/(\d+)/) → [ 'Lớp', '10', 'Phòng', '2', '' ]

Tham số & trả về

phanCach: chuỗi hoặc regex; bỏ qua thì trả về mảng một phần tử là cả chuỗi
gioiHan: số phần tử tối đa của mảng kết quả
Trả về: mảng chuỗi

Lưu ý

- Regex có nhóm bắt `( )` sẽ chèn cả phần phân cách vào kết quả
- `''.split(',')` ra `['']` chứ không phải mảng rỗng
- Tách từng ký tự thật (kể cả biểu tượng) dùng `[...chuoi]`, không dùng `split('')`

`chuoi.trim()` loại bỏ mọi khoảng trắng (dấu cách, tab, xuống dòng, ký tự trắng Unicode) ở đầu và cuối chuỗi, giữ nguyên khoảng trắng ở giữa. Nên dùng ngay với dữ liệu người dùng nhập vào form trước khi kiểm tra hoặc lưu.

console.log('  Chào cả lớp  '.trim());
console.log('  An  Bình  '.trim());
console.log('\n\t  Bài tập \n'.trim());
console.log('   '.trim() === '');
console.log('An'.trim());
const typed = '  an@school.edu.vn ';
console.log(typed.trim().length);

Kết quả

'  Chào cả lớp  '.trim() → 'Chào cả lớp'
'  An  Bình  '.trim() → 'An  Bình'
'\n\t  Bài tập \n'.trim() → 'Bài tập'
'   '.trim() === '' → true
'An'.trim() → 'An'
typed.trim().length → 16

Tham số & trả về

Không có tham số
Trả về: chuỗi mới đã bỏ khoảng trắng đầu cuối

Lưu ý

- Chỉ cắt đầu và cuối; để gộp nhiều khoảng trắng ở giữa dùng `replace(/\s+/g, ' ')`
- Kiểm tra "ô nhập rỗng" nên dùng `chuoi.trim() === ''`

`chuoi.includes(timKiem, viTri)` trả về `true` nếu chuỗi chứa đoạn cần tìm, phân biệt hoa thường. Dễ đọc hơn `indexOf(...) !== -1`. Không nhận biểu thức chính quy (truyền regex sẽ ném `TypeError`); với regex hãy dùng `regex.test()`.

const note = 'Học sinh giỏi môn Toán';
console.log(note.includes('Toán'));
console.log(note.includes('toán'));
console.log(note.toLowerCase().includes('toán'));
console.log(note.includes('giỏi', 12));
console.log(note.includes(''));
try {
  note.includes(/Toán/);
} catch (e) {
  console.log(e.name);
}

Kết quả

note.includes('Toán') → true
note.includes('toán') → false
note.toLowerCase().includes('toán') → true
note.includes('giỏi', 12) → false
note.includes('') → true
e.name → 'TypeError'

Tham số & trả về

timKiem: chuỗi cần tìm
viTri: vị trí bắt đầu tìm, mặc định 0
Trả về: `true` hoặc `false`

Lưu ý

- Muốn không phân biệt hoa thường thì chuyển cả hai vế về chữ thường trước
- Tìm trong mảng dùng `arr.includes()`, tìm khóa trong object dùng `in` hoặc `Object.hasOwn()`

`chuoi.indexOf(timKiem, viTri)` trả về vị trí xuất hiện đầu tiên của đoạn cần tìm, hoặc `-1` nếu không có. Dùng khi bạn cần biết vị trí (để cắt chuỗi, đếm số lần xuất hiện), còn chỉ cần biết có hay không thì dùng `includes()`.

const s = 'Hà Nội, Hà Nam, Hà Giang';
console.log(s.indexOf('Hà'));
console.log(s.indexOf('Hà', 2));
console.log(s.indexOf('Nam'));
console.log(s.indexOf('x'));
console.log(s.indexOf(''));
let count = 0;
let i = s.indexOf('Hà');
while (i !== -1) {
  count++;
  i = s.indexOf('Hà', i + 1);
}
console.log(count);

Kết quả

s.indexOf('Hà') → 0
s.indexOf('Hà', 2) → 8
s.indexOf('Nam') → 11
s.indexOf('x') → -1
s.indexOf('') → 0
count → 3

Tham số & trả về

timKiem: chuỗi cần tìm (phân biệt hoa thường)
viTri: vị trí bắt đầu tìm
Trả về: chỉ số hoặc `-1`

Lưu ý

- Kiểm tra bằng `=== -1` hoặc `>= 0`, đừng dùng `if (s.indexOf(x))` vì vị trí 0 là falsy
- `lastIndexOf()` tìm từ cuối chuỗi về đầu

`chuoi.startsWith(tienTo, viTri)` trả về `true` nếu chuỗi bắt đầu bằng đoạn chỉ định (bắt đầu kiểm tra từ `viTri` nếu có). Rõ ràng hơn `chuoi.indexOf(x) === 0` hoặc `chuoi.slice(0, n) === x`. Thường dùng để kiểm tra giao thức URL, tiền tố đường dẫn hay lệnh.

const url = 'https://truonghoc.edu.vn/lop-10a1';
console.log(url.startsWith('https://'));
console.log(url.startsWith('http://'));
console.log(url.startsWith('truonghoc', 8));
console.log('Lớp 10A1'.startsWith('lớp'));
console.log('abc'.startsWith(''));

Kết quả

url.startsWith('https://') → true
url.startsWith('http://') → false
url.startsWith('truonghoc', 8) → true
'Lớp 10A1'.startsWith('lớp') → false
'abc'.startsWith('') → true

Tham số & trả về

tienTo: chuỗi cần kiểm tra ở đầu
viTri: vị trí bắt đầu so khớp, mặc định 0
Trả về: `true` hoặc `false`

Lưu ý

- Phân biệt hoa thường; không nhận regex
- Chuỗi rỗng luôn là tiền tố hợp lệ

`chuoi.endsWith(hauTo, doDai)` trả về `true` nếu chuỗi kết thúc bằng đoạn chỉ định. Tham số `doDai` coi như chuỗi chỉ dài đến đó. Phù hợp để kiểm tra phần mở rộng tên file hoặc đuôi tên miền.

const file = 'bang-diem-10a1.xlsx';
console.log(file.endsWith('.xlsx'));
console.log(file.endsWith('.pdf'));
console.log(file.endsWith('bang', 4));
console.log('truonghoc.edu.vn'.endsWith('.edu.vn'));
console.log('abc'.endsWith(''));

Kết quả

file.endsWith('.xlsx') → true
file.endsWith('.pdf') → false
file.endsWith('bang', 4) → true
'truonghoc.edu.vn'.endsWith('.edu.vn') → true
'abc'.endsWith('') → true

Tham số & trả về

hauTo: chuỗi cần kiểm tra ở cuối
doDai: coi chuỗi chỉ gồm `doDai` ký tự đầu, mặc định toàn chuỗi
Trả về: `true` hoặc `false`

Lưu ý

- Phân biệt hoa thường: dùng `toLowerCase()` trước nếu cần bỏ qua hoa thường
- Kiểm tra phần mở rộng nên chuyển về chữ thường rồi mới so sánh

`chuoi.replace(mau, thayThe)` trả về chuỗi mới trong đó lần khớp đầu tiên của `mau` được thay bằng `thayThe`. `mau` là chuỗi (chỉ thay lần đầu) hoặc regex (thêm cờ `g` để thay mọi lần). `thayThe` có thể là chuỗi (hỗ trợ `$1`, `$&`) hoặc hàm nhận phần khớp rồi trả về giá trị thay thế.

console.log('Toán-Văn-Anh'.replace('-', '+'));
console.log('Toán-Văn-Anh'.replace(/-/g, '+'));
console.log('Nguyễn An'.replace(/(\S+) (\S+)/, '$2 $1'));
console.log('điểm 8 và 9'.replace(/\d+/g, (n) => n * 10));
console.log('xin chao ca lop'.replace(/\b\w/g, (c) => c.toUpperCase()));
console.log('An.Bình'.replace('.', '!'));
const original = 'An';
original.replace('A', 'B');
console.log(original);

Kết quả

'Toán-Văn-Anh'.replace('-', '+') → 'Toán+Văn-Anh'
'Toán-Văn-Anh'.replace(/-/g, '+') → 'Toán+Văn+Anh'
'Nguyễn An'.replace(/(\S+) (\S+)/, '$2 $1') → 'An Nguyễn'
'điểm 8 và 9'.replace(/\d+/g, (n) => n * 10) → 'điểm 80 và 90'
'xin chao ca lop'.replace(/\b\w/g, (c) => c.toUpperCase()) → 'Xin Chao Ca Lop'
'An.Bình'.replace('.', '!') → 'An!Bình'
original → 'An'

Tham số & trả về

mau: chuỗi hoặc regex cần tìm
thayThe: chuỗi (có `$1`, `$&`, `$<ten>`) hoặc hàm `(phanKhop, ...nhom) => chuoi`
Trả về: chuỗi mới; chuỗi gốc không đổi

Lưu ý

- Với `mau` là chuỗi, chỉ thay lần đầu; muốn thay tất cả dùng `replaceAll()` hoặc regex `/.../g`
- Ký tự `$` trong chuỗi thay thế có nghĩa đặc biệt; dùng hàm khi chuỗi thay thế đến từ người dùng
- `\w` và `\b` chỉ hiểu chữ ASCII: với chữ có dấu tiếng Việt hãy dùng cờ `u` và `\p{L}`

`chuoi.replaceAll(mau, thayThe)` thay mọi lần xuất hiện của `mau`, không cần regex cho trường hợp chuỗi thường. Nếu `mau` là regex thì bắt buộc có cờ `g`, nếu không sẽ ném `TypeError`. Có từ ES2021.

console.log('Toán-Văn-Anh-Sử'.replaceAll('-', ''));
console.log('2025.09.05'.replaceAll('.', '/'));
console.log('em chào cô, em chào thầy'.replaceAll('em', 'con'));
console.log('aaa'.replaceAll(/a/g, (m, i) => i));
try {
  'aaa'.replaceAll(/a/, 'b');
} catch (e) {
  console.log(e.name);
}

Kết quả

'Toán-Văn-Anh-Sử'.replaceAll('-', '') → 'ToánVănAnhSử'
'2025.09.05'.replaceAll('.', '/') → '2025/09/05'
'em chào cô, em chào thầy'.replaceAll('em', 'con') → 'con chào cô, con chào thầy'
'aaa'.replaceAll(/a/g, (m, i) => i) → '012'
e.name → 'TypeError'

Tham số & trả về

mau: chuỗi hoặc regex có cờ `g`
thayThe: chuỗi hoặc hàm, giống `replace()`
Trả về: chuỗi mới

Lưu ý

- Với chuỗi thường, không cần thoát ký tự đặc biệt của regex như `.` hay `*`
- Trình duyệt hoặc Node.js cũ có thể chưa hỗ trợ; dùng `replace(/.../g, ...)` thay thế

`chuoi.toUpperCase()` trả về chuỗi mới với mọi chữ cái chuyển thành chữ hoa, theo quy tắc Unicode chuẩn (xử lý đúng chữ có dấu tiếng Việt). Có `toLocaleUpperCase(locale)` khi cần quy tắc riêng của một ngôn ngữ, ví dụ tiếng Thổ Nhĩ Kỳ với chữ `i`.

console.log('lớp 10a1'.toUpperCase());
console.log('Hà Nội đẹp'.toUpperCase());
console.log('straße'.toUpperCase());
console.log('i'.toLocaleUpperCase('tr'));
const name = 'an';
console.log(name[0].toUpperCase() + name.slice(1));

Kết quả

'lớp 10a1'.toUpperCase() → 'LỚP 10A1'
'Hà Nội đẹp'.toUpperCase() → 'HÀ NỘI ĐẸP'
'straße'.toUpperCase() → 'STRASSE'
'i'.toLocaleUpperCase('tr') → 'İ'
name[0].toUpperCase() + name.slice(1) → 'An'

Tham số & trả về

Không có tham số
Trả về: chuỗi mới viết hoa; chuỗi gốc không đổi

Lưu ý

- Một số ký tự đổi độ dài khi viết hoa (`'ß'` thành `'SS'`)
- Viết hoa chữ cái đầu: ghép `chuoi[0].toUpperCase()` với `chuoi.slice(1)`

`chuoi.toLowerCase()` trả về chuỗi mới với mọi chữ cái chuyển thành chữ thường. Thường dùng để chuẩn hóa dữ liệu trước khi so sánh hoặc tìm kiếm không phân biệt hoa thường (email, tên người dùng, từ khóa). Có `toLocaleLowerCase(locale)` cho quy tắc theo ngôn ngữ.

console.log('LỚP 10A1'.toLowerCase());
const typedEmail = 'An@School.EDU.VN';
console.log(typedEmail.toLowerCase());
console.log('Lớp 10A1'.toLowerCase() === 'lớp 10a1');
const keyword = 'giỏi';
console.log('Học Sinh Giỏi'.toLowerCase().includes(keyword));
console.log('İ'.toLowerCase().length);

Kết quả

'LỚP 10A1'.toLowerCase() → 'lớp 10a1'
typedEmail.toLowerCase() → 'an@school.edu.vn'
'Lớp 10A1'.toLowerCase() === 'lớp 10a1' → true
'Học Sinh Giỏi'.toLowerCase().includes(keyword) → true
'İ'.toLowerCase().length → 2

Tham số & trả về

Không có tham số
Trả về: chuỗi mới viết thường

Lưu ý

- So sánh không phân biệt hoa thường tốt nhất nên chuẩn hóa cả hai vế, hoặc dùng `localeCompare` với `sensitivity: 'base'`
- Chuẩn hóa tiếng Việt còn cần `normalize('NFC')` để dấu ở dạng nhất quán

`chuoi.padStart(doDaiDich, kyTuDem)` thêm ký tự vào đầu chuỗi cho đủ độ dài đích, mặc định thêm dấu cách. Cách chuẩn để hiển thị số có chữ số 0 đứng đầu (giờ, ngày, mã đơn hàng) hoặc căn phải văn bản trong bảng. Nếu chuỗi đã đủ dài thì giữ nguyên.

console.log('7'.padStart(3, '0'));
console.log(String(5).padStart(2, '0'));
const hour = 7;
const minute = 5;
console.log(`${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`);
console.log('abc'.padStart(2, '0'));
console.log('ab'.padStart(7, '12'));
console.log('5'.padStart(4));

Kết quả

'7'.padStart(3, '0') → '007'
String(5).padStart(2, '0') → '05'
07:05
'abc'.padStart(2, '0') → 'abc'
'ab'.padStart(7, '12') → '12121ab'
'5'.padStart(4) → '   5'

Tham số & trả về

doDaiDich: độ dài mong muốn của chuỗi kết quả
kyTuDem: chuỗi dùng để đệm, mặc định `' '`; lặp lại và cắt cho vừa
Trả về: chuỗi mới

Lưu ý

- Chỉ áp dụng cho chuỗi; chuyển số sang chuỗi trước bằng `String(n)`
- Đệm số âm hoặc số thực cần xử lý dấu và phần thập phân trước

`chuoi.repeat(soLan)` trả về chuỗi mới gồm `soLan` bản sao nối liền nhau. Dùng để vẽ đường kẻ trong console, tạo thụt đầu dòng hoặc sinh dữ liệu mẫu. `soLan` là 0 cho chuỗi rỗng; số âm hoặc vô cực ném `RangeError`.

console.log('ab'.repeat(3));
console.log('='.repeat(10));
console.log('x'.repeat(0) === '');
console.log('  '.repeat(2) + 'thụt hai cấp');
try {
  'a'.repeat(-1);
} catch (e) {
  console.log(e.name);
}

Kết quả

'ab'.repeat(3) → 'ababab'
'='.repeat(10) → '=========='
'x'.repeat(0) === '' → true
'  '.repeat(2) + 'thụt hai cấp' → '    thụt hai cấp'
e.name → 'RangeError'

Tham số & trả về

soLan: số lần lặp, số nguyên không âm
Trả về: chuỗi mới

Lưu ý

- Số lần lặp phần thập phân bị cắt: `'a'.repeat(2.9)` ra `'aa'`
- Chuỗi kết quả quá dài (vượt giới hạn bộ nhớ) cũng ném `RangeError`

Thuộc tính `length` cho biết số đơn vị UTF-16 của chuỗi. Với chữ cái thông thường đó là số ký tự, nhưng ký tự ngoài mặt phẳng cơ bản (nhiều biểu tượng, một số chữ hiếm) chiếm hai đơn vị. Chuỗi rỗng có độ dài 0 và `length` không sửa được.

console.log('Hà Nội'.length);
console.log(''.length);
console.log('An'.length);
console.log('\u{1F600}'.length);
console.log([...'\u{1F600}'].length);
const name = 'An';
name.length = 10;
console.log(name.length);

Kết quả

'Hà Nội'.length → 6
''.length → 0
'An'.length → 2
'\u{1F600}'.length → 2
[...'\u{1F600}'].length → 1
name.length → 2

Lưu ý

- Gán vào `length` của chuỗi bị bỏ qua vì chuỗi bất biến
- Đếm đúng số ký tự thật cần `[...chuoi].length` hoặc `Intl.Segmenter`
- Dấu cách và ký tự xuống dòng cũng được tính

`Object.keys(obj)` trả về mảng các khóa chuỗi riêng và đếm được của object, theo thứ tự đã nói ở trên. Không bao gồm khóa kế thừa hay khóa symbol. Là cách chuẩn để duyệt object bằng các phương thức mảng, và để kiểm tra object rỗng.

const student = { name: 'An', age: 15 };
console.log(Object.keys(student));
console.log(Object.keys(student).length);
console.log(Object.keys({}).length === 0);
console.log(Object.keys(['An', 'Bình']));
console.log(Object.keys('An'));
const inherited = Object.create({ school: 'THPT A' });
inherited.own = 2;
console.log(Object.keys(inherited));
for (const k of Object.keys(student)) console.log(`${k} = ${student[k]}`);

Kết quả

Object.keys(student) → [ 'name', 'age' ]
Object.keys(student).length → 2
Object.keys({}).length === 0 → true
Object.keys(['An', 'Bình']) → [ '0', '1' ]
Object.keys('An') → [ '0', '1' ]
Object.keys(inherited) → [ 'own' ]
name = An
age = 15

Tham số & trả về

obj: object cần liệt kê
Trả về: mảng chuỗi

Lưu ý

- Kiểm tra object rỗng: `Object.keys(obj).length === 0`
- Muốn cả giá trị dùng `Object.entries()`; cả khóa symbol dùng `Reflect.ownKeys()`

`Object.values(obj)` trả về mảng giá trị của các thuộc tính riêng đếm được, cùng thứ tự với `Object.keys()`. Tiện để tính tổng, tìm lớn nhất hoặc lọc các giá trị mà không cần quan tâm khóa.

const scores = { math: 8, literature: 7, english: 9 };
console.log(Object.values(scores));
console.log(Object.values(scores).reduce((a, b) => a + b, 0));
console.log(Math.max(...Object.values(scores)));
console.log(Object.values('An'));
console.log(Object.values([5, 6]));
console.log(Object.values({}));

Kết quả

Object.values(scores) → [ 8, 7, 9 ]
Object.values(scores).reduce((a, b) => a + b, 0) → 24
Math.max(...Object.values(scores)) → 9
Object.values('An') → [ 'A', 'n' ]
Object.values([5, 6]) → [ 5, 6 ]
Object.values({}) → []

Tham số & trả về

obj: object cần lấy giá trị
Trả về: mảng giá trị

Lưu ý

- Giá trị object lồng vẫn là tham chiếu, không sao chép
- Kết hợp với `Object.keys()` thông qua `Object.entries()` khi cần cả hai

`Object.entries(obj)` trả về mảng các cặp `[khoa, giaTri]` của thuộc tính riêng đếm được. Kết hợp với destructuring trong `for...of` để duyệt cả khóa và giá trị, hoặc với `map`/`filter` để biến đổi object (rồi `Object.fromEntries()` để quay về object).

const fees = { math: 100, english: 120 };
console.log(Object.entries(fees));
for (const [subject, fee] of Object.entries(fees)) {
  console.log(`${subject}: ${fee}`);
}
console.log(Object.entries(fees).map(([k, v]) => `${k}=${v}`).join('&'));
console.log(new Map(Object.entries(fees)));
console.log(Object.entries(['An', 'Bình']));
console.log(Object.entries({}).length);

Kết quả

Object.entries(fees) → [ [ 'math', 100 ], [ 'english', 120 ] ]
math: 100
english: 120
Object.entries(fees).map(([k, v]) => `${k}=${v}`).join('&') → 'math=100&english=120'
new Map(Object.entries(fees)) → Map(2) { 'math' => 100, 'english' => 120 }
Object.entries(['An', 'Bình']) → [ [ '0', 'An' ], [ '1', 'Bình' ] ]
Object.entries({}).length → 0

Tham số & trả về

obj: object cần liệt kê
Trả về: mảng các cặp `[khoa, giaTri]`

Lưu ý

- Đảo chiều: `Object.fromEntries()`
- Chuyển object sang `Map`: `new Map(Object.entries(obj))`

`Object.fromEntries(cacCap)` dựng object từ một iterable các cặp `[khoa, giaTri]` (mảng cặp, `Map`...). Là phép ngược của `Object.entries()`, nên kết hợp cả hai với `map`/`filter` cho phép biến đổi object một cách gọn gàng.

console.log(Object.fromEntries([['An', 8], ['Bình', 6]]));
console.log(Object.fromEntries(new Map([['Toán', 9], ['Văn', 7]])));
const fees = { math: 100, literature: 80, english: 120 };
const discounted = Object.fromEntries(Object.entries(fees).map(([k, v]) => [k, v * 0.5]));
console.log(discounted);
const cheap = Object.fromEntries(Object.entries(fees).filter(([, v]) => v < 110));
console.log(cheap);
console.log(Object.fromEntries(new URLSearchParams('class=10A1&room=12')));

Kết quả

Object.fromEntries([['An', 8], ['Bình', 6]]) → { An: 8, 'Bình': 6 }
Object.fromEntries(new Map([['Toán', 9], ['Văn', 7]])) → { 'Toán': 9, 'Văn': 7 }
discounted → { math: 50, literature: 40, english: 60 }
cheap → { math: 100, literature: 80 }
Object.fromEntries(new URLSearchParams('class=10A1&room=12')) → { class: '10A1', room: '12' }

Tham số & trả về

cacCap: iterable các cặp `[khoa, giaTri]`
Trả về: object mới

Lưu ý

- Khóa trùng: giá trị cuối cùng thắng
- Có từ ES2019

`Object.assign(dich, ...nguon)` sao chép các thuộc tính riêng đếm được từ mỗi nguồn vào `dich` (theo thứ tự, nguồn sau ghi đè nguồn trước) và trả về chính `dich`. Nó SỬA `dich`, nên để tạo bản mới hãy dùng `{}` làm đích hoặc cú pháp spread `{ ...a, ...b }`. Là sao chép nông.

const a = { name: 'An', age: 15 };
const b = { age: 16, city: 'Hà Nội' };
const merged = Object.assign({}, a, b);
console.log(merged);
console.log(a);
const target = { name: 'Bình' };
const returned = Object.assign(target, { name: 'Chi' });
console.log(returned === target, target);
console.log({ ...a, ...b, city: 'ghi đè' });
const classInfo = { teacher: { name: 'Cô Lan' } };
const shallow = Object.assign({}, classInfo);
shallow.teacher.name = 'Thầy Hải';
console.log(classInfo.teacher.name);

Kết quả

merged → { name: 'An', age: 16, city: 'Hà Nội' }
a → { name: 'An', age: 15 }
returned === target, target → true { name: 'Chi' }
{ ...a, ...b, city: 'ghi đè' } → { name: 'An', age: 16, city: 'ghi đè' }
classInfo.teacher.name → 'Thầy Hải'

Tham số & trả về

dich: object nhận thuộc tính (bị sửa)
nguon: một hoặc nhiều object nguồn
Trả về: chính `dich`

Lưu ý

- Không sao chép thuộc tính kế thừa hay không đếm được, và gọi getter/setter chứ không sao chép chúng
- Spread `{ ...a }` làm cùng việc gọn hơn và không sửa object nào
- Cần sao chép sâu: `structuredClone()`

`Object.freeze(obj)` đóng băng object: không thêm, xóa, hay đổi giá trị thuộc tính nào và không đổi được cờ thuộc tính. Chỉ có tác dụng một tầng; object lồng bên trong vẫn sửa được. `Object.isFrozen(obj)` kiểm tra trạng thái. Với mảng đóng băng, các phương thức sửa như `push` ném `TypeError`.

const config = Object.freeze({ mode: 'dev', year: 2025, teacher: { name: 'Cô Lan' } });
config.mode = 'prod';
config.extra = 1;
delete config.year;
console.log(config);
config.teacher.name = 'Thầy Hải';
console.log(config.teacher.name);
console.log(Object.isFrozen(config), Object.isFrozen(config.teacher));
const names = Object.freeze(['An', 'Bình']);
try {
  names.push('Chi');
} catch (e) {
  console.log(e.name);
}
const deepFreeze = (o) => {
  Object.values(o).forEach((v) => typeof v === 'object' && v !== null && deepFreeze(v));
  return Object.freeze(o);
};
console.log(Object.isFrozen(deepFreeze({ klass: { teacher: 'Cô Lan' } }).klass));

Kết quả

config → { mode: 'dev', year: 2025, teacher: { name: 'Cô Lan' } }
config.teacher.name → 'Thầy Hải'
Object.isFrozen(config), Object.isFrozen(config.teacher) → true false
e.name → 'TypeError'
Object.isFrozen(deepFreeze({ klass: { teacher: 'Cô Lan' } }).klass) → true

Tham số & trả về

obj: object cần đóng băng
Trả về: chính `obj`

Lưu ý

- Ở chế độ thường các thao tác vi phạm bị bỏ qua im lặng; ở strict mode chúng ném `TypeError`
- Đóng băng sâu cần đệ quy như ví dụ cuối
- Chống việc xóa hoặc thêm nhưng vẫn cho đổi giá trị: dùng `Object.seal()`

`Object.hasOwn(obj, khoa)` trả về `true` nếu object có thuộc tính riêng với khóa đó, không tính thuộc tính kế thừa. Là cách thay thế an toàn và ngắn gọn cho `obj.hasOwnProperty(khoa)`, vì hoạt động cả với object tạo bằng `Object.create(null)` và không bị che bởi thuộc tính trùng tên.

const student = { name: 'An', nickname: undefined };
console.log(Object.hasOwn(student, 'name'));
console.log(Object.hasOwn(student, 'nickname'));
console.log(Object.hasOwn(student, 'age'));
console.log(Object.hasOwn(student, 'toString'));
console.log('toString' in student);
const dictionary = Object.create(null);
dictionary.An = 8;
console.log(Object.hasOwn(dictionary, 'An'));
console.log(Object.hasOwn(['An', 'Bình'], 1));

Kết quả

Object.hasOwn(student, 'name') → true
Object.hasOwn(student, 'nickname') → true
Object.hasOwn(student, 'age') → false
Object.hasOwn(student, 'toString') → false
'toString' in student → true
Object.hasOwn(dictionary, 'An') → true
Object.hasOwn(['An', 'Bình'], 1) → true

Tham số & trả về

obj: object cần kiểm tra
khoa: khóa chuỗi hoặc symbol
Trả về: `true` hoặc `false`

Lưu ý

- Có từ ES2022; thay thế `Object.prototype.hasOwnProperty.call(obj, khoa)`
- `in` bao gồm cả thuộc tính kế thừa, còn `hasOwn` thì không

`so.toFixed(soChuSoLe)` làm tròn số tới số chữ số thập phân chỉ định và trả về một CHUỖI, thêm số 0 ở cuối nếu cần. Dùng để hiển thị giá tiền, phần trăm, điểm. Vì trả về chuỗi nên cần `Number()` hoặc dấu `+` nếu muốn dùng tiếp trong phép tính.

console.log((8.33333).toFixed(2));
console.log((8).toFixed(1));
console.log((1.005).toFixed(2));
console.log((7.5).toFixed(0));
console.log(typeof (8.5).toFixed(1));
console.log(+(8.256).toFixed(2) * 2);
console.log((1500.5678).toFixed(1));
console.log((-1.5).toFixed(0));

Kết quả

(8.33333).toFixed(2) → '8.33'
(8).toFixed(1) → '8.0'
(1.005).toFixed(2) → '1.00'
(7.5).toFixed(0) → '8'
typeof (8.5).toFixed(1) → 'string'
+(8.256).toFixed(2) * 2 → 16.52
(1500.5678).toFixed(1) → '1500.6'
(-1.5).toFixed(0) → '-2'

Tham số & trả về

soChuSoLe: số chữ số sau dấu thập phân, từ 0 đến 100, mặc định 0
Trả về: chuỗi

Lưu ý

- Do sai số số thực, `(1.005).toFixed(2)` ra `'1.00'` chứ không phải `'1.01'`
- Dùng `Intl.NumberFormat` hoặc `toLocaleString()` để thêm dấu phân cách hàng nghìn
- Gọi trên số nguyên viết thẳng cần ngoặc hoặc hai dấu chấm: `(5).toFixed(2)`, `5..toFixed(2)`

`parseInt(chuoi, coSo)` đọc phần số nguyên ở đầu chuỗi theo cơ số chỉ định và bỏ qua mọi thứ phía sau, nên đọc được `'12px'` hay `'42 tuổi'`. Nếu ký tự đầu không phải chữ số hợp lệ thì trả về `NaN`. Luôn nên truyền cơ số (thường 10) để kết quả không phụ thuộc quy tắc tự đoán.

console.log(parseInt('15'));
console.log(parseInt('8.5'));
console.log(parseInt('10A1'));
console.log(parseInt('A10'));
console.log(parseInt('ff', 16));
console.log(parseInt('1010', 2));
console.log(parseInt('  9  '));
console.log(parseInt(''));
console.log(['8', '9', '7'].map(parseInt));
console.log(['8', '9', '7'].map((x) => parseInt(x, 10)));

Kết quả

parseInt('15') → 15
parseInt('8.5') → 8
parseInt('10A1') → 10
parseInt('A10') → NaN
parseInt('ff', 16) → 255
parseInt('1010', 2) → 10
parseInt('  9  ') → 9
parseInt('') → NaN
['8', '9', '7'].map(parseInt) → [ 8, NaN, NaN ]
['8', '9', '7'].map((x) => parseInt(x, 10)) → [ 8, 9, 7 ]

Tham số & trả về

chuoi: giá trị cần đọc, nếu không phải chuỗi sẽ được chuyển thành chuỗi
coSo: cơ số từ 2 đến 36; bỏ qua thì mặc định 10 (hoặc 16 nếu chuỗi bắt đầu `0x`)
Trả về: số nguyên, hoặc `NaN`

Lưu ý

- `arr.map(parseInt)` cho kết quả sai vì `map` truyền cả chỉ số làm cơ số; hãy bọc bằng hàm mũi tên
- Muốn đọc cả số thực dùng `parseFloat()`; muốn kiểm tra chuỗi hoàn toàn là số dùng `Number()`

`parseFloat(chuoi)` đọc số thực ở đầu chuỗi (có thể có phần thập phân và phần mũ) và bỏ qua phần còn lại. Chỉ nhận cơ số 10. Trả về `NaN` nếu ký tự đầu không đọc được thành số.

console.log(parseFloat('8.5'));
console.log(parseFloat('8.5 điểm'));
console.log(parseFloat('.5'));
console.log(parseFloat('1e3'));
console.log(parseFloat('điểm 8.5'));
console.log(parseFloat('-0.5 điểm'));
console.log(parseFloat('8,5'));
console.log(parseFloat('10') === Number('10'));

Kết quả

parseFloat('8.5') → 8.5
parseFloat('8.5 điểm') → 8.5
parseFloat('.5') → 0.5
parseFloat('1e3') → 1000
parseFloat('điểm 8.5') → NaN
parseFloat('-0.5 điểm') → -0.5
parseFloat('8,5') → 8
parseFloat('10') === Number('10') → true

Tham số & trả về

chuoi: giá trị cần đọc
Trả về: số thực hoặc `NaN`

Lưu ý

- Dấu phẩy thập phân kiểu Việt `'8,5'` chỉ đọc được phần `8`; đổi dấu phẩy sang dấu chấm trước
- `Number.parseFloat === parseFloat` (cùng một hàm), không có khác biệt

`Number.isInteger(giaTri)` trả về `true` nếu giá trị là một số và không có phần thập phân. Không ép kiểu: chuỗi `'5'` bị coi là không phải số nguyên. `5.0` là số nguyên vì trong JavaScript nó chính là `5`.

console.log(Number.isInteger(30));
console.log(Number.isInteger(30.0));
console.log(Number.isInteger(7.5));
console.log(Number.isInteger('30'));
console.log(Number.isInteger(NaN));
console.log(Number.isInteger(Infinity));
console.log(Number.isInteger(2 ** 53));

Kết quả

Number.isInteger(30) → true
Number.isInteger(30.0) → true
Number.isInteger(7.5) → false
Number.isInteger('30') → false
Number.isInteger(NaN) → false
Number.isInteger(Infinity) → false
Number.isInteger(2 ** 53) → true

Tham số & trả về

giaTri: giá trị cần kiểm tra
Trả về: `true` hoặc `false`

Lưu ý

- Kiểm tra số nguyên đủ lớn có an toàn không thì dùng `Number.isSafeInteger()`
- Để kiểm tra chuỗi là số nguyên, dùng `Number.isInteger(Number(chuoi))` kèm kiểm tra chuỗi không rỗng

`Number.isNaN(giaTri)` trả về `true` chỉ khi giá trị thật sự là `NaN`, không ép kiểu. Khác với hàm toàn cục `isNaN()` vốn ép sang số trước nên cho kết quả sai với chuỗi chữ. Vì `NaN !== NaN`, đây là cách đáng tin cậy để phát hiện kết quả phép tính hỏng.

console.log(Number.isNaN(NaN));
console.log(Number.isNaN(0 / 0));
console.log(Number.isNaN('chưa chấm'));
console.log(isNaN('chưa chấm'));
console.log(Number.isNaN(undefined));
console.log(isNaN(undefined));
const score = Number('9 điểm');
console.log(Number.isNaN(score) ? 'đầu vào không hợp lệ' : score);

Kết quả

Number.isNaN(NaN) → true
Number.isNaN(0 / 0) → true
Number.isNaN('chưa chấm') → false
isNaN('chưa chấm') → true
Number.isNaN(undefined) → false
isNaN(undefined) → true
Number.isNaN(score) ? 'đầu vào không hợp lệ' : score → 'đầu vào không hợp lệ'

Tham số & trả về

giaTri: giá trị cần kiểm tra
Trả về: `true` hoặc `false`

Lưu ý

- Luôn ưu tiên `Number.isNaN()` hơn `isNaN()`
- Muốn bao gồm cả `Infinity` khi kiểm tra "số hợp lệ" dùng `Number.isFinite()`

`so.toString(coSo)` chuyển số thành chuỗi theo cơ số từ 2 đến 36 (mặc định 10). Là cách chuẩn để đổi sang nhị phân, thập lục phân (màu, byte) và cơ số 36 (mã ngắn). Phép ngược là `parseInt(chuoi, coSo)`.

const studentId = 255;
console.log(studentId.toString());
console.log(studentId.toString(2));
console.log(studentId.toString(16));
console.log(studentId.toString(16).toUpperCase().padStart(4, '0'));
console.log((35).toString(36));
console.log((0.5).toString(2));
console.log(parseInt('ff', 16));
console.log((-studentId).toString(16));

Kết quả

studentId.toString() → '255'
studentId.toString(2) → '11111111'
studentId.toString(16) → 'ff'
studentId.toString(16).toUpperCase().padStart(4, '0') → '00FF'
(35).toString(36) → 'z'
(0.5).toString(2) → '0.1'
parseInt('ff', 16) → 255
(-studentId).toString(16) → '-ff'

Tham số & trả về

coSo: số nguyên từ 2 đến 36
Trả về: chuỗi

Lưu ý

- Gọi trên số viết thẳng cần ngoặc: `(255).toString(16)`
- Với `BigInt`, `toString(coSo)` hoạt động tương tự và không mất chính xác

`Math` là đối tượng có sẵn chứa các hằng số (`Math.PI`, `Math.E`) và hàm toán học: làm tròn, lũy thừa, căn, logarit, lượng giác, số ngẫu nhiên, lớn nhất/nhỏ nhất. Không phải constructor nên không viết `new Math()`; mọi thành viên đều là thuộc tính tĩnh. Chỉ làm việc với kiểu `number` (không dùng được với `BigInt`).

console.log(Math.PI);
console.log(Math.E);
console.log(Math.SQRT2);
console.log(Math.max(7, 9, 5));
console.log(Math.round(8.5), Math.floor(8.9), Math.ceil(8.1), Math.trunc(-2.9));
console.log(Math.abs(-7), Math.sqrt(16), Math.pow(2, 5));
console.log(typeof Math);

Kết quả

Math.PI → 3.141592653589793
Math.E → 2.718281828459045
Math.SQRT2 → 1.4142135623730951
Math.max(7, 9, 5) → 9
Math.round(8.5), Math.floor(8.9), Math.ceil(8.1), Math.trunc(-2.9) → 9 8 9 -2
Math.abs(-7), Math.sqrt(16), Math.pow(2, 5) → 7 4 32
typeof Math → 'object'

Lưu ý

- Hàm lượng giác dùng radian: đổi từ độ bằng `do * Math.PI / 180`
- Các hàm riêng lẻ nằm ở các mục con bên dưới

`Math.round(x)` làm tròn đến số nguyên gần nhất. Với phần thập phân đúng 0.5 nó làm tròn về phía dương vô cực (2.5 thành 3, nhưng -2.5 thành -2), khác với cách làm tròn "ra xa số 0" quen thuộc. Làm tròn tới số chữ số lẻ tùy ý bằng cách nhân, làm tròn rồi chia.

console.log(Math.round(8.4));
console.log(Math.round(8.5));
console.log(Math.round(-2.5));
console.log(Math.round(-2.6));
console.log(Math.round(1.005 * 100) / 100);
console.log(Math.round(8.3333 * 100) / 100);
console.log(Math.round('7.6'));
console.log(Math.round(null));

Kết quả

Math.round(8.4) → 8
Math.round(8.5) → 9
Math.round(-2.5) → -2
Math.round(-2.6) → -3
Math.round(1.005 * 100) / 100 → 1
Math.round(8.3333 * 100) / 100 → 8.33
Math.round('7.6') → 8
Math.round(null) → 0

Tham số & trả về

x: số cần làm tròn (tham số khác số sẽ bị ép sang số)
Trả về: số nguyên gần nhất

Lưu ý

- Làm tròn tới 2 chữ số lẻ kiểu `Math.round(x * 100) / 100` vẫn có thể sai do số thực nhị phân
- Muốn chuỗi có đúng 2 chữ số lẻ dùng `toFixed(2)`

`Math.floor(x)` làm tròn xuống số nguyên nhỏ hơn hoặc bằng `x`, tức là hướng về âm vô cực. Với số dương nó bỏ phần thập phân, nhưng với số âm kết quả nhỏ hơn: `Math.floor(-2.1)` là `-3`. Thường dùng để lấy chỉ số, tính trang, và sinh số nguyên ngẫu nhiên.

console.log(Math.floor(2.9));
console.log(Math.floor(2));
console.log(Math.floor(-2.1));
console.log(Math.trunc(-2.1));
console.log(Math.floor(7 / 2));
const totalStudents = 47;
const perPage = 10;
console.log(Math.floor((totalStudents - 1) / perPage) + 1);

Kết quả

Math.floor(2.9) → 2
Math.floor(2) → 2
Math.floor(-2.1) → -3
Math.trunc(-2.1) → -2
Math.floor(7 / 2) → 3
Math.floor((totalStudents - 1) / perPage) + 1 → 5

Tham số & trả về

x: số cần làm tròn
Trả về: số nguyên lớn nhất không vượt quá `x`

Lưu ý

- Với số âm, `floor` khác `trunc`: `trunc` luôn bỏ phần thập phân, `floor` luôn đi xuống
- Chia lấy phần nguyên: `Math.floor(a / b)`

`Math.ceil(x)` làm tròn lên số nguyên nhỏ nhất lớn hơn hoặc bằng `x`. Cần dùng để tính số trang, số hộp, số lượt khi dù chỉ dư một phần nhỏ cũng cần thêm một đơn vị đầy đủ.

console.log(Math.ceil(2.1));
console.log(Math.ceil(2));
console.log(Math.ceil(-2.9));
console.log(Math.ceil(47 / 10));
console.log(Math.ceil(0.0001));
const students = 25;
const perTable = 4;
console.log(Math.ceil(students / perTable));

Kết quả

Math.ceil(2.1) → 3
Math.ceil(2) → 2
Math.ceil(-2.9) → -2
Math.ceil(47 / 10) → 5
Math.ceil(0.0001) → 1
Math.ceil(students / perTable) → 7

Tham số & trả về

x: số cần làm tròn
Trả về: số nguyên nhỏ nhất không nhỏ hơn `x`

Lưu ý

- `Math.ceil(-0.5)` ra `-0`, in ra như `0` nhưng `Object.is(-0, 0)` là `false`
- Tính số trang: `Math.ceil(totalStudents / perPage)`

`Math.random()` trả về số thực giả ngẫu nhiên trong khoảng từ 0 (có thể bằng) đến 1 (không bao giờ bằng). Từ đó suy ra số nguyên ngẫu nhiên trong khoảng bằng `Math.floor(Math.random() * (max - min + 1)) + min`. Không an toàn cho mật mã (token, mật khẩu): dùng `crypto.getRandomValues()` hoặc `crypto.randomUUID()`.

const x = Math.random();
console.log(x >= 0 && x < 1);
const randomScore = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
const samples = Array.from({ length: 1000 }, () => randomScore(5, 10));
console.log(Math.min(...samples), Math.max(...samples));
console.log(samples.every((n) => Number.isInteger(n)));
const roll = ['An', 'Bình', 'Chi', 'Dũng'];
const picked = roll[Math.floor(Math.random() * roll.length)];
console.log(roll.includes(picked));

Kết quả

x >= 0 && x < 1 → true
Math.min(...samples), Math.max(...samples) → 5 10
samples.every((n) => Number.isInteger(n)) → true
roll.includes(picked) → true

Tham số & trả về

Không có tham số
Trả về: số thực trong `[0, 1)`

Lưu ý

- Kết quả ngẫu nhiên nên ví dụ chỉ kiểm tra tính chất (khoảng giá trị), không in giá trị cụ thể
- Không dùng cho mã bảo mật; `Math.random()` không thể gieo hạt (seed) để tái lập kết quả
- Xáo trộn mảng đúng cách dùng thuật toán Fisher-Yates, đừng dùng `sort(() => Math.random() - 0.5)`

`Math.max(...cacSo)` trả về số lớn nhất trong các đối số, và `-Infinity` nếu không truyền gì. Không nhận mảng trực tiếp: dùng spread `Math.max(...mang)` hoặc `Math.max.apply(null, mang)`. Trả về `NaN` nếu một đối số không chuyển được sang số.

console.log(Math.max(7, 9, 5));
console.log(Math.max());
console.log(Math.max(-1, -5));
console.log(Math.max(1, 'abc'));
const scores = [7, 9, 4, 8];
console.log(Math.max(...scores));
console.log(Math.max(...scores, 10));
console.log(scores.reduce((a, b) => Math.max(a, b), -Infinity));

Kết quả

Math.max(7, 9, 5) → 9
Math.max() → -Infinity
Math.max(-1, -5) → -1
Math.max(1, 'abc') → NaN
Math.max(...scores) → 9
Math.max(...scores, 10) → 10
scores.reduce((a, b) => Math.max(a, b), -Infinity) → 9

Tham số & trả về

cacSo: không hoặc nhiều số
Trả về: số lớn nhất, `-Infinity` nếu không có đối số

Lưu ý

- Với mảng rất lớn (hàng trăm nghìn phần tử), spread có thể vượt giới hạn số đối số; dùng `reduce()`
- Tìm đối tượng có giá trị lớn nhất dùng `reduce` hoặc sắp xếp, không dùng `Math.max`

`Math.min(...cacSo)` trả về số nhỏ nhất, và `Infinity` nếu không có đối số. Kết hợp `Math.min` với `Math.max` cho phép "kẹp" một giá trị vào khoảng cho phép (clamp), thường dùng khi giới hạn thanh trượt, số lượng, tọa độ.

console.log(Math.min(7, 9, 5));
console.log(Math.min());
console.log(Math.min(...[7, 2, 8]));
const clamp = (x, low, high) => Math.min(Math.max(x, low), high);
console.log(clamp(15, 0, 10));
console.log(clamp(-5, 0, 10));
console.log(clamp(8, 0, 10));

Kết quả

Math.min(7, 9, 5) → 5
Math.min() → Infinity
Math.min(...[7, 2, 8]) → 2
clamp(15, 0, 10) → 10
clamp(-5, 0, 10) → 0
clamp(8, 0, 10) → 8

Tham số & trả về

cacSo: không hoặc nhiều số
Trả về: số nhỏ nhất, `Infinity` nếu không có đối số

Lưu ý

- Clamp viết là `Math.min(Math.max(x, thap), cao)`; CSS có hàm `clamp()` tương tự
- Một đối số `NaN` làm cả kết quả thành `NaN`

`Math.abs(x)` trả về giá trị tuyệt đối của số: bỏ dấu âm. Dùng để tính khoảng cách (hiệu hai số không phân biệt thứ tự) và để so sánh hai số thực với một khoảng sai số.

console.log(Math.abs(-5));
console.log(Math.abs(5));
console.log(Math.abs(-0));
console.log(Math.abs('-3'));
console.log(Math.abs(null));
console.log(Math.abs(undefined));
const gap = (a, b) => Math.abs(a - b);
console.log(gap(3, 10), gap(10, 3));
console.log(Math.abs(0.1 + 0.2 - 0.3) < 1e-9);

Kết quả

Math.abs(-5) → 5
Math.abs(5) → 5
Math.abs(-0) → 0
Math.abs('-3') → 3
Math.abs(null) → 0
Math.abs(undefined) → NaN
gap(3, 10), gap(10, 3) → 7 7
Math.abs(0.1 + 0.2 - 0.3) < 1e-9 → true

Tham số & trả về

x: số cần lấy giá trị tuyệt đối
Trả về: số không âm

Lưu ý

- `Math.abs(undefined)` ra `NaN`
- So sánh số thực bằng `Math.abs(a - b) < Number.EPSILON` hoặc ngưỡng sai số riêng

`Math.pow(co, mu)` trả về `co` mũ `mu`. Toán tử `**` (ES2016) làm cùng việc và ngắn gọn hơn, hỗ trợ cả `BigInt`. Hỗ trợ số mũ âm (nghịch đảo) và số mũ thập phân (căn).

console.log(Math.pow(2, 10));
console.log(2 ** 10);
console.log(Math.pow(2, -1));
console.log(Math.pow(9, 0.5));
console.log(Math.pow(0, 0));
console.log(Math.pow(-8, 1 / 3));
console.log(Math.cbrt(-8));
const laiKep = 1000 * Math.pow(1 + 0.05, 3);
console.log(laiKep.toFixed(2));

Kết quả

Math.pow(2, 10) → 1024
2 ** 10 → 1024
Math.pow(2, -1) → 0.5
Math.pow(9, 0.5) → 3
Math.pow(0, 0) → 1
Math.pow(-8, 1 / 3) → NaN
Math.cbrt(-8) → -2
laiKep.toFixed(2) → '1157.63'

Tham số & trả về

co: cơ số
mu: số mũ
Trả về: kết quả lũy thừa

Lưu ý

- Căn bậc ba của số âm dùng `Math.cbrt()`, không dùng mũ `1/3`
- Dùng `**` trong code mới; `Math.pow` chỉ cần khi truyền hàm như callback

`Math.sqrt(x)` trả về căn bậc hai của `x`, hoặc `NaN` nếu `x` âm (số thực không có căn bậc hai của số âm). Dùng trong công thức khoảng cách, độ lệch chuẩn; riêng khoảng cách hai điểm nên dùng `Math.hypot()` cho gọn và tránh tràn số.

console.log(Math.sqrt(16));
console.log(Math.sqrt(2));
console.log(Math.sqrt(0));
console.log(Math.sqrt(-4));
console.log(Math.sqrt(1e300 * 1e300));
console.log(Math.hypot(3, 4));
console.log(Math.sqrt(3 ** 2 + 4 ** 2));

Kết quả

Math.sqrt(16) → 4
Math.sqrt(2) → 1.4142135623730951
Math.sqrt(0) → 0
Math.sqrt(-4) → NaN
Math.sqrt(1e300 * 1e300) → Infinity
Math.hypot(3, 4) → 5
Math.sqrt(3 ** 2 + 4 ** 2) → 5

Tham số & trả về

x: số không âm
Trả về: căn bậc hai, hoặc `NaN` nếu `x < 0`

Lưu ý

- Kiểm tra số chính phương: `Number.isInteger(Math.sqrt(n))`
- Căn bậc `n` tổng quát dùng `x ** (1 / n)`

`new Date()` cho thời điểm hiện tại; `new Date(timestamp)` từ số mili giây; `new Date(chuoi)` từ chuỗi (ISO 8601 như `'2024-03-15T10:30:00Z'` là định dạng đáng tin cậy nhất); `new Date(nam, thang, ngay, gio, phut, giay, ms)` từ các phần theo GIỜ ĐỊA PHƯƠNG, trong đó tháng bắt đầu từ 0. Chuỗi ngày không đúng chuẩn cho kết quả khác nhau giữa trình duyệt. Chuỗi không hợp lệ cho `Invalid Date`.

console.log(new Date(0).toISOString());
console.log(new Date(1710498645000).toISOString());
console.log(new Date('2024-03-15').toISOString());
console.log(new Date('2024-03-15T10:30:00Z').toISOString());
console.log(new Date('2024-03-15T10:30:00+07:00').toISOString());
console.log(new Date(Date.UTC(2024, 11, 25, 8, 0)).toISOString());
console.log(new Date(Date.UTC(2024, 1, 30)).toISOString());
console.log(Number.isNaN(new Date('15/03/2024').getTime()));
const sao = new Date(new Date('2024-03-15T00:00:00Z'));
console.log(sao.toISOString());
console.log(typeof new Date(), typeof Date());

Kết quả

new Date(0).toISOString() → '1970-01-01T00:00:00.000Z'
new Date(1710498645000).toISOString() → '2024-03-15T10:30:45.000Z'
new Date('2024-03-15').toISOString() → '2024-03-15T00:00:00.000Z'
new Date('2024-03-15T10:30:00Z').toISOString() → '2024-03-15T10:30:00.000Z'
new Date('2024-03-15T10:30:00+07:00').toISOString() → '2024-03-15T03:30:00.000Z'
new Date(Date.UTC(2024, 11, 25, 8, 0)).toISOString() → '2024-12-25T08:00:00.000Z'
new Date(Date.UTC(2024, 1, 30)).toISOString() → '2024-03-01T00:00:00.000Z'
Number.isNaN(new Date('15/03/2024').getTime()) → true
sao.toISOString() → '2024-03-15T00:00:00.000Z'
typeof new Date(), typeof Date() → 'object' 'string'

Lưu ý

- Chuỗi chỉ có ngày (`'2024-03-15'`) được hiểu là UTC, còn chuỗi có giờ mà không có múi giờ (`'2024-03-15T10:00'`) được hiểu là giờ địa phương
- Ngày vượt phạm vi tự tràn sang tháng sau: 30/2 thành 1/3 hoặc 2/3
- Gọi `Date()` không `new` trả về chuỗi, không phải đối tượng

`Date.now()` trả về số mili giây từ epoch đến thời điểm hiện tại, mà không phải tạo đối tượng `Date`. Dùng làm dấu thời gian, đo khoảng thời gian thô và tạo ID đơn giản. Để đo hiệu năng chính xác hơn dùng `performance.now()` (độ phân giải cao, không bị lùi khi đồng hồ hệ thống chỉnh).

const t = Date.now();
console.log(typeof t, Number.isInteger(t));
console.log(t > 1_700_000_000_000);
console.log(new Date(t).getUTCFullYear() >= 2024);
const luc = Date.now();
let tong = 0;
for (let i = 0; i < 1e6; i++) tong += i;
const troiQua = Date.now() - luc;
console.log(troiQua >= 0, troiQua < 5000);
console.log(+new Date() - Date.now() <= 5);
console.log(Math.floor(Date.now() / 1000) === Math.floor(new Date().getTime() / 1000));

Kết quả

typeof t, Number.isInteger(t) → 'number' true
t > 1_700_000_000_000 → true
new Date(t).getUTCFullYear() >= 2024 → true
troiQua >= 0, troiQua < 5000 → true true
+new Date() - Date.now() <= 5 → true
Math.floor(Date.now() / 1000) === Math.floor(new Date().getTime() / 1000) → true

Lưu ý

- Giá trị phụ thuộc đồng hồ hệ thống nên ví dụ chỉ kiểm tra tính chất, không in số cụ thể
- Timestamp theo giây (như nhiều API) bằng `Math.floor(Date.now() / 1000)`

`date.getFullYear()` trả về năm bốn chữ số theo múi giờ địa phương; `getUTCFullYear()` theo UTC. Đừng dùng `getYear()` đã bỏ vì trả về năm trừ 1900. Có cặp ghi `setFullYear(nam, thang?, ngay?)`. Hai biến thể địa phương và UTC chênh nhau khi thời điểm gần lúc giao thừa tùy múi giờ.

const d = new Date('2023-12-31T20:00:00Z');
console.log(d.getUTCFullYear());
const copy = new Date(d);
copy.setUTCFullYear(2030);
console.log(copy.toISOString());
console.log(d.toISOString());
const isLeapYear = (n) => (n % 4 === 0 && n % 100 !== 0) || n % 400 === 0;
console.log(isLeapYear(2024), isLeapYear(1900), isLeapYear(2000));
console.log(new Date(Date.UTC(2024, 1, 29)).getUTCDate());
console.log(2025 - new Date('2010-06-01T00:00:00Z').getUTCFullYear());

Kết quả

d.getUTCFullYear() → 2023
copy.toISOString() → '2030-12-31T20:00:00.000Z'
d.toISOString() → '2023-12-31T20:00:00.000Z'
isLeapYear(2024), isLeapYear(1900), isLeapYear(2000) → true false true
new Date(Date.UTC(2024, 1, 29)).getUTCDate() → 29
2025 - new Date('2010-06-01T00:00:00Z').getUTCFullYear() → 15

Lưu ý

- Ở múi giờ UTC+7, thời điểm `2023-12-31T20:00:00Z` đã là năm 2024 theo `getFullYear()` nhưng vẫn là 2023 theo `getUTCFullYear()`
- Tuổi chính xác cần so sánh cả tháng và ngày, không chỉ trừ năm

`date.getMonth()` trả về chỉ số tháng từ 0 đến 11, nghĩa là tháng 1 là 0 và tháng 12 là 11 (kỳ quặc nhất của `Date`). Luôn nhớ cộng 1 khi hiển thị số tháng. Muốn tên tháng thì dùng `toLocaleDateString` với `{ month: 'long' }` hoặc `Intl.DateTimeFormat` thay vì mảng tự viết. `setMonth` ghi tháng và tự tràn sang năm kế khi vượt 11.

const d = new Date('2024-03-15T00:00:00Z');
console.log(d.getUTCMonth());
console.log(d.getUTCMonth() + 1);
console.log(d.toLocaleDateString('vi-VN', { month: 'long', timeZone: 'UTC' }));
console.log(d.toLocaleDateString('en-US', { month: 'long', timeZone: 'UTC' }));
const sau = new Date(d);
sau.setUTCMonth(sau.getUTCMonth() + 11);
console.log(sau.toISOString());
const cuoiThang = new Date(Date.UTC(2024, 2, 0));
console.log(cuoiThang.getUTCDate());
console.log(new Date(Date.UTC(2023, 1, 29)).toISOString());

Kết quả

d.getUTCMonth() → 2
d.getUTCMonth() + 1 → 3
d.toLocaleDateString('vi-VN', { month: 'long', timeZone: 'UTC' }) → 'Tháng 3'
d.toLocaleDateString('en-US', { month: 'long', timeZone: 'UTC' }) → 'March'
sau.toISOString() → '2025-02-15T00:00:00.000Z'
cuoiThang.getUTCDate() → 29
new Date(Date.UTC(2023, 1, 29)).toISOString() → '2023-03-01T00:00:00.000Z'

Lưu ý

- `new Date(nam, 1, 0)` là ngày cuối của tháng 1; mẹo lấy ngày cuối tháng bằng ngày 0 của tháng kế
- Cộng tháng cuối tháng dễ tràn (31/1 cộng một tháng ra 3/3); cần xử lý riêng

`date.getDate()` trả về ngày trong tháng từ 1 đến 31 (khác `getDay()` là thứ trong tuần). `setDate(n)` đặt ngày và tự tràn: `setDate(getDate() + 30)` cộng 30 ngày, qua tháng và năm chính xác. Cộng bớt ngày cách này đúng theo lịch hơn là cộng số mili giây, vì bỏ qua chuyển giờ mùa hè.

const d = new Date('2024-01-31T00:00:00Z');
console.log(d.getUTCDate());
const plus30 = new Date(d);
plus30.setUTCDate(plus30.getUTCDate() + 30);
console.log(plus30.toISOString().slice(0, 10));
const previousMonth = new Date(d);
previousMonth.setUTCDate(0);
console.log(previousMonth.toISOString().slice(0, 10));
const today = new Date('2024-03-15T00:00:00Z');
const deadline = new Date('2024-04-01T00:00:00Z');
console.log((deadline - today) / 86_400_000);
console.log(new Date(Date.UTC(2024, 0, 32)).toISOString().slice(0, 10));

Kết quả

d.getUTCDate() → 31
plus30.toISOString().slice(0, 10) → '2024-03-01'
previousMonth.toISOString().slice(0, 10) → '2023-12-31'
(deadline - today) / 86_400_000 → 17
new Date(Date.UTC(2024, 0, 32)).toISOString().slice(0, 10) → '2024-02-01'

Lưu ý

- Hiệu hai ngày chia 86.400.000 cho số ngày là gần đúng khi có chuyển giờ mùa hè theo múi giờ địa phương; tính theo UTC để chắc chắn
- Dùng `date-fns` hoặc `Temporal` cho phép tính ngày tháng phức tạp

`date.getDay()` trả về thứ trong tuần từ 0 đến 6, trong đó 0 là Chủ nhật, 1 là thứ Hai, ..., 6 là thứ Bảy. Đừng nhầm với `getDate()` (ngày trong tháng). Để lấy tên thứ theo ngôn ngữ dùng `toLocaleDateString(locale, { weekday: 'long' })`.

const d = new Date('2024-03-17T00:00:00Z');
console.log(d.getUTCDay());
console.log(d.toLocaleDateString('vi-VN', { weekday: 'long', timeZone: 'UTC' }));
console.log(d.toLocaleDateString('en-US', { weekday: 'short', timeZone: 'UTC' }));
const isWeekend = (x) => [0, 6].includes(x.getUTCDay());
console.log(isWeekend(d), isWeekend(new Date('2024-03-18T00:00:00Z')));
const monday = new Date(d);
monday.setUTCDate(monday.getUTCDate() - ((monday.getUTCDay() + 6) % 7));
console.log(monday.toISOString().slice(0, 10));

Kết quả

d.getUTCDay() → 0
d.toLocaleDateString('vi-VN', { weekday: 'long', timeZone: 'UTC' }) → 'Chủ Nhật'
d.toLocaleDateString('en-US', { weekday: 'short', timeZone: 'UTC' }) → 'Sun'
isWeekend(d), isWeekend(new Date('2024-03-18T00:00:00Z')) → true false
monday.toISOString().slice(0, 10) → '2024-03-11'

Lưu ý

- Tuần bắt đầu từ Chủ nhật theo `getDay()`; nhiều nước (cả Việt Nam) coi thứ Hai là đầu tuần nên cần chuyển đổi như ví dụ
- Số `getDay()` phụ thuộc múi giờ lúc gần nửa đêm

`date.getTime()` trả về timestamp tính bằng mili giây (cũng là `date.valueOf()` và `+date`). Cho phép so sánh hai ngày bằng toán tử quan hệ (`a < b`), trừ để ra khoảng cách (`b - a` là số mili giây) nhưng KHÔNG so sánh bằng `===` hai đối tượng `Date` (so tham chiếu); phải so sánh `getTime()`. `Invalid Date` cho `NaN`.

const openDay = new Date('2024-03-15T00:00:00Z');
const sameDay = new Date('2024-03-15T00:00:00Z');
console.log(openDay === sameDay, openDay.getTime() === sameDay.getTime());
console.log(openDay == sameDay, +openDay === +sameDay);
console.log(openDay.getTime());
const examDay = new Date('2024-03-16T12:00:00Z');
console.log(examDay > openDay, examDay - openDay);
console.log((examDay - openDay) / 3_600_000);
console.log([examDay, openDay].sort((x, y) => x - y).map((x) => x.toISOString().slice(0, 10)));
console.log(new Date(NaN).getTime());

Kết quả

openDay === sameDay, openDay.getTime() === sameDay.getTime() → false true
openDay == sameDay, +openDay === +sameDay → false true
openDay.getTime() → 1710460800000
examDay > openDay, examDay - openDay → true 129600000
(examDay - openDay) / 3_600_000 → 36
[examDay, openDay].sort((x, y) => x - y).map((x) => x.toISOString().slice(0, 10)) →
  [ '2024-03-15', '2024-03-16' ]
new Date(NaN).getTime() → NaN

Lưu ý

- Sắp xếp mảng ngày bằng `(x, y) => x - y`
- Kiểm tra ngày hợp lệ bằng `!Number.isNaN(d.getTime())`

`date.toISOString()` trả về chuỗi theo chuẩn ISO 8601 ở UTC với dạng `YYYY-MM-DDTHH:mm:ss.sssZ`. Đây là định dạng tốt nhất để lưu vào cơ sở dữ liệu, truyền qua API và `JSON` (`toJSON()` cũng gọi nó), vì không mơ hồ và sắp xếp được theo chữ cái. Ném `RangeError` với `Invalid Date`. `new Date(chuoiISO)` đọc lại chính xác.

const submittedAt = new Date('2024-03-15T17:30:45.123+07:00');
console.log(submittedAt.toISOString());
console.log(submittedAt.toISOString().slice(0, 10));
console.log(submittedAt.toISOString().slice(11, 19));
console.log(new Date(submittedAt.toISOString()).getTime() === submittedAt.getTime());
console.log(JSON.stringify({ submittedAt }));
console.log(submittedAt.toJSON() === submittedAt.toISOString());
try {
  new Date('hỏng').toISOString();
} catch (e) {
  console.log(e.name);
}
console.log(['2024-03-15', '2023-12-01', '2024-01-20'].sort());

Kết quả

submittedAt.toISOString() → '2024-03-15T10:30:45.123Z'
submittedAt.toISOString().slice(0, 10) → '2024-03-15'
submittedAt.toISOString().slice(11, 19) → '10:30:45'
new Date(submittedAt.toISOString()).getTime() === submittedAt.getTime() → true
JSON.stringify({ submittedAt }) → '{"submittedAt":"2024-03-15T10:30:45.123Z"}'
submittedAt.toJSON() === submittedAt.toISOString() → true
e.name → 'RangeError'
['2024-03-15', '2023-12-01', '2024-01-20'].sort() → [ '2023-12-01', '2024-01-20', '2024-03-15' ]

Lưu ý

- Luôn ở múi giờ UTC (hậu tố `Z`), khác `toString()` theo giờ địa phương
- Chuỗi ISO có cùng độ dài sắp xếp theo thứ tự chữ cái đúng với thứ tự thời gian

`date.toLocaleDateString(locale, tuyChon)` định dạng phần ngày theo quy ước của ngôn ngữ (thứ tự ngày/tháng/năm, tên tháng, thứ). Cùng họ có `toLocaleTimeString` (giờ) và `toLocaleString` (cả hai). `tuyChon` gồm `dateStyle`, `timeStyle`, `year`, `month`, `day`, `weekday`, `hour`, `minute`, `timeZone`, `hour12`. Đặt `timeZone` rõ ràng cho kết quả không phụ thuộc máy. Bên dưới dùng `Intl.DateTimeFormat`; khi định dạng nhiều ngày nên tạo sẵn một bộ định dạng.

const d = new Date('2024-03-15T10:30:45Z');
console.log(d.toLocaleDateString('vi-VN', { timeZone: 'UTC' }));
console.log(d.toLocaleDateString('en-US', { timeZone: 'UTC' }));
console.log(d.toLocaleDateString('vi-VN', { dateStyle: 'full', timeZone: 'UTC' }));
const kieu = { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' };
console.log(d.toLocaleDateString('en-GB', kieu));
console.log(d.toLocaleTimeString('vi-VN', { timeZone: 'UTC', hour12: false }));
console.log(d.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }));
console.log(d.toLocaleString('en-US', { timeZone: 'America/New_York', timeStyle: 'short' }));

Kết quả

d.toLocaleDateString('vi-VN', { timeZone: 'UTC' }) → '15/3/2024'
d.toLocaleDateString('en-US', { timeZone: 'UTC' }) → '3/15/2024'
d.toLocaleDateString('vi-VN', { dateStyle: 'full', timeZone: 'UTC' }) → 'Thứ Sáu, 15 tháng 3, 2024'
d.toLocaleDateString('en-GB', kieu) → '15 Mar 2024'
d.toLocaleTimeString('vi-VN', { timeZone: 'UTC', hour12: false }) → '10:30:45'
d.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }) → '17:30:45 15/3/2024'
d.toLocaleString('en-US', { timeZone: 'America/New_York', timeStyle: 'short' }) → '6:30 AM'

Lưu ý

- Không đặt `timeZone` thì dùng múi giờ máy chạy, nên kết quả khác giữa các máy
- Chuỗi định dạng chỉ để hiển thị; không phân tích ngược lại bằng `new Date(chuoi)`

`JSON.parse(chuoi, reviver)` đọc chuỗi JSON thành giá trị JavaScript, ném `SyntaxError` nếu không hợp lệ. Hàm `reviver(khoa, giaTri)` tùy chọn chạy cho từng khóa từ trong ra ngoài để biến đổi giá trị (hay dùng để đổi chuỗi ISO thành `Date`). Không dùng được trên chuỗi chứa số lớn hơn `MAX_SAFE_INTEGER` mà không mất độ chính xác.

console.log(JSON.parse('[1, 2, {"a": true}]'));
console.log(JSON.parse('"chuỗi"'), JSON.parse('3.5'), JSON.parse('null'));
const withDate = JSON.parse('{"name":"An","birthday":"2010-05-20T00:00:00.000Z"}', (key, value) =>
  key === 'birthday' ? new Date(value) : value
);
console.log(withDate.birthday.getUTCFullYear());
for (const broken of ['{name: 1}', '{"a":1,}', '', "'x'", 'undefined']) {
  try {
    JSON.parse(broken);
  } catch (e) {
    console.log(e.name);
  }
}
console.log(JSON.parse('12345678901234567890'));

Kết quả

JSON.parse('[1, 2, {"a": true}]') → [ 1, 2, { a: true } ]
JSON.parse('"chuỗi"'), JSON.parse('3.5'), JSON.parse('null') → 'chuỗi' 3.5 null
withDate.birthday.getUTCFullYear() → 2010
e.name → 'SyntaxError'
e.name → 'SyntaxError'
e.name → 'SyntaxError'
e.name → 'SyntaxError'
e.name → 'SyntaxError'
JSON.parse('12345678901234567890') → 12345678901234567000

Lưu ý

- Thông báo lỗi của `SyntaxError` khác nhau giữa các engine; chỉ dựa vào loại lỗi
- Không bao giờ dùng `eval` để đọc JSON; nguy hiểm và không cần thiết

`JSON.stringify(giaTri, replacer, space)` chuyển giá trị thành chuỗi JSON. `replacer` là mảng tên khóa được giữ hoặc hàm `(khoa, giaTri)` để lọc hay biến đổi; `space` là số hoặc chuỗi để thụt lề dễ đọc. Thuộc tính `undefined`, hàm, symbol bị bỏ (trong mảng thành `null`), `NaN` và `Infinity` thành `null`, `Date` gọi `toJSON()` ra chuỗi ISO. Object có phương thức `toJSON()` tự quyết định hình thức. Tham chiếu vòng và `BigInt` gây `TypeError`.

const student = { name: 'An', age: 15, password: 'bi-mat', createdAt: new Date(0) };
console.log(JSON.stringify(student));
console.log(JSON.stringify(student, ['name', 'age']));
console.log(JSON.stringify(student, (k, v) => (k === 'password' ? undefined : v)));
console.log(JSON.stringify({ a: [1, { b: 2 }] }, null, 2));
console.log(JSON.stringify({ a: 1 }, null, '--'));
class Fee {
  constructor(amount) {
    this.amount = amount;
  }
  toJSON() {
    return `${this.amount} đồng`;
  }
}
console.log(JSON.stringify({ tuition: new Fee(500) }));
const loop = {};
loop.self = loop;
try {
  JSON.stringify(loop);
} catch (e) {
  console.log(e.name);
}
try {
  JSON.stringify({ n: 1n });
} catch (e) {
  console.log(e.name);
}

Kết quả

JSON.stringify(student) →
  '{"name":"An","age":15,"password":"bi-mat","createdAt":"1970-01-01T00:00:00.000Z"}'
JSON.stringify(student, ['name', 'age']) → '{"name":"An","age":15}'
JSON.stringify(student, (k, v) => (k === 'password' ? undefined : v)) →
  '{"name":"An","age":15,"createdAt":"1970-01-01T00:00:00.000Z"}'
JSON.stringify({ a: [1, { b: 2 }] }, null, 2) →
  '{\n  "a": [\n    1,\n    {\n      "b": 2\n    }\n  ]\n}'
JSON.stringify({ a: 1 }, null, '--') → '{\n--"a": 1\n}'
JSON.stringify({ tuition: new Fee(500) }) → '{"tuition":"500 đồng"}'
e.name → 'TypeError'
e.name → 'TypeError'

Lưu ý

- Thứ tự khóa theo thứ tự thêm vào (khóa nguyên đứng trước)
- `JSON.stringify` không giữ `Map`, `Set` (ra `{}`); chuyển sang mảng hoặc object trước
- Muốn xuất chuỗi gọn để gửi dùng không `space`; in cho người đọc dùng `space = 2`

`promise.then(onThanhCong, onThatBai)` đăng ký hàm chạy khi Promise ngã ngũ và luôn trả về một Promise MỚI. Giá trị bạn `return` trong `then` trở thành giá trị của promise mới (nếu trả về một Promise, chuỗi chờ nó); ném lỗi thì promise mới bị từ chối. Nhờ vậy nối chuỗi `then().then()` biến đổi dữ liệu theo từng bước và tránh callback lồng nhau. Hàm trong `then` luôn chạy BẤT ĐỒNG BỘ (sau mã đồng bộ hiện tại), ngay cả khi promise đã xong.

const load = (v) => new Promise((resolve) => setTimeout(() => resolve(v), 5));

load(2)
  .then((x) => x * 10)
  .then((x) => load(x + 1))
  .then((x) => {
    console.log('điểm cuối:', x);
    return 'xong';
  })
  .then(console.log);

Promise.resolve('đã sẵn').then((v) => console.log(v));
console.log('mã đồng bộ chạy trước');

Kết quả

mã đồng bộ chạy trước
v → 'đã sẵn'
điểm cuối: 21
xong

Lưu ý

- Luôn `return` giá trị hoặc Promise trong `then`, nếu không bước kế tiếp nhận `undefined`
- Đừng lồng `then` bên trong `then`; hãy nối chuỗi phẳng

`promise.catch(onLoi)` tương đương `then(undefined, onLoi)`: nhận lỗi khi promise bị từ chối hoặc khi một `then` phía trên ném ngoại lệ. Lỗi "trôi" xuống theo chuỗi, bỏ qua các `then` trung gian cho đến khi gặp `catch`. Giá trị `catch` trả về làm chuỗi tiếp tục như bình thường (đã phục hồi), còn ném lại lỗi thì chuỗi vẫn ở trạng thái lỗi. Promise bị từ chối mà không ai `catch` gây sự kiện `unhandledrejection` (Node.js mặc định làm sập tiến trình).

Promise.resolve(1)
  .then((x) => {
    if (x === 1) throw new Error('hỏng ở bước 1');
    return x;
  })
  .then(() => console.log('bị bỏ qua'))
  .catch((e) => {
    console.log('bắt được:', e.message);
    return 'đã phục hồi';
  })
  .then((v) => console.log('tiếp tục với', v));

Promise.reject(new TypeError('điểm sai kiểu')).catch((e) => console.log(e.name));

Kết quả

e.name → 'TypeError'
bắt được: hỏng ở bước 1
tiếp tục với đã phục hồi

Lưu ý

- Đặt `catch` ở cuối chuỗi để bắt mọi lỗi phía trên
- Với `async/await` dùng `try/catch`

`promise.finally(fn)` chạy `fn` bất kể promise thành công hay thất bại, dùng để dọn dẹp (tắt vòng xoay "đang tải", đóng kết nối, mở khóa nút). `fn` không nhận đối số và giá trị nó trả về bị bỏ qua: promise mới giữ nguyên kết quả hoặc lỗi gốc đi qua. Nếu `fn` ném lỗi (hoặc trả Promise bị từ chối), lỗi mới đó thay thế kết quả.

const load = (fail) => (fail ? Promise.reject(new Error('mạng hỏng')) : Promise.resolve('bảng điểm'));
const log = [];

await load(false)
  .then((v) => log.push('thành công: ' + v))
  .finally(() => log.push('dọn dẹp 1'));

await load(true)
  .catch((e) => log.push('lỗi: ' + e.message))
  .finally(() => log.push('dọn dẹp 2'));

const unchanged = await Promise.resolve(42).finally(() => 'bị bỏ qua');
console.log(log);
console.log(unchanged);

Kết quả

log → [ 'thành công: bảng điểm', 'dọn dẹp 1', 'lỗi: mạng hỏng', 'dọn dẹp 2' ]
unchanged → 42

Lưu ý

- Đừng dùng `finally` để biến đổi kết quả; dùng `then`
- Hợp để bảo đảm tài nguyên được giải phóng ở cả hai nhánh

`Promise.allSettled(iterable)` chờ mọi promise ngã ngũ (thành công hoặc thất bại) rồi trả về mảng các object: `{ status: 'fulfilled', value }` hoặc `{ status: 'rejected', reason }`. Không bao giờ bị từ chối, nên phù hợp khi muốn chạy mọi việc và xử lý riêng từng kết quả: tải nhiều tài nguyên, gửi hàng loạt yêu cầu.

const ok = (ms, v) => new Promise((resolve) => setTimeout(() => resolve(v), ms));
const bad = (ms, m) => new Promise((_, reject) => setTimeout(() => reject(new Error(m)), ms));
Promise.allSettled([ok(10, 'An'), bad(5, 'Bình vắng'), ok(15, 'Chi')]).then((results) => {
  console.log(results.map((r) => r.status));
  const present = results.filter((r) => r.status === 'fulfilled').map((r) => r.value);
  const absent = results.filter((r) => r.status === 'rejected').map((r) => r.reason.message);
  console.log(present, absent);
});
Promise.allSettled([1, Promise.reject('x')]).then((results) => console.log(results));

Kết quả

results → [ { status: 'fulfilled', value: 1 }, { status: 'rejected', reason: 'x' } ]
results.map((r) => r.status) → [ 'fulfilled', 'rejected', 'fulfilled' ]
present, absent → [ 'An', 'Chi' ] [ 'Bình vắng' ]

Tham số & trả về

iterable: danh sách promise hoặc giá trị
Trả về: promise cho mảng `{ status, value | reason }`

Lưu ý

- Có từ ES2020
- Kết quả giữ nguyên thứ tự đầu vào

`Promise.race(iterable)` ngã ngũ ngay khi promise đầu tiên trong danh sách ngã ngũ, dù thành công hay thất bại, và lấy đúng kết quả đó. Kinh điển để đặt thời hạn (timeout) cho một tác vụ: đua giữa tác vụ thật và một hẹn giờ từ chối.

const ok = (ms, v) => new Promise((resolve) => setTimeout(() => resolve(v), ms));
const bad = (ms, m) => new Promise((_, reject) => setTimeout(() => reject(new Error(m)), ms));
Promise.race([ok(30, 'Bình nộp chậm'), ok(10, 'An nộp nhanh')]).then((r) => console.log('nộp đầu:', r));
Promise.race([ok(30, 'chậm'), bad(10, 'lỗi sớm')]).catch((e) => console.log('thua vì:', e.message));
const late = (ms) => new Promise((_, reject) => setTimeout(() => reject(new Error(`quá ${ms}ms`)), ms));
const withTimeout = (p, ms) => Promise.race([p, late(ms)]);
withTimeout(ok(50, 'xong'), 10).catch((e) => console.log(e.message));
withTimeout(ok(5, 'kịp'), 100).then((r) => console.log(r));

Kết quả

r → 'kịp'
nộp đầu: An nộp nhanh
thua vì: lỗi sớm
e.message → 'quá 10ms'

Tham số & trả về

iterable: danh sách promise
Trả về: promise ngã ngũ cùng promise đầu tiên

Lưu ý

- Promise thua cuộc vẫn chạy tiếp; để thực sự dừng cần `AbortController`
- `Promise.race([])` mãi mãi ở trạng thái chờ

`Promise.any(iterable)` thành công với kết quả của promise ĐẦU TIÊN thành công, bỏ qua các promise thất bại trước đó. Chỉ khi tất cả đều thất bại nó mới bị từ chối với `AggregateError` chứa mọi lỗi. Hợp để thử nhiều nguồn dự phòng (nhiều máy chủ, nhiều CDN) và lấy nguồn nào trả lời đầu tiên.

const ok = (ms, v) => new Promise((resolve) => setTimeout(() => resolve(v), ms));
const bad = (ms, m) => new Promise((_, reject) => setTimeout(() => reject(new Error(m)), ms));
Promise.any([bad(5, 'lớp A hỏng'), ok(20, 'lớp B ổn'), ok(10, 'lớp C nhanh')]).then((r) =>
  console.log('any:', r)
);
Promise.any([bad(5, 'lớp A hỏng'), bad(10, 'lớp B hỏng')]).catch((e) => {
  console.log(e.name);
  console.log(e.errors.map((x) => x.message));
});
Promise.race([bad(5, 'lỗi'), ok(10, 'ổn')]).catch((e) => console.log('race gặp lỗi trước:', e.message));

Kết quả

race gặp lỗi trước: lỗi
any: lớp C nhanh
e.name → 'AggregateError'
e.errors.map((x) => x.message) → [ 'lớp A hỏng', 'lớp B hỏng' ]

Tham số & trả về

iterable: danh sách promise
Trả về: promise cho giá trị thành công đầu tiên, hoặc bị từ chối với `AggregateError`

Lưu ý

- Khác `race`: `any` bỏ qua lỗi cho đến khi có một thành công
- Có từ ES2021

`Promise.resolve(giaTri)` trả về một Promise đã thành công với giá trị đó; nếu truyền vào một Promise thì trả chính nó, nếu là "thenable" (đối tượng có `.then`) thì nó theo kết quả của thenable. Hữu ích để đồng nhất hàm vừa trả giá trị thường vừa trả Promise, hoặc khởi đầu một chuỗi. `Promise.reject(loi)` tạo Promise đã bị từ chối. Cả hai đều dựng promise ngay lập tức nhưng `then` vẫn chạy bất đồng bộ.

const p = Promise.resolve(5);
console.log(Promise.resolve(p) === p);

const thenable = { then: (resolve) => resolve('từ thenable') };
Promise.resolve(thenable).then((v) => console.log(v));

const doubleScore = (v) => Promise.resolve(v).then((x) => x * 2);
console.log(await doubleScore(3), await doubleScore(Promise.resolve(4)));

console.log(await Promise.reject(new Error('x')).catch((e) => e.message));

Kết quả

Promise.resolve(p) === p → true
v → 'từ thenable'
await doubleScore(3), await doubleScore(Promise.resolve(4)) → 6 8
await Promise.reject(new Error('x')).catch((e) => e.message) → 'x'

Lưu ý

- Trong hàm `async`, `return value` đã tự bọc thành Promise
- Dùng `Promise.reject(new Error(...))` với đối tượng lỗi để có stack trace

`document.getElementById(id)` trả về phần tử có thuộc tính `id` khớp, hoặc `null` nếu không có. Rất nhanh vì tra theo bảng id, và không cần ký hiệu `#`. `id` phải duy nhất trong trang. Cùng việc có thể làm bằng `querySelector('#id')`.

<h1 id="tieu-de">Xin chào</h1>
<p id="mo-ta" class="doan">Mô tả</p>

const tieuDe = document.getElementById('tieu-de');
console.log(tieuDe.textContent);
console.log(document.getElementById('khong-co'));
console.log(tieuDe === document.querySelector('#tieu-de'));
console.log(tieuDe.tagName);

Kết quả

- `tieuDe.textContent` in `Xin chào`
- Id không tồn tại: in `null` (nên kiểm tra trước khi dùng)
- `getElementById('tieu-de')` và `querySelector('#tieu-de')` trả về cùng một phần tử: in `true`
- `tieuDe.tagName` in `H1`

Lưu ý

- Truyền `'#tieu-de'` (có dấu `#`) cho `getElementById` sẽ không tìm thấy gì
- Script phải chạy sau khi phần tử đã có trong trang (đặt `<script>` cuối `<body>`, hoặc dùng `defer`)

`document.querySelector(boChon)` trả về phần tử ĐẦU TIÊN khớp bộ chọn CSS, hoặc `null` nếu không có. Dùng được mọi bộ chọn CSS: thẻ, class, id, thuộc tính, quan hệ cha con, giả lớp. Cũng gọi được trên một phần tử để tìm trong phạm vi của nó: `el.querySelector('.con')`.

<ul id="ds">
  <li class="muc">Một</li>
  <li class="muc dang-chon">Hai</li>
</ul>

console.log(document.querySelector('.muc').textContent);
console.log(document.querySelector('.dang-chon').textContent);
console.log(document.querySelector('#ds > li:last-child').textContent);
console.log(document.querySelector('li[class~="dang-chon"]') !== null);
console.log(document.querySelector('.khong-co'));
const ds = document.querySelector('#ds');
console.log(ds.querySelector('li').textContent);

Kết quả

- `.muc` khớp phần tử đầu tiên: in `Một`
- `.dang-chon`: in `Hai`
- `#ds > li:last-child`: in `Hai`
- Selector theo thuộc tính khớp: in `true`
- Không có phần tử khớp: in `null`
- Tìm trong phạm vi `ds`: in `Một`

Lưu ý

- Bộ chọn sai cú pháp ném `SyntaxError`
- Kết quả là snapshot tại thời điểm gọi; phần tử thêm sau không xuất hiện

`document.querySelectorAll(boChon)` trả về `NodeList` tĩnh gồm mọi phần tử khớp (rỗng nếu không có, không bao giờ `null`). `NodeList` có `forEach` và `length` nhưng không phải mảng; chuyển bằng `Array.from()` hoặc spread để dùng `map`/`filter`. Là danh sách tĩnh nên không tự cập nhật khi trang đổi.

<p class="tin">A</p>
<p class="tin">B</p>
<p class="tin">C</p>

const cacTin = document.querySelectorAll('.tin');
console.log(cacTin.length);
cacTin.forEach((p, i) => console.log(i, p.textContent));
const chu = [...cacTin].map((p) => p.textContent);
console.log(chu);
console.log(document.querySelectorAll('.khong-co').length);
console.log(Array.isArray(cacTin));

Kết quả

- `cacTin.length` in `3`
- `forEach` in lần lượt `0 A`, `1 B`, `2 C`
- Chuyển sang mảng rồi `map`: in `['A', 'B', 'C']`
- Không có phần tử khớp: `length` là `0`
- `Array.isArray(cacTin)` in `false` (là NodeList)

Lưu ý

- `getElementsByClassName` trả về danh sách "sống" tự cập nhật, khác với danh sách tĩnh ở đây
- Muốn dùng `map`/`filter`/`reduce` phải chuyển thành mảng

`el.closest(boChon)` đi từ chính phần tử lên các tổ tiên và trả về phần tử đầu tiên khớp bộ chọn, hoặc `null`. Rất hữu ích trong ủy quyền sự kiện: khi người dùng bấm vào một thẻ con bên trong nút, `e.target.closest('button')` cho ra chính nút đó.

<ul id="menu">
  <li class="muc"><span class="nhan">Trang chủ</span></li>
</ul>

const nhan = document.querySelector('.nhan');
console.log(nhan.closest('.muc').tagName);
console.log(nhan.closest('#menu').id);
console.log(nhan.closest('.nhan') === nhan);
console.log(nhan.closest('table'));
document.querySelector('#menu').addEventListener('click', (e) => {
  const muc = e.target.closest('.muc');
  if (muc) console.log('bấm vào', muc.textContent);
});

Kết quả

- `nhan.closest('.muc').tagName` in `LI`
- `nhan.closest('#menu').id` in `menu`
- Chính phần tử cũng được xét: `true`
- Không có tổ tiên khớp: in `null`
- Khi bấm vào chữ "Trang chủ", handler in `bấm vào Trang chủ`

Lưu ý

- Kiểm tra `if (muc)` vì có thể là `null`; sau đó có thể kiểm tra thêm `container.contains(muc)`
- `el.matches(boChon)` chỉ kiểm tra chính phần tử, không đi lên

`el.getAttribute(ten)` trả về giá trị chuỗi của thuộc tính như viết trong HTML, hoặc `null` nếu thuộc tính không có. `el.hasAttribute(ten)` chỉ kiểm tra tồn tại. Với thuộc tính boolean như `disabled`, giá trị là chuỗi rỗng khi có mặt. Để lấy giá trị đã chuẩn hóa (ví dụ đường dẫn tuyệt đối của `href`) dùng thuộc tính DOM `el.href`.

<a id="lk" href="/trang" data-ma="42" disabled>Liên kết</a>

const lk = document.getElementById('lk');
console.log(lk.getAttribute('href'));
console.log(lk.href);
console.log(lk.getAttribute('data-ma'));
console.log(lk.getAttribute('disabled'));
console.log(lk.getAttribute('khong-co'));
console.log(lk.hasAttribute('disabled'));

Kết quả

- `getAttribute('href')` in `/trang` (đúng như viết)
- `lk.href` in địa chỉ đầy đủ, ví dụ `https://example.com/trang`
- `getAttribute('data-ma')` in `42` (luôn là chuỗi)
- Thuộc tính boolean `disabled` có mặt: in chuỗi rỗng
- Thuộc tính không tồn tại: in `null`
- `hasAttribute('disabled')` in `true`

Lưu ý

- Giá trị luôn là chuỗi hoặc `null`; ép sang số khi cần
- Không dùng `getAttribute('value')` để biết giá trị hiện tại của ô nhập; dùng `el.value`

`el.setAttribute(ten, giaTri)` đặt (hoặc ghi đè) thuộc tính, giá trị được chuyển thành chuỗi. Với thuộc tính boolean, `setAttribute('disabled', '')` bật còn `removeAttribute('disabled')` tắt; `el.toggleAttribute('disabled', true | false)` tiện hơn. Nhiều thuộc tính chuẩn cũng có thuộc tính DOM tương ứng (`el.id`, `el.href`, `el.disabled`) dùng trực tiếp được.

<img id="anh" src="a.png">
<button id="nut">Gửi</button>

const anh = document.getElementById('anh');
anh.setAttribute('src', 'b.png');
anh.setAttribute('alt', 'Ảnh minh họa');
console.log(anh.getAttribute('src'), anh.alt);
const nut = document.getElementById('nut');
nut.setAttribute('disabled', '');
console.log(nut.disabled);
nut.toggleAttribute('disabled');
console.log(nut.hasAttribute('disabled'));
nut.setAttribute('data-so', 5);
console.log(typeof nut.getAttribute('data-so'));

Kết quả

- Ảnh đổi sang `b.png` và có `alt`: in `b.png Ảnh minh họa`
- Sau `setAttribute('disabled', '')`, `nut.disabled` là `true` và nút bị vô hiệu hóa
- `toggleAttribute` bật lại: nút được kích hoạt, `hasAttribute` in `false`
- Giá trị số `5` được lưu thành chuỗi: in `string`

Lưu ý

- `setAttribute('disabled', 'false')` VẪN làm nút bị vô hiệu hóa vì thuộc tính có mặt; dùng `removeAttribute` hoặc `el.disabled = false`
- Đổi thuộc tính `class` nên dùng `classList` cho gọn

`el.removeAttribute(ten)` xóa hẳn thuộc tính khỏi phần tử; nếu thuộc tính không có thì không làm gì và không báo lỗi. Cách đúng để "bật lại" nút bị `disabled`, bỏ `hidden`, hay gỡ `readonly`.

<input id="o" readonly value="khóa" data-tam="x">
<p id="p" hidden>Ẩn</p>

const o = document.getElementById('o');
o.removeAttribute('readonly');
console.log(o.hasAttribute('readonly'), o.readOnly);
o.removeAttribute('data-tam');
console.log(o.dataset.tam);
document.getElementById('p').removeAttribute('hidden');
console.log(document.getElementById('p').hidden);
o.removeAttribute('khong-co');

Kết quả

- Sau khi xóa `readonly`: `hasAttribute` in `false`, `o.readOnly` in `false`, ô nhập sửa được
- `o.dataset.tam` in `undefined` sau khi xóa `data-tam`
- Đoạn văn hiện lại: `hidden` in `false`
- Xóa thuộc tính không tồn tại: không lỗi, không thay đổi

Lưu ý

- Với thuộc tính boolean, đặt `el.hidden = false` tương đương `removeAttribute('hidden')`

`el.dataset` là object cho phép đọc và ghi các thuộc tính `data-*` như thuộc tính thường, trong đó tên kiểu kebab (`data-user-id`) được đổi sang camelCase (`dataset.userId`). Giá trị luôn là chuỗi. Dùng để gắn dữ liệu nhỏ vào phần tử HTML (id bản ghi, trạng thái) mà JavaScript hoặc CSS (`[data-trang-thai="loi"]`) cùng đọc được.

<li id="muc" data-user-id="7" data-trang-thai="moi">An</li>

const muc = document.getElementById('muc');
console.log(muc.dataset.userId);
console.log(typeof muc.dataset.userId);
console.log(muc.dataset.trangThai);
muc.dataset.daXem = 'true';
console.log(muc.getAttribute('data-da-xem'));
delete muc.dataset.trangThai;
console.log(muc.hasAttribute('data-trang-thai'));
console.log(muc.dataset.khongCo);
console.log(Object.keys(muc.dataset));

Kết quả

- `dataset.userId` in `7`, kiểu `string`
- `dataset.trangThai` in `moi` (từ `data-trang-thai`)
- Gán `dataset.daXem` tạo thuộc tính `data-da-xem="true"` trong HTML
- `delete` xóa `data-trang-thai`: `hasAttribute` in `false`
- Khóa không tồn tại: `undefined`
- `Object.keys` in `['userId', 'daXem']`

Lưu ý

- Giá trị là chuỗi nên cần `Number()` hoặc `JSON.parse()` khi cần số hoặc object
- Không lưu dữ liệu nhạy cảm hay lớn trong `data-*` vì người dùng thấy được

`el.classList.add(...cacClass)` thêm một hoặc nhiều class; class đã có thì bỏ qua, không trùng lặp. Tiện hơn nhiều so với nối chuỗi vào `el.className`. Thêm class là cách chuẩn để kích hoạt kiểu dáng đã định nghĩa trong CSS (ẩn/hiện, trạng thái lỗi, hoạt ảnh).

<div id="hop" class="the">Nội dung</div>

const hop = document.getElementById('hop');
hop.classList.add('noi-bat');
hop.classList.add('lon', 'dam');
hop.classList.add('the');
console.log(hop.className);
console.log([...hop.classList]);
console.log(hop.classList.length);

Kết quả

- Sau các lần thêm, `className` in `the noi-bat lon dam` (class `the` đã có nên không lặp)
- Spread `classList` in `['the', 'noi-bat', 'lon', 'dam']`
- `classList.length` in `4`

Lưu ý

- Truyền chuỗi có dấu cách như `add('a b')` ném `InvalidCharacterError`; truyền từng class riêng
- `className = 'x'` ghi đè toàn bộ class, còn `classList.add` chỉ thêm

`el.classList.remove(...cacClass)` gỡ các class chỉ định; class không có thì bỏ qua, không lỗi. Dùng để tắt trạng thái như `dang-tai`, `an`, `loi` sau khi xong việc.

<div id="hop" class="the noi-bat lon">Nội dung</div>

const hop = document.getElementById('hop');
hop.classList.remove('noi-bat');
console.log(hop.className);
hop.classList.remove('lon', 'khong-co');
console.log(hop.className);
hop.classList.remove('the');
console.log(hop.className === '', hop.hasAttribute('class'));

Kết quả

- Sau khi gỡ `noi-bat`: `className` in `the lon`
- Gỡ `lon` và một class không tồn tại: in `the`, không lỗi
- Gỡ hết class: `className` là chuỗi rỗng, thuộc tính `class` vẫn còn nhưng trống (`true true`)

Lưu ý

- Có thể gỡ nhiều class trong một lần gọi
- Không dùng `classList.remove` với chuỗi chứa khoảng trắng

`el.classList.toggle(ten, ep)` thêm class nếu chưa có, gỡ nếu đã có, và trả về `true` nếu class có mặt sau thao tác. Tham số thứ hai boolean ép trạng thái: `toggle('an', dieuKien)` thêm khi điều kiện đúng và gỡ khi sai. Là cách ngắn nhất để viết nút bật/tắt menu, chế độ tối, mục đang chọn.

<nav id="menu" class="dong">Menu</nav>

const menu = document.getElementById('menu');
console.log(menu.classList.toggle('mo'));
console.log(menu.className);
console.log(menu.classList.toggle('mo'));
console.log(menu.className);
console.log(menu.classList.toggle('dong', false));
console.log(menu.className === '');
const tamTat = true;
menu.classList.toggle('toi', tamTat);
console.log(menu.className);

Kết quả

- Lần 1: thêm `mo`, trả về `true`, `className` in `dong mo`
- Lần 2: gỡ `mo`, trả về `false`, `className` in `dong`
- `toggle('dong', false)` ép gỡ: trả về `false`, hết class
- `toggle('toi', true)` ép thêm: `className` in `toi`

Lưu ý

- Dùng tham số ép khi bạn đã biết trạng thái đích, tránh lệch khi sự kiện bấm nhanh
- `toggle` trả về trạng thái cuối cùng, tiện để cập nhật `aria-expanded`

`el.classList.contains(ten)` trả về `true` nếu phần tử có class đó. Phân biệt hoa thường. Dùng để rẽ nhánh theo trạng thái hiện tại của giao diện. Muốn kiểm tra theo bộ chọn CSS phức tạp hơn dùng `el.matches('.a.b')`.

<li id="muc" class="muc chon">Mục</li>

const muc = document.getElementById('muc');
console.log(muc.classList.contains('chon'));
console.log(muc.classList.contains('Chon'));
console.log(muc.classList.contains('khong-co'));
console.log(muc.matches('.muc.chon'));
if (muc.classList.contains('chon')) console.log('đang được chọn');

Kết quả

- `contains('chon')` in `true`
- Phân biệt hoa thường: `contains('Chon')` in `false`
- Class không có: `false`
- `matches('.muc.chon')` in `true`
- Dòng cuối in `đang được chọn`

Lưu ý

- Truyền một class mỗi lần; không dùng chuỗi nhiều class

`el.style` truy cập style nội tuyến của phần tử qua các thuộc tính camelCase (`backgroundColor` thay cho `background-color`); giá trị là chuỗi kèm đơn vị. Chỉ đọc được style gán trực tiếp trên phần tử, KHÔNG đọc được style đến từ stylesheet; để lấy giá trị tính toán cuối cùng dùng `getComputedStyle(el)`. Với biến CSS dùng `el.style.setProperty('--ten', giaTri)`.

<div id="hop" style="color: red">Hộp</div>

const hop = document.getElementById('hop');
console.log(hop.style.color);
hop.style.backgroundColor = 'yellow';
hop.style.width = '200px';
console.log(hop.getAttribute('style'));
console.log(hop.style.padding === '');
hop.style.setProperty('--mau-chinh', '#09f');
console.log(getComputedStyle(hop).width);
hop.style.removeProperty('width');
hop.style.cssText = 'margin: 0';
console.log(hop.getAttribute('style'));

Kết quả

- `hop.style.color` in `red`
- Sau khi gán, thuộc tính `style` in `color: red; background-color: yellow; width: 200px;`
- `padding` chưa đặt trong style nội tuyến: chuỗi rỗng (`true`)
- `getComputedStyle(hop).width` in `200px` (giá trị cuối cùng đã tính)
- Sau `cssText = 'margin: 0'`, thuộc tính `style` in `margin: 0px;`

Lưu ý

- Ưu tiên `classList` để đổi giao diện; chỉ dùng `style` cho giá trị động (vị trí, tiến độ)
- Cần ghi giá trị số kèm đơn vị: `el.style.width = '200px'`, không phải `200`

`document.createElement(tenThe)` tạo một phần tử mới trong bộ nhớ, chưa nằm trong trang cho tới khi thêm vào cây bằng `append` hay `prepend`. Sau khi tạo, đặt nội dung, class, thuộc tính, trình nghe sự kiện rồi mới chèn để trình duyệt chỉ phải vẽ lại một lần. Với nhiều phần tử, dùng `DocumentFragment` hoặc thẻ `<template>`.

<ul id="ds"></ul>

const ds = document.getElementById('ds');
const li = document.createElement('li');
li.textContent = 'Mục mới';
li.className = 'muc';
li.dataset.id = '1';
console.log(li.parentElement);
ds.append(li);
console.log(li.parentElement.id, ds.children.length);
console.log(ds.innerHTML);
const mang = ['A', 'B', 'C'];
const khung = document.createDocumentFragment();
mang.forEach((t) => {
  const x = document.createElement('li');
  x.textContent = t;
  khung.append(x);
});
ds.append(khung);
console.log(ds.children.length);

Kết quả

- Trước khi chèn: `li.parentElement` in `null`
- Sau `ds.append(li)`: in `ds 1`
- `ds.innerHTML` in `<li class="muc" data-id="1">Mục mới</li>`
- Thêm ba phần tử qua fragment (một lần chèn): `ds.children.length` in `4`

Lưu ý

- Đặt nội dung bằng `textContent` (an toàn) thay vì `innerHTML` khi dữ liệu đến từ người dùng
- Lặp thêm từng phần tử vào trang trong vòng lặp gây nhiều lần vẽ lại; gom bằng fragment

`el.append(...cacNodeHoacChuoi)` thêm nhiều node hoặc chuỗi vào CUỐI phần tử; chuỗi được thêm như đoạn văn bản (không phân tích HTML nên an toàn). Khác `appendChild` ở chỗ nhận nhiều đối số, nhận chuỗi và không trả về node. Nếu node đã nằm đâu đó trong cây, nó được DI CHUYỂN sang vị trí mới. Còn `before()` và `after()` chèn bên cạnh phần tử.

<ul id="ds"><li id="a">A</li></ul>

const ds = document.getElementById('ds');
const b = document.createElement('li');
b.textContent = 'B';
ds.append(b, 'chữ thường', document.createElement('li'));
console.log(ds.children.length, ds.childNodes.length);
const a = document.getElementById('a');
ds.append(a);
console.log(ds.firstElementChild.textContent, ds.lastElementChild.id);
b.after(document.createElement('hr'));
console.log(b.nextElementSibling.tagName);
console.log(ds.append('<b>không phải html</b>'));

Kết quả

- Sau khi thêm node B, chuỗi và một `li` rỗng: `children.length` in `3`, `childNodes.length` in `4` (có thêm node chữ)
- Chèn lại `a` đã có sẵn thì nó được di chuyển xuống cuối: phần tử đầu là `B`, phần tử cuối có id `a`
- `b.after(hr)` chèn ngay sau `B`: phần tử kế bên in `HR`
- Chuỗi `'<b>...'` hiện nguyên văn như chữ, không thành thẻ; `append` trả về `undefined`

Lưu ý

- `appendChild(node)` cũ hơn, chỉ nhận một node và trả về node đó
- Chèn nhiều phần tử một lần để trình duyệt vẽ lại ít hơn

`el.prepend(...cacNodeHoacChuoi)` thêm node hoặc chuỗi vào ĐẦU phần tử, trước mọi con hiện có. Cùng cách hoạt động với `append()` (nhận nhiều đối số, chuỗi thành văn bản, di chuyển node có sẵn) nhưng ở vị trí đầu. Hay dùng để chèn tin mới nhất lên đầu danh sách.

<ul id="tin"><li>Cũ</li></ul>

const tin = document.getElementById('tin');
const moi = document.createElement('li');
moi.textContent = 'Mới nhất';
tin.prepend(moi);
console.log(tin.firstElementChild.textContent);
tin.prepend('A', 'B');
console.log(tin.childNodes.length, tin.firstChild.textContent);
console.log([...tin.children].map((li) => li.textContent));

Kết quả

- Sau `prepend(moi)`: phần tử đầu tiên in `Mới nhất`
- `prepend('A', 'B')` thêm hai node chữ ở đầu: `childNodes.length` in `4`, node đầu in `A`
- Danh sách phần tử `li` in `['Mới nhất', 'Cũ']`

Lưu ý

- `prepend` chèn trước mọi con; để chèn trước một con cụ thể dùng `con.before(node)`

`el.remove()` gỡ phần tử khỏi cây DOM (không có tác dụng nếu nó không nằm trong cây). Phần tử vẫn tồn tại trong bộ nhớ nên có thể thêm lại sau, miễn là còn tham chiếu. Các trình nghe sự kiện gắn trên phần tử vẫn còn; chúng được dọn khi phần tử không còn ai tham chiếu. `el.replaceWith(node)` thay thế phần tử bằng node khác.

<ul id="ds"><li id="a">A</li><li id="b">B</li></ul>

const ds = document.getElementById('ds');
const a = document.getElementById('a');
a.remove();
console.log(ds.children.length, a.isConnected, a.parentElement);
ds.append(a);
console.log(ds.lastElementChild.id, a.isConnected);
document.getElementById('b').replaceWith('đã thay');
console.log(ds.children.length, ds.textContent);
a.remove();
a.remove();

Kết quả

- Sau `a.remove()`: `children.length` in `1`, `a.isConnected` in `false`, `a.parentElement` in `null`
- Thêm lại bằng `append`: phần tử cuối có id `a`, `isConnected` in `true`
- `replaceWith('đã thay')`: `B` bị thay bằng văn bản; `children.length` in `1`, `textContent` in `đã thayA`
- Gọi `remove()` hai lần liên tiếp không gây lỗi

Lưu ý

- Xóa nhiều phần tử: `document.querySelectorAll('.x').forEach((e) => e.remove())`
- Dọn trình nghe sự kiện và bộ hẹn giờ liên quan trước khi xóa để tránh rò rỉ bộ nhớ

`el.children` là `HTMLCollection` "sống" gồm các phần tử con trực tiếp (không có node chữ); `el.childNodes` thì gồm cả node chữ và chú thích. Các thuộc tính điều hướng: `firstElementChild`, `lastElementChild`, `parentElement`, `nextElementSibling`, `previousElementSibling`. Vì là danh sách sống, nó tự cập nhật khi cây thay đổi. Chuyển thành mảng để dùng `map`/`filter`.

<ul id="ds">
  <li>A</li>
  <li>B</li>
  <li>C</li>
</ul>

const ds = document.getElementById('ds');
console.log(ds.children.length, ds.childNodes.length);
console.log(ds.firstElementChild.textContent, ds.lastElementChild.textContent);
const b = ds.children[1];
console.log(b.previousElementSibling.textContent, b.nextElementSibling.textContent);
console.log(b.parentElement.id);
console.log([...ds.children].map((li) => li.textContent));
ds.append(document.createElement('li'));
console.log(ds.children.length);

Kết quả

- `children.length` in `3`, còn `childNodes.length` in `7` (3 phần tử và 4 node chữ chứa xuống dòng)
- Phần tử đầu và cuối: `A` và `C`
- Hàng xóm của `B`: `A` trước, `C` sau
- `b.parentElement.id` in `ds`
- Chuyển sang mảng `map`: in `['A', 'B', 'C']`
- Danh sách sống nên sau khi thêm một `li`, `children.length` in `4`

Lưu ý

- Dùng `children` thay `childNodes` khi chỉ quan tâm phần tử
- Xóa phần tử trong lúc duyệt `children` làm danh sách đổi theo; sao chép sang mảng trước

`el.textContent` đọc hoặc ghi toàn bộ văn bản của phần tử và các con cháu của nó. Khi ghi, mọi thẻ HTML trong chuỗi chỉ hiện thành chữ (không được phân tích) nên an toàn trước tấn công XSS, và mọi con cũ bị thay bằng một node chữ. Khác `innerText` ở chỗ `textContent` không phụ thuộc CSS (không bỏ qua phần tử ẩn) và nhanh hơn.

<div id="hop">Xin <b>chào</b> <span hidden>ẩn</span></div>

const hop = document.getElementById('hop');
console.log(hop.textContent);
console.log(hop.innerText);
hop.textContent = '<img src=x onerror=alert(1)>';
console.log(hop.innerHTML);
console.log(hop.children.length);
hop.textContent = '';
console.log(hop.childNodes.length);

Kết quả

- `textContent` đọc cả văn bản của phần tử ẩn: in `Xin chào ẩn`
- `innerText` bỏ qua phần tử bị ẩn: in `Xin chào`
- Gán chuỗi chứa thẻ: hiện nguyên văn như chữ, `innerHTML` in `&lt;img src=x onerror=alert(1)&gt;` và không chạy mã
- Sau khi gán, `children.length` in `0` (chỉ còn một node chữ)
- Gán chuỗi rỗng xóa hết nội dung: `childNodes.length` in `0`

Lưu ý

- Luôn dùng `textContent` cho dữ liệu từ người dùng
- Gán `textContent = ''` là cách nhanh để xóa mọi con của phần tử

`el.innerHTML` đọc hoặc ghi nội dung của phần tử dưới dạng chuỗi HTML. Khi ghi, chuỗi được phân tích thành cây DOM mới và thay toàn bộ con cũ. Tiện để dựng khối giao diện từ chuỗi mẫu nhưng NGUY HIỂM nếu chuỗi chứa dữ liệu người dùng chưa lọc (XSS): kẻ tấn công chèn được thẻ và thuộc tính thực thi mã như `onerror`. Gán `innerHTML` cũng xóa trình nghe sự kiện của các con cũ. Cần chèn thêm mà không ghi đè dùng `insertAdjacentHTML`.

<ul id="ds"><li>Cũ</li></ul>

const ds = document.getElementById('ds');
console.log(ds.innerHTML);
ds.innerHTML = '<li>A</li><li>B</li>';
console.log(ds.children.length);
ds.insertAdjacentHTML('beforeend', '<li>C</li>');
ds.insertAdjacentHTML('afterbegin', '<li>Đầu</li>');
console.log([...ds.children].map((li) => li.textContent));
console.log(ds.outerHTML.startsWith('<ul'));
const ten = '<img src=x onerror=alert(1)>';
ds.innerHTML = `<li>${ten}</li>`;
console.log(ds.querySelector('img') !== null);

Kết quả

- Đọc lần đầu in `<li>Cũ</li>`
- Gán chuỗi hai `li`: `children.length` in `2`
- `insertAdjacentHTML` chèn ở cuối và đầu: danh sách in `['Đầu', 'A', 'B', 'C']`
- `outerHTML` bao cả thẻ ngoài: in `true`
- Chèn chuỗi chứa thẻ độc hại bằng `innerHTML` thực sự tạo ra phần tử `img` có `onerror`: in `true`, lỗ hổng XSS

Lưu ý

- Dữ liệu người dùng phải dùng `textContent` hoặc lọc bằng thư viện như DOMPurify trước khi chèn
- `insertAdjacentHTML` nhận vị trí `beforebegin`, `afterbegin`, `beforeend`, `afterend`
- Ghi lại toàn bộ `innerHTML` trong vòng lặp rất chậm; dựng một chuỗi hoặc dùng `append` rồi gán một lần

`el.value` là giá trị hiện tại của ô nhập (`input`, `textarea`, `select`), luôn là CHUỖI kể cả với `type="number"`. Khác thuộc tính HTML `value` (giá trị ban đầu viết trong thẻ). Với `checkbox` và `radio` dùng `el.checked` (boolean). Dùng `el.valueAsNumber` để lấy số từ ô số, và `el.files` cho ô chọn tệp. Ghi vào `el.value` để đặt lại nội dung ô.

<input id="tuoi" type="number" value="18">
<input id="ten" value="An">
<input id="dong-y" type="checkbox" checked>
<select id="thanh-pho"><option value="hn">Hà Nội</option><option value="dn" selected>Đà Nẵng</option></select>

const tuoi = document.getElementById('tuoi');
console.log(tuoi.value, typeof tuoi.value, tuoi.valueAsNumber);
const ten = document.getElementById('ten');
ten.value = 'Bình';
console.log(ten.value, ten.getAttribute('value'));
console.log(document.getElementById('dong-y').checked);
const tp = document.getElementById('thanh-pho');
console.log(tp.value, tp.selectedOptions[0].textContent);
console.log(Number(tuoi.value) + 1);
console.log(tuoi.value + 1);

Kết quả

- Ô số: `value` in `18`, kiểu `string`, còn `valueAsNumber` in `18` (số)
- Sau khi gán, `ten.value` in `Bình` nhưng thuộc tính HTML `value` vẫn in `An` (giá trị ban đầu)
- `checkbox.checked` in `true`
- Select: `value` in `dn`, văn bản mục chọn in `Đà Nẵng`
- Cộng số đúng cách `Number(tuoi.value) + 1` in `19`, cộng thẳng chuỗi `tuoi.value + 1` in `181`

Lưu ý

- Luôn ép kiểu (`Number()`) và kiểm tra `Number.isFinite` trước khi tính toán với giá trị ô nhập
- Gắn sự kiện `input` để theo dõi từng ký tự gõ, `change` khi rời ô

`el.addEventListener(loai, ham, tuyChon)` đăng ký hàm chạy mỗi khi sự kiện `loai` xảy ra trên phần tử; có thể đăng ký nhiều hàm cho cùng một sự kiện, chạy theo thứ tự đăng ký. `tuyChon` là object: `once` (tự gỡ sau lần chạy đầu), `passive` (hứa không gọi `preventDefault`, giúp cuộn mượt), `capture` (nghe ở pha bắt) và `signal` (gỡ bằng `AbortController`). Hàm nhận đối tượng `Event` làm đối số; trong hàm thường `this` là phần tử, trong hàm mũi tên thì không.

<button id="nut">Bấm tôi</button>

const nut = document.getElementById('nut');
let dem = 0;
nut.addEventListener('click', () => {
  dem++;
  console.log(`bấm lần ${dem}`);
});
nut.addEventListener('click', function (e) {
  console.log(e.type, this === e.currentTarget);
});
nut.addEventListener('click', () => console.log('chỉ một lần'), { once: true });
const ac = new AbortController();
nut.addEventListener('click', () => console.log('có thể hủy'), { signal: ac.signal });
nut.click();
nut.click();
ac.abort();
nut.click();

Kết quả

- Lần click đầu in: `bấm lần 1`, `click true`, `chỉ một lần`, `có thể hủy`
- Lần click thứ hai in: `bấm lần 2`, `click true`, `có thể hủy` (hàm `once` đã tự gỡ)
- Sau `ac.abort()`, lần click thứ ba in: `bấm lần 3`, `click true` (hàm gắn `signal` bị gỡ)

Lưu ý

- Gắn cùng một hàm (cùng tham chiếu) hai lần với cùng tùy chọn chỉ có một lần được tính
- Muốn gỡ sau này phải lưu lại tham chiếu của hàm, hoặc dùng `signal`
- Gắn `passive: true` cho `scroll`, `touchmove`, `wheel` để trình duyệt không chờ

`el.removeEventListener(loai, ham, tuyChon)` gỡ listener đã đăng ký; phải truyền ĐÚNG cùng loại, cùng tham chiếu hàm và cùng tùy chọn `capture`. Hàm ẩn danh viết trực tiếp trong `addEventListener` không gỡ được vì không còn tham chiếu. Gỡ listener khi phần tử hay component bị hủy là cách ngăn rò rỉ bộ nhớ và hành vi lặp.

<button id="nut">Bấm</button>

const nut = document.getElementById('nut');
function chao() {
  console.log('xin chào');
}
nut.addEventListener('click', chao);
nut.click();
nut.removeEventListener('click', chao);
nut.click();
nut.addEventListener('click', () => console.log('ẩn danh'));
nut.removeEventListener('click', () => console.log('ẩn danh'));
nut.click();

Kết quả

- Click đầu tiên in `xin chào`
- Sau `removeEventListener`, click lần hai không in gì
- Hàm ẩn danh không gỡ được vì hai biểu thức hàm là hai hàm khác nhau: click lần ba in `ẩn danh`

Lưu ý

- Với nhiều listener cần gỡ cùng lúc, dùng `AbortController` và truyền `signal` khi đăng ký
- Phải khớp tùy chọn `capture` khi gỡ

`e.preventDefault()` hủy hành vi mặc định gắn với sự kiện: không điều hướng khi bấm liên kết, không gửi form khi `submit`, không mở menu chuột phải, không cuộn khi `wheel` hoặc `touchmove`. Chỉ có tác dụng với sự kiện `cancelable` và không dừng sự kiện lan truyền. Với listener gắn `passive: true`, lời gọi bị bỏ qua.

<a id="lk" href="https://example.com">Mở</a>
<input id="so" type="checkbox">

document.getElementById('lk').addEventListener('click', (e) => {
  e.preventDefault();
  console.log(e.defaultPrevented);
});
document.getElementById('so').addEventListener('click', (e) => {
  e.preventDefault();
  console.log('không đổi trạng thái:', e.target.checked);
});
document.getElementById('lk').click();
document.getElementById('so').click();

Kết quả

- Bấm liên kết in `true` và trình duyệt không chuyển trang
- Bấm hộp kiểm in `không đổi trạng thái: false` vì hành vi mặc định (đổi `checked`) bị hủy

Lưu ý

- Gọi `preventDefault` trong listener `passive: true` bị trình duyệt cảnh báo và bỏ qua
- Không nhầm với `stopPropagation`: hai hàm làm việc hoàn toàn khác nhau

`e.stopPropagation()` ngăn sự kiện tiếp tục lan lên (hoặc xuống) các phần tử khác sau listener hiện tại, nhưng các listener khác trên cùng phần tử vẫn chạy. `e.stopImmediatePropagation()` còn chặn cả các listener còn lại trên chính phần tử đó. Hãy dùng tiết kiệm: nó phá cơ chế ủy quyền sự kiện và các listener toàn cục (như đóng menu khi bấm ra ngoài).

<div id="cha"><button id="con">Bấm</button></div>

const cha = document.getElementById('cha');
const con = document.getElementById('con');
cha.addEventListener('click', () => console.log('cha nhận'));
con.addEventListener('click', (e) => {
  console.log('con nhận 1');
  e.stopPropagation();
});
con.addEventListener('click', () => console.log('con nhận 2'));
con.click();

Kết quả

- In `con nhận 1` rồi `con nhận 2` (listener khác trên cùng phần tử vẫn chạy)
- Không in `cha nhận` vì sự kiện bị chặn không nổi lên cha

Lưu ý

- Dùng `stopImmediatePropagation()` nếu muốn chặn cả listener `con nhận 2`
- Đừng lạm dụng; thường có cách khác như kiểm tra `e.target` ở listener cha

`e.target` là phần tử sâu nhất phát sinh sự kiện (nơi người dùng thực sự bấm), có thể là con cháu của phần tử mà listener được gắn. Nền tảng của ủy quyền sự kiện: gắn một listener ở cha rồi dùng `e.target` (kèm `closest`) để biết con nào được tác động. Muốn biết phần tử đang chạy listener dùng `e.currentTarget`.

<ul id="ds"><li><b>Mục 1</b></li><li>Mục 2</li></ul>

const ds = document.getElementById('ds');
ds.addEventListener('click', (e) => {
  console.log(e.target.tagName, e.currentTarget.id);
  const li = e.target.closest('li');
  if (li) console.log('mục:', li.textContent);
});
ds.querySelector('b').click();
ds.querySelectorAll('li')[1].click();

Kết quả

- Bấm vào chữ đậm trong mục 1: in `B ds` rồi `mục: Mục 1` (`target` là thẻ `b`, không phải `li`)
- Bấm mục 2: in `LI ds` rồi `mục: Mục 2`

Lưu ý

- Luôn dùng `closest()` để tìm phần tử mong muốn từ `target`, vì người dùng có thể bấm vào con
- `target` của sự kiện trên Shadow DOM bị che về phần tử chủ

`e.currentTarget` là phần tử đang chạy listener (nơi listener được gắn), khác `e.target` là phần tử gốc. Giá trị này chỉ có trong lúc listener chạy; sau đó (ví dụ trong callback bất đồng bộ) nó trở thành `null`. Trong hàm thường `this` cũng bằng `currentTarget`, còn trong hàm mũi tên thì dùng `e.currentTarget`.

<div id="cha"><span id="con">chữ</span></div>

const cha = document.getElementById('cha');
let giu;
cha.addEventListener('click', (e) => {
  giu = e;
  console.log(e.currentTarget.id, e.target.id, e.currentTarget === e.target);
});
document.getElementById('con').click();
document.getElementById('cha').click();
console.log(giu.currentTarget);

Kết quả

- Bấm `con`: in `cha con false`
- Bấm trực tiếp `cha`: in `cha cha true`
- Sau khi listener kết thúc, `giu.currentTarget` in `null`

Lưu ý

- Lưu `e.currentTarget` vào biến cục bộ nếu cần dùng sau `await` hoặc trong `setTimeout`

Ủy quyền sự kiện tận dụng việc sự kiện nổi lên: gắn MỘT listener ở phần tử cha thay vì gắn riêng cho từng con, rồi dùng `e.target.closest(...)` để biết con nào được tác động. Lợi ích: tiết kiệm bộ nhớ khi có hàng trăm mục, và tự hoạt động với phần tử được thêm sau này (danh sách động) mà không cần gắn lại. Với các sự kiện không nổi lên dùng `focusin`/`focusout` hoặc pha bắt.

<ul id="ds">
  <li data-id="1">Mua sữa <button class="xoa">x</button></li>
  <li data-id="2">Học bài <button class="xoa">x</button></li>
</ul>

const ds = document.getElementById('ds');
ds.addEventListener('click', (e) => {
  const nut = e.target.closest('.xoa');
  if (!nut || !ds.contains(nut)) return;
  const li = nut.closest('li');
  console.log('xóa mục', li.dataset.id);
  li.remove();
});
const moi = document.createElement('li');
moi.dataset.id = '3';
moi.innerHTML = 'Đi ngủ <button class="xoa">x</button>';
ds.append(moi);

Kết quả

- Bấm nút `x` ở mục 1: in `xóa mục 1` và mục đó bị gỡ
- Mục 3 được thêm bằng code vẫn xóa được (in `xóa mục 3`) dù không gắn listener riêng
- Chỉ có một listener duy nhất trên `ds` cho mọi mục

Lưu ý

- Kiểm tra `ds.contains(nut)` để tránh khớp phần tử ngoài vùng (khi `closest` đi ra khỏi cha)
- Chọn selector cụ thể (`.xoa`) thay vì xử lý mọi click trong cha

Sự kiện `click` xảy ra khi người dùng bấm xong (nhấn rồi thả) trên phần tử, và cả khi kích hoạt bằng bàn phím (Enter hoặc Space với nút) hay phương thức `el.click()`. Đối tượng sự kiện là `MouseEvent`: có `clientX`, `clientY`, `button`, `shiftKey`... Dùng thẻ `<button>` cho hành động để có sẵn hỗ trợ bàn phím và trợ năng.

<button id="nut">Thích</button>
<a id="lk" href="/trang">Liên kết</a>

document.getElementById('nut').addEventListener('click', (e) => {
  console.log(e.type, e.button, e.shiftKey);
});
document.getElementById('lk').addEventListener('click', (e) => {
  e.preventDefault();
  console.log('không chuyển trang');
});
document.getElementById('nut').click();
document.getElementById('lk').click();

Kết quả

- Gọi `nut.click()` in `click 0 false` (nút trái, không giữ Shift)
- Click vào liên kết in `không chuyển trang` vì `preventDefault()` chặn việc điều hướng mặc định

Lưu ý

- Không dùng `<div>` làm nút bấm nếu không thêm `role="button"`, `tabindex` và xử lý phím
- `dblclick` cho bấm đúp; `contextmenu` cho bấm chuột phải

Sự kiện `input` xảy ra ngay mỗi lần giá trị của `input`, `textarea` hoặc phần tử `contenteditable` thay đổi: mỗi ký tự gõ, dán, xóa, kể cả chọn ở `select` hay kéo thanh trượt. Khác `change` (chỉ khi rời ô hoặc xác nhận). Hay dùng cho tìm kiếm tức thời, đếm ký tự, kiểm tra hợp lệ khi gõ; kết hợp debounce để tránh gọi quá nhiều.

<input id="o" placeholder="Gõ gì đó">
<span id="dem">0</span>

const o = document.getElementById('o');
o.addEventListener('input', (e) => {
  document.getElementById('dem').textContent = e.target.value.length;
  console.log(e.inputType, JSON.stringify(e.data), e.target.value);
});

Kết quả

- Người dùng gõ chữ `a`: in `insertText "a" a`, bộ đếm hiện `1`
- Gõ tiếp `b`: in `insertText "b" ab`, bộ đếm hiện `2`
- Nhấn Backspace: in `deleteContentBackward null a`, bộ đếm hiện `1`
- Dán chuỗi: `inputType` là `insertFromPaste`

Lưu ý

- Với tiếng Việt dùng bộ gõ, `input` bắn nhiều lần trong lúc ghép dấu; kiểm tra `e.isComposing` hoặc dùng `compositionend` khi cần
- Dùng `e.target.value` để lấy nội dung hiện tại

Sự kiện `change` xảy ra khi giá trị được xác nhận: với ô văn bản là khi người dùng rời ô (mất focus) sau khi đã sửa; với `checkbox`, `radio`, `select` và ô chọn tệp là ngay lúc chọn. Phù hợp cho các lựa chọn rời rạc, còn gõ liên tục nên dùng `input`.

<select id="tp"><option value="hn">Hà Nội</option><option value="dn">Đà Nẵng</option></select>
<input id="dy" type="checkbox">

document.getElementById('tp').addEventListener('change', (e) => {
  console.log('thành phố:', e.target.value);
});
document.getElementById('dy').addEventListener('change', (e) => {
  console.log('đồng ý:', e.target.checked);
});

Kết quả

- Chọn "Đà Nẵng" trong danh sách: in `thành phố: dn`
- Bấm vào hộp kiểm: in `đồng ý: true`, bấm lần nữa in `đồng ý: false`
- Với ô văn bản, `change` chỉ bắn khi rời ô sau khi giá trị đã khác lúc vào

Lưu ý

- Gán `el.value = ...` bằng code không bắn `change` hay `input`; muốn thì tự `dispatchEvent(new Event('change'))`
- Với `radio`, `change` chỉ bắn trên nút mới được chọn

Sự kiện `submit` xảy ra trên phần tử `<form>` khi người dùng gửi biểu mẫu (bấm nút gửi hoặc Enter trong ô nhập). Mặc định trình duyệt tải lại trang tới `action`; gọi `e.preventDefault()` để chặn và tự xử lý bằng JavaScript (kiểm tra, gọi `fetch`). Lắng nghe trên `form` chứ không phải trên nút gửi. Lấy dữ liệu bằng `new FormData(form)`.

<form id="dk">
  <input name="email" type="email" required>
  <input name="tuoi" type="number">
  <button>Gửi</button>
</form>

const form = document.getElementById('dk');
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const du_lieu = Object.fromEntries(new FormData(form));
  console.log(du_lieu);
});

Kết quả

- Nhập `an@example.com` và `20` rồi gửi: in `{ email: 'an@example.com', tuoi: '20' }` (mọi giá trị là chuỗi)
- Trang không tải lại nhờ `preventDefault()`
- Nếu `email` bỏ trống, trình duyệt tự báo lỗi `required` và không bắn `submit`

Lưu ý

- Lắng nghe trên `<form>`: bắt cả trường hợp gửi bằng phím Enter
- Dùng `form.requestSubmit()` để gửi bằng code mà vẫn chạy kiểm tra hợp lệ và bắn sự kiện

Sự kiện `keydown` bắn khi nhấn một phím (và lặp lại nếu giữ), `keyup` khi thả. Đối tượng `KeyboardEvent` có `key` (giá trị ký tự hoặc tên phím như `'Enter'`, `'Escape'`, `'ArrowUp'`), `code` (vị trí phím vật lý như `'KeyA'`, không đổi theo bố cục bàn phím), cùng `ctrlKey`, `shiftKey`, `altKey`, `metaKey` và `repeat`. Dùng làm phím tắt và điều hướng bàn phím; không dùng để đọc nội dung ô nhập (dùng `input`).

document.addEventListener('keydown', (e) => {
  if (e.ctrlKey && e.key === 's') {
    e.preventDefault();
    console.log('lưu bằng phím tắt');
  } else if (e.key === 'Escape') {
    console.log('đóng hộp thoại');
  } else if (e.code === 'KeyW') {
    console.log('tiến lên', e.key, e.repeat);
  }
});

Kết quả

- Nhấn Ctrl+S: in `lưu bằng phím tắt` và trình duyệt không mở hộp thoại lưu trang
- Nhấn Esc: in `đóng hộp thoại`
- Nhấn phím W: in `tiến lên w false`; giữ phím in thêm các dòng với `repeat` là `true`
- Trên bàn phím AZERTY, phím vật lý ở vị trí W cho `e.code` là `KeyW` nhưng `e.key` có thể khác

Lưu ý

- `e.key` đổi theo ngôn ngữ và phím Shift; `e.code` ổn định cho trò chơi và phím tắt theo vị trí
- Bỏ qua phím tắt khi đang gõ trong ô nhập: kiểm tra `e.target.matches('input, textarea')`

Sự kiện `scroll` bắn liên tục khi cuộn trang hoặc một phần tử có thanh cuộn. Vì bắn rất dày, handler phải nhẹ: tránh đọc bố cục nặng và tránh cập nhật DOM nhiều. Có thể gắn `{ passive: true }`. Với các việc như "tải thêm khi cuộn tới cuối" hay "hiện nút lên đầu trang", nên dùng `IntersectionObserver` thay vì tự tính vị trí trong `scroll`. Vị trí cuộn đọc từ `window.scrollY` hoặc `el.scrollTop`.

const nutLen = document.getElementById('len-dau');
window.addEventListener(
  'scroll',
  () => {
    nutLen.hidden = window.scrollY < 300;
    console.log(Math.round(window.scrollY));
  },
  { passive: true }
);
nutLen.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));

Kết quả

- Cuộn xuống 150px: in `150`, nút vẫn ẩn (`hidden` là `true`)
- Cuộn xuống 400px: in `400`, nút hiện ra (`hidden` là `false`)
- Bấm nút: trang cuộn mượt về đầu, handler in các vị trí giảm dần về `0`

Lưu ý

- Handler `scroll` chạy trên luồng chính; công việc nặng làm giật; dùng `requestAnimationFrame` hoặc throttle
- `scrollend` là sự kiện mới báo khi dừng cuộn (trình duyệt hiện đại)

`DOMContentLoaded` bắn trên `document` khi HTML đã được phân tích xong và cây DOM sẵn sàng, không chờ ảnh, stylesheet con hay iframe. Sự kiện `load` trên `window` bắn muộn hơn, khi mọi tài nguyên đã tải. Nếu đặt `<script>` ở cuối `<body>` hoặc dùng `defer`, hay module ES thì DOM đã sẵn khi script chạy nên thường không cần lắng nghe; code chạy ở mọi thời điểm kiểm tra bằng `document.readyState`.

console.log(document.readyState);
document.addEventListener('DOMContentLoaded', () => {
  console.log('DOM sẵn sàng', document.readyState);
});
window.addEventListener('load', () => console.log('mọi tài nguyên đã tải'));
function khiSanSang(fn) {
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fn);
  else fn();
}
khiSanSang(() => console.log('chạy đúng lúc'));

Kết quả

- Script trong `<head>` không `defer`: `readyState` in `loading`, sau đó in `DOM sẵn sàng interactive`, rồi `chạy đúng lúc`, cuối cùng `mọi tài nguyên đã tải`
- Script có `defer`, ở cuối body hoặc là module: `readyState` đã là `interactive`, `chạy đúng lúc` in ngay

Lưu ý

- Thuộc tính `defer` hay `type="module"` thường thay thế được việc phải chờ `DOMContentLoaded`
- Tránh `window.onload` cho khởi tạo giao diện vì phải chờ cả ảnh lớn

Sự kiện `resize` bắn trên `window` khi kích thước cửa sổ trình duyệt đổi và bắn dày khi người dùng kéo. Dùng để tính lại bố cục bằng JavaScript (canvas, biểu đồ). Để theo dõi kích thước một phần tử cụ thể dùng `ResizeObserver`; để phản ứng theo điểm ngắt của giao diện dùng `window.matchMedia('(min-width: 768px)')`. Nên throttle hoặc debounce handler.

const doiBoCuc = () => console.log(`${window.innerWidth} x ${window.innerHeight}`);
window.addEventListener('resize', doiBoCuc);
const dienThoai = window.matchMedia('(max-width: 600px)');
const capNhat = (e) => console.log(e.matches ? 'điện thoại' : 'máy tính');
dienThoai.addEventListener('change', capNhat);
capNhat(dienThoai);

Kết quả

- Cửa sổ rộng 1200px: `capNhat` in `máy tính`
- Kéo cửa sổ nhỏ hơn 600px: `matchMedia` bắn `change` đúng một lần và in `điện thoại`, trong khi `resize` in liên tục các kích thước như `598 x 800`

Lưu ý

- `matchMedia` chỉ báo khi vượt điểm ngắt nên nhẹ hơn nhiều so với lắng nghe `resize`
- Theo dõi kích thước phần tử (không phải cửa sổ) dùng `ResizeObserver`

`console.log(...cacGiaTri)` in các giá trị cách nhau bằng dấu cách. Nhận số đối số tùy ý, mọi kiểu dữ liệu; chuỗi đầu tiên có thể chứa `%s` (chuỗi), `%d` (số), `%i`, `%f`, `%o`/`%O` (object), `%c` (CSS ở trình duyệt). Trả về `undefined`. Cách gỡ lỗi nhanh nhất; nhớ rằng kết quả tùy môi trường hiển thị.

console.log('Xin chào');
console.log('a', 1, true, null, undefined);
console.log({ x: 1 }, [1, 2, 3]);
console.log('%s đã mua %d món', 'An', 3);
console.log();
const ten = 'An';
console.log({ ten });
console.log(`giá trị: ${ten}`);
const kq = console.log('x');
console.log(kq);

Kết quả

- `Xin chào`
- `a 1 true null undefined`
- `{ x: 1 } [ 1, 2, 3 ]`
- `An đã mua 3 món`
- Dòng trống (không đối số in một dòng rỗng)
- `{ name: 'An' }` (bọc trong object để in cả tên biến)
- `giá trị: An`
- `x`, rồi `undefined` vì `console.log` trả về `undefined`

Lưu ý

- Bọc biến trong object `{ name }` để in cả tên lẫn giá trị: `{ name: 'An' }`
- Gọi với nhiều đối số hơn dùng phép nối chuỗi để dễ đọc hơn
- Mọi `console.log` còn sót trong sản phẩm là rác; dùng ESLint `no-console`

`console.error(...)` in thông điệp ở mức lỗi: hiển thị màu đỏ trong DevTools (kèm vết gọi hàm) và ghi vào luồng lỗi `stderr` trong Node.js, nên có thể tách khỏi kết quả chương trình khi chuyển hướng. `console.warn` ở mức cảnh báo (vàng). Truyền đối tượng `Error` để in đầy đủ `stack`. Chúng không làm dừng chương trình.

console.error('Có lỗi xảy ra');
console.warn('Sắp hết dung lượng');
try {
  JSON.parse('{');
} catch (e) {
  console.error('Không đọc được JSON:', e.message);
}
const loi = new Error('hỏng');
console.error(loi);

Kết quả

- `Có lỗi xảy ra` hiện màu đỏ ở mức lỗi
- `Sắp hết dung lượng` hiện màu vàng ở mức cảnh báo
- `Không đọc được JSON: Expected property name or '}' in JSON at position 1` (nội dung thông báo tùy engine)
- `console.error(loi)` in `Error: hỏng` kèm vết gọi hàm (stack) đầy đủ
- Trong Node.js, các dòng `error` và `warn` đi vào `stderr`

Lưu ý

- Ghi log lỗi bằng `console.error(error)` truyền thẳng đối tượng `Error` thay vì chỉ `loi.message` để giữ `stack`
- Trong Node.js dùng `node app.js 2> loi.txt` để lưu riêng các dòng `error` và `warn`

`console.table(duLieu, cacCot)` in mảng object (hoặc object lồng) dưới dạng bảng có cột là các khóa, rất dễ đọc khi gỡ lỗi danh sách. Tham số thứ hai là mảng tên cột cần hiển thị. Hỗ trợ cả mảng hai chiều và `Map`/`Set`.

const sinhVien = [
  { ten: 'An', diem: 8 },
  { ten: 'Bình', diem: 6.5 },
  { ten: 'Chi', diem: 9 },
];
console.table(sinhVien);
console.table(sinhVien, ['ten']);
console.table([[1, 2], [3, 4]]);

Kết quả

- Lệnh đầu in bảng ba hàng với cột `(index)`, `ten`, `diem`: `0 An 8`, `1 Bình 6.5`, `2 Chi 9`
- Lệnh thứ hai chỉ hiện cột `ten`
- Mảng hai chiều in bảng với cột `0` và `1`: hàng `0` có `1 2`, hàng `1` có `3 4`

Lưu ý

- Trình duyệt hiển thị bảng có thể sắp xếp theo cột; Node.js in bảng bằng ký tự
- Phù hợp với danh sách vừa phải; với dữ liệu rất lớn bảng khó đọc

`console.time(nhan)` bắt đầu bộ đếm có nhãn, `console.timeLog(nhan)` in thời gian đã trôi qua mà không dừng, `console.timeEnd(nhan)` in và dừng. Đo nhanh thời gian chạy một đoạn code khi gỡ lỗi. Đo chính xác hơn dùng `performance.now()` (độ phân giải cao); đo benchmark nghiêm túc cần lặp nhiều lần để loại nhiễu của engine.

console.time('vong lap');
let tong = 0;
for (let i = 0; i < 1e7; i++) tong += i;
console.timeLog('vong lap');
console.timeEnd('vong lap');
const t0 = performance.now();
Array.from({ length: 1e5 }, (_, i) => i * 2);
const mili = performance.now() - t0;
console.log(mili > 0, typeof mili);

Kết quả

- `timeLog` in `vong lap: 8.35ms` (số cụ thể phụ thuộc máy)
- `timeEnd` in `vong lap: 8.4ms` rồi dừng bộ đếm, gọi lại báo cảnh báo không có bộ đếm
- `performance.now()` cho số thực tính bằng mili giây: in `true number`

Lưu ý

- Kết quả dao động mỗi lần chạy; chạy nhiều lần và dùng tab Performance của DevTools để phân tích sâu
- Nhãn phải khớp giữa `time` và `timeEnd`

`location.href` là chuỗi URL đầy đủ của trang; đọc để lấy địa chỉ hiện tại, ghi để chuyển trang (tương đương `location.assign(url)`). Khác `location.replace(url)` ở chỗ có lưu mục lịch sử nên nút Back quay lại được. Không tải được trang nếu URL dùng giao thức bị chặn (như `javascript:` trong nhiều ngữ cảnh).

console.log(location.href);
const url = new URL(location.href);
url.searchParams.set('trang', 2);
console.log(url.href);
location.href = 'https://example.com/ket-qua';
location.replace('/dang-nhap');

Kết quả

- Đọc `href`: in `https://example.com/tim?q=js`
- Dựng URL mới bằng `URL`: in `https://example.com/tim?q=js&trang=2`
- Gán `location.href` chuyển sang trang kết quả, thêm một mục lịch sử
- `location.replace('/dang-nhap')` chuyển sang trang đăng nhập nhưng không để lại mục lịch sử nên Back không về lại

Lưu ý

- Sau khi gán `href` code phía sau vẫn chạy cho tới khi trang thực sự chuyển
- Dùng `URL` và `URLSearchParams` để dựng URL thay vì nối chuỗi thủ công

`location.pathname` là phần đường dẫn của URL, bắt đầu bằng `/`, không gồm chuỗi truy vấn và hash. Là thứ router đọc để biết đang ở trang nào. Gán `location.pathname = '/moi'` chuyển trang trong cùng origin và giữ nguyên các phần khác.

// Trang: https://example.com/danh-muc/ao-so-mi?size=M#chi-tiet
console.log(location.pathname);
console.log(location.pathname.split('/').filter(Boolean));
const [mucLon, slug] = location.pathname.split('/').filter(Boolean);
console.log(mucLon, slug);
console.log(location.pathname.startsWith('/danh-muc'));

Kết quả

- `pathname` in `/danh-muc/ao-so-mi` (không có `?size=M` hay `#chi-tiet`)
- Tách thành các đoạn: `['danh-muc', 'ao-so-mi']`
- Destructuring: `danh-muc ao-so-mi`
- Kiểm tra tiền tố: `true`

Lưu ý

- Với ứng dụng triển khai dưới thư mục con (như GitHub Pages `/ten-repo/`), cần tính tiền tố cơ sở khi đọc đường dẫn
- Dùng thư viện router cho định tuyến phức tạp

`location.search` là chuỗi truy vấn gồm cả dấu `?` đầu (chuỗi rỗng nếu không có). Cách đọc đúng là bọc trong `URLSearchParams`, vốn tự giải mã `%20` và `+`. Ghi `location.search = '?x=1'` tải lại trang với truy vấn mới; để đổi mà không tải lại dùng `history.replaceState`.

// Trang: https://example.com/tim?q=xin%20ch%C3%A0o&loai=a&loai=b&trang=2
console.log(location.search);
const p = new URLSearchParams(location.search);
console.log(p.get('q'), p.get('trang'), typeof p.get('trang'));
console.log(p.getAll('loai'));
console.log(p.has('khong-co'), p.get('khong-co'));
console.log(Object.fromEntries(p));
p.set('trang', 3);
history.replaceState(null, '', `${location.pathname}?${p}`);

Kết quả

- `search` in `?q=xin%20ch%C3%A0o&loai=a&loai=b&trang=2`
- `get('q')` tự giải mã: `xin chào`; `get('trang')` in `2` kiểu `string`
- `getAll('loai')` in `['a', 'b']`
- Khóa không có: `has` in `false`, `get` in `null`
- `Object.fromEntries` chỉ giữ giá trị cuối của khóa lặp (`loai` thành `b`)
- `replaceState` cập nhật thanh địa chỉ thành `/tim?q=xin+ch%C3%A0o&loai=a&loai=b&trang=3` mà không tải lại

Lưu ý

- Giá trị luôn là chuỗi; ép kiểu số khi cần
- `URLSearchParams` mã hóa khoảng trắng thành `+`, còn `encodeURIComponent` thành `%20`

`location.reload()` tải lại trang hiện tại như bấm nút làm mới; toàn bộ trạng thái JavaScript hiện có bị mất. Trình duyệt hiện đại ưu tiên dùng bộ nhớ đệm tùy tiêu đề HTTP. Hiếm khi cần: thay vì tải lại hãy cập nhật giao diện bằng JavaScript, hoặc dùng `location.href = location.href` khi muốn tải lại kèm xử lý đặc biệt.

const nutLamMoi = document.getElementById('lam-moi');
nutLamMoi.addEventListener('click', () => location.reload());
window.addEventListener('beforeunload', () => console.log('sắp tải lại hoặc rời trang'));
sessionStorage.setItem('daLamMoi', '1');
console.log(performance.getEntriesByType('navigation')[0]?.type);

Kết quả

- Bấm nút: trang tải lại, toàn bộ biến bị đặt lại
- Trước khi tải lại in `sắp tải lại hoặc rời trang`
- `sessionStorage` vẫn còn sau khi tải lại (cùng tab)
- Sau khi tải lại, loại điều hướng in `reload`

Lưu ý

- Tải lại xóa trạng thái trong bộ nhớ: lưu cần thiết vào `sessionStorage` hoặc URL trước
- Gắn `beforeunload` làm hỏng bộ nhớ đệm đi lui/tiến; chỉ dùng khi cần cảnh báo mất dữ liệu

`history.pushState(state, tieuDe, url)` thêm một mục mới vào lịch sử và đổi URL hiển thị mà không tải lại trang hay gửi yêu cầu. `state` là dữ liệu tùy ý lưu cùng mục (lấy lại bằng `history.state` hoặc `e.state` của `popstate`); `tieuDe` hiện bị bỏ qua (truyền chuỗi rỗng). `replaceState` cùng tham số nhưng thay mục hiện tại thay vì thêm. Không bắn `popstate`; tự vẽ lại giao diện.

function dieuHuong(duongDan, state = {}) {
  history.pushState(state, '', duongDan);
  veTrang(duongDan);
}
const veTrang = (p) => console.log('vẽ', p);
document.addEventListener('click', (e) => {
  const lk = e.target.closest('a[data-link]');
  if (!lk) return;
  e.preventDefault();
  dieuHuong(lk.getAttribute('href'), { tu: location.pathname });
});
dieuHuong('/gioi-thieu');
console.log(history.state);

Kết quả

- Gọi `dieuHuong('/gioi-thieu')` in `vẽ /gioi-thieu`, URL trên thanh địa chỉ đổi mà không tải lại
- `history.state` in `{}` cho mục vừa thêm
- Bấm vào liên kết có `data-link`: ngăn điều hướng mặc định, URL đổi và vẽ lại trang tương ứng

Lưu ý

- URL truyền vào phải cùng origin, nếu không ném `SecurityError`
- Phải xử lý nút Back và Forward bằng sự kiện `popstate`

`history.back()` giống bấm nút Back của trình duyệt: lùi một mục lịch sử; `history.forward()` tiến một mục; `history.go(n)` đi `n` mục (âm là lùi, `0` là tải lại). Thao tác này bất đồng bộ: URL và nội dung chỉ đổi sau khi trình duyệt xử lý, và sẽ bắn `popstate` khi cùng tài liệu. Nếu không còn mục để quay lại thì không làm gì.

document.getElementById('quay-lai').addEventListener('click', () => {
  if (history.length > 1) history.back();
  else location.href = '/';
});
window.addEventListener('popstate', () => console.log('đã quay lại', location.pathname));
history.go(-2);
history.forward();

Kết quả

- Bấm nút khi lịch sử có nhiều mục: lùi một trang; nếu không, chuyển về trang chủ
- Với các mục cùng ứng dụng một trang, in `đã quay lại /san-pham/1`
- `history.go(-2)` lùi hai mục, `history.forward()` tiến một mục

Lưu ý

- Không thể đọc nội dung hay URL của các mục lịch sử khác (bảo mật)
- `history.length` tính cả mục trang khác nên không chính xác để biết "còn trang trước trong ứng dụng"

`navigator.clipboard` cho phép ghi và đọc bảng nhớ tạm hệ thống bằng Promise: `writeText(chuoi)`, `readText()`, và `write()`/`read()` cho dữ liệu giàu (ảnh). Chỉ chạy trên ngữ cảnh an toàn (HTTPS hay localhost) và thường cần thao tác của người dùng (bấm nút); đọc còn cần cấp quyền. Cách làm nút "Sao chép" đơn giản và đúng.

const nut = document.getElementById('sao-chep');
nut.addEventListener('click', async () => {
  try {
    await navigator.clipboard.writeText('https://example.com/moi-ban-be');
    nut.textContent = 'Đã sao chép';
    console.log('đã ghi vào bảng nhớ tạm');
  } catch (e) {
    console.log('không được phép:', e.name);
  }
});
const doc = async () => console.log(await navigator.clipboard.readText());

Kết quả

- Bấm nút trên trang HTTPS: bảng nhớ tạm chứa đường dẫn, nút đổi chữ và in `đã ghi vào bảng nhớ tạm`
- Gọi ngoài thao tác của người dùng hoặc không có quyền: in `không được phép: NotAllowedError`
- `readText()` hỏi quyền người dùng rồi in nội dung bảng nhớ tạm

Lưu ý

- Không dùng được trên trang HTTP thường (ngoài localhost)
- Phương án cũ `document.execCommand('copy')` đã lỗi thời

`navigator.geolocation` lấy vị trí địa lý người dùng sau khi họ đồng ý: `getCurrentPosition(thanhCong, loi, tuyChon)` lấy một lần, `watchPosition` theo dõi liên tục (huỷ bằng `clearWatch`). Kết quả có `coords.latitude`, `coords.longitude`, `coords.accuracy` (mét). Chỉ chạy trên HTTPS. Luôn xử lý trường hợp từ chối quyền hoặc hết thời gian.

navigator.geolocation.getCurrentPosition(
  (viTri) => {
    const { latitude, longitude, accuracy } = viTri.coords;
    console.log(latitude.toFixed(2), longitude.toFixed(2), accuracy);
  },
  (loi) => console.log(loi.code, loi.message),
  { enableHighAccuracy: true, timeout: 5000, maximumAge: 60000 }
);

Kết quả

- Người dùng đồng ý: in vĩ độ, kinh độ và độ chính xác, ví dụ `21.03 105.85 35`
- Người dùng từ chối: in `1 User denied Geolocation` (mã 1 là từ chối quyền)
- Quá thời hạn 5 giây: in `3 Timeout expired`

Lưu ý

- Chỉ xin vị trí khi thật cần và giải thích lý do trước khi hỏi quyền
- Dữ liệu vị trí là nhạy cảm, đừng gửi lên máy chủ nếu không cần

`navigator.userAgent` là chuỗi tự nhận diện của trình duyệt (tên, phiên bản, hệ điều hành, engine). Chuỗi này phức tạp và dễ bị giả mạo, trình duyệt còn cố ý giảm bớt thông tin, nên đoán trình duyệt theo nó thường sai. Nên kiểm tra tính năng trực tiếp (`'IntersectionObserver' in window`) hoặc truy vấn media; chỉ dùng `userAgent` để ghi thống kê.

console.log(typeof navigator.userAgent);
console.log(navigator.userAgent.includes('Mozilla'));
console.log('IntersectionObserver' in window);
console.log(CSS.supports('display', 'grid'));
console.log(navigator.userAgentData?.mobile);
console.log(window.matchMedia('(pointer: coarse)').matches);

Kết quả

- `typeof` in `string`
- Gần như mọi trình duyệt đều có `Mozilla` trong chuỗi (di sản lịch sử): in `true`
- Kiểm tra tính năng đáng tin cậy hơn: in `true true` trên trình duyệt hiện đại
- `userAgentData.mobile` in `false` trên máy tính (chỉ có ở trình duyệt nhân Chromium)
- Truy vấn con trỏ cảm ứng thô: `true` trên điện thoại, `false` với chuột

Lưu ý

- Không rẽ nhánh chức năng theo `userAgent`; dùng kiểm tra tính năng và truy vấn media
- Chuỗi `userAgent` sẽ còn bị đóng băng thêm theo chính sách riêng tư

`setTimeout(ham, ms, ...doiSo)` chạy hàm một lần sau ít nhất `ms` mili giây và trả về một số id (trong trình duyệt) để hủy bằng `clearTimeout(id)`. Thời gian là tối thiểu vì phải chờ tới lượt trong event loop. `setTimeout(ham, 0)` đẩy hàm ra sau khi code đang chạy và các microtask xong, thường dùng để "nhường" luồng chính cho trình duyệt vẽ lại.

console.log('A');
const id = setTimeout(() => console.log('C - sau 100ms'), 100);
setTimeout(() => console.log('B - sau 0ms'), 0);
setTimeout((ten, tuoi) => console.log('đối số:', ten, tuoi), 10, 'An', 20);
console.log(typeof id);
const huy = setTimeout(() => console.log('không in'), 50);
clearTimeout(huy);
console.log('D');

Kết quả

- In ngay: `A`, `number`, `D`
- Sau đó `B - sau 0ms`, rồi `đối số: An 20` (sau 10ms), rồi `C - sau 100ms`
- Hẹn giờ đã bị `clearTimeout` không bao giờ chạy: không in `không in`

Lưu ý

- Hàm truyền vào `setTimeout` có `this` là `window` ở hàm thường; dùng hàm mũi tên hoặc `bind` khi cần
- Trình duyệt giới hạn bộ hẹn giờ ở tab nền, và `setTimeout` lồng sâu có độ trễ tối thiểu khoảng 4ms

`setInterval(ham, ms)` chạy hàm lặp lại mỗi `ms` mili giây cho tới khi gọi `clearInterval(id)`. Không chờ lần chạy trước kết thúc, nên nếu hàm chạy lâu hơn chu kỳ thì các lần gọi chồng chất; với tác vụ bất đồng bộ nên dùng `setTimeout` đệ quy. Không dùng cho hoạt ảnh (dùng `requestAnimationFrame`), và nhớ hủy khi không cần nữa.

let dem = 0;
const id = setInterval(() => {
  dem++;
  console.log(`tick ${dem}`);
  if (dem === 3) {
    clearInterval(id);
    console.log('đã dừng');
  }
}, 100);
const thuLai = async () => {
  const ok = await goiApi();
  if (!ok) setTimeout(thuLai, 1000);
};

Kết quả

- Sau 100ms in `tick 1`, sau 200ms in `tick 2`, sau 300ms in `tick 3` và `đã dừng`
- Sau đó không còn tick nào nữa vì đã `clearInterval`
- Mẫu `setTimeout` đệ quy chỉ hẹn lần kế tiếp sau khi lần trước hoàn tất, không bị chồng

Lưu ý

- Tab ở chế độ nền có thể làm bộ hẹn giờ chạy thưa, nên không dùng để đếm thời gian chính xác; lưu mốc `Date.now()` rồi tính hiệu
- Luôn hủy bộ hẹn khi component bị gỡ để tránh rò rỉ

`map.set(khoa, giaTri)` thêm cặp mới hoặc cập nhật giá trị nếu khóa đã có, và trả về chính `Map` nên gọi nối tiếp được. Khóa so sánh theo "SameValueZero": `NaN` bằng `NaN`, nhưng hai object khác nhau là hai khóa.

const grades = new Map();
grades.set('An', 8).set('Bình', 6).set('An', 9);
console.log(grades);
console.log(grades.size);
grades.set(NaN, 'chưa có mã').set(NaN, 'vẫn là một khóa');
console.log(grades.get(NaN), grades.size);
const key = {};
grades.set(key, 'object');
console.log(grades.get(key), grades.get({}));
console.log(new Map().set(1, 'An') instanceof Map);

Kết quả

grades → Map(2) { 'An' => 9, 'Bình' => 6 }
grades.size → 2
grades.get(NaN), grades.size → 'vẫn là một khóa' 3
grades.get(key), grades.get({}) → 'object' undefined
new Map().set(1, 'An') instanceof Map → true

Tham số & trả về

khoa: khóa bất kỳ kiểu
giaTri: giá trị
Trả về: chính `Map`

Lưu ý

- Khóa đã tồn tại giữ nguyên vị trí cũ, chỉ đổi giá trị
- Khóa `0` và `-0` được coi là một

`map.get(khoa)` trả về giá trị ứng với khóa, hoặc `undefined` nếu khóa không có. Phân biệt "không có khóa" với "khóa có giá trị `undefined`" bằng `has()`. Phổ biến để tạo bộ đếm hoặc cache: `map.set(k, (map.get(k) ?? 0) + 1)`.

const grades = new Map([['An', 8], ['Bình', undefined]]);
console.log(grades.get('An'));
console.log(grades.get('Bình'));
console.log(grades.get('Chi'));
console.log(grades.has('Bình'), grades.has('Chi'));
const attendance = new Map();
for (const name of ['An', 'Bình', 'An', 'An']) attendance.set(name, (attendance.get(name) ?? 0) + 1);
console.log(attendance);
console.log(grades.get('Chi') ?? 'chưa có điểm');

Kết quả

grades.get('An') → 8
grades.get('Bình') → undefined
grades.get('Chi') → undefined
grades.has('Bình'), grades.has('Chi') → true false
attendance → Map(2) { 'An' => 3, 'Bình' => 1 }
grades.get('Chi') ?? 'chưa có điểm' → 'chưa có điểm'

Tham số & trả về

khoa: khóa cần tìm
Trả về: giá trị hoặc `undefined`

Lưu ý

- Dùng `has()` khi giá trị hợp lệ có thể là `undefined`
- Khóa là object phải truyền đúng tham chiếu

`map.has(khoa)` trả về `true` nếu khóa tồn tại, kể cả khi giá trị là `undefined`. Thời gian tra cứu gần như không đổi dù `Map` lớn, nhanh hơn `arr.includes()` khi dữ liệu nhiều.

const grades = new Map([['An', 8], ['Bình', undefined]]);
console.log(grades.has('An'));
console.log(grades.has('Bình'));
console.log(grades.has('Chi'));
console.log(grades.has(1));
const seen = new Map();
console.log(['An', 'Bình', 'An', 'Chi', 'Bình'].filter((n) => !seen.has(n) && seen.set(n, true)));

Kết quả

grades.has('An') → true
grades.has('Bình') → true
grades.has('Chi') → false
grades.has(1) → false
['An', 'Bình', 'An', 'Chi', 'Bình'].filter((n) => !seen.has(n) && seen.set(n, true)) →
  [ 'An', 'Bình', 'Chi' ]

Tham số & trả về

khoa: khóa cần kiểm tra
Trả về: `true` hoặc `false`

Lưu ý

- Với tập giá trị không cần cặp, dùng `Set` và `set.has()`

`map.delete(khoa)` xóa cặp có khóa đó và trả về `true` nếu khóa từng tồn tại. `map.clear()` xóa toàn bộ phần tử. Xóa trong lúc đang duyệt `Map` bằng `for...of` là an toàn.

const roster = new Map([['An', 8], ['Bình', 6], ['Chi', 9]]);
console.log(roster.delete('Bình'));
console.log(roster.delete('Dũng'));
console.log([...roster.keys()]);
for (const [name] of roster) if (name === 'An') roster.delete(name);
console.log([...roster.keys()]);
roster.clear();
console.log(roster.size);

Kết quả

roster.delete('Bình') → true
roster.delete('Dũng') → false
[...roster.keys()] → [ 'An', 'Chi' ]
[...roster.keys()] → [ 'Chi' ]
roster.size → 0

Tham số & trả về

khoa: khóa cần xóa
Trả về: `true` nếu có xóa, `false` nếu không có khóa

Lưu ý

- Với object phải dùng toán tử `delete obj.khoa`
- `clear()` không trả về gì (`undefined`)

`map.size` là số cặp hiện có trong `Map`. Khác `arr.length`, nó chỉ đọc (không gán được) và tính ngay chứ không phải đếm lại, kể cả với `Map` lớn. Tương tự có `set.size`.

const roster = new Map([['An', 8], ['Bình', 6]]);
console.log(roster.size);
roster.set('Chi', 9);
console.log(roster.size);
roster.delete('An');
console.log(roster.size);
roster.size = 100;
console.log(roster.size);
console.log(Object.keys({ An: 8 }).length);

Kết quả

roster.size → 2
roster.size → 3
roster.size → 2
roster.size → 2
Object.keys({ An: 8 }).length → 1

Lưu ý

- Gán vào `size` bị bỏ qua (hoặc ném lỗi ở strict mode)
- Với object phải dùng `Object.keys(obj).length`

`set.add(giaTri)` thêm giá trị vào tập hợp nếu chưa có và trả về chính `Set`, nên gọi nối tiếp được. Thêm giá trị đã tồn tại không có tác dụng và không đổi vị trí.

const classIds = new Set();
classIds.add(10).add(11).add(11).add('11');
console.log(classIds);
console.log(classIds.size);
const monitor = { name: 'An' };
classIds.add(monitor).add(monitor);
console.log(classIds.size);
console.log(classIds.add(99) === classIds);

Kết quả

classIds → Set(3) { 10, 11, '11' }
classIds.size → 3
classIds.size → 4
classIds.add(99) === classIds → true

Tham số & trả về

giaTri: giá trị cần thêm
Trả về: chính `Set`

Lưu ý

- `11` và `'11'` là hai giá trị khác nhau
- Thêm cùng một object nhiều lần chỉ giữ một

`set.has(giaTri)` trả về `true` nếu tập hợp chứa giá trị. Tra cứu rất nhanh bất kể kích thước, nên đổi mảng lớn sang `Set` khi cần kiểm tra thành viên nhiều lần.

const classIds = new Set([10, 11, 12]);
console.log(classIds.has(11));
console.log(classIds.has('11'));
console.log(classIds.has(13));
const absent = new Set(['Bình', 'Dũng']);
const roll = ['An', 'Bình', 'Chi', 'Dũng'];
console.log(roll.filter((name) => !absent.has(name)));
console.log(new Set([NaN]).has(NaN));

Kết quả

classIds.has(11) → true
classIds.has('11') → false
classIds.has(13) → false
roll.filter((name) => !absent.has(name)) → [ 'An', 'Chi' ]
new Set([NaN]).has(NaN) → true

Tham số & trả về

giaTri: giá trị cần kiểm tra
Trả về: `true` hoặc `false`

Lưu ý

- Tìm được cả `NaN`, khác `indexOf`

`set.delete(giaTri)` xóa giá trị và trả về `true` nếu có xóa. `set.clear()` xóa mọi phần tử. Dùng để theo dõi trạng thái "đang chọn" hay "đã thấy" mà có thể bỏ đi.

const selected = new Set(['An', 'Bình', 'Chi']);
console.log(selected.delete('Bình'));
console.log(selected.delete('Dũng'));
console.log([...selected]);
const toggle = (set, name) => (set.has(name) ? set.delete(name) : set.add(name));
toggle(selected, 'An');
toggle(selected, 'Em');
console.log([...selected]);
selected.clear();
console.log(selected.size);

Kết quả

selected.delete('Bình') → true
selected.delete('Dũng') → false
[...selected] → [ 'An', 'Chi' ]
[...selected] → [ 'Chi', 'Em' ]
selected.size → 0

Tham số & trả về

giaTri: giá trị cần xóa
Trả về: `true` nếu từng có, `false` nếu không

Lưu ý

- Mẫu "bật/tắt" phần tử trong tập hợp được dùng nhiều trong giao diện chọn nhiều mục

`set.size` là số phần tử duy nhất hiện có. Chỉ đọc. Đếm số giá trị khác nhau trong mảng: `new Set(mang).size`.

const names = new Set(['An', 'An', 'Bình', 'Chi']);
console.log(names.size);
names.add('Dũng');
console.log(names.size);
console.log(new Set([8, 8, 9, 7, 7]).size);
console.log(new Set('Anna').size);
console.log(new Set().size);

Kết quả

names.size → 3
names.size → 4
new Set([8, 8, 9, 7, 7]).size → 3
new Set('Anna').size → 3
new Set().size → 0

Lưu ý

- Đếm ký tự khác nhau trong chuỗi: `new Set(chuoi).size`

HỢP của các tập: mọi phần tử có trong ít nhất một tập. Toán tử tương đương: a | b.

a.union(b, ...)
a | b

Tham số & trả về

b...: iterable (với toán tử | thì phải là set)
Trả về: set MỚI

Ví dụ

a, b = {1, 2}, {2, 3}
a | b              # {1, 2, 3}
a.union([3, 4])    # {1, 2, 3, 4}

Khối else sau except chỉ chạy khi try KHÔNG có lỗi — tách phần "code có thể lỗi" khỏi phần "làm tiếp khi thành công".

try:
    x = int(chuoi)
except ValueError:
    print('Không phải số')
else:
    print('Bình phương:', x * x)   # chỉ chạy khi đổi kiểu thành công

Vì sao dùng else

- Giữ khối try thật ngắn: chỉ chứa đúng dòng có thể gây lỗi mình đang bắt
- Lỗi xảy ra trong khối else sẽ không bị except phía trên nuốt nhầm

Tạo loại lỗi riêng bằng cách kế thừa Exception, giúp người gọi bắt đúng lỗi nghiệp vụ của bạn.

class LoiNghiepVu(Exception):
    """Lỗi chung của ứng dụng."""

class KhongDuSoDu(LoiNghiepVu):
    def __init__(self, can, con):
        super().__init__(f'Cần {can}, chỉ còn {con}')
        self.can, self.con = can, con

try:
    raise KhongDuSoDu(500, 200)
except KhongDuSoDu as e:
    print(e, e.con)        # Cần 500, chỉ còn 200 200
except LoiNghiepVu:
    ...

Lưu ý

- Kế thừa Exception, không kế thừa BaseException (dành cho KeyboardInterrupt, SystemExit)
- Đặt một lỗi gốc cho cả ứng dụng để người dùng có thể bắt tất cả bằng một except

Biến một phần tử thành flex container: các con TRỰC TIẾP của nó xếp thành một hàng (mặc định) và có thể căn chỉnh, co giãn linh hoạt.

.hop { display: flex; }
.hop-nho { display: inline-flex; }   /* container nằm trên dòng như chữ */

Giá trị

flex: container dạng khối, chiếm cả chiều ngang
inline-flex: container chỉ rộng bằng nội dung, nằm cùng dòng với chữ

Ví dụ

.thanh-menu {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

Kết quả

.hop:        [con1][con2][con3]   <- con xếp ngang trên một dòng
.hop-nho:    chữ [con1][con2] chữ <- container nằm trong dòng chữ
.thanh-menu: [Logo]            [Menu]  <- hai đầu, căn giữa dọc

Lưu ý

- Chỉ các con TRỰC TIẾP mới là flex item; cháu bên trong không bị ảnh hưởng

Quy định TRỤC CHÍNH, tức hướng xếp các item.

flex-direction: row | row-reverse | column | column-reverse;

Giá trị

row (mặc định): trái sang phải
column: trên xuống dưới
row-reverse / column-reverse: đảo ngược thứ tự hiển thị

Ví dụ

.the { display: flex; flex-direction: column; gap: 8px; }
@media (min-width: 768px) {
  .bo-cuc { flex-direction: row; }   /* điện thoại xếp dọc, máy tính xếp ngang */
}

Kết quả

.the: các con xếp dọc, cách nhau 8px
.bo-cuc: điện thoại (< 768px) xếp dọc; máy tính xếp ngang

Lưu ý

- Đổi sang column thì justify-content căn theo chiều DỌC còn align-items căn theo chiều NGANG

Cho phép item XUỐNG DÒNG khi không đủ chỗ thay vì bị ép co lại trên một hàng.

flex-wrap: nowrap | wrap | wrap-reverse;

Giá trị

nowrap (mặc định): tất cả trên một dòng, item bị co lại
wrap: tràn thì xuống dòng mới

Ví dụ

.luoi-the {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}
.luoi-the > .the { flex: 1 1 240px; }   /* mỗi thẻ tối thiểu ~240px, tự xuống dòng */

Kết quả

Khung 800px, thẻ tối thiểu 240px:
[the][the][the]      <- 3 thẻ mỗi hàng, thẻ thứ 4 xuống dòng
Khung 500px:
[the    ][the    ]   <- 2 thẻ mỗi hàng, giãn cho kín

Lưu ý

- Viết tắt: flex-flow: row wrap; (= flex-direction + flex-wrap)

Căn các item theo TRỤC PHỤ (chiều dọc nếu flex-direction là row).

align-items: stretch | flex-start | center | flex-end | baseline;

Giá trị

stretch (mặc định): kéo giãn cao bằng container (nếu item không đặt height)
center: căn giữa theo chiều dọc
baseline: thẳng hàng theo đường chân chữ, hợp khi chữ các item có cỡ khác nhau

Ví dụ

.dong-thong-tin {
  display: flex;
  align-items: center;   /* icon và chữ thẳng hàng giữa */
  gap: 8px;
}

Kết quả

[icon] Địa chỉ giao hàng     <- icon 24px và chữ 16px thẳng hàng ở giữa
Không có align-items: center: icon lệch lên trên so với chữ

Căn và chia khoảng cách giữa CÁC DÒNG item theo trục phụ. Chỉ có tác dụng khi có nhiều dòng (flex-wrap: wrap).

align-content: stretch | flex-start | center | flex-end | space-between | space-around;

Giá trị

giống justify-content nhưng áp dụng cho các DÒNG theo trục phụ

Ví dụ

.gallery {
  display: flex;
  flex-wrap: wrap;
  height: 600px;
  align-content: flex-start;   /* các dòng dồn lên trên, không bị giãn cách */
}

Kết quả

Gallery cao 600px, ảnh chiếm 2 dòng:
flex-start: 2 dòng ảnh dồn lên trên, phần trống ở dưới
stretch (mặc định): 2 dòng giãn ra chia đôi 600px, có khe lớn giữa hai dòng

Lưu ý

- Hay nhầm với align-items: align-items căn item TRONG một dòng, align-content căn CÁC dòng với nhau

Biến phần tử thành grid container để xếp các con theo LƯỚI hai chiều: hàng và cột cùng lúc.

.luoi { display: grid; }

Giá trị

grid: container dạng khối; inline-grid: nằm trên dòng như chữ

Ví dụ

.trang {
  display: grid;
  grid-template-columns: 240px 1fr;
  gap: 24px;
}

Kết quả

.trang:
| 240px menu |   nội dung (phần còn lại)   |
            ^ khe 24px

Lưu ý

- Flexbox cho bố cục MỘT chiều (một hàng/cột), Grid cho bố cục HAI chiều (lưới, khung trang)

Định nghĩa số CỘT và độ rộng từng cột của lưới.

.a { display: grid; grid-template-columns: 200px 1fr 1fr; }
.bang-dieu-khien { display: grid; grid-template-columns: repeat(4, 1fr); }
.the-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); }

danh sách độ rộng, mỗi giá trị là một cột: px, %, fr, auto, minmax(), repeat()

Kết quả

.a trong 1000px:        200 | 400 | 400
.bang-dieu-khien:       4 ô thống kê bằng nhau trên một hàng
.the-list trong 800px:  4 cột 200px; trong 400px: 2 cột 200px

Đặt TÊN cho các vùng của lưới rồi "vẽ" bố cục bằng chữ, dễ đọc như sơ đồ.

grid-template-areas: "ten ten" "ten ten";
.item { grid-area: ten; }

Giá trị

mỗi chuỗi là một hàng; mỗi từ là một ô; dấu chấm . là ô trống

Ví dụ

.trang {
  display: grid;
  grid-template-columns: 220px 1fr;
  grid-template-areas:
    "header header"
    "menu   noidung"
    "footer footer";
}
header { grid-area: header; }
nav    { grid-area: menu; }
main   { grid-area: noidung; }
footer { grid-area: footer; }

Kết quả

+----------------------+
|        header        |
+--------+-------------+
|  menu  |   noidung   |
| 220px  |             |
+--------+-------------+
|        footer        |
+----------------------+
Đổi bố cục điện thoại: chỉ cần viết lại grid-template-areas trong @media

Lưu ý

- Đổi bố cục trên điện thoại chỉ cần viết lại grid-template-areas trong media query

Căn nội dung BÊN TRONG mỗi ô lưới: viết tắt cho align-items (dọc) và justify-items (ngang).

place-items: <align-items> <justify-items>;

Giá trị

start, center, end, stretch (mặc định)

Ví dụ

.giua-man-hinh {
  display: grid;
  place-items: center;   /* cách ngắn nhất để căn giữa một phần tử */
  min-height: 100vh;
}

Kết quả

- .giua-man-hinh: phần tử con nằm chính giữa màn hình cả ngang lẫn dọc, chỉ với 3 dòng CSS

Khoảng cách từ phần tử đã định vị tới cạnh tương ứng của mốc định vị.

top: 10px; right: 0; bottom: auto; left: 50%;
inset: 0;   /* viết tắt cả 4 cạnh */

Giá trị

độ dài, %, auto; % tính theo kích thước của mốc định vị

Ví dụ

.giua-tuyet-doi {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
}

Kết quả

- top 10px, right 0: dính mép phải, cách đỉnh 10px; left 50%: mép trái ở giữa cha
- .giua-tuyet-doi: nằm chính giữa cha (lùi lại nửa kích thước của chính nó)

Định nghĩa các "khung hình" của một hoạt ảnh: trạng thái ở từng mốc phần trăm thời gian.

@keyframes ten-hoat-anh {
  from { ... }    /* = 0% */
  50%  { ... }
  to   { ... }    /* = 100% */
}

Ví dụ

@keyframes nhap-nhay {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.2; }
}
@keyframes quay { to { transform: rotate(360deg); } }

Kết quả

- nhap-nhay: phần tử mờ xuống 20% rồi sáng lại, một chu kỳ
- quay: xoay tròn một vòng (chỉ cần khai báo "to", "from" lấy trạng thái hiện tại)
- Tự @keyframes không chạy gì — phải gắn qua thuộc tính animation

Lưu ý

- @keyframes chỉ định nghĩa; phải gắn vào phần tử bằng thuộc tính animation

Áp dụng một nhóm quy tắc CSS chỉ khi thiết bị thỏa điều kiện: độ rộng màn hình, hướng, chế độ tối...

@media (dieu-kien) { /* quy tắc */ }

Điều kiện hay dùng

(min-width: 768px): màn hình từ 768px trở lên
(orientation: portrait): màn hình dọc
(prefers-color-scheme: dark): người dùng bật chế độ tối
(hover: hover): thiết bị có chuột thật

Ví dụ

.luoi { display: grid; grid-template-columns: 1fr; }
@media (min-width: 768px)  { .luoi { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1200px) { .luoi { grid-template-columns: repeat(4, 1fr); } }

Kết quả

Kéo cửa sổ từ hẹp ra rộng:
< 768px   [1]
          [2]
768px+    [1][2]
1200px+   [1][2][3][4]

Lưu ý

- Viết kiểu "mobile first": CSS mặc định cho điện thoại, dùng min-width để mở rộng cho màn hình lớn

Giá trị nhỏ nhất / lớn nhất của một cột (số, chuỗi, ngày).

SELECT MIN(gia), MAX(gia) FROM products;
SELECT user_id, MAX(ngay) AS lan_mua_cuoi FROM orders GROUP BY user_id;

Kiểm tra giá trị có nằm trong một DANH SÁCH (hoặc kết quả subquery).

SELECT * FROM orders WHERE trang_thai IN ('moi', 'dang_giao');
SELECT * FROM users WHERE id IN (SELECT user_id FROM orders WHERE tong_tien > 1000000);

Lưu ý

- NOT IN với danh sách có NULL sẽ cho KẾT QUẢ RỖNG; an toàn hơn dùng NOT EXISTS

Kiểm tra giá trị rỗng (NULL). Không dùng được dấu = vì NULL = NULL không phải là đúng.

SELECT * FROM users WHERE so_dien_thoai IS NULL;
SELECT * FROM users WHERE so_dien_thoai IS NOT NULL;
SELECT ten, COALESCE(biet_danh, ten) AS hien_thi FROM users;   -- thay NULL bằng giá trị khác

Lưu ý

- WHERE cot = NULL luôn trả về rỗng: lỗi rất hay gặp

Cột (hoặc nhóm cột) định danh DUY NHẤT mỗi hàng: không trùng, không NULL. Mỗi bảng có đúng một khóa chính.

CREATE TABLE users (
  id INTEGER PRIMARY KEY,           -- tự tăng trong SQLite
  email TEXT NOT NULL
);
CREATE TABLE enrollments (
  student_id INT, course_id INT,
  PRIMARY KEY (student_id, course_id)   -- khóa chính ghép
);

Kiểu mảng mà mọi phần tử cùng kiểu T; hai cách viết tương đương.

const diem: number[] = [8, 9, 7];
const ten: Array<string> = ['An', 'Bình'];
const hon_hop: (string | number)[] = ['a', 1];
const coDinh: readonly number[] = [1, 2];   // không cho push, sửa

Lưu ý

- (string | number)[] là mảng chứa lẫn cả hai; string[] | number[] là mảng toàn chuỗi HOẶC toàn số

Mảng có SỐ PHẦN TỬ cố định và kiểu cụ thể ở TỪNG vị trí.

let toaDo: [number, number] = [10, 20];
let nguoi: [ten: string, tuoi: number] = ['An', 20];   // tuple có đặt tên
const [x, y] = toaDo;

function useDem(): [number, () => void] {   // giống useState của React
  let n = 0;
  return [n, () => n++];
}

Lưu ý

- Hàm trả về mảng cố định nên khai báo kiểu tuple hoặc dùng as const, nếu không TypeScript suy luận thành mảng thường

Kiểu "chưa biết" an toàn: nhận được mọi giá trị nhưng KHÔNG dùng được cho tới khi kiểm tra (thu hẹp) kiểu.

function xuLy(duLieu: unknown) {
  duLieu.toUpperCase();                 // Lỗi: chưa biết là gì
  if (typeof duLieu === 'string') {
    duLieu.toUpperCase();               // OK: đã thu hẹp thành string
  }
}
try { ... } catch (e) {                 // e mặc định là unknown
  if (e instanceof Error) console.log(e.message);
}

Lưu ý

- Dùng unknown cho dữ liệu từ bên ngoài (JSON.parse, API) rồi kiểm tra trước khi dùng

Kiểu KHÔNG BAO GIỜ có giá trị: hàm không bao giờ trả về (luôn ném lỗi, lặp vô hạn), hoặc nhánh code không thể xảy ra.

function baoLoi(msg: string): never {
  throw new Error(msg);
}

type Hinh = { loai: 'tron'; r: number } | { loai: 'vuong'; canh: number };
function dienTich(h: Hinh) {
  switch (h.loai) {
    case 'tron': return Math.PI * h.r ** 2;
    case 'vuong': return h.canh ** 2;
    default: const khongConGi: never = h;   // thêm loại mới mà quên xử lý -> lỗi biên dịch
  }
}

Kiểu trả về của hàm KHÔNG trả về giá trị gì có ý nghĩa.

function ghiLog(msg: string): void {
  console.log(msg);
}
const xuLy: (e: MouseEvent) => void = (e) => { /* ... */ };

Lưu ý

- Khác never: hàm void vẫn kết thúc bình thường (trả về undefined), hàm never thì không bao giờ kết thúc

Kiểu chỉ nhận ĐÚNG một giá trị cụ thể; kết hợp union để tạo tập giá trị cho phép (thay cho enum).

type HuongDi = 'bac' | 'nam' | 'dong' | 'tay';
let huong: HuongDi = 'bac';
huong = 'len';            // Lỗi: không nằm trong tập cho phép

type Size = 'sm' | 'md' | 'lg';
function nut(size: Size = 'md') { }

const CAU_HINH = { che_do: 'toi' } as const;   // che_do có kiểu 'toi', không phải string

Partial<T> biến MỌI thuộc tính của T thành tùy chọn (thêm dấu ?).

interface User { id: number; ten: string; email: string; }

function capNhat(id: number, thayDoi: Partial<User>) { /* ... */ }
capNhat(1, { email: 'moi@mail.com' });    // chỉ cần truyền trường muốn sửa

Lưu ý

- Chỉ áp dụng một tầng: object lồng bên trong vẫn giữ nguyên thuộc tính bắt buộc

Required<T> ngược với Partial: mọi thuộc tính đều BẮT BUỘC (bỏ dấu ?).

interface TuyChon { mau?: string; co?: number; }
const macDinh: Required<TuyChon> = { mau: 'xanh', co: 14 };   // phải đủ cả hai

Pick<T, K> tạo kiểu mới CHỈ GỒM các thuộc tính K được chọn từ T.

interface User { id: number; ten: string; email: string; matKhau: string; }
type TheUser = Pick<User, 'id' | 'ten'>;    // { id: number; ten: string }

Record<K, T> là kiểu object có key thuộc K và mọi giá trị đều kiểu T.

const diem: Record<string, number> = { an: 8, binh: 9 };

type TrangThai = 'moi' | 'dang_giao' | 'xong';
const nhan: Record<TrangThai, string> = {
  moi: 'Mới', dang_giao: 'Đang giao', xong: 'Hoàn tất',   // thiếu key nào sẽ báo lỗi
};

ReturnType<T> lấy ra kiểu TRẢ VỀ của một kiểu hàm; Parameters<T> lấy kiểu các tham số (dạng tuple).

function taoUser(ten: string, tuoi: number) {
  return { id: Date.now(), ten, tuoi };
}
type User = ReturnType<typeof taoUser>;      // { id: number; ten: string; tuoi: number }
type ThamSo = Parameters<typeof taoUser>;    // [ten: string, tuoi: number]

Lưu ý

- Nhớ typeof trước tên hàm: ReturnType cần một KIỂU, không phải một giá trị

Awaited<T> "mở" Promise để lấy kiểu giá trị bên trong (kể cả Promise lồng nhau).

async function layUser() { return { id: 1, ten: 'An' }; }
type KetQua = Awaited<ReturnType<typeof layUser>>;   // { id: number; ten: string }
type X = Awaited<Promise<Promise<number>>>;           // number

Kiểm tra map có chứa một key hay không.

map.containsKey(key)

Ví dụ

if (!cache.containsKey(id)) {
  cache.put(id, taiDuLieu(id));
}
cache.computeIfAbsent(id, k -> taiDuLieu(k));   // cùng ý tưởng, gọn hơn

Thêm phần tử vào cuối Vec (pop() lấy ra phần tử cuối, trả về Option).

v.push(phan_tu);
v.pop()   // Option<T>

Ví dụ

let mut so = Vec::new();   // phải có mut mới push được
so.push(1);
so.push(2);
if let Some(cuoi) = so.pop() {
    println!("lấy ra {cuoi}");
}
println!("{} phần tử", so.len());

Lưu ý

- Truy cập v[10] vượt quá độ dài sẽ panic; v.get(10) trả về Option an toàn hơn

Macro tạo nhanh một Vec với các phần tử khởi đầu.

let v = vec![1, 2, 3];
let khong = vec![0; 5];     // [0, 0, 0, 0, 0]

Ví dụ

let mut ten = vec![String::from("An"), String::from("Bình")];
ten.sort();
for t in &ten {             // mượn (&) để duyệt mà không lấy mất quyền sở hữu
    println!("{t}");
}

Chuỗi xử lý iterator: iter() tạo iterator, map()/filter() biến đổi (lười), collect() gom lại thành collection.

let ket_qua: Vec<_> = v.iter().map(|x| x * 2).collect();

Ví dụ

let so = vec![1, 2, 3, 4];
let chan_binh_phuong: Vec<i32> = so.iter()
    .filter(|&&x| x % 2 == 0)
    .map(|x| x * x)
    .collect();                               // [4, 16]
let tong: i32 = so.iter().sum();

Lưu ý

- iter() mượn phần tử (&T), into_iter() lấy quyền sở hữu, iter_mut() mượn để sửa
- collect() thường cần chú thích kiểu kết quả (Vec<_>, HashMap<_, _>...)

Lấy giá trị bên trong Option/Result; nếu là None/Err thì PANIC (dừng chương trình). expect() cho phép ghi thông báo lỗi.

let v = gia_tri.unwrap();
let v = gia_tri.expect("thông báo khi lỗi");

Ví dụ

let so: i32 = "42".parse().unwrap();
let cau_hinh = std::fs::read_to_string("config.toml")
    .expect("Không đọc được file config.toml");

Lưu ý

- Chỉ nên dùng trong ví dụ, test, hoặc khi CHẮC CHẮN không thể lỗi; code thật nên xử lý lỗi bằng ?, match hoặc unwrap_or

Đọc dữ liệu nhập từ bàn phím theo chuỗi định dạng; phải truyền ĐỊA CHỈ biến (&).

scanf("định dạng", &bien1, &bien2);

Tham số & trả về

Trả về: số biến đã đọc thành công (nên kiểm tra)

Ví dụ

int a, b;
if (scanf("%d %d", &a, &b) != 2) {
    printf("Nhập sai\n");
    return 1;
}
char ten[50];
scanf("%49s", ten);     // mảng đã là địa chỉ, không cần &; giới hạn độ dài để tránh tràn

Lưu ý

- %s dừng ở khoảng trắng; đọc cả dòng dùng fgets(ten, sizeof ten, stdin)

Trả về độ dài chuỗi, tính tới trước ký tự kết thúc '\0'.

#include <string.h>
size_t n = strlen(chuoi);

Ví dụ

char s[20] = "Xin chao";
strlen(s);        // 8
sizeof(s);        // 20 (kích thước mảng, không phải độ dài chuỗi)

Lưu ý

- strlen đếm BYTE: chuỗi UTF-8 có dấu tiếng Việt dài hơn số ký tự thấy được
- Gọi strlen trong điều kiện vòng for làm đếm lại mỗi vòng: lưu ra biến trước

Cấp phát một vùng nhớ trên HEAP với kích thước cho trước (byte), trả về con trỏ tới vùng đó.

T *p = malloc(so_phan_tu * sizeof *p);

Tham số & trả về

Trả về: con trỏ tới vùng nhớ, hoặc NULL nếu không đủ bộ nhớ
calloc(n, size): cấp phát và gán toàn bộ về 0; realloc(p, size): đổi kích thước

Ví dụ

int n = 100;
int *mang = malloc(n * sizeof *mang);
if (mang == NULL) { perror("malloc"); return 1; }
for (int i = 0; i < n; i++) mang[i] = i * i;
free(mang);

Lưu ý

- Vùng nhớ malloc chứa rác (giá trị ngẫu nhiên): khởi tạo trước khi đọc hoặc dùng calloc

Giải phóng vùng nhớ đã cấp phát bằng malloc/calloc/realloc.

free(p);
p = NULL;

Ví dụ

char *buf = malloc(256);
/* ... dùng buf ... */
free(buf);
buf = NULL;      // tránh vô tình dùng lại con trỏ đã giải phóng

Lưu ý

- Quên free: rò rỉ bộ nhớ (memory leak); free hai lần hoặc dùng sau khi free: hành vi không xác định, lỗi bảo mật
- free(NULL) là hợp lệ và không làm gì

Mảng ĐỘNG tự tăng kích thước — container dùng nhiều nhất trong C++.

std::vector<int> v = {3, 1, 2};
v.push_back(4);
v.size(); v[0]; v.at(0); v.back(); v.pop_back();

Ví dụ

#include <vector>
std::vector<std::string> ten;
ten.push_back("An");
ten.emplace_back("Bình");            // dựng tại chỗ, tránh tạo bản sao
for (const auto& t : ten) std::cout << t << "\n";

Lưu ý

- v[i] không kiểm tra giới hạn; v.at(i) có kiểm tra và ném exception
- push_back có thể cấp phát lại bộ nhớ, làm các con trỏ/iterator cũ trỏ vào vùng không hợp lệ

Map có key được SẮP XẾP (cây đỏ đen): tìm/thêm/xóa O(log n), duyệt theo thứ tự key.

std::map<std::string, int> diem;
diem["An"] = 8;
diem.insert({"Bình", 9});

Ví dụ

for (const auto& [ten, d] : diem)       // duyệt theo thứ tự key (C++17)
    std::cout << ten << ": " << d << "\n";
if (diem.count("Chi") == 0) { /* không có */ }
if (auto it = diem.find("An"); it != diem.end()) std::cout << it->second;

Lưu ý

- Đọc diem["Chi"] khi chưa có key sẽ TỰ TẠO key đó với giá trị 0; chỉ kiểm tra thì dùng find() hoặc contains() (C++20)

Map dựa trên bảng băm: tìm/thêm/xóa trung bình O(1), KHÔNG giữ thứ tự.

std::unordered_map<std::string, int> dem;
dem["go"]++;

Ví dụ

std::unordered_map<std::string, int> tanSuat;
for (const auto& tu : cacTu) tanSuat[tu]++;

Lưu ý

- Chọn unordered_map khi chỉ cần tra cứu nhanh; chọn map khi cần duyệt theo thứ tự key

Tập hợp các giá trị KHÔNG TRÙNG, được sắp xếp (unordered_set: không sắp xếp, nhanh hơn).

std::set<int> s = {3, 1, 3, 2};   // {1, 2, 3}
s.insert(5); s.erase(1); s.count(2);

Ví dụ

std::vector<int> v = {5, 1, 5, 2};
std::set<int> khongTrung(v.begin(), v.end());   // loại trùng và sắp xếp

Sắp xếp các phần tử trong một khoảng [begin, end) — mặc định tăng dần.

std::sort(v.begin(), v.end());
std::sort(v.begin(), v.end(), hamSoSanh);

Ví dụ

#include <algorithm>
std::vector<int> v = {3, 1, 2};
std::sort(v.begin(), v.end());                          // 1 2 3
std::sort(v.begin(), v.end(), std::greater<int>());     // 3 2 1
std::sort(sv.begin(), sv.end(), [](const SV& a, const SV& b) { return a.diem > b.diem; });
std::ranges::sort(v);                                   // C++20 gọn hơn

Lưu ý

- Hàm so sánh phải là "nhỏ hơn nghiêm ngặt" (trả false khi hai phần tử bằng nhau), viết <= có thể làm chương trình lỗi

Tìm phần tử ĐẦU TIÊN bằng giá trị (find_if: thỏa điều kiện) trong một khoảng; trả về iterator.

auto it = std::find(v.begin(), v.end(), gia_tri);

Ví dụ

auto it = std::find(v.begin(), v.end(), 42);
if (it != v.end()) std::cout << "vị trí " << (it - v.begin());
auto nguoiLon = std::find_if(ds.begin(), ds.end(), [](int t) { return t >= 18; });

Lưu ý

- Không tìm thấy thì trả về end(): luôn so sánh với end() trước khi dùng *it

Gộp các phần tử thành một giá trị (mặc định là tổng), giống reduce.

#include <numeric>
auto tong = std::accumulate(v.begin(), v.end(), 0);

Ví dụ

std::vector<double> gia = {1.5, 2.5};
double tong = std::accumulate(gia.begin(), gia.end(), 0.0);   // 4.0
int tich = std::accumulate(v.begin(), v.end(), 1, std::multiplies<int>());

Lưu ý

- Kiểu của giá trị ban đầu quyết định kiểu kết quả: truyền 0 (int) với vector<double> sẽ bị cắt mất phần thập phân

Giữ lại các phần tử thỏa điều kiện.

let ketQua = mang.filter { dieuKien($0) }

Ví dụ

let tuoi = [12, 25, 17, 30]
let nguoiLon = tuoi.filter { $0 >= 18 }    // [25, 30]
let coHetHang = gio.contains { $0.soLuong == 0 }

Gộp mảng thành một giá trị, bắt đầu từ giá trị khởi đầu.

let ketQua = mang.reduce(giaTriDau) { tichLuy, phanTu in ... }

Ví dụ

let tong = [1, 2, 3].reduce(0, +)               // 6
let tongTien = gio.reduce(0) { $0 + $1.gia * $1.soLuong }

sorted() trả về mảng MỚI đã sắp xếp; sort() sắp xếp tại chỗ (mảng phải là var).

let moi = mang.sorted()
let moi = mang.sorted { $0.diem > $1.diem }

Ví dụ

var ten = ["Chi", "An", "Bình"]
ten.sort()
let theoDiem = sv.sorted { $0.diem > $1.diem }

Tạo list mới bằng cách biến đổi từng phần tử; mapNotNull bỏ các kết quả null.

val moi = danhSach.map { it * 2 }

Ví dụ

val gia = listOf(100, 250, 80)
val coThue = gia.map { it * 1.1 }
val so = listOf("1", "x", "3").mapNotNull { it.toIntOrNull() }   // [1, 3]

Gom phần tử thành Map theo một khóa: mỗi khóa ứng với list các phần tử có khóa đó.

val nhom: Map<K, List<T>> = danhSach.groupBy { khoa(it) }

Ví dụ

data class SV(val ten: String, val lop: String)
val theoLop = svs.groupBy { it.lop }        // {10A=[...], 10B=[...]}
val theoTen = svs.associateBy { it.ten }    // Map ten -> SV (mỗi khóa một phần tử)

Chạy một khối lệnh cho từng phần tử.

danhSach.forEach { println(it) }
danhSach.forEachIndexed { i, x -> println("$i: $x") }

Ví dụ

listOf("An", "Bình").forEachIndexed { i, ten -> println("${i + 1}. $ten") }
for (ten in danhSach) println(ten)   // vòng for thường hỗ trợ break/continue

Lưu ý

- return bên trong forEach { } thoát khỏi CẢ hàm chứa nó; muốn bỏ qua phần tử hiện tại dùng return@forEach

Hooks là các hàm bắt đầu bằng `use` cho phép component hàm có state, hiệu ứng phụ, context, tham chiếu và tối ưu. Hai quy tắc bắt buộc: chỉ gọi hook ở cấp cao nhất của component (không trong `if`, vòng lặp hay hàm lồng) và chỉ gọi trong component hoặc hook tùy biến. React nhận ra từng hook theo thứ tự gọi, nên thứ tự đó phải y hệt giữa các lần render. Nhóm này gồm useState, useEffect, useContext, useRef, useMemo, useCallback, useReducer và hook tùy biến.

function Sai({ dangNhap }) {
  if (dangNhap) {
    const [ten, setTen] = useState('');
  }
  return null;
}

function Dung({ dangNhap }) {
  const [ten, setTen] = useState('');
  return dangNhap ? <p>{ten}</p> : null;
}

Kết quả

- `Sai`: hook nằm trong `if` nên thứ tự hook đổi giữa các lần render, React ném lỗi `Rendered more hooks than during the previous render`
- `Dung`: hook luôn được gọi, điều kiện đặt ở phần trả về nên chạy ổn định

Lưu ý

- Bật plugin `eslint-plugin-react-hooks` để phát hiện vi phạm tự động
- Đặt điều kiện bên trong hook hoặc ở JSX, không bao quanh lời gọi hook

`useContext(MyContext)` trả về `value` của Provider gần nhất phía trên trong cây; nếu không có Provider thì trả về giá trị mặc định đưa vào `createContext`. Component đọc context sẽ vẽ lại mỗi khi `value` đổi. Từ React 19 có thể dùng `use(MyContext)` và gọi được trong điều kiện.

import { createContext, useContext } from 'react';

const GiaoDien = createContext('sang');

function Nut() {
  const giaoDien = useContext(GiaoDien);
  return <button className={giaoDien}>Chế độ {giaoDien}</button>;
}

function App() {
  return (
    <GiaoDien.Provider value="toi">
      <Nut />
    </GiaoDien.Provider>
  );
}

Kết quả

- `Nut` bên trong Provider hiện `Chế độ toi` với class `toi`
- Nếu đặt `Nut` ngoài Provider, nó nhận giá trị mặc định `sang` và hiện `Chế độ sang`

Lưu ý

- Đặt `useContext` trong hook tùy biến để có thông báo lỗi rõ ràng khi thiếu Provider

`useRef(giaTriBanDau)` trả về object `{ current }` tồn tại suốt vòng đời component. Thay đổi `ref.current` không làm vẽ lại. Hai việc chính: giữ tham chiếu tới phần tử DOM (gắn qua thuộc tính `ref` để gọi `focus()`, đo kích thước, phát video) và lưu giá trị "ngoài giao diện" như id của timer hay giá trị trước đó. Đừng đọc hoặc ghi `ref.current` trong lúc render, chỉ làm trong effect và hàm xử lý sự kiện.

import { useRef, useEffect } from 'react';

function OTimKiem() {
  const oNhap = useRef(null);
  useEffect(() => {
    oNhap.current.focus();
  }, []);
  return <input ref={oNhap} placeholder="Tìm kiếm..." />;
}

Kết quả

- Khi trang mở, ô nhập tự nhận con trỏ (focus) vì `oNhap.current` trỏ tới phần tử `<input>` thật
- Gán `oNhap.current.value = ''` sửa ô nhập trực tiếp mà không kích hoạt vẽ lại

Lưu ý

- Nếu giá trị cần hiển thị lên màn hình thì dùng state, không dùng ref
- React 19 cho truyền `ref` như prop thường, không cần `forwardRef` nữa

`useMemo(() => tinh(a, b), [a, b])` ghi nhớ kết quả tính toán và chỉ tính lại khi `a` hoặc `b` đổi. Dùng khi phép tính thật sự nặng (lọc, sắp xếp, chuyển đổi danh sách lớn) hoặc khi cần giữ nguyên tham chiếu object/mảng truyền cho component con đã bọc `memo`. Đừng bọc mọi thứ: bản thân việc ghi nhớ cũng có chi phí. React Compiler mới có thể tự thêm ghi nhớ giúp bạn.

import { useMemo, useState } from 'react';

function DanhSach({ ds }) {
  const [tuKhoa, setTuKhoa] = useState('');
  const loc = useMemo(() => ds.filter((x) => x.includes(tuKhoa)), [ds, tuKhoa]);
  return (
    <>
      <input value={tuKhoa} onChange={(e) => setTuKhoa(e.target.value)} />
      <p>{loc.length} kết quả</p>
    </>
  );
}

Kết quả

- Với `ds = ['táo', 'cam', 'chanh']` và ô nhập rỗng hiện `3 kết quả`
- Gõ `ch` thì còn `1 kết quả` (chỉ `chanh`); phép lọc chạy lại vì `tuKhoa` đổi
- Khi component vẽ lại vì lý do khác (state không liên quan), `loc` lấy từ bộ nhớ đệm, không lọc lại

Lưu ý

- Đo hiệu năng trước khi tối ưu; `useMemo` không phải mặc định cần có
- Là gợi ý tối ưu chứ không đảm bảo ngữ nghĩa: code phải đúng ngay cả khi không có nó

`useCallback(fn, deps)` trả về cùng một hàm giữa các lần render chừng nào `deps` không đổi (tương đương `useMemo(() => fn, deps)`). Mỗi lần render, hàm tạo trong component là hàm MỚI; nếu truyền cho con bọc `React.memo` hoặc dùng làm phụ thuộc của `useEffect`, hàm mới sẽ kích hoạt vẽ lại hoặc chạy lại effect. `useCallback` giữ nguyên tham chiếu để tránh việc đó.

import { memo, useCallback, useState } from 'react';

const Nut = memo(function Nut({ khiBam }) {
  console.log('vẽ Nut');
  return <button onClick={khiBam}>+1</button>;
});

function BoDem() {
  const [dem, setDem] = useState(0);
  const tang = useCallback(() => setDem((d) => d + 1), []);
  return (
    <>
      <p>{dem}</p>
      <Nut khiBam={tang} />
    </>
  );
}

Kết quả

- `vẽ Nut` chỉ in một lần lúc đầu
- Bấm nút tăng số đếm lên 1, 2, 3...; `BoDem` vẽ lại nhưng `Nut` không vẽ lại vì `tang` giữ nguyên tham chiếu
- Bỏ `useCallback`, mỗi lần bấm sẽ in thêm `vẽ Nut` vì hàm mới mỗi lần

Lưu ý

- Chỉ hữu ích khi kết hợp với `memo` hoặc làm phụ thuộc của effect
- Dạng hàm `setDem((d) => d + 1)` giúp mảng phụ thuộc rỗng mà vẫn đúng

`useReducer(reducer, trangThaiDau)` là phương án thay cho `useState` khi state có nhiều phần liên quan hoặc nhiều cách thay đổi. `reducer(trangThai, hanhDong)` là hàm thuần trả về state mới; component gọi `dispatch({ type: ... })` để yêu cầu thay đổi. Logic cập nhật gom về một chỗ, dễ kiểm thử riêng và dễ đọc. Cùng ý tưởng với Redux nhưng ở phạm vi một component.

function reducer(state, action) {
  switch (action.type) {
    case 'add':
      return { ...state, roll: [...state.roll, action.name] };
    case 'remove':
      return { ...state, roll: state.roll.filter((x) => x !== action.name) };
    default:
      throw new Error(`Không biết hành động ${action.type}`);
  }
}
let s = { roll: [] };
s = reducer(s, { type: 'add', name: 'An' });
s = reducer(s, { type: 'add', name: 'Bình' });
console.log(s.roll);
s = reducer(s, { type: 'remove', name: 'An' });
console.log(s.roll);

Kết quả

s.roll → [ 'An', 'Bình' ]
s.roll → [ 'Bình' ]

Lưu ý

- Trong component: `const [state, dispatch] = useReducer(reducer, { roll: [] })`
- Reducer phải thuần: không sửa state cũ, không gọi API, không dùng ngẫu nhiên

Hook tùy biến là hàm có tên bắt đầu bằng `use` và gọi các hook khác bên trong, dùng để tái sử dụng LOGIC có trạng thái (không phải giao diện) giữa các component. Mỗi nơi gọi nhận state riêng. Ví dụ phổ biến: `useLocalStorage`, `useDebounce`, `useFetch`, `useMediaQuery`, `useOnlineStatus`.

import { useState, useEffect } from 'react';

function useLocalStorage(khoa, giaTriDau) {
  const [giaTri, setGiaTri] = useState(() => {
    const luu = localStorage.getItem(khoa);
    return luu ? JSON.parse(luu) : giaTriDau;
  });
  useEffect(() => {
    localStorage.setItem(khoa, JSON.stringify(giaTri));
  }, [khoa, giaTri]);
  return [giaTri, setGiaTri];
}

function CaiDat() {
  const [mau, setMau] = useLocalStorage('mau', 'sang');
  return <button onClick={() => setMau(mau === 'sang' ? 'toi' : 'sang')}>{mau}</button>;
}

Kết quả

- Lần đầu nút hiện `sang`; bấm đổi thành `toi` và giá trị được ghi vào `localStorage`
- Tải lại trang, nút vẫn hiện `toi` vì hook đọc lại từ `localStorage`
- Hai component cùng gọi `useLocalStorage` mỗi bên có state riêng (nhưng cùng khóa lưu)

Lưu ý

- Tên phải bắt đầu bằng `use` để ESLint kiểm tra quy tắc hook
- Hook tùy biến chia sẻ logic, không chia sẻ state; muốn chia sẻ state dùng context

`fs.readFile(duongDan, tuyChon)` đọc toàn bộ tệp vào bộ nhớ. Không truyền mã hóa thì nhận `Buffer`; truyền `'utf8'` (hoặc `{ encoding: 'utf8' }`) thì nhận chuỗi. Dạng nên dùng là `fs/promises`, đi cùng `await` và `try...catch`. Đường dẫn tương đối tính từ thư mục làm việc hiện tại (`process.cwd()`), không phải từ thư mục chứa tệp mã. Với tệp lớn nên đọc theo luồng (`createReadStream`) để không nạp hết vào bộ nhớ.

import { readFile } from 'node:fs/promises';
import { readFileSync } from 'node:fs';

const chu = await readFile('./ghi-chu.txt', 'utf8');
console.log(chu);
const buf = await readFile('./ghi-chu.txt');
console.log(buf instanceof Buffer, buf.length);
const cauHinh = JSON.parse(await readFile('./cau-hinh.json', 'utf8'));
console.log(cauHinh.cong);
try {
  await readFile('./khong-co.txt', 'utf8');
} catch (e) {
  console.log(e.code, e.syscall);
}
console.log(readFileSync('./ghi-chu.txt', 'utf8').length);

Kết quả

- Với tệp `ghi-chu.txt` chứa `Xin chào`: dòng đầu in `Xin chào`
- Không đặt mã hóa: in `true 9` (đối tượng `Buffer` có 9 byte vì chữ `à` chiếm 2 byte UTF-8)
- Đọc JSON rồi `JSON.parse`: in giá trị `cong`, ví dụ `3000`
- Tệp không tồn tại: in `ENOENT open`
- `readFileSync` chặn luồng đến khi đọc xong rồi in độ dài chuỗi: `8`

Lưu ý

- Hầu hết lỗi đọc file có `e.code`: `ENOENT` (không có), `EACCES` (không quyền), `EISDIR` (là thư mục)
- Không dùng dạng đồng bộ trong máy chủ xử lý nhiều yêu cầu vì chặn mọi người dùng khác
- Tệp rất lớn dùng `fs.createReadStream` hoặc `readline`

`fs.writeFile(duongDan, duLieu, tuyChon)` ghi chuỗi hoặc `Buffer` vào tệp, TẠO nếu chưa có và GHI ĐÈ nếu đã có. Thêm vào cuối tệp dùng `appendFile` hoặc `{ flag: 'a' }`; chỉ tạo khi chưa tồn tại dùng `{ flag: 'wx' }`. Với object cần `JSON.stringify` trước. Để tránh tệp bị hỏng khi tiến trình dừng giữa chừng, ghi ra tệp tạm rồi `rename` đè lên tệp đích.

import { writeFile, appendFile, readFile } from 'node:fs/promises';

await writeFile('./nhat-ky.txt', 'dòng 1\n');
await appendFile('./nhat-ky.txt', 'dòng 2\n');
console.log(JSON.stringify(await readFile('./nhat-ky.txt', 'utf8')));
await writeFile('./cau-hinh.json', JSON.stringify({ cong: 3000 }, null, 2));
await writeFile('./nhat-ky.txt', 'ghi đè\n');
console.log(await readFile('./nhat-ky.txt', 'utf8'));
try {
  await writeFile('./nhat-ky.txt', 'x', { flag: 'wx' });
} catch (e) {
  console.log(e.code);
}
await writeFile('./tam.bin', Buffer.from([1, 2, 3]));

Kết quả

- Sau `writeFile` và `appendFile`: in `"dòng 1\ndòng 2\n"`
- Tạo `cau-hinh.json` với nội dung JSON thụt lề hai khoảng trắng
- Ghi đè lần hai làm mất nội dung cũ: in `ghi đè`
- Cờ `wx` thất bại vì tệp đã có: in `EEXIST`
- Ghi `Buffer` tạo tệp `tam.bin` đúng 3 byte

Lưu ý

- Thư mục cha phải tồn tại; tạo bằng `mkdir(duongDan, { recursive: true })`
- Ghi đồng thời nhiều tiến trình vào cùng một tệp có thể lẫn dữ liệu; dùng khóa hoặc cơ sở dữ liệu

`path.join(...doan)` nối các đoạn đường dẫn bằng dấu phân cách của hệ điều hành và chuẩn hóa kết quả (bỏ `.`, xử lý `..`, bỏ dấu phân cách thừa). Nên luôn dùng nó thay vì nối chuỗi. Khác `path.resolve` ở chỗ không biến kết quả thành đường dẫn tuyệt đối. Dùng `path.posix.join` hoặc `path.win32.join` để ép kiểu đường dẫn cụ thể.

const path = require('path');
console.log(path.posix.join('truong', 'lop-10a1', 'diem.txt'));
console.log(path.posix.join('truong/lop-10a1', '../lop-10a2', './diem.txt'));
console.log(path.posix.join('/goc', 'a//b/'));
console.log(path.posix.join());
console.log(path.win32.join('C:\\truong', 'lop-10a1', 'diem.txt'));
console.log(path.posix.normalize('/a/./b/../c'));
console.log(path.posix.sep, path.win32.sep, path.posix.delimiter);
console.log('truong' + '/' + 'diem');

Kết quả

path.posix.join('truong', 'lop-10a1', 'diem.txt') → 'truong/lop-10a1/diem.txt'
path.posix.join('truong/lop-10a1', '../lop-10a2', './diem.txt') → 'truong/lop-10a2/diem.txt'
path.posix.join('/goc', 'a//b/') → '/goc/a/b/'
path.posix.join() → '.'
path.win32.join('C:\\truong', 'lop-10a1', 'diem.txt') → 'C:\\truong\\lop-10a1\\diem.txt'
path.posix.normalize('/a/./b/../c') → '/a/c'
path.posix.sep, path.win32.sep, path.posix.delimiter → '/' '\\' ':'
'truong' + '/' + 'diem' → 'truong/diem'

Lưu ý

- Truyền chuỗi rỗng bị bỏ qua; truyền không phải chuỗi ném `TypeError`
- Chuẩn hóa không bảo vệ khỏi path traversal: kiểm tra kết quả `resolve` còn nằm trong thư mục gốc cho phép

`process.env` là object chứa các biến môi trường của tiến trình; mọi giá trị luôn là CHUỖI (hoặc `undefined` nếu không có), kể cả khi trông như số hay boolean. Cách chuẩn để cấu hình ứng dụng theo môi trường (cổng, địa chỉ cơ sở dữ liệu, khóa API) mà không đưa vào mã nguồn. Có thể nạp từ tệp `.env` bằng cờ `node --env-file=.env` (Node.js 20 trở lên) hoặc thư viện `dotenv`. `NODE_ENV` thường là `development` hoặc `production`.

// chạy: PORT=8080 DEBUG=true node app.js
console.log(process.env.PORT, typeof process.env.PORT);
console.log(Number(process.env.PORT) + 1);
console.log(process.env.DEBUG === 'true', Boolean(process.env.DEBUG));
console.log(process.env.KHONG_CO);
const cong = Number(process.env.PORT ?? 3000);
console.log(cong);
process.env.TUY_CHINH = 42;
console.log(typeof process.env.TUY_CHINH);
console.log(process.env.NODE_ENV ?? 'chưa đặt');
if (!process.env.API_KEY) throw new Error('thiếu API_KEY');

Kết quả

- `process.env.PORT` in `8080 string`
- Chuyển số: `Number('8080') + 1` in `8081`
- `DEBUG` là chuỗi: so với `'true'` in `true`, `Boolean('true')` in `true`; ngay cả `DEBUG=false` cũng cho `Boolean` là `true`
- Biến không có: in `undefined`
- Có giá trị mặc định: in `8080`
- Gán số `42` cũng được lưu thành chuỗi: in `string`
- Thiếu `API_KEY`: ném lỗi `thiếu API_KEY` ngay lúc khởi động

Lưu ý

- Đừng đưa tệp `.env` thật vào kho mã nguồn; đưa `.env.example`
- Kiểm tra và ép kiểu mọi biến bắt buộc ngay khi khởi động (ví dụ với thư viện Zod)

`process.argv` là mảng các tham số dòng lệnh dạng chuỗi: phần tử 0 là đường dẫn trình `node`, phần tử 1 là đường dẫn tệp đang chạy, từ phần tử 2 trở đi là tham số của bạn. Dùng `process.argv.slice(2)` để lấy tham số người dùng. Với cờ và giá trị phức tạp dùng `util.parseArgs` (có sẵn từ Node.js 18.3) hoặc thư viện `commander`, `yargs`.

const argv = ['node', '/ung-dung/app.js', 'xin-chao', '--ten=An', '-v', '--cong', '8080'];
const thamSo = argv.slice(2);
console.log(thamSo);
const { parseArgs } = require('util');
const kq = parseArgs({
  args: thamSo,
  allowPositionals: true,
  options: {
    ten: { type: 'string' },
    v: { type: 'boolean', short: 'v' },
    cong: { type: 'string', default: '3000' },
  },
});
console.log(kq.values);
console.log(kq.positionals);
console.log(Number(kq.values.cong) + 1);
console.log(process.argv.length >= 2, typeof process.argv[0]);

Kết quả

thamSo → [ 'xin-chao', '--ten=An', '-v', '--cong', '8080' ]
kq.values → [Object: null prototype] { ten: 'An', v: true, cong: '8080' }
kq.positionals → [ 'xin-chao' ]
Number(kq.values.cong) + 1 → 8081
process.argv.length >= 2, typeof process.argv[0] → true 'string'

Lưu ý

- Giá trị luôn là chuỗi; tự ép kiểu số hoặc boolean
- Với ứng dụng CLI thực tế, dùng thư viện cho trợ giúp `--help`, kiểm tra và thông báo lỗi

Khi gặp tình huống không xử lý nổi, mã có thể "ném" (`throw`) một ngoại lệ, thường là đối tượng `Error`. Ngoại lệ làm dừng hàm hiện tại và lan ngược lên ngăn xếp gọi cho đến khi gặp khối `try...catch` bắt nó; nếu không ai bắt, chương trình dừng với lỗi chưa xử lý. Bắt lỗi ở nơi biết cách xử lý (hiển thị thông báo, thử lại, ghi log), đừng nuốt lỗi âm thầm. Lỗi trong mã bất đồng bộ cần xử lý riêng (`.catch` hoặc `try/await`).

function average(total, count) {
  if (count === 0) throw new RangeError('lớp chưa có học sinh');
  return total / count;
}
function report() {
  return average(80, 0);
}
try {
  report();
} catch (e) {
  console.log(e.name, e.message, e instanceof Error);
} finally {
  console.log('luôn chạy');
}
try {
  null.x;
} catch (e) {
  console.log(e.name);
}
console.log('chương trình vẫn tiếp tục');

Kết quả

e.name, e.message, e instanceof Error → 'RangeError' 'lớp chưa có học sinh' true
luôn chạy
e.name → 'TypeError'
chương trình vẫn tiếp tục

Lưu ý

- Luôn ném `Error` (hoặc lớp con), không ném chuỗi, để có `stack`
- Chi tiết từng phần: `try...catch...finally`, `throw`, `new Error()`, các loại lỗi dựng sẵn và lớp lỗi tùy chỉnh

Khối `finally` luôn chạy sau `try` và `catch`, dù có lỗi hay không, kể cả khi `try` hoặc `catch` đã `return`, `break` hay ném lỗi. Dùng để dọn dẹp tài nguyên (đóng file, tắt trạng thái đang tải, giải phóng khóa). Từ ES2019 có thể bỏ tên biến lỗi: `catch { ... }`. Có thể ném lại lỗi (`throw loi`) sau khi xử lý một phần để tầng trên tiếp tục xử lý.

function attempt(fail) {
  try {
    if (fail) throw new Error('hỏng');
    return 'try xong';
  } catch (e) {
    return `catch: ${e.message}`;
  } finally {
    console.log('finally luôn chạy');
  }
}
console.log(attempt(false));
console.log(attempt(true));
function override() {
  try {
    return 'từ try';
  } finally {
    return 'từ finally';
  }
}
console.log(override());
let isLoading = true;
try {
  throw new Error('mất kết nối bảng điểm');
} catch {
  console.log('có lỗi nhưng không cần biết chi tiết');
} finally {
  isLoading = false;
}
console.log(isLoading);
try {
  try {
    throw new TypeError('gốc');
  } catch (e) {
    console.log('xử lý một phần');
    throw e;
  }
} catch (e) {
  console.log('tầng ngoài nhận:', e.name);
}

Kết quả

finally luôn chạy
attempt(false) → 'try xong'
finally luôn chạy
attempt(true) → 'catch: hỏng'
override() → 'từ finally'
có lỗi nhưng không cần biết chi tiết
isLoading → false
xử lý một phần
tầng ngoài nhận: TypeError

Lưu ý

- `return` trong `finally` ghi đè mọi `return` hoặc lỗi trước đó: tránh làm vậy
- `catch` có thể bỏ tên biến khi không cần dùng đối tượng lỗi
- `try...finally` không có `catch` vẫn hợp lệ: lỗi tiếp tục nổi lên sau khi dọn dẹp

`throw giaTri` dừng hàm hiện tại và ném ngoại lệ lên các tầng gọi cho đến khi có `catch`. Về mặt cú pháp ném được bất kỳ giá trị nào (chuỗi, số, object) nhưng nên luôn ném đối tượng `Error` hoặc lớp con của nó, vì chỉ `Error` mang theo `stack` (vết gọi hàm) để gỡ lỗi. `throw` là câu lệnh, không dùng trực tiếp trong biểu thức; ngoài ra có thể bọc trong hàm.

try {
  throw 'một chuỗi';
} catch (e) {
  console.log(typeof e, e);
}
try {
  throw new Error('một Error');
} catch (e) {
  console.log(typeof e, e.message, typeof e.stack);
}
try {
  throw { code: 404 };
} catch (e) {
  console.log(e.code, e instanceof Error);
}
const required = (name) => {
  throw new TypeError(`thiếu tham số ${name}`);
};
const enroll = (student = required('student')) => student;
try {
  enroll();
} catch (e) {
  console.log(e.message);
}
console.log(enroll('An'));

Kết quả

typeof e, e → 'string' 'một chuỗi'
typeof e, e.message, typeof e.stack → 'object' 'một Error' 'string'
e.code, e instanceof Error → 404 false
e.message → 'thiếu tham số student'
enroll('An') → 'An'

Lưu ý

- Ném chuỗi hoặc object thường làm mất `stack` và làm `instanceof Error` sai
- Lỗi chưa được bắt làm chương trình dừng (Node.js) hoặc in lỗi ra console (trình duyệt)

`new Error(message, { cause })` tạo đối tượng lỗi với `message` (mô tả), `name` (loại lỗi, mặc định `'Error'`) và `stack` (chuỗi vết gọi hàm, không chuẩn hóa nhưng mọi engine đều có). Tùy chọn `cause` (ES2022) gắn lỗi gốc để giữ ngữ cảnh khi bọc lỗi. `String(loi)` cho `'Name: message'`. Có thể gọi `Error()` không cần `new` nhưng nên viết `new`.

const error = new Error('không lưu được điểm', { cause: 'mất kết nối' });
console.log(error.name, '|', error.message, '|', error.cause);
console.log(String(error));
console.log(error instanceof Error, Object.prototype.toString.call(error));
console.log(typeof error.stack, error.stack.split('\n')[0]);
console.log(Object.keys(error));
console.log(Object.getOwnPropertyNames(error).sort());
console.log(JSON.stringify(error));
console.log(JSON.stringify({ ...error, message: error.message }));
const e2 = new Error('A');
e2.name = 'ScoreError';
console.log(String(e2));

Kết quả

error.name, '|', error.message, '|', error.cause →
  'Error' '|' 'không lưu được điểm' '|' 'mất kết nối'
String(error) → 'Error: không lưu được điểm'
error instanceof Error, Object.prototype.toString.call(error) → true '[object Error]'
typeof error.stack, error.stack.split('\n')[0] → 'string' 'Error: không lưu được điểm'
Object.keys(error) → []
Object.getOwnPropertyNames(error).sort() → [ 'cause', 'message', 'stack' ]
JSON.stringify(error) → '{}'
JSON.stringify({ ...error, message: error.message }) → '{"message":"không lưu được điểm"}'
String(e2) → 'ScoreError: A'

Lưu ý

- `message`, `stack` là thuộc tính không đếm được nên `JSON.stringify(loi)` ra `{}`; tự chọn trường khi cần gửi đi
- `error.stack` hữu ích khi ghi log nhưng không nên hiển thị cho người dùng cuối

Tạo lớp lỗi riêng bằng `class LoiXacThuc extends Error` để phân biệt các tình huống nghiệp vụ và đính kèm dữ liệu bổ sung (mã lỗi, trường sai, mã HTTP). Nhớ gọi `super(message)`, đặt `this.name` (thường bằng `this.constructor.name`) và truyền `{ cause }` khi bọc lỗi gốc. Có thể phân loại bằng `instanceof` thay vì so sánh chuỗi thông điệp.

class AppError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = this.constructor.name;
  }
}
class ValidationError extends AppError {
  constructor(field, options) {
    super(`Trường "${field}" không hợp lệ`, options);
    this.field = field;
    this.code = 'E_VALIDATION';
  }
}
class NetworkError extends AppError {
  status = 503;
}
function handle(error) {
  if (error instanceof ValidationError) return `nhập sai: ${error.field}`;
  if (error instanceof NetworkError) return `mạng: ${error.status}`;
  return 'lỗi không rõ';
}
console.log(handle(new ValidationError('score')));
console.log(handle(new NetworkError('hết giờ')));
console.log(handle(new Error('khác')));
const e = new ValidationError('age', { cause: new RangeError('âm') });
console.log(e.name, e.code, e.cause.name);
console.log(e instanceof AppError, e instanceof Error, String(e));

Kết quả

handle(new ValidationError('score')) → 'nhập sai: score'
handle(new NetworkError('hết giờ')) → 'mạng: 503'
handle(new Error('khác')) → 'lỗi không rõ'
e.name, e.code, e.cause.name → 'ValidationError' 'E_VALIDATION' 'RangeError'
e instanceof AppError, e instanceof Error, String(e) →
  true true 'ValidationError: Trường "age" không hợp lệ'

Lưu ý

- Với lỗi chuyển qua mạng hoặc JSON, hãy thêm `toJSON()` để gửi đủ thông tin vì `message` và `stack` không được serialize mặc định
- Đừng tạo quá nhiều lớp lỗi: vài lớp theo nhóm xử lý (xác thực, mạng, không tìm thấy) là đủ

`ham.call(thisArg, ...doiSo)` gọi hàm ngay lập tức với giá trị `this` do bạn chỉ định và các đối số liệt kê từng cái. Dùng để "mượn" phương thức của object khác, gọi hàm cha trong cú pháp prototype cũ, hoặc dùng phương thức của mảng cho object giống mảng.

function introduce(greeting, mark) {
  return `${greeting}, tôi là ${this.name}${mark}`;
}
const an = { name: 'An' };
const binh = { name: 'Bình' };
console.log(introduce.call(an, 'Chào', '!'));
console.log(introduce.call(binh, 'Hi', '.'));
console.log(Array.prototype.map.call('An', (c) => c.toUpperCase()));
const bag = { 0: 'sách', 1: 'vở', length: 2 };
console.log(Array.prototype.join.call(bag, '-'));
console.log(Math.max.call(null, 8, 9, 7));

Kết quả

introduce.call(an, 'Chào', '!') → 'Chào, tôi là An!'
introduce.call(binh, 'Hi', '.') → 'Hi, tôi là Bình.'
Array.prototype.map.call('An', (c) => c.toUpperCase()) → [ 'A', 'N' ]
Array.prototype.join.call(bag, '-') → 'sách-vở'
Math.max.call(null, 8, 9, 7) → 9

Tham số & trả về

thisArg: giá trị `this` bên trong hàm
doiSo: các đối số, liệt kê từng cái
Trả về: kết quả của hàm được gọi

Lưu ý

- Hiện nay thường dùng spread và hàm mũi tên; `call` vẫn hữu ích khi mượn phương thức
- Ở chế độ không strict, `thisArg` là `null` hoặc `undefined` sẽ thành đối tượng toàn cục

`ham.apply(thisArg, mangDoiSo)` giống `call()` nhưng truyền các đối số dưới dạng một mảng (hoặc object giống mảng). Trước khi có spread, đây là cách truyền mảng thành danh sách đối số, ví dụ `Math.max.apply(null, mang)`. Nay `ham(...mang)` hoặc `ham.call(thisArg, ...mang)` gọn hơn.

function total(a, b, c) {
  return `${this.label}: ${a + b + c}`;
}
const context = { label: 'Tổng điểm' };
console.log(total.apply(context, [8, 9, 7]));
console.log(Math.max.apply(null, [8, 6, 9]));
console.log(Math.max(...[8, 6, 9]));
console.log(Array.prototype.concat.apply([], [['An'], ['Bình', 'Chi']]));
console.log(Math.min.apply(Math, [8, 3, 6]));

Kết quả

total.apply(context, [8, 9, 7]) → 'Tổng điểm: 24'
Math.max.apply(null, [8, 6, 9]) → 9
Math.max(...[8, 6, 9]) → 9
Array.prototype.concat.apply([], [['An'], ['Bình', 'Chi']]) → [ 'An', 'Bình', 'Chi' ]
Math.min.apply(Math, [8, 3, 6]) → 3

Tham số & trả về

thisArg: giá trị `this` bên trong hàm
mangDoiSo: mảng (hoặc object giống mảng) các đối số
Trả về: kết quả của hàm được gọi

Lưu ý

- `apply` với mảng quá lớn có thể vượt giới hạn số đối số của engine
- Trong code mới ưu tiên spread: `ham(...mang)`

`ham.bind(thisArg, ...doiSoDau)` trả về một hàm MỚI có `this` bị cố định vào `thisArg` (và các đối số đầu đã điền sẵn), không gọi hàm ngay. Cần khi truyền phương thức làm callback mà vẫn muốn giữ `this` đúng, ví dụ `setTimeout(obj.method.bind(obj), 100)`. Hàm đã bind không thể đổi `this` lần nữa bằng `call`, `apply` hay `bind`.

const student = {
  name: 'An',
  greet() {
    return `Xin chào, ${this.name}`;
  },
};
const detached = student.greet;
try {
  console.log(detached());
} catch (e) {
  console.log(e.name);
}
const bound = student.greet.bind(student);
console.log(bound());
const multiply = (a, b) => a * b;
const double = multiply.bind(null, 2);
console.log(double(21));
console.log(bound.call({ name: 'khác' }));
console.log(bound.name);
console.log(bound.length, double.length);

Kết quả

detached() → 'Xin chào, undefined'
bound() → 'Xin chào, An'
double(21) → 42
bound.call({ name: 'khác' }) → 'Xin chào, An'
bound.name → 'bound greet'
bound.length, double.length → 0 1

Tham số & trả về

thisArg: giá trị `this` cố định cho hàm mới
doiSoDau: các đối số điền sẵn
Trả về: hàm mới (bound function)

Lưu ý

- Hàm mũi tên không có `this` riêng nên `bind` không đổi được `this` của nó
- Trong lớp, hàm mũi tên làm trường class (`xuLy = () => ...`) là cách phổ biến thay `bind` trong constructor

`get ten() {}` và `set ten(v) {}` tạo accessor: đọc `obj.ten` gọi getter, gán `obj.ten = x` gọi setter, nhưng bề ngoài giống thuộc tính thường. Dùng để tính giá trị từ trạng thái khác, kiểm tra dữ liệu khi gán hoặc ẩn chi tiết bên trong. Thiếu setter thì thuộc tính chỉ đọc (gán bị bỏ qua, hoặc ném lỗi ở strict mode). Cũng dùng được trong object literal.

class Score {
  #value = 0;
  get value() {
    return this.#value;
  }
  set value(v) {
    if (typeof v !== 'number') throw new TypeError('phải là số');
    this.#value = v;
  }
  get percent() {
    return this.#value * 10;
  }
}
const s = new Score();
s.value = 8;
console.log(s.value, s.percent);
try {
  s.value = 'giỏi';
} catch (e) {
  console.log(e.name, e.message);
}
try {
  s.percent = 0;
} catch (e) {
  console.log(e.name);
}
const o = {
  lastName: 'Nguyễn',
  firstName: 'An',
  get fullName() {
    return `${this.lastName} ${this.firstName}`;
  },
};
console.log(o.fullName, Object.keys(o));

Kết quả

s.value, s.percent → 8 80
e.name, e.message → 'TypeError' 'phải là số'
o.fullName, Object.keys(o) → 'Nguyễn An' [ 'lastName', 'firstName', 'fullName' ]

Lưu ý

- Getter chạy mỗi lần đọc, nên đừng đặt tính toán nặng bên trong
- Accessor khai báo trong class nằm trên prototype nên không hiện trong `Object.keys()`; accessor của object literal thì có
- Tránh đặt tên trường trùng tên accessor (gây đệ quy vô hạn); dùng trường `#private` làm kho lưu

Thành viên `static` (phương thức, trường, getter) gắn vào chính lớp chứ không vào thể hiện, truy cập bằng `TenLop.thanhVien`. Dùng cho hàm tiện ích, hằng số, bộ đếm, và hàm nhà máy (factory) tạo thể hiện theo cách khác nhau. Lớp con kế thừa các thành viên tĩnh của lớp cha. Khối `static { }` (ES2022) cho phép chạy code khởi tạo phức tạp cho lớp.

class Seat {
  static #created = 0;
  static FIRST = new Seat(1, 1);
  constructor(row, col) {
    this.row = row;
    this.col = col;
    Seat.#created++;
  }
  static fromArray([row, col]) {
    return new this(row, col);
  }
  static get created() {
    return Seat.#created;
  }
  static {
    Seat.LABEL = 'ghế';
  }
}
console.log(Seat.fromArray([3, 4]));
console.log(Seat.FIRST, Seat.LABEL);
console.log(Seat.created);
const p = new Seat(2, 2);
console.log(p.fromArray, typeof Seat.fromArray);
class Desk extends Seat {}
console.log(Desk.fromArray([5, 6]) instanceof Desk);

Kết quả

Seat.fromArray([3, 4]) → Seat { row: 3, col: 4 }
Seat.FIRST, Seat.LABEL → Seat { row: 1, col: 1 } 'ghế'
Seat.created → 2
p.fromArray, typeof Seat.fromArray → undefined 'function'
Desk.fromArray([5, 6]) instanceof Desk → true

Lưu ý

- Trong phương thức tĩnh, `this` là chính lớp đó (hay lớp con nếu gọi qua lớp con)
- Thể hiện không truy cập được thành viên tĩnh qua `this`; viết `TenLop.x` hoặc `this.constructor.x`
- Lớp chỉ toàn thành viên tĩnh thường nên là module hoặc object thường

Tên bắt đầu bằng `#` (ES2022) là riêng tư thực sự: chỉ truy cập được bên trong thân lớp, kể cả lớp con cũng không thấy, và truy cập từ ngoài là lỗi cú pháp (không chỉ là quy ước như tiền tố `_`). Áp dụng cho trường, phương thức, getter/setter và thành viên tĩnh. Có thể kiểm tra tồn tại bằng `#x in obj`. Đây là cách đóng gói dữ liệu chuẩn của ngôn ngữ.

class Wallet {
  #balance = 0;
  static #count = 0;
  constructor(owner) {
    this.owner = owner;
    Wallet.#count++;
  }
  deposit(amount) {
    if (amount <= 0) throw new RangeError('số tiền phải dương');
    this.#balance += amount;
    return this;
  }
  #afterFee() {
    return this.#balance * 0.99;
  }
  withdraw() {
    return this.#afterFee();
  }
  static isWallet(o) {
    return #balance in o;
  }
  get balance() {
    return this.#balance;
  }
}
const w = new Wallet('An').deposit(1000);
console.log(w.balance, w.withdraw());
console.log(w.balance === w['#balance'], w['#balance']);
console.log(Object.keys(w), JSON.stringify(w));
console.log(Wallet.isWallet(w), Wallet.isWallet({}));
console.log(Object.getOwnPropertyNames(w));

Kết quả

w.balance, w.withdraw() → 1000 990
w.balance === w['#balance'], w['#balance'] → false undefined
Object.keys(w), JSON.stringify(w) → [ 'owner' ] '{"owner":"An"}'
Wallet.isWallet(w), Wallet.isWallet({}) → true false
Object.getOwnPropertyNames(w) → [ 'owner' ]

Lưu ý

- Truy cập `obj.#x` ngoài lớp là `SyntaxError` ngay lúc phân tích, không phải lỗi lúc chạy
- Trường private không hiện trong `Object.keys`, `JSON.stringify` hay debug thông thường
- Muốn chia sẻ với lớp con hãy dùng phương thức công khai hoặc quy ước `_ten`

Biểu thức chính quy (RegExp) mô tả một mẫu chuỗi để tìm, kiểm tra, trích xuất và thay thế. Viết bằng literal `/mau/co` hoặc `new RegExp('mau', 'co')` (dùng khi mẫu đến từ biến). Dùng với các phương thức của regex (`test`, `exec`) và của chuỗi (`match`, `matchAll`, `replace`, `replaceAll`, `split`, `search`). Cú pháp mẫu và các cờ nằm ở mục con.

const phone = /^(0|\+84)\d{9}$/;
console.log(phone.test('0912345678'), phone.test('09123'));
console.log('Toán 8 và Văn 9'.match(/\d+/g));
console.log('lớp 10A1 phòng 12'.replace(/\d+/g, '#'));
console.log('2025-09-05'.split(/-/));
console.log(/xin/i.test('XIN CHÀO'));
const keyword = 'a.b';
const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
console.log(new RegExp(keyword).test('axb'));
console.log(new RegExp(escape(keyword)).test('axb'));
console.log(/abc/.source, /abc/gi.flags);

Kết quả

phone.test('0912345678'), phone.test('09123') → true false
'Toán 8 và Văn 9'.match(/\d+/g) → [ '8', '9' ]
'lớp 10A1 phòng 12'.replace(/\d+/g, '#') → 'lớp #A# phòng #'
'2025-09-05'.split(/-/) → [ '2025', '09', '05' ]
/xin/i.test('XIN CHÀO') → true
new RegExp(keyword).test('axb') → true
new RegExp(escape(keyword)).test('axb') → false
/abc/.source, /abc/gi.flags → 'abc' 'gi'

Lưu ý

- Chuỗi truyền vào `new RegExp` phải thoát dấu gạch chéo ngược gấp đôi (`'\\d+'`)
- Escape ký tự đặc biệt khi đưa chuỗi người dùng vào regex, tránh lỗi và tấn công ReDoS
- Đừng dùng regex để phân tích HTML hay JSON

`regex.test(chuoi)` trả về `true` nếu mẫu khớp ở bất kỳ vị trí nào, `false` nếu không. Dùng để kiểm tra hợp lệ (email, số điện thoại). Cẩn thận với cờ `g` hoặc `y`: regex giữ trạng thái `lastIndex` giữa các lần gọi nên `test` lặp lại với cùng một regex có thể cho kết quả xen kẽ. Dùng neo `^...$` để kiểm tra toàn bộ chuỗi.

console.log(/\d/.test('lớp10'), /\d/.test('lớp'));
console.log(/^\d+$/.test('123'), /^\d+$/.test('12a'));
const email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
console.log(email.test('an@school.edu.vn'), email.test('an@'));
const g = /a/g;
console.log(g.test('aa'), g.lastIndex);
console.log(g.test('aa'), g.lastIndex);
console.log(g.test('aa'), g.lastIndex);
const noG = /a/;
console.log(noG.test('aa'), noG.test('aa'));

Kết quả

/\d/.test('lớp10'), /\d/.test('lớp') → true false
/^\d+$/.test('123'), /^\d+$/.test('12a') → true false
email.test('an@school.edu.vn'), email.test('an@') → true false
g.test('aa'), g.lastIndex → true 1
g.test('aa'), g.lastIndex → true 2
g.test('aa'), g.lastIndex → false 0
noG.test('aa'), noG.test('aa') → true true

Lưu ý

- Không đặt cờ `g` trên regex dùng lại cho `test()`, hoặc đặt `regex.lastIndex = 0` trước mỗi lần gọi
- Kiểm tra email đúng chuẩn rất phức tạp; một mẫu đơn giản rồi xác thực bằng email thật là thực tế hơn

`regex.exec(chuoi)` trả về mảng kết quả khớp đầu tiên (phần tử 0 là phần khớp, các phần tử sau là nhóm bắt) kèm `index`, `input` và `groups` (nhóm có tên), hoặc `null` nếu không khớp. Với cờ `g` hoặc `y`, mỗi lần gọi tiếp tục từ `lastIndex` nên lặp trong `while` để duyệt mọi kết quả khớp. Hiện nay `str.matchAll()` gọn hơn cho việc duyệt này.

const m = /(\d+)-(\d+)/.exec('Phòng 12-34 tầng 2');
console.log(m[0], m[1], m[2], m.index);
console.log(/z/.exec('abc'));
const name = /(?<last>\w+) (?<first>\w+)/.exec('Nguyen An');
console.log(name.groups.last, name.groups.first);
const re = /\d+/g;
let result;
const all = [];
while ((result = re.exec('Toán8Văn9Anh10')) !== null) all.push([result[0], result.index]);
console.log(all);
console.log(re.lastIndex);

Kết quả

m[0], m[1], m[2], m.index → '12-34' '12' '34' 6
/z/.exec('abc') → null
name.groups.last, name.groups.first → 'Nguyen' 'An'
all → [ [ '8', 4 ], [ '9', 8 ], [ '10', 12 ] ]
re.lastIndex → 0

Lưu ý

- Vòng lặp `while` với regex không có cờ `g` chạy vô hạn vì luôn khớp lần đầu; luôn thêm `g`
- Dùng `str.match()` hoặc `matchAll()` khi chỉ cần danh sách kết quả

`chuoi.match(regex)` hoạt động khác nhau theo cờ: không có `g` thì giống `regex.exec()` (khớp đầu tiên kèm nhóm và `index`); có `g` thì trả về mảng mọi phần khớp (chỉ chuỗi, không có nhóm), hoặc `null` khi không khớp. Vì `null` thay vì mảng rỗng nên cần `?? []` khi muốn duyệt. Cần nhóm của mọi kết quả thì dùng `matchAll()`.

console.log('Lớp có 30 nam, 15 nữ'.match(/\d+/));
console.log('Lớp có 30 nam, 15 nữ'.match(/\d+/g));
console.log('chưa có điểm'.match(/\d+/g));
console.log(('chưa có điểm'.match(/\d+/g) ?? []).length);
const [whole, day, month] = '15/03/2024'.match(/(\d+)\/(\d+)/);
console.log(whole, day, month);
console.log('a,b;c'.match(/[a-z]/g).join(''));
console.log('Hello World'.match(/[A-Z]/g));

Kết quả

'Lớp có 30 nam, 15 nữ'.match(/\d+/) →
  [
    '30',
    index: 7,
    input: 'Lớp có 30 nam, 15 nữ',
    groups: undefined
  ]
'Lớp có 30 nam, 15 nữ'.match(/\d+/g) → [ '30', '15' ]
'chưa có điểm'.match(/\d+/g) → null
('chưa có điểm'.match(/\d+/g) ?? []).length → 0
whole, day, month → '15/03' '15' '03'
'a,b;c'.match(/[a-z]/g).join('') → 'abc'
'Hello World'.match(/[A-Z]/g) → [ 'H', 'W' ]

Lưu ý

- Không có `g`, `match` mất `index` khi so với `exec`? Không: vẫn có `index` và `groups`; có `g` thì mất nhóm và `index`
- Dùng `?? []` khi kết quả có thể là `null`

`chuoi.matchAll(regex)` trả về iterator, mỗi phần tử là kết quả khớp đầy đủ như `exec()` (nhóm bắt, `index`, `groups`), cho mọi lần khớp. Regex BẮT BUỘC có cờ `g` (nếu không ném `TypeError`). Chuyển thành mảng bằng spread hoặc `Array.from`. Gọn và an toàn hơn vòng lặp `exec`, không phụ thuộc `lastIndex`.

const text = 'toan=9, van=8, anh=10';
const matches = [...text.matchAll(/(\w+)=(\d+)/g)];
console.log(matches.length);
console.log(matches.map((m) => [m[1], m[2], m.index]));
const parts = [...text.matchAll(/(?<subject>\w+)=(?<score>\d+)/g)];
const pairs = parts.map((m) => [m.groups.subject, Number(m.groups.score)]);
console.log(Object.fromEntries(pairs));
for (const m of 'x1y2'.matchAll(/[a-z](\d)/g)) console.log(m[0], m[1]);
try {
  'abc'.matchAll(/a/);
} catch (e) {
  console.log(e.name);
}

Kết quả

matches.length → 3
matches.map((m) => [m[1], m[2], m.index]) →
  [
    [ 'toan', '9', 0 ],
    [ 'van', '8', 8 ],
    [ 'anh', '10', 15 ]
  ]
Object.fromEntries(pairs) → { toan: 9, van: 8, anh: 10 }
m[0], m[1] → 'x1' '1'
m[0], m[1] → 'y2' '2'
e.name → 'TypeError'

Lưu ý

- Iterator chỉ duyệt một lần; chuyển sang mảng nếu cần dùng lại
- Có từ ES2020

Cờ đặt sau regex literal để đổi cách khớp: `g` (global, tìm mọi kết quả), `i` (không phân biệt hoa thường), `m` (multiline, `^` và `$` khớp từng dòng), `s` (dotAll, `.` khớp cả xuống dòng), `u` (unicode, hiểu điểm mã và `\p{...}`), `y` (sticky, khớp đúng tại `lastIndex`), `d` (hasIndices, trả vị trí các nhóm), `v` (unicodeSets, mở rộng của `u` với phép toán tập hợp). Thuộc tính `regex.flags` liệt kê cờ đang bật.

console.log('aAa'.match(/a/g).length, 'aAa'.match(/a/gi).length);
console.log('dòng 1\ndòng 2'.match(/^dòng \d$/gm));
console.log(/a.b/.test('a\nb'), /a.b/s.test('a\nb'));
console.log('Đà Nẵng'.match(/\p{Lu}/gu));
const y = /a/y;
console.log(y.test('ba'), (y.lastIndex = 1, y.test('ba')));
const d = /(?<so>\d+)/d.exec('ab12');
console.log(d.indices.groups.so);
console.log(/x/gimsuy.flags, /x/d.hasIndices);
console.log('x'.replace(/X/i, 'y'));

Kết quả

'aAa'.match(/a/g).length, 'aAa'.match(/a/gi).length → 2 3
'dòng 1\ndòng 2'.match(/^dòng \d$/gm) → [ 'dòng 1', 'dòng 2' ]
/a.b/.test('a\nb'), /a.b/s.test('a\nb') → false true
'Đà Nẵng'.match(/\p{Lu}/gu) → [ 'Đ', 'N' ]
y.test('ba'), (y.lastIndex = 1, y.test('ba')) → false true
d.indices.groups.so → [ 2, 4 ]
/x/gimsuy.flags, /x/d.hasIndices → 'gimsuy' true
'x'.replace(/X/i, 'y') → 'y'

Lưu ý

- Cờ `g` làm `exec` và `test` giữ trạng thái `lastIndex`
- `m` đổi `^` và `$` từ "đầu và cuối chuỗi" thành "đầu và cuối mỗi dòng"

`Intl` là bộ API quốc tế hóa có sẵn: `Intl.NumberFormat` (số, tiền tệ, phần trăm, đơn vị), `Intl.DateTimeFormat` (ngày giờ), `Intl.RelativeTimeFormat` ("2 ngày trước"), `Intl.PluralRules` (quy tắc số nhiều), `Intl.ListFormat` ("A, B và C"), `Intl.Collator` (sắp xếp chuỗi theo ngôn ngữ), `Intl.Segmenter` (tách ký tự, từ, câu), `Intl.DisplayNames` (tên ngôn ngữ, quốc gia). Tạo bộ định dạng một lần rồi dùng lại; các hàm `toLocaleString` bên dưới đều dựa trên chúng.

console.log(new Intl.NumberFormat('vi-VN').format(1234567.89));
console.log(new Intl.DateTimeFormat('vi-VN', { timeZone: 'UTC' }).format(new Date(0)));
console.log(new Intl.ListFormat('vi', { type: 'conjunction' }).format(['An', 'Bình', 'Chi']));
console.log(new Intl.PluralRules('en').select(1), new Intl.PluralRules('en').select(5));
console.log(new Intl.DisplayNames('vi', { type: 'region' }).of('JP'));
console.log(Intl.DateTimeFormat().resolvedOptions().locale.length > 0);
console.log(Intl.supportedValuesOf('currency').includes('VND'));

Kết quả

new Intl.NumberFormat('vi-VN').format(1234567.89) → '1.234.567,89'
new Intl.DateTimeFormat('vi-VN', { timeZone: 'UTC' }).format(new Date(0)) → '1/1/1970'
new Intl.ListFormat('vi', { type: 'conjunction' }).format(['An', 'Bình', 'Chi']) → 'An, Bình và Chi'
new Intl.PluralRules('en').select(1), new Intl.PluralRules('en').select(5) → 'one' 'other'
new Intl.DisplayNames('vi', { type: 'region' }).of('JP') → 'Nhật Bản'
Intl.DateTimeFormat().resolvedOptions().locale.length > 0 → true
Intl.supportedValuesOf('currency').includes('VND') → true

Lưu ý

- Truyền mảng ngôn ngữ ưu tiên `['vi-VN', 'en']` để có dự phòng
- Dữ liệu ngôn ngữ phụ thuộc môi trường; Node.js hiện đại đi kèm đầy đủ

`new Intl.NumberFormat(locale, tuyChon).format(so)` định dạng số theo ngôn ngữ: dấu phân cách nghìn và thập phân, tiền tệ (`style: 'currency'`), phần trăm, đơn vị (`style: 'unit'`), ký pháp gọn (`notation: 'compact'` ra "1,2 N" hoặc "1.2K"), số chữ số lẻ. Tạo một lần dùng nhiều lần để nhanh hơn `toLocaleString` gọi lặp lại; còn có `formatToParts` để lấy từng phần.

const tuition = 1234567.891;
console.log(new Intl.NumberFormat('vi-VN').format(tuition));
console.log(new Intl.NumberFormat('en-US').format(tuition));
console.log(new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(1500000));
console.log(new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(1234.5));
console.log(new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 }).format(0.956));
console.log(new Intl.NumberFormat('en', { notation: 'compact' }).format(1234567));
console.log(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'kilometer-per-hour' }).format(60));
console.log(new Intl.NumberFormat('en-US', { minimumFractionDigits: 2 }).format(8));
console.log(new Intl.NumberFormat('de-DE').formatToParts(1234.5).map((p) => p.type).join(','));

Kết quả

new Intl.NumberFormat('vi-VN').format(tuition) → '1.234.567,891'
new Intl.NumberFormat('en-US').format(tuition) → '1,234,567.891'
new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(1500000) →
  '1.500.000 ₫'
new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(1234.5) → '$1,234.50'
new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 }).format(0.956) →
  '95.6%'
new Intl.NumberFormat('en', { notation: 'compact' }).format(1234567) → '1.2M'
new Intl.NumberFormat('en-US', { style: 'unit', unit: 'kilometer-per-hour' }).format(60) → '60 km/h'
new Intl.NumberFormat('en-US', { minimumFractionDigits: 2 }).format(8) → '8.00'
new Intl.NumberFormat('de-DE').formatToParts(1234.5).map((p) => p.type).join(',') →
  'integer,group,integer,decimal,fraction'

Lưu ý

- Định dạng chỉ để hiển thị; không dùng chuỗi kết quả cho tính toán
- Mã tiền tệ theo chuẩn ISO 4217 (`VND`, `USD`, `EUR`)

`new Intl.DateTimeFormat(locale, tuyChon).format(ngay)` định dạng ngày giờ theo ngôn ngữ và múi giờ (`timeZone` dùng tên IANA như `Asia/Ho_Chi_Minh`). Tùy chọn gọn: `dateStyle` và `timeStyle` (`full`, `long`, `medium`, `short`); hoặc chi tiết: `weekday`, `year`, `month`, `day`, `hour`, `minute`, `second`, `hour12`, `timeZoneName`. Có `formatRange(a, b)` cho khoảng ngày và `formatToParts()` để tự ghép.

const d = new Date('2025-09-05T07:30:00Z');
const f = (loc, opt) => new Intl.DateTimeFormat(loc, { timeZone: 'UTC', ...opt }).format(d);
console.log(f('vi-VN'));
console.log(f('vi-VN', { dateStyle: 'full' }));
console.log(f('en-US', { dateStyle: 'medium', timeStyle: 'short' }));
console.log(f('en-GB', { weekday: 'long', day: 'numeric', month: 'long' }));
const hcm = new Intl.DateTimeFormat('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', timeStyle: 'short' });
console.log(hcm.format(d));
const short = new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', month: 'short', day: 'numeric' });
console.log(short.formatRange(d, new Date('2025-09-10T00:00:00Z')));
const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'UTC' }).formatToParts(d);
console.log(parts.map((p) => p.type).join(','));

Kết quả

f('vi-VN') → '5/9/2025'
f('vi-VN', { dateStyle: 'full' }) → 'Thứ Sáu, 5 tháng 9, 2025'
f('en-US', { dateStyle: 'medium', timeStyle: 'short' }) → 'Sep 5, 2025, 7:30 AM'
f('en-GB', { weekday: 'long', day: 'numeric', month: 'long' }) → 'Friday 5 September'
hcm.format(d) → '14:30'
short.formatRange(d, new Date('2025-09-10T00:00:00Z')) → 'Sep 5 – 10'
parts.map((p) => p.type).join(',') → 'month,literal,day,literal,year'

Lưu ý

- Luôn đặt `timeZone` khi cần kết quả giống nhau trên mọi máy
- Với một giờ hiển thị nhiều lần, tạo sẵn bộ định dạng thay vì gọi `toLocaleString` lặp

`new Intl.RelativeTimeFormat(locale, { numeric })` định dạng khoảng thời gian tương đối theo ngôn ngữ: `format(-2, 'day')` ra "2 ngày trước", `format(3, 'hour')` ra "3 giờ nữa". Với `numeric: 'auto'` dùng cách nói tự nhiên như "hôm qua", "ngày mai" khi có thể. Đơn vị gồm `second`, `minute`, `hour`, `day`, `week`, `month`, `year`. Kết hợp tính khoảng cách để làm nhãn "x phút trước".

const vi = new Intl.RelativeTimeFormat('vi');
console.log(vi.format(-2, 'day'), '|', vi.format(3, 'hour'));
const viAuto = new Intl.RelativeTimeFormat('vi', { numeric: 'auto' });
console.log(viAuto.format(-1, 'day'), '|', viAuto.format(1, 'day'), '|', viAuto.format(0, 'day'));
const en = new Intl.RelativeTimeFormat('en', { numeric: 'auto' });
console.log(en.format(-1, 'day'), '|', en.format(2, 'week'));
const ago = (ms) => {
  const seconds = Math.round(ms / 1000);
  if (Math.abs(seconds) < 60) return vi.format(-seconds, 'second');
  if (Math.abs(seconds) < 3600) return vi.format(-Math.round(seconds / 60), 'minute');
  return vi.format(-Math.round(seconds / 3600), 'hour');
};
console.log(ago(5 * 60 * 1000), ago(3 * 3600 * 1000));

Kết quả

vi.format(-2, 'day'), '|', vi.format(3, 'hour') → '2 ngày trước' '|' 'sau 3 giờ nữa'
viAuto.format(-1, 'day'), '|', viAuto.format(1, 'day'), '|', viAuto.format(0, 'day') →
  'Hôm qua' '|' 'Ngày mai' '|' 'Hôm nay'
en.format(-1, 'day'), '|', en.format(2, 'week') → 'yesterday' '|' 'in 2 weeks'
ago(5 * 60 * 1000), ago(3 * 3600 * 1000) → '5 phút trước' '3 giờ trước'

Lưu ý

- Số âm là quá khứ, số dương là tương lai
- Hãy tính khoảng cách tới thời điểm hiện tại rồi chọn đơn vị phù hợp như hàm `ago`

`so.toLocaleString(locale, tuyChon)` định dạng số theo quy ước của một ngôn ngữ: dấu phân cách hàng nghìn, dấu thập phân, tiền tệ, phần trăm, số chữ số lẻ. Với tiếng Việt (`'vi-VN'`) dấu chấm ngăn cách hàng nghìn và dấu phẩy ngăn cách phần thập phân. Dùng cho hiển thị, không dùng để lưu trữ hay tính toán.

const tuition = 1234567.891;
console.log(tuition.toLocaleString('vi-VN'));
console.log(tuition.toLocaleString('en-US'));
console.log(tuition.toLocaleString('de-DE', { maximumFractionDigits: 1 }));
console.log((1500000).toLocaleString('vi-VN', { style: 'currency', currency: 'VND' }));
console.log((0.956).toLocaleString('vi-VN', { style: 'percent' }));
console.log((1234.5).toLocaleString('en-US', { minimumFractionDigits: 2 }));

Kết quả

tuition.toLocaleString('vi-VN') → '1.234.567,891'
tuition.toLocaleString('en-US') → '1,234,567.891'
tuition.toLocaleString('de-DE', { maximumFractionDigits: 1 }) → '1.234.567,9'
(1500000).toLocaleString('vi-VN', { style: 'currency', currency: 'VND' }) → '1.500.000 ₫'
(0.956).toLocaleString('vi-VN', { style: 'percent' }) → '96%'
(1234.5).toLocaleString('en-US', { minimumFractionDigits: 2 }) → '1,234.50'

Tham số & trả về

locale: mã ngôn ngữ như `'vi-VN'`, `'en-US'`
tuyChon: `style` (`decimal`, `currency`, `percent`), `currency`, `minimumFractionDigits`, `maximumFractionDigits`...
Trả về: chuỗi đã định dạng

Lưu ý

- Tạo sẵn một `Intl.NumberFormat` khi định dạng nhiều số để nhanh hơn
- Kết quả phụ thuộc dữ liệu ngôn ngữ của môi trường; dùng chuỗi này để hiển thị chứ không phân tích lại

`BigInt` biểu diễn số nguyên lớn tùy ý, viết bằng hậu tố `n` (`123n`) hoặc hàm `BigInt()`. Dùng khi số vượt quá `Number.MAX_SAFE_INTEGER`, như ID 64 bit, băm, tính giai thừa lớn. `BigInt` không trộn được với `number` trong phép tính (phải chuyển kiểu rõ ràng), phép chia cắt bỏ phần lẻ và không có số thực.

console.log(2n ** 64n);
console.log(typeof 10n);
console.log(BigInt(123) + 1n);
console.log(7n / 2n);
console.log(1n == 1, 1n === 1);
console.log(2n > 1);
console.log(Number(10n) + 1);
try {
  console.log(1n + 1);
} catch (e) {
  console.log(e.name, e.message);
}

Kết quả

2n ** 64n → 18446744073709551616n
typeof 10n → 'bigint'
BigInt(123) + 1n → 124n
7n / 2n → 3n
1n == 1, 1n === 1 → true false
2n > 1 → true
Number(10n) + 1 → 11
e.name, e.message → 'TypeError' 'Cannot mix BigInt and other types, use explicit conversions'

Lưu ý

- `JSON.stringify()` không hỗ trợ `BigInt` và ném `TypeError`; chuyển sang chuỗi trước
- `Math.*` không dùng được với `BigInt`
- Chuyển `BigInt` sang `number` lớn hơn 2^53 sẽ mất chính xác

`res.ok` là boolean `true` khi mã trạng thái HTTP nằm trong khoảng 200 đến 299. Vì `fetch` không tự coi 4xx và 5xx là lỗi, đây là kiểm tra bắt buộc trước khi đọc dữ liệu. `res.status` cho mã số và `res.statusText` cho chữ mô tả. `res.redirected`, `res.url`, `res.headers` cho thêm thông tin phản hồi.

const res = await fetch('/api/san-pham/1');
console.log(res.ok, res.status, res.statusText);
console.log(res.headers.get('content-type'));
console.log(res.redirected, res.url);
if (!res.ok) {
  const loi = await res.json().catch(() => ({}));
  throw new Error(loi.message ?? `HTTP ${res.status}`);
}

Kết quả

- Phản hồi thành công: in `true 200 OK`
- Loại nội dung: in `application/json; charset=utf-8`
- Không bị chuyển hướng: `false` và URL đầy đủ của yêu cầu
- Với phản hồi 404 kèm `{ "message": "Không tìm thấy" }`: ném `Error: Không tìm thấy`

Lưu ý

- 304 Not Modified không nằm trong 200-299 nhưng `fetch` thường tự xử lý bộ nhớ đệm và trả về 200
- Đọc thông điệp lỗi từ body (nếu máy chủ gửi) giúp báo lỗi rõ hơn cho người dùng

`res.json()` đọc toàn bộ body và phân tích như JSON, trả về Promise cho giá trị JavaScript tương ứng; từ chối với `SyntaxError` nếu nội dung không phải JSON hợp lệ. Các phương thức đọc khác: `text()` (chuỗi), `blob()` (tệp nhị phân), `arrayBuffer()`, `formData()`. Body chỉ đọc được MỘT lần; muốn đọc lại phải `res.clone()` trước.

const res = await fetch('/api/nguoi-dung');
const nguoi = await res.json();
console.log(nguoi.ten, nguoi.tuoi);
const res2 = await fetch('/trang-chu.html');
const html = await res2.text();
console.log(html.slice(0, 15));
const res3 = await fetch('/anh.png');
const anh = await res3.blob();
console.log(anh.type, anh.size > 0);
try {
  await res3.json();
} catch (e) {
  console.log(e.name);
}
const res4 = await fetch('/api/khong-phai-json');
try {
  await res4.json();
} catch (e) {
  console.log(e.name);
}

Kết quả

- Đọc JSON: in `An 20`
- `text()` của trang HTML: in `<!doctype html>`
- `blob()` của ảnh: in `image/png true`
- Đọc body lần hai: ném `TypeError` (body đã bị dùng)
- Nội dung không phải JSON: ném `SyntaxError`

Lưu ý

- Kiểm tra `res.ok` trước, và `Content-Type` nếu máy chủ có thể trả HTML lỗi thay vì JSON
- Phản hồi lớn nên đọc theo luồng qua `res.body` thay vì nạp hết vào bộ nhớ

Tham số thứ hai của `fetch` là object tùy chọn: `method` (`GET` mặc định, `POST`, `PUT`, `PATCH`, `DELETE`), `headers` (đối tượng hoặc `Headers`), `body` (chuỗi, `FormData`, `Blob`, `URLSearchParams`), `credentials` (`'same-origin'` mặc định, `'include'` để gửi cookie sang miền khác), `cache`, `mode` (`'cors'`...), `redirect`, `signal` (để hủy). Với JSON phải tự đặt `Content-Type: application/json` và `JSON.stringify` body; với `FormData` thì KHÔNG đặt `Content-Type` để trình duyệt tự thêm ranh giới.

const guiJson = await fetch('/api/bai-viet', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', Authorization: 'Bearer abc' },
  body: JSON.stringify({ tieuDe: 'Xin chào' }),
  credentials: 'include',
  signal: AbortSignal.timeout(5000),
});
console.log(guiJson.status);
const form = new FormData();
form.append('tep', new Blob(['nội dung'], { type: 'text/plain' }), 'ghi-chu.txt');
const taiLen = await fetch('/api/tai-len', { method: 'POST', body: form });
console.log(taiLen.status);
const truyVan = new URLSearchParams({ q: 'js', trang: 2 });
const tim = await fetch(`/api/tim?${truyVan}`);
console.log(tim.url);

Kết quả

- POST JSON thành công: in `201`
- Tải tệp bằng `FormData`: in `200`, trình duyệt tự đặt `multipart/form-data` kèm ranh giới
- URL tìm kiếm in `https://example.com/api/tim?q=js&trang=2`

Lưu ý

- `credentials: 'include'` cần máy chủ cho phép CORS kèm `Access-Control-Allow-Credentials`
- Quá hạn `AbortSignal.timeout` làm fetch từ chối với `TimeoutError`

`FormData` tạo tập các cặp khóa-giá trị (cả tệp) theo định dạng `multipart/form-data`. Khởi tạo từ một form có sẵn (`new FormData(form)` lấy mọi trường có `name`) hoặc rỗng rồi `append`. Có `get`, `getAll`, `set`, `delete`, `has` và duyệt được, chuyển thành object bằng `Object.fromEntries()` (mất các khóa lặp). Truyền thẳng làm `body` của `fetch`.

const form = document.getElementById('dk');
const du_lieu = new FormData(form);
console.log(du_lieu.get('ten'), du_lieu.get('tuoi'));
du_lieu.append('nguon', 'web');
du_lieu.append('so-thich', 'đọc');
du_lieu.append('so-thich', 'bơi');
console.log(du_lieu.getAll('so-thich'));
console.log(du_lieu.has('nguon'), du_lieu.has('khong-co'));
console.log(Object.fromEntries(du_lieu));
for (const [khoa, giaTri] of du_lieu) console.log(khoa, giaTri);
await fetch('/api/dang-ky', { method: 'POST', body: du_lieu });

Kết quả

- Từ form có `ten=An`, `tuoi=20`: in `An 20`
- `getAll('so-thich')` in `['đọc', 'bơi']`
- `has` in `true false`
- `Object.fromEntries` chỉ giữ giá trị cuối của khóa lặp: `so-thich` thành `bơi`
- Tệp trong ô `input type="file"` có `name` được thêm dưới dạng `File`

Lưu ý

- Không tự đặt header `Content-Type` khi gửi `FormData`
- Giá trị luôn là chuỗi hoặc `File`; ép kiểu số khi cần

`AbortController` cho phép hủy yêu cầu `fetch` đang chạy: tạo controller, truyền `controller.signal` vào tùy chọn `signal`, gọi `controller.abort()` khi muốn hủy; `fetch` bị từ chối với `AbortError` (hoặc lý do bạn truyền). `AbortSignal.timeout(ms)` tạo sẵn tín hiệu tự hủy sau thời gian chỉ định. Rất hữu ích cho ô tìm kiếm (hủy yêu cầu cũ khi có yêu cầu mới) và dọn dẹp trong React.

let boDieuKhien;
async function timKiem(tuKhoa) {
  boDieuKhien?.abort();
  boDieuKhien = new AbortController();
  try {
    const res = await fetch(`/api/tim?q=${tuKhoa}`, { signal: boDieuKhien.signal });
    console.log('kết quả cho', tuKhoa, (await res.json()).length);
  } catch (e) {
    if (e.name === 'AbortError') return console.log('đã hủy', tuKhoa);
    throw e;
  }
}
timKiem('j');
timKiem('ja');
timKiem('jav');
try {
  await fetch('/cham', { signal: AbortSignal.timeout(100) });
} catch (e) {
  console.log(e.name);
}

Kết quả

- Ba lệnh gọi liên tiếp: in `đã hủy j`, `đã hủy ja`, chỉ yêu cầu `jav` hoàn tất và in `kết quả cho jav 5`
- Yêu cầu chậm quá 100ms: in `TimeoutError`

Lưu ý

- Một controller chỉ dùng được một lần: đã `abort()` thì tạo controller mới
- Luôn phân biệt `AbortError` với lỗi thật khi bắt lỗi

`IntersectionObserver` báo cho bạn khi một phần tử đi vào hoặc rời khỏi khung nhìn (hay một phần tử cha), mà không cần lắng nghe `scroll` và tự tính vị trí. Hiệu quả vì trình duyệt tối ưu bên trong. Dùng để tải ảnh lười (lazy loading), cuộn vô hạn, chạy hoạt ảnh khi hiện ra, đo thời gian xem quảng cáo. Callback nhận danh sách `entries`, mỗi mục có `isIntersecting`, `intersectionRatio`, `target`.

const quanSat = new IntersectionObserver(
  (cacMuc, qs) => {
    for (const m of cacMuc) {
      if (!m.isIntersecting) continue;
      const anh = m.target;
      anh.src = anh.dataset.src;
      console.log('đã hiện', anh.dataset.src, m.intersectionRatio.toFixed(2));
      qs.unobserve(anh);
    }
  },
  { rootMargin: '200px', threshold: 0.1 }
);
document.querySelectorAll('img[data-src]').forEach((anh) => quanSat.observe(anh));

Kết quả

- Khi cuộn tới gần ảnh `a.jpg` (cách khung nhìn 200px): ảnh bắt đầu tải và in `đã hiện a.jpg 0.12`
- Sau khi tải, ảnh bị bỏ theo dõi nên không in lại
- Ảnh ở rất xa chưa cuộn tới không tải, tiết kiệm dữ liệu

Lưu ý

- `threshold` nhận số hoặc mảng số từ 0 đến 1
- Gọi `observer.disconnect()` để ngừng quan sát tất cả khi không cần nữa
- Thuộc tính `loading="lazy"` của thẻ `<img>` đã thay thế được nhiều trường hợp lazy loading đơn giản

`ResizeObserver` báo khi kích thước của MỘT PHẦN TỬ thay đổi (do cửa sổ, nội dung hay CSS), khác `resize` chỉ theo dõi cửa sổ. Dùng cho biểu đồ, canvas, bố cục theo kích thước chứa (component co giãn theo khung của nó). Callback nhận `entries` với `contentRect` hoặc `contentBoxSize`.

const khung = document.getElementById('bieu-do');
const theoDoi = new ResizeObserver((cacMuc) => {
  for (const m of cacMuc) {
    const { width, height } = m.contentRect;
    console.log(`${Math.round(width)} x ${Math.round(height)}`);
    m.target.classList.toggle('hep', width < 400);
  }
});
theoDoi.observe(khung);

Kết quả

- Ngay khi bắt đầu quan sát: in kích thước hiện tại, ví dụ `600 x 300`
- Khi kéo hẹp khung còn 380px: in `380 x 300` và thêm class `hep`
- Phóng to lại: in kích thước mới và gỡ class `hep`

Lưu ý

- Thay đổi kích thước phần tử trong chính callback có thể gây vòng lặp vô hạn
- CSS container queries (`@container`) thay thế được nhiều nhu cầu thuần giao diện mà không cần JavaScript

`requestAnimationFrame(ham)` hẹn chạy hàm ngay trước lần vẽ lại màn hình kế tiếp (thường 60 lần mỗi giây, đồng bộ với tần số quét), và truyền vào một mốc thời gian chính xác. Là cách đúng để làm hoạt ảnh bằng JavaScript và vòng lặp trò chơi, hơn hẳn `setInterval`: không vẽ thừa khi tab ẩn, đồng bộ với màn hình. Muốn hoạt ảnh liên tục thì gọi lại chính nó trong hàm; hủy bằng `cancelAnimationFrame(id)`.

const hop = document.getElementById('hop');
let batDau;
function buoc(thoiGian) {
  batDau ??= thoiGian;
  const tienDo = Math.min((thoiGian - batDau) / 1000, 1);
  hop.style.transform = `translateX(${tienDo * 300}px)`;
  if (tienDo < 1) requestAnimationFrame(buoc);
  else console.log('xong sau', Math.round(thoiGian - batDau), 'ms');
}
const id = requestAnimationFrame(buoc);
console.log(typeof id);

Kết quả

- `typeof id` in `number`
- Hộp trượt mượt sang phải 300px trong 1 giây, cập nhật mỗi khung hình
- Cuối cùng in `xong sau 1000 ms` (gần 1000 do làm tròn theo khung hình)

Lưu ý

- Dùng mốc thời gian được truyền vào để tính tốc độ, không đếm số khung hình, vì màn hình 120Hz chạy nhanh gấp đôi
- Với hoạt ảnh đơn giản, CSS transition/animation hoặc `el.animate()` (Web Animations) nhẹ hơn

`structuredClone(giaTri)` sao chép SÂU một giá trị: object và mảng lồng nhau, `Date`, `Map`, `Set`, `RegExp`, `ArrayBuffer`, `Blob`, và cả tham chiếu vòng. Thay thế mẹo `JSON.parse(JSON.stringify(x))` vốn làm mất `Date`, `undefined`, `Map` và lỗi với tham chiếu vòng. Không sao chép được hàm, phần tử DOM, symbol; gặp chúng sẽ ném `DataCloneError`. Mất cả prototype: lớp tùy chỉnh chỉ còn là object thường.

const original = {
  name: 'An',
  birthday: new Date('2010-05-20'),
  subjects: new Set(['Toán', 'Văn']),
  address: { rooms: [101, 102] },
};
const copy = structuredClone(original);
copy.address.rooms.push(103);
console.log(original.address.rooms, copy.address.rooms);
console.log(copy.birthday.getFullYear(), copy.subjects.size, copy.subjects.has('Văn'));
console.log(copy.birthday === original.birthday);
const loop = { name: 'v' };
loop.self = loop;
const copyLoop = structuredClone(loop);
console.log(copyLoop.self === copyLoop, copyLoop === loop);
console.log(JSON.parse(JSON.stringify({ n: undefined, d: new Date(0) })));
try {
  structuredClone({ fn: () => 1 });
} catch (e) {
  console.log(e.name);
}
class Student {
  study() {}
}
console.log(structuredClone(new Student()) instanceof Student);

Kết quả

original.address.rooms, copy.address.rooms → [ 101, 102 ] [ 101, 102, 103 ]
copy.birthday.getFullYear(), copy.subjects.size, copy.subjects.has('Văn') → 2010 2 true
copy.birthday === original.birthday → false
copyLoop.self === copyLoop, copyLoop === loop → true false
JSON.parse(JSON.stringify({ n: undefined, d: new Date(0) })) → { d: '1970-01-01T00:00:00.000Z' }
e.name → 'DataCloneError'
structuredClone(new Student()) instanceof Student → false

Lưu ý

- Có sẵn trong trình duyệt hiện đại và Node.js 17 trở lên
- Spread `{ ...obj }` chỉ sao chép nông; `structuredClone` sao chép toàn bộ các tầng
- Với object có hàm hoặc lớp riêng cần tự viết hàm sao chép

`Symbol()` tạo ra một giá trị duy nhất, không bao giờ trùng với giá trị nào khác dù có cùng mô tả. Thường dùng làm khóa thuộc tính không đụng độ và không bị liệt kê bởi `for...in` hay `Object.keys()`. `Symbol.for(khoa)` lấy symbol từ sổ đăng ký toàn cục để dùng chung. Ngôn ngữ cũng có các "well-known symbol" như `Symbol.iterator` để tùy biến hành vi như vòng lặp `for...of`.

const id1 = Symbol('id');
const id2 = Symbol('id');
console.log(id1 === id2);
console.log(id1.description);
console.log(typeof id1);
const student = { name: 'An', [id1]: 123 };
console.log(Object.keys(student));
console.log(student[id1]);
console.log(Object.getOwnPropertySymbols(student).length);
console.log(Symbol.for('school') === Symbol.for('school'));
const roll = {
  *[Symbol.iterator]() {
    yield 'An';
    yield 'Bình';
  },
};
console.log([...roll]);

Kết quả

id1 === id2 → false
id1.description → 'id'
typeof id1 → 'symbol'
Object.keys(student) → [ 'name' ]
student[id1] → 123
Object.getOwnPropertySymbols(student).length → 1
Symbol.for('school') === Symbol.for('school') → true
[...roll] → [ 'An', 'Bình' ]

Lưu ý

- Symbol không tự chuyển thành chuỗi: `'' + sym` ném `TypeError`; dùng `sym.toString()` hoặc `sym.description`
- `JSON.stringify` bỏ qua thuộc tính có khóa symbol
- Trong mã hóa dữ liệu thông thường, dùng chuỗi làm khóa là đủ; symbol hữu ích cho thư viện và giao thức nội bộ

Generator là hàm khai báo bằng `function*` có thể tạm dừng ở `yield` và tiếp tục sau đó. Gọi generator không chạy thân ngay mà trả về một iterator; mỗi lần `next()` chạy tiếp đến `yield` kế tiếp và trả `{ value, done }`. Vì sinh giá trị theo yêu cầu (lazy), generator biểu diễn được dãy vô hạn mà không tốn bộ nhớ. `yield*` ủy quyền cho iterable khác; `next(giaTri)` đưa dữ liệu ngược vào generator.

function* periods(max) {
  for (let i = 1; i <= max; i++) yield i;
}
console.log([...periods(4)]);
const it = periods(2);
console.log(it.next(), it.next(), it.next());
function* studentIds() {
  let id = 1000;
  while (true) yield ++id;
}
const take = (iter, k) => {
  const out = [];
  for (const x of iter) {
    if (out.length >= k) break;
    out.push(x);
  }
  return out;
};
console.log(take(studentIds(), 5));
function* combine() {
  yield 'An';
  yield* ['Bình', 'Chi'];
  yield* periods(2);
}
console.log([...combine()]);
function* interview() {
  const name = yield 'tên bạn là gì?';
  return `xin chào ${name}`;
}
const g = interview();
console.log(g.next().value, g.next('An'));

Kết quả

[...periods(4)] → [ 1, 2, 3, 4 ]
it.next(), it.next(), it.next() →
  { value: 1, done: false } { value: 2, done: false } { value: undefined, done: true }
take(studentIds(), 5) → [ 1001, 1002, 1003, 1004, 1005 ]
[...combine()] → [ 'An', 'Bình', 'Chi', 1, 2 ]
g.next().value, g.next('An') → 'tên bạn là gì?' { value: 'xin chào An', done: true }

Lưu ý

- Generator vô hạn cần điều kiện dừng khi duyệt (`break`, `take`)
- Generator bất đồng bộ (`async function*`) kết hợp với `for await...of` để đọc dữ liệu dạng luồng
- Iterator helper (ES2025) như `.take()`, `.map()` giúp xử lý dãy vô hạn gọn hơn

`arr.at(chiSo)` trả về phần tử tại vị trí chỉ định và hỗ trợ chỉ số âm đếm từ cuối (`-1` là phần tử cuối). Gọn hơn `arr[arr.length - 1]` và không cần lưu mảng vào biến tạm khi mảng là kết quả của một biểu thức.

const roll = ['An', 'Bình', 'Chi', 'Dũng'];
console.log(roll.at(0));
console.log(roll.at(-1));
console.log(roll.at(-2));
console.log(roll.at(10));
console.log('Toán-Văn-Anh'.split('-').at(-1));
console.log(roll[roll.length - 1]);

Kết quả

roll.at(0) → 'An'
roll.at(-1) → 'Dũng'
roll.at(-2) → 'Chi'
roll.at(10) → undefined
'Toán-Văn-Anh'.split('-').at(-1) → 'Anh'
roll[roll.length - 1] → 'Dũng'

Tham số & trả về

chiSo: vị trí cần lấy, số âm đếm từ cuối
Trả về: phần tử hoặc `undefined` nếu ngoài phạm vi

Lưu ý

- Có từ ES2022
- `m[-1]` không làm việc như `at(-1)`

`arr.fill(giaTri, batDau, ketThuc)` ghi cùng một giá trị vào các vị trí trong khoảng chỉ định, sửa mảng gốc và trả về chính mảng đó. Dùng để khởi tạo mảng với giá trị mặc định, ví dụ `new Array(5).fill(0)`.

console.log(new Array(4).fill(0));
console.log([7, 8, 9, 6, 5].fill(10, 1, 3));
console.log(new Array(3).fill('vắng'));
const seats = Array.from({ length: 2 }, () => Array(3).fill('trống'));
console.log(seats);
const wrong = Array(2).fill([]);
wrong[0].push('An');
console.log(wrong);

Kết quả

new Array(4).fill(0) → [ 0, 0, 0, 0 ]
[7, 8, 9, 6, 5].fill(10, 1, 3) → [ 7, 10, 10, 6, 5 ]
new Array(3).fill('vắng') → [ 'vắng', 'vắng', 'vắng' ]
seats → [ [ 'trống', 'trống', 'trống' ], [ 'trống', 'trống', 'trống' ] ]
wrong → [ [ 'An' ], [ 'An' ] ]

Tham số & trả về

giaTri: giá trị ghi vào
batDau, ketThuc: khoảng cần điền (không gồm `ketThuc`), mặc định cả mảng
Trả về: chính mảng đã sửa

Lưu ý

- `fill` với object/mảng dùng CHUNG một tham chiếu cho mọi ô (ví dụ cuối); tạo lưới 2 chiều bằng `Array.from` kèm hàm
- Có thể dùng chỉ số âm cho `batDau` và `ketThuc`

`arr.entries()` trả về iterator các cặp `[chiSo, giaTri]`, `arr.keys()` trả về iterator các chỉ số và `arr.values()` trả về iterator các giá trị. Dùng kèm `for...of` để lấy cả chỉ số và giá trị một cách sạch sẽ, thay cho vòng `for` đếm thủ công.

const roll = ['An', 'Bình', 'Chi'];
for (const [i, name] of roll.entries()) {
  console.log(`${i + 1}: ${name}`);
}
console.log([...roll.keys()]);
console.log([...roll.values()]);
console.log(Array.from(roll.entries()));
console.log(Object.fromEntries(roll.entries()));

Kết quả

1: An
2: Bình
3: Chi
[...roll.keys()] → [ 0, 1, 2 ]
[...roll.values()] → [ 'An', 'Bình', 'Chi' ]
Array.from(roll.entries()) → [ [ 0, 'An' ], [ 1, 'Bình' ], [ 2, 'Chi' ] ]
Object.fromEntries(roll.entries()) → { '0': 'An', '1': 'Bình', '2': 'Chi' }

Tham số & trả về

Không có tham số
Trả về: iterator (dùng được với `for...of`, spread, `Array.from`)

Lưu ý

- Iterator chỉ dùng được một lần
- `Object.entries(obj)` là phiên bản cho object; `map.entries()` cho `Map`

`chuoi.at(chiSo)` trả về ký tự ở vị trí chỉ định và hỗ trợ chỉ số âm đếm từ cuối chuỗi (`-1` là ký tự cuối). Gọn hơn nhiều so với `chuoi[chuoi.length - 1]`. Chỉ số ngoài phạm vi cho `undefined`.

const fullName = 'Nguyễn Văn An';
console.log(fullName.at(0));
console.log(fullName.at(-1));
console.log(fullName.at(-3));
console.log(fullName.at(99));
console.log(fullName[fullName.length - 1]);

Kết quả

fullName.at(0) → 'N'
fullName.at(-1) → 'n'
fullName.at(-3) → ' '
fullName.at(99) → undefined
fullName[fullName.length - 1] → 'n'

Tham số & trả về

chiSo: vị trí cần lấy; số âm đếm từ cuối
Trả về: chuỗi một ký tự, hoặc `undefined` nếu ngoài phạm vi

Lưu ý

- `s[-1]` không hoạt động như `at(-1)`: nó tìm thuộc tính tên `'-1'` và cho `undefined`
- Có từ ES2022; mọi trình duyệt hiện nay đều hỗ trợ

`chuoi.localeCompare(khac, locale, tuyChon)` so sánh hai chuỗi theo quy tắc của ngôn ngữ (thứ tự bảng chữ cái, dấu, hoa thường) và trả về số âm, 0 hoặc số dương. Đây là cách đúng để sắp xếp chuỗi có dấu như tiếng Việt, vì so sánh `<` thông thường chỉ so mã ký tự. Tùy chọn `numeric` giúp "file2" đứng trước "file10".

console.log('a'.localeCompare('b'));
console.log('b'.localeCompare('a'));
console.log('a'.localeCompare('a'));
const names = ['Đào', 'Anh', 'Ân', 'Bình', 'Dũng'];
console.log([...names].sort());
console.log([...names].sort((x, y) => x.localeCompare(y, 'vi')));
const files = ['bai10', 'bai2', 'bai1'];
console.log(files.sort((x, y) => x.localeCompare(y, undefined, { numeric: true })));
console.log('a'.localeCompare('A', undefined, { sensitivity: 'base' }));

Kết quả

'a'.localeCompare('b') → -1
'b'.localeCompare('a') → 1
'a'.localeCompare('a') → 0
[...names].sort() → [ 'Anh', 'Bình', 'Dũng', 'Ân', 'Đào' ]
[...names].sort((x, y) => x.localeCompare(y, 'vi')) → [ 'Anh', 'Ân', 'Bình', 'Dũng', 'Đào' ]
files.sort((x, y) => x.localeCompare(y, undefined, { numeric: true })) → [ 'bai1', 'bai2', 'bai10' ]
'a'.localeCompare('A', undefined, { sensitivity: 'base' }) → 0

Tham số & trả về

khac: chuỗi để so sánh
locale: mã ngôn ngữ như `'vi'`, `'en'`; bỏ qua thì dùng ngôn ngữ mặc định của môi trường
tuyChon: ví dụ `{ numeric: true }`, `{ sensitivity: 'base' }`
Trả về: số âm, 0 hoặc số dương

Lưu ý

- Khi sắp xếp mảng lớn, tạo sẵn `new Intl.Collator('vi')` rồi dùng `collator.compare` sẽ nhanh hơn
- Kết quả có thể khác nhau chút ít giữa trình duyệt và Node.js tùy dữ liệu ngôn ngữ cài sẵn

Cùng một chữ có dấu có thể được lưu theo hai cách: một ký tự dựng sẵn (NFC) hoặc chữ cái cộng dấu tách rời (NFD), và hai dạng này không bằng nhau khi so sánh. `chuoi.normalize(dang)` đưa chuỗi về một dạng thống nhất. Mẹo hay dùng: chuẩn hóa về NFD rồi xóa các dấu tách rời để bỏ dấu tiếng Việt khi tìm kiếm hoặc tạo slug.

const composed = 'é';
const decomposed = 'é';
console.log(composed === decomposed);
console.log(composed.normalize() === decomposed.normalize());
console.log(composed.length, decomposed.length);
const stripAccents = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
console.log(stripAccents('Nguyễn Văn Đức'));
console.log(stripAccents('Trường Tiểu học Hà Nội').toLowerCase().replaceAll(' ', '-'));

Kết quả

composed === decomposed → false
composed.normalize() === decomposed.normalize() → true
composed.length, decomposed.length → 1 2
stripAccents('Nguyễn Văn Đức') → 'Nguyen Van Duc'
stripAccents('Trường Tiểu học Hà Nội').toLowerCase().replaceAll(' ', '-') → 'truong-tieu-hoc-ha-noi'

Tham số & trả về

dang: `'NFC'` (mặc định), `'NFD'`, `'NFKC'` hoặc `'NFKD'`
Trả về: chuỗi đã chuẩn hóa

Lưu ý

- Chữ `đ` không phân rã thành chữ cái cộng dấu nên cần xử lý riêng
- Chuẩn hóa dữ liệu người dùng về NFC trước khi lưu để so sánh và tìm kiếm nhất quán

`Object.create(prototype, moTaThuocTinh)` tạo object mới có prototype là đối tượng chỉ định, nên object mới kế thừa các thuộc tính và phương thức của prototype đó. Truyền `null` để tạo object "sạch" không kế thừa gì (không có `toString`, `hasOwnProperty`), rất hợp cho bảng tra cứu thuần túy. Đây là nền tảng của kế thừa prototype thủ công.

const person = {
  introduce() {
    return `${this.name} giới thiệu`;
  },
};
const student = Object.create(person);
student.name = 'An';
console.log(student.introduce());
console.log(Object.getPrototypeOf(student) === person);
console.log('introduce' in student, Object.hasOwn(student, 'introduce'));
const dictionary = Object.create(null);
dictionary.An = 8;
console.log(dictionary.toString);
console.log('toString' in {});
console.log(Object.keys(Object.create({ school: 1 }, { own: { value: 2, enumerable: true } })));

Kết quả

student.introduce() → 'An giới thiệu'
Object.getPrototypeOf(student) === person → true
'introduce' in student, Object.hasOwn(student, 'introduce') → true false
dictionary.toString → undefined
'toString' in {} → true
Object.keys(Object.create({ school: 1 }, { own: { value: 2, enumerable: true } })) → [ 'own' ]

Tham số & trả về

prototype: object làm prototype, hoặc `null`
moTaThuocTinh: object mô tả thuộc tính như `defineProperties` (tùy chọn)
Trả về: object mới

Lưu ý

- Với cú pháp lớp (`class ... extends`) thì không cần dùng `Object.create` trực tiếp
- Object tạo bằng `create(null)` không có `hasOwnProperty`; dùng `Object.hasOwn()`

`Object.defineProperty(obj, khoa, moTa)` thêm hoặc sửa một thuộc tính với các cờ chỉ định rõ ràng, hoặc định nghĩa accessor bằng `get`/`set`. Dùng để tạo thuộc tính chỉ đọc, thuộc tính ẩn khỏi vòng lặp, hay thuộc tính tính toán. Các cờ không nêu mặc định là `false`. `Object.defineProperties()` định nghĩa nhiều thuộc tính cùng lúc.

const student = { name: 'An' };
Object.defineProperty(student, 'id', { value: 7, writable: false, enumerable: true });
student.id = 99;
console.log(student.id);
Object.defineProperty(student, 'secret', { value: 'x', enumerable: false });
console.log(Object.keys(student), student.secret);
console.log(JSON.stringify(student));
let birthYear = 2010;
Object.defineProperty(student, 'age', {
  get: () => 2025 - birthYear,
  set: (v) => (birthYear = 2025 - v),
  enumerable: true,
});
student.age = 16;
console.log(student.age, birthYear);
Object.defineProperties(student, { grade: { value: 10 }, room: { value: 2 } });
console.log(student.grade + student.room);

Kết quả

student.id → 7
Object.keys(student), student.secret → [ 'name', 'id' ] 'x'
JSON.stringify(student) → '{"name":"An","id":7}'
student.age, birthYear → 16 2009
student.grade + student.room → 12

Tham số & trả về

obj: object đích
khoa: tên thuộc tính
moTa: `{ value, writable, enumerable, configurable }` hoặc `{ get, set, enumerable, configurable }`
Trả về: chính `obj`

Lưu ý

- Không thể trộn `value`/`writable` với `get`/`set` trong cùng mô tả
- Thuộc tính `configurable: false` không đổi lại hay xóa được nữa
- Trong class, dùng cú pháp `get`/`set` thay vì `defineProperty`

Method khởi tạo, tự chạy khi tạo đối tượng mới; self là chính đối tượng đang được tạo.

class TenLop:
    def __init__(self, tham_so):
        self.thuoc_tinh = tham_so

Ví dụ

class TaiKhoan:
    def __init__(self, chu_tk, so_du=0):
        self.chu_tk = chu_tk
        self.so_du = so_du

tk = TaiKhoan('An', 100)
tk.so_du          # 100

Lưu ý

- Đừng dùng giá trị mặc định là list/dict (def __init__(self, ds=[])): mọi đối tượng sẽ dùng CHUNG một list; dùng None rồi tạo mới bên trong

Biến một method thành thuộc tính đọc được như biến thường; kèm .setter để kiểm tra khi gán.

@property
def ten(self): ...
@ten.setter
def ten(self, gia_tri): ...

Ví dụ

class HinhTron:
    def __init__(self, r): self.r = r
    @property
    def dien_tich(self): return 3.14159 * self.r ** 2
    @property
    def r(self): return self._r
    @r.setter
    def r(self, v):
        if v <= 0: raise ValueError('Bán kính phải dương')
        self._r = v

ht = HinhTron(2)
ht.dien_tich      # 12.566... (không có dấu ngoặc)

@classmethod nhận chính LỚP (cls) thay vì đối tượng — hay dùng làm hàm tạo thay thế; @staticmethod không nhận self hay cls, chỉ là hàm để gọn trong lớp.

@classmethod
def tu_chuoi(cls, s): ...
@staticmethod
def hop_le(x): ...

Ví dụ

class Ngay:
    def __init__(self, d, m, y): self.d, self.m, self.y = d, m, y
    @classmethod
    def tu_chuoi(cls, s):                      # Ngay.tu_chuoi('29/09/2026')
        return cls(*map(int, s.split('/')))
    @staticmethod
    def nam_nhuan(y): return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

Tự sinh __init__, __repr__, __eq__ từ khai báo thuộc tính — viết lớp chứa dữ liệu ngắn gọn.

from dataclasses import dataclass, field
@dataclass
class TenLop:
    truong: kieu = mac_dinh

Ví dụ

from dataclasses import dataclass, field

@dataclass(frozen=True)            # frozen: không sửa được, dùng làm key được
class Diem:
    x: float
    y: float = 0

@dataclass
class GioHang:
    mon: list[str] = field(default_factory=list)   # mặc định là list mới cho mỗi đối tượng

Diem(1, 2)                   # Diem(x=1, y=2)
Diem(1, 2) == Diem(1, 2)     # True

Giống list comprehension nhưng tạo dict ({k: v for ...}) hoặc set ({x for ...}).

{khoa: gia_tri for x in nguon}
{bieu_thuc for x in nguon}

Ví dụ

ten = ['An', 'Bình', 'Chi']
do_dai = {t: len(t) for t in ten}                     # {'An': 2, 'Bình': 4, 'Chi': 3}
dao = {v: k for k, v in do_dai.items()}               # đảo key và giá trị
chu_dau = {t[0] for t in ten}                         # {'A', 'B', 'C'}
dat = {k: v for k, v in gia.items() if v > 100}       # lọc dict

Decorator ghi nhớ kết quả của hàm theo đối số: gọi lại với cùng đối số thì trả kết quả cũ ngay.

from functools import lru_cache, cache
@lru_cache(maxsize=128)
def ham(x): ...

Ví dụ

from functools import cache

@cache
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

fib(100)     # tức thì; không có cache sẽ phải gọi hàng tỉ tỉ lần

Lưu ý

- Đối số phải hashable (không truyền được list, dict)

Bảng băm: dùng hàm băm biến key thành chỉ số của một mảng "bucket" để tra cứu, thêm, xóa gần như tức thời. dict của Python, Map/object của JavaScript, HashMap của Java đều là bảng băm.

# Minh họa rất đơn giản: xử lý va chạm bằng danh sách trong mỗi bucket
class BangBam:
    def __init__(self, n=8):
        self.bucket = [[] for _ in range(n)]
    def _vi_tri(self, key):
        return hash(key) % len(self.bucket)
    def dat(self, key, gia_tri):
        b = self.bucket[self._vi_tri(key)]
        for cap in b:
            if cap[0] == key: cap[1] = gia_tri; return
        b.append([key, gia_tri])
    def lay(self, key):
        for k, v in self.bucket[self._vi_tri(key)]:
            if k == key: return v
        raise KeyError(key)

Độ phức tạp

Trung bình: tra cứu/thêm/xóa O(1); tệ nhất (nhiều va chạm): O(n)

Lưu ý

- Key phải băm được và không đổi giá trị băm (vì vậy list không làm key dict được)
- Bảng tự mở rộng (rehash) khi quá đầy để giữ tốc độ O(1)

Cây tiền tố: mỗi cạnh là một ký tự, đường đi từ gốc tạo thành từ — tìm kiếm theo TIỀN TỐ cực nhanh (gợi ý tự động hoàn thành, kiểm tra chính tả).

class Trie:
    def __init__(self):
        self.goc = {}
    def them(self, tu):
        nut = self.goc
        for ch in tu:
            nut = nut.setdefault(ch, {})
        nut['$'] = True                      # đánh dấu kết thúc một từ
    def co_tien_to(self, tien_to):
        nut = self.goc
        for ch in tien_to:
            if ch not in nut: return False
            nut = nut[ch]
        return True

t = Trie()
for tu in ['java', 'javascript', 'python']: t.them(tu)
t.co_tien_to('jav')     # True

Độ phức tạp

Thêm / tìm một từ độ dài m: O(m), không phụ thuộc số lượng từ đã lưu

Lưu ý

- Tốn bộ nhớ hơn set/dict khi các từ ít chung tiền tố

Duyệt lần lượt từng phần tử cho tới khi tìm thấy — đơn giản, không cần dữ liệu sắp xếp.

def tim(a, x):
    for i, v in enumerate(a):
        if v == x:
            return i
    return -1

Độ phức tạp

Thời gian: O(n); bộ nhớ: O(1)

Lưu ý

- arr.indexOf / list.index / 'x in list' đều là tìm kiếm tuyến tính; tra cứu nhiều lần thì chuyển sang set/dict (O(1))

Duyệt đồ thị theo từng TẦNG: thăm mọi đỉnh kề trước rồi mới đi xa hơn, dùng hàng đợi. Tìm được đường đi NGẮN NHẤT (theo số cạnh) trên đồ thị không trọng số.

from collections import deque

def bfs(do_thi, bat_dau):
    khoang_cach = {bat_dau: 0}
    q = deque([bat_dau])
    while q:
        u = q.popleft()
        for v in do_thi[u]:
            if v not in khoang_cach:
                khoang_cach[v] = khoang_cach[u] + 1
                q.append(v)
    return khoang_cach

do_thi = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': []}
bfs(do_thi, 'A')     # {'A': 0, 'B': 1, 'C': 1, 'D': 2}

Độ phức tạp

Thời gian: O(V + E); bộ nhớ: O(V)

Duyệt đồ thị đi SÂU nhất có thể theo một nhánh rồi mới quay lui — dùng đệ quy hoặc stack. Dùng để tìm thành phần liên thông, phát hiện chu trình, sắp xếp topo.

def dfs(do_thi, u, da_tham=None):
    if da_tham is None:
        da_tham = set()
    da_tham.add(u)
    for v in do_thi[u]:
        if v not in da_tham:
            dfs(do_thi, v, da_tham)
    return da_tham

# Đếm số "hòn đảo" (thành phần liên thông)
so_dao = 0
da_tham = set()
for dinh in do_thi:
    if dinh not in da_tham:
        dfs(do_thi, dinh, da_tham)
        so_dao += 1

Độ phức tạp

Thời gian: O(V + E); bộ nhớ: O(V) cho ngăn xếp đệ quy

Lưu ý

- Đồ thị rất sâu có thể vượt giới hạn đệ quy của Python (~1000): chuyển sang dùng stack tự quản lý

Tìm đường đi ngắn nhất từ một đỉnh tới mọi đỉnh trên đồ thị có trọng số KHÔNG ÂM, dùng hàng đợi ưu tiên luôn mở rộng đỉnh gần nhất trước.

import heapq

def dijkstra(do_thi, nguon):           # do_thi: {u: [(v, trong_so), ...]}
    kc = {nguon: 0}
    h = [(0, nguon)]
    while h:
        d, u = heapq.heappop(h)
        if d > kc.get(u, float('inf')):
            continue                   # bản ghi cũ, đã có đường ngắn hơn
        for v, w in do_thi[u]:
            if d + w < kc.get(v, float('inf')):
                kc[v] = d + w
                heapq.heappush(h, (kc[v], v))
    return kc

Độ phức tạp

Thời gian: O((V + E) log V) với heap

Lưu ý

- Sai với cạnh trọng số âm: dùng Bellman-Ford; ứng dụng: bản đồ chỉ đường, định tuyến mạng

Sắp xếp các đỉnh của đồ thị có hướng KHÔNG chu trình sao cho mọi cạnh u -> v thì u đứng trước v — thứ tự thực hiện các việc có phụ thuộc (build, cài package, môn học tiên quyết).

from collections import deque

def topo(do_thi):
    bac_vao = {u: 0 for u in do_thi}
    for u in do_thi:
        for v in do_thi[u]:
            bac_vao[v] += 1
    q = deque(u for u, b in bac_vao.items() if b == 0)
    thu_tu = []
    while q:
        u = q.popleft(); thu_tu.append(u)
        for v in do_thi[u]:
            bac_vao[v] -= 1
            if bac_vao[v] == 0: q.append(v)
    if len(thu_tu) != len(do_thi): raise ValueError('Có chu trình')
    return thu_tu

Độ phức tạp

Thời gian: O(V + E)

Cây nhị phân mà mọi nút bên TRÁI nhỏ hơn nút cha và mọi nút bên PHẢI lớn hơn — tìm, thêm, xóa theo kiểu tìm kiếm nhị phân.

class Nut:
    def __init__(self, k): self.k, self.trai, self.phai = k, None, None

def them(goc, k):
    if goc is None: return Nut(k)
    if k < goc.k: goc.trai = them(goc.trai, k)
    else: goc.phai = them(goc.phai, k)
    return goc

def tim(goc, k):
    while goc and goc.k != k:
        goc = goc.trai if k < goc.k else goc.phai
    return goc

Độ phức tạp

Trung bình O(log n); tệ nhất O(n) khi cây lệch (thêm dữ liệu đã sắp xếp)

Lưu ý

- Cây tự cân bằng (AVL, đỏ đen) đảm bảo O(log n): TreeMap của Java, std::map của C++ dùng cây đỏ đen

Giải bài toán lớn bằng cách chia thành các bài toán con CHỒNG LẤP và LƯU LẠI kết quả từng bài con để không tính lại. Hai cách: từ trên xuống (đệ quy + ghi nhớ) và từ dưới lên (bảng).

# Số cách leo n bậc thang, mỗi lần 1 hoặc 2 bậc
def leo_thang(n):
    a, b = 1, 1                      # dp[0], dp[1]
    for _ in range(n - 1):
        a, b = b, a + b              # dp[i] = dp[i-1] + dp[i-2]
    return b

# Đổi tiền: số đồng xu ít nhất để tạo ra tổng S
def doi_tien(xu, S):
    dp = [0] + [float('inf')] * S
    for s in range(1, S + 1):
        for c in xu:
            if c <= s:
                dp[s] = min(dp[s], dp[s - c] + 1)
    return dp[S] if dp[S] != float('inf') else -1

Cách nhận diện

- Bài hỏi "số cách", "nhỏ nhất/lớn nhất", "có thể hay không" và lời giải đệ quy tính lại cùng một bài con nhiều lần
- Xác định: trạng thái (dp[i] nghĩa là gì), công thức chuyển, trường hợp cơ sở

Dùng hai chỉ số di chuyển trên mảng (thường từ hai đầu tiến vào, hoặc cùng chiều nhanh/chậm) để giảm từ O(n^2) xuống O(n).

# Mảng đã sắp xếp: có cặp nào tổng bằng k?
def co_cap(a, k):
    i, j = 0, len(a) - 1
    while i < j:
        tong = a[i] + a[j]
        if tong == k: return (a[i], a[j])
        if tong < k: i += 1
        else: j -= 1
    return None

# Chuỗi đối xứng (palindrome)
def doi_xung(s):
    return all(s[i] == s[-1 - i] for i in range(len(s) // 2))

Thử lần lượt từng lựa chọn, đi tiếp; nếu dẫn tới ngõ cụt thì QUAY LUI, bỏ lựa chọn đó và thử lựa chọn khác. Dùng cho bài toán liệt kê mọi tổ hợp, hoán vị, hay tìm lời giải thỏa ràng buộc (Sudoku, N quân hậu).

def hoan_vi(ds):
    kq, hien_tai, da_dung = [], [], [False] * len(ds)
    def thu():
        if len(hien_tai) == len(ds):
            kq.append(hien_tai[:]); return
        for i, x in enumerate(ds):
            if not da_dung[i]:
                da_dung[i] = True; hien_tai.append(x)
                thu()
                hien_tai.pop(); da_dung[i] = False    # quay lui
    thu()
    return kq

hoan_vi([1, 2, 3])     # 6 hoán vị

Lưu ý

- Độ phức tạp thường là hàm mũ; cắt tỉa sớm (dừng nhánh chắc chắn không có lời giải) là chìa khóa để đủ nhanh

`ref(giaTri)` tạo một "hộp" phản ứng chứa giá trị; trong script đọc và ghi qua `.value`, còn trong template Vue tự mở hộp nên viết thẳng tên biến. Dùng được cho MỌI kiểu dữ liệu (số, chuỗi, object, mảng); nếu chứa object thì nó được bọc thành reactive sâu. Khi gán `ref.value = x`, mọi nơi dùng nó (template, `computed`, `watch`) cập nhật. Cũng dùng làm tham chiếu tới phần tử DOM (template ref: `const el = ref(null)` kèm `ref="el"`). `shallowRef` chỉ theo dõi việc gán `.value`, không theo dõi sâu.

<script setup>
import { ref } from 'vue';
const dem = ref(0);
const nguoi = ref({ ten: 'An', tuoi: 20 });
dem.value++;
nguoi.value.tuoi++;
console.log(dem.value, nguoi.value.tuoi);
nguoi.value = { ten: 'Bình', tuoi: 30 };
console.log(nguoi.value.ten);
</script>

<template>
  <p>{{ dem }} - {{ nguoi.ten }} ({{ nguoi.tuoi }})</p>
</template>

Kết quả

- Console in `1 21`, rồi `Bình`
- Template hiển thị `1 - Bình (30)`; mỗi thay đổi `.value` cập nhật giao diện
- Trong template viết `dem`, không phải `dem.value`

Lưu ý

- Quên `.value` trong script là lỗi phổ biến nhất khi dùng `ref`
- Destructure một thuộc tính khỏi `ref` object làm mất phản ứng; dùng `toRef`/`toRefs`

`computed(() => ...)` tạo giá trị suy ra từ trạng thái khác. Nó ghi nhớ kết quả và chỉ tính lại khi dữ liệu nó đọc đổi, nên rẻ hơn gọi hàm trong template. Hàm tính phải thuần (không sửa state, không gọi API). Truyền object `{ get, set }` để tạo computed có thể ghi. Nên dùng computed cho mọi thứ "suy ra" thay vì lưu thêm một state phải đồng bộ.

<script setup>
import { ref, computed } from 'vue';
const ho = ref('Nguyễn');
const ten = ref('An');
const tenDayDu = computed(() => `${ho.value} ${ten.value}`);
const giaTien = ref(100000);
const giaChu = computed({
  get: () => `${giaTien.value.toLocaleString('vi-VN')}đ`,
  set: (v) => (giaTien.value = Number(String(v).replace(/\D/g, ''))),
});
console.log(tenDayDu.value, giaChu.value);
giaChu.value = '250.000đ';
console.log(giaTien.value);
</script>

Kết quả

- Dòng đầu in `Nguyễn An 100.000đ`
- Gán `giaChu.value = '250.000đ'` gọi `set`, bỏ ký tự không phải số: dòng sau in `250000`
- Đổi `ten.value = 'Bình'` thì `tenDayDu.value` tự thành `Nguyễn Bình`; nếu không có gì đổi, lần đọc tiếp theo lấy từ cache

Lưu ý

- Không sửa state bên trong hàm computed
- Dùng `watch` khi cần phản ứng bằng hiệu ứng phụ, `computed` khi chỉ cần giá trị

`watch(nguon, (moi, cu) => {...}, tuyChon)` chạy hàm khi nguồn đổi: nguồn là `ref`, getter `() => obj.x` hoặc mảng nhiều nguồn. Tùy chọn: `immediate` chạy ngay lần đầu, `deep` theo dõi sâu object, `once` chỉ một lần. `watchEffect(() => ...)` tự theo dõi mọi thứ nó đọc và chạy lập tức. Dùng cho hiệu ứng phụ (gọi API, lưu storage); hàm nhận `onCleanup` để hủy yêu cầu cũ.

<script setup>
import { ref, watch, watchEffect } from 'vue';
const tuKhoa = ref('');
watch(tuKhoa, (moi, cu) => console.log(`đổi: "${cu}" -> "${moi}"`));
watchEffect(() => console.log('độ dài:', tuKhoa.value.length));
tuKhoa.value = 'vue';
</script>

Kết quả

- `watchEffect` chạy ngay: in `độ dài: 0`
- Gán `tuKhoa.value = 'vue'` (callback của Vue chạy ở lần cập nhật kế tiếp): in `đổi: "" -> "vue"` và `độ dài: 3`
- `watch` không chạy lúc đầu (khác `watchEffect`) trừ khi có `immediate: true`

Lưu ý

- Với giá trị suy ra dùng `computed`; `watch` dành cho hiệu ứng phụ
- Muốn hủy theo dõi, gọi hàm mà `watch` trả về

Vòng đời Vue có các móc: `onBeforeMount`, `onMounted` (đã gắn vào DOM, truy cập được phần tử), `onBeforeUpdate`, `onUpdated`, `onBeforeUnmount`, `onUnmounted`. Gọi đồng bộ trong `setup`. Việc điển hình trong `onMounted`: đo kích thước, khởi tạo thư viện cần DOM, gọi API lần đầu, đăng ký sự kiện cửa sổ; đừng quên gỡ trong `onUnmounted`.

<script setup>
import { ref, onMounted, onUnmounted } from 'vue';
const rong = ref(0);
const capNhat = () => (rong.value = window.innerWidth);
onMounted(() => {
  capNhat();
  window.addEventListener('resize', capNhat);
  console.log('đã mount');
});
onUnmounted(() => {
  window.removeEventListener('resize', capNhat);
  console.log('đã gỡ');
});
</script>

<template><p>Rộng {{ rong }}px</p></template>

Kết quả

- Khi component hiện: console in `đã mount` và đoạn văn hiện `Rộng 1280px` (tùy cửa sổ)
- Kéo đổi kích thước cửa sổ thì số tự cập nhật
- Khi component bị gỡ: in `đã gỡ` và trình nghe `resize` được dọn

Lưu ý

- Khi render phía server (SSR) `onMounted` chỉ chạy ở trình duyệt, nên là chỗ an toàn để dùng `window`

Decorator khai báo một class là component Angular: selector (thẻ HTML), template và style.

@Component({
  selector: 'app-the-san-pham',
  standalone: true,
  template: `<h3>{{ sp.ten }}</h3><button (click)="them()">Thêm</button>`,
  styles: [`h3 { color: #0f6 }`],
})
export class TheSanPham {
  @Input() sp!: SanPham;
  @Output() daThem = new EventEmitter<number>();
  them() { this.daThem.emit(this.sp.id); }
}

Cú pháp điều khiển luồng trong template (Angular 17+), thay cho *ngIf và *ngFor cũ.

@if (dangTai) {
  <p>Đang tải...</p>
} @else {
  <ul>
    @for (sp of sanPham; track sp.id) {
      <li>{{ sp.ten }}</li>
    } @empty {
      <li>Chưa có sản phẩm</li>
    }
  </ul>
}

Service chứa logic dùng chung (gọi API, lưu state); Angular tự tạo và "tiêm" (inject) service vào nơi cần.

@Injectable({ providedIn: 'root' })        // một thể hiện dùng chung cho cả app
export class GioHangService {
  private ds = signal<SanPham[]>([]);
  them(sp: SanPham) { this.ds.update((d) => [...d, sp]); }
}

export class TheSanPham {
  private gio = inject(GioHangService);    // hoặc nhận qua constructor
}

State phản ứng của Angular (16+): signal() giữ giá trị, computed() tính từ signal khác, effect() chạy side effect.

const dem = signal(0);
const gapDoi = computed(() => dem() * 2);   // đọc signal bằng cách GỌI nó như hàm
dem.set(5);
dem.update((x) => x + 1);
effect(() => console.log('dem =', dem()));

Service gọi HTTP có sẵn của Angular, trả về Observable, tự parse JSON.

export class SanPhamService {
  private http = inject(HttpClient);
  layTatCa() { return this.http.get<SanPham[]>('/api/san-pham'); }
  tao(sp: SanPham) { return this.http.post<SanPham>('/api/san-pham', sp); }
}

`page.tsx` xuất component mặc định là giao diện RIÊNG của một route, và việc có tệp này mới làm thư mục thành một URL truy cập được. Là Server Component theo mặc định, có thể `async` để tải dữ liệu trực tiếp. Nhận props `params` (đoạn động, từ Next 15 là Promise cần `await`) và `searchParams` (truy vấn, cũng là Promise). Trang không bọc lại khi chuyển giữa các route nên khác với `layout.tsx`.

// app/bai/[id]/page.tsx
export default async function Bai({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string }>;
}) {
  const { id } = await params;
  const { tab = 'noi-dung' } = await searchParams;
  return (
    <h1>
      Bài {id} - {tab}
    </h1>
  );
}

Kết quả

- Vào `/bai/42?tab=binh-luan` hiện `Bài 42 - binh-luan`
- Vào `/bai/42` không có truy vấn hiện `Bài 42 - noi-dung` (giá trị mặc định)
- Thư mục `bai/[id]` không có `page.tsx` thì `/bai/42` trả 404

Lưu ý

- Trong Next 14 trở xuống `params` là object thường, không cần `await`
- Dùng `generateStaticParams` để dựng sẵn các giá trị `id` phổ biến

Trong App Router mọi component là Server Component theo mặc định: chạy trên máy chủ, có thể là `async`, truy cập trực tiếp cơ sở dữ liệu và biến bí mật, và không gửi JavaScript của chính nó tới trình duyệt (gói nhỏ hơn). Chúng không dùng được `useState`, `useEffect` hay sự kiện. Khi cần tương tác, đặt `'use client'` ở dòng đầu của tệp để tạo Client Component. Server Component có thể chứa Client Component và truyền dữ liệu qua props, nhưng không ngược lại với import.

// app/san-pham/page.tsx  (Server Component)
import NutMua from './NutMua';

export default async function SanPham() {
  const ds = await fetch('https://api.example.com/san-pham').then((r) => r.json());
  return ds.map((sp: { id: number; ten: string }) => (
    <div key={sp.id}>{sp.ten} <NutMua id={sp.id} /></div>
  ));
}

// app/san-pham/NutMua.tsx  (Client Component)
'use client';
import { useState } from 'react';
export default function NutMua({ id }: { id: number }) {
  const [da, setDa] = useState(false);
  return <button onClick={() => setDa(true)}>{da ? 'Đã thêm' : 'Mua'}</button>;
}

Kết quả

- Danh sách sản phẩm được tải và dựng thành HTML trên máy chủ; trình duyệt nhận HTML sẵn có
- Mã tải dữ liệu không nằm trong gói gửi tới trình duyệt
- Chỉ `NutMua` gửi JavaScript; bấm `Mua` đổi nhãn thành `Đã thêm`

Lưu ý

- Giữ `'use client'` ở các lá của cây (nút, biểu mẫu) để gói JS nhỏ
- Biến môi trường bí mật chỉ dùng được trong Server Component

`<Link href="/duong-dan">` từ `next/link` chuyển trang phía client (không tải lại toàn trang) và TỰ TẢI TRƯỚC (prefetch) tài nguyên của trang đích khi liên kết xuất hiện trong khung nhìn (bản production), nên chuyển trang gần như tức thì. Prop: `replace`, `scroll={false}` (không cuộn lên đầu), `prefetch={false}`. `href` nhận chuỗi hoặc object `{ pathname, query }`. Render thẻ `<a>` thật, tốt cho SEO và khả năng truy cập. Liên kết ra ngoài dùng thẻ `<a>` thường.

import Link from 'next/link';

export default function Menu() {
  return (
    <nav>
      <Link href="/">Trang chủ</Link>
      <Link href="/bai?trang=2" prefetch={false}>Bài viết</Link>
      <Link href={{ pathname: '/bai/[id]', query: { id: 7 } }}>Bài 7</Link>
      <Link href="/gioi-thieu" replace scroll={false}>Giới thiệu</Link>
    </nav>
  );
}

Kết quả

- Bấm `Bài viết` chuyển sang `/bai?trang=2` mà không tải lại trang; trang này không được tải trước (`prefetch={false}`)
- `Trang chủ` được tải trước ngay khi menu hiện, nên bấm vào hầu như tức thì
- `Giới thiệu` thay mục lịch sử hiện tại và giữ nguyên vị trí cuộn

Lưu ý

- Link ra ngoài trang web dùng `<a href>`
- Muốn đánh dấu mục hiện tại, đọc `usePathname()`

Trong Server Component bạn gọi `fetch` hoặc truy vấn cơ sở dữ liệu ngay trong hàm `async`, không cần `useEffect`. Độ "tươi" của dữ liệu cấu hình theo từng yêu cầu hoặc theo route: `fetch(url, { next: { revalidate: 60 } })` tái tạo sau tối đa 60 giây (ISR), `{ cache: 'no-store' }` luôn lấy mới, `export const dynamic = 'force-dynamic'` làm cả trang động. Làm mới theo yêu cầu: `revalidatePath('/bai')` hoặc `revalidateTag('bai')` (sau khi sửa dữ liệu). Mặc định của Next 15 là không lưu đệm `fetch`, nên bật lưu đệm một cách tường minh.

export const revalidate = 60;

export default async function Tin() {
  const tin = await fetch('https://api.example.com/tin', { next: { tags: ['tin'] } }).then((r) => r.json());
  return <ul>{tin.map((t: { id: number; tieuDe: string }) => <li key={t.id}>{t.tieuDe}</li>)}</ul>;
}

Kết quả

- Người truy cập đầu tiên làm máy chủ gọi API và dựng HTML; trong 60 giây sau, mọi người nhận bản đã lưu
- Sau 60 giây, người kế tiếp vẫn nhận bản cũ ngay trong khi bản mới được tạo ở nền (stale-while-revalidate)
- Gọi `revalidateTag('tin')` (ví dụ trong Server Action) làm bản lưu hết hạn tức thì

Lưu ý

- Gọi nhiều `fetch` độc lập bằng `Promise.all` để tránh chờ lần lượt
- Cùng một URL fetch trong một lần render được loại trùng tự động

Tệp `route.ts` trong `app/` định nghĩa endpoint HTTP bằng cách xuất các hàm đặt tên theo phương thức: `GET`, `POST`, `PUT`, `DELETE`... Mỗi hàm nhận `Request` chuẩn Web và trả về `Response` (hoặc `NextResponse.json`). Đoạn động như `[id]` có trong tham số thứ hai. Dùng cho webhook, API công khai cho ứng dụng di động, hoặc khi cần phản hồi không phải HTML. Với việc ghi dữ liệu từ biểu mẫu của chính ứng dụng, Server Action thường gọn hơn.

// app/api/bai/route.ts
import { NextResponse } from 'next/server';

export async function GET(req: Request) {
  const trang = new URL(req.url).searchParams.get('trang') ?? '1';
  return NextResponse.json({ trang: Number(trang), muc: ['a', 'b'] });
}

export async function POST(req: Request) {
  const { tieuDe } = await req.json();
  if (!tieuDe) return NextResponse.json({ loi: 'thiếu tiêu đề' }, { status: 400 });
  return NextResponse.json({ id: 1, tieuDe }, { status: 201 });
}

Kết quả

- `GET /api/bai?trang=2` trả JSON `{ "trang": 2, "muc": ["a", "b"] }`
- `POST /api/bai` với `{"tieuDe":"Chào"}` trả mã `201` và `{ "id": 1, "tieuDe": "Chào" }`
- `POST` thiếu `tieuDe` trả mã `400` kèm `{ "loi": "thiếu tiêu đề" }`

Lưu ý

- Một thư mục không thể có đồng thời `route.ts` và `page.tsx`
- Handler `GET` không lưu đệm theo mặc định từ Next 15

Server Action là hàm `async` có chỉ thị `'use server'`, chạy trên máy chủ nhưng gọi từ trình duyệt như hàm thường: đặt vào thuộc tính `action` của `<form>` (hoạt động cả khi chưa có JavaScript) hoặc gọi trong sự kiện. Dùng để ghi dữ liệu, rồi `revalidatePath`/`revalidateTag` để làm mới giao diện, hoặc `redirect`. Luôn kiểm tra đầu vào và quyền bên trong hàm vì nó là endpoint công khai.

// app/viec/actions.ts
'use server';
import { revalidatePath } from 'next/cache';

export async function themViec(formData: FormData) {
  const ten = String(formData.get('ten') ?? '').trim();
  if (!ten) return;
  await db.viec.create({ data: { ten } });
  revalidatePath('/viec');
}

// app/viec/page.tsx
import { themViec } from './actions';
export default function Trang() {
  return (
    <form action={themViec}>
      <input name="ten" />
      <button>Thêm</button>
    </form>
  );
}

Kết quả

- Nhập `Học Next` rồi bấm `Thêm`: trình duyệt gửi POST, `themViec` chạy trên máy chủ và lưu vào cơ sở dữ liệu
- `revalidatePath('/viec')` làm trang tải lại danh sách, mục mới hiện ra mà không cần tải lại toàn trang
- Gửi chuỗi rỗng: hàm thoát sớm, không ghi gì

Lưu ý

- Xác thực người dùng và kiểm tra dữ liệu ở trong action; đừng tin client
- Dùng `useActionState` để hiện lỗi và trạng thái đang gửi

`<Image>` từ `next/image` tự tạo nhiều kích thước ảnh, chuyển sang định dạng hiện đại (WebP/AVIF), tải lười (lazy) và giữ chỗ để không bị dịch chuyển bố cục (CLS). Bắt buộc có `width` và `height` (hoặc `fill` để lấp đầy phần tử cha có `position: relative`). Thêm `priority` cho ảnh đầu trang (LCP) để tải sớm, `sizes` để chọn đúng kích thước theo màn hình. Ảnh từ tên miền ngoài phải được cho phép trong `images.remotePatterns` của `next.config`.

import Image from 'next/image';
import anhBia from './bia.jpg';

export default function Banner() {
  return (
    <>
      <Image src={anhBia} alt="Ảnh bìa" priority placeholder="blur" />
      <Image src="https://cdn.example.com/a.png" alt="Logo" width={120} height={40} />
    </>
  );
}

Kết quả

- Ảnh bìa nhập từ tệp có sẵn kích thước và ảnh mờ giữ chỗ (`placeholder="blur"`), tải sớm nhờ `priority`
- Ảnh logo từ CDN được chuyển thành định dạng nhẹ hơn và chỉ tải khi sắp hiện trong khung nhìn
- Thiếu `width/height` với ảnh từ xa gây lỗi lúc build

Lưu ý

- Luôn viết `alt` có ý nghĩa
- Khai báo tên miền ảnh ngoài trong `next.config.js` để tránh lỗi

`$effect(() => {...})` chạy sau khi DOM cập nhật và chạy lại khi bất kỳ state nào nó đọc thay đổi (tự theo dõi, không cần mảng phụ thuộc). Dùng cho tác vụ ngoài Svelte: vẽ canvas, gọi API, đổi tiêu đề trang, đăng ký sự kiện. Trả về hàm để dọn dẹp trước lần chạy tiếp và khi component bị hủy. Tránh dùng để đồng bộ state với state: dùng `$derived`.

<script>
  let giay = $state(0);
  $effect(() => {
    const id = setInterval(() => giay++, 1000);
    return () => clearInterval(id);
  });
  $effect(() => {
    document.title = `Đã ${giay} giây`;
  });
</script>

<p>{giay} giây</p>

Kết quả

- Mỗi giây `giay` tăng 1: đoạn văn hiện `1 giây`, `2 giây`...
- Effect thứ hai đổi tiêu đề tab thành `Đã 1 giây`, `Đã 2 giây`...
- Khi component bị gỡ, hàm dọn dẹp chạy `clearInterval` để dừng bộ hẹn giờ

Lưu ý

- Không chạy khi render phía máy chủ (SSR)
- Chỉ state được đọc đồng bộ trong effect mới được theo dõi

Thư mục `server/api/` chứa các endpoint HTTP chạy trên Nitro cùng với ứng dụng Nuxt. Tệp `server/api/bai.get.ts` thành `GET /api/bai`; hậu tố `.post`, `.put`, `.delete` giới hạn phương thức; `[id]` tạo đoạn động. Mỗi tệp `export default defineEventHandler(async (event) => ...)`: giá trị trả về tự chuyển thành JSON. Đọc dữ liệu bằng `getQuery`, `getRouterParam`, `readBody`; ném lỗi bằng `createError({ statusCode, statusMessage })`.

// server/api/bai/[id].get.js
export default defineEventHandler((event) => {
  const id = Number(getRouterParam(event, 'id'));
  if (!Number.isInteger(id)) {
    throw createError({ statusCode: 400, statusMessage: 'id không hợp lệ' });
  }
  return { id, tieuDe: `Bài số ${id}` };
});

Kết quả

- `GET /api/bai/3` trả JSON `{ "id": 3, "tieuDe": "Bài số 3" }`
- `GET /api/bai/abc` trả mã `400` với thông báo `id không hợp lệ`
- Từ trang gọi `useFetch('/api/bai/3')` cho cùng kết quả mà không cần máy chủ riêng

Lưu ý

- Hàm `defineEventHandler`, `getRouterParam`... được auto-import, không cần `import`
- Biến môi trường bí mật chỉ đọc ở server qua `useRuntimeConfig()`

Nuxt tự import những thứ hay dùng nên bạn bỏ được các dòng `import`: API của Vue (`ref`, `computed`, `watch`), hàm của Nuxt (`useFetch`, `useRoute`, `navigateTo`), component trong `components/` (đặt tên theo đường dẫn: `components/nut/Chinh.vue` thành `<NutChinh />`), composable trong `composables/` (tệp xuất hàm `useXxx`), hàm trong `utils/`. Mọi thứ vẫn được tree-shake, chỉ phần dùng mới vào gói. Có thể tắt hoặc xem định nghĩa kiểu trong `.nuxt/imports.d.ts`.

// utils/dinhDang.js
export const tienViet = (n) => `${n.toLocaleString('vi-VN')}đ`;

// composables/useDem.js
export const useDem = () => {
  const dem = useState('dem', () => 0);
  return { dem, tang: () => dem.value++ };
};

// pages/index.vue: không có dòng import nào
// const { dem, tang } = useDem();
// tang();
// console.log(tienViet(dem.value * 1000));

Kết quả

- Trang gọi `useDem()` và `tienViet()` mà không có `import` nào
- Sau một lần `tang()`, console in `1.000đ`
- `useState` của Nuxt dùng khóa `'dem'` nên mọi component chia sẻ cùng giá trị và an toàn với SSR

Lưu ý

- Tên tệp trong `composables/` và `utils/` phải khớp tên hàm xuất ra để tránh nhầm
- Có thể tắt tự động import trong `nuxt.config` nếu muốn import tường minh

React Native cho viết ứng dụng di động gốc (iOS và Android) bằng JavaScript/TypeScript và React. Thay vì thẻ HTML, bạn dùng các component gốc như `View`, `Text`, `Image`, `ScrollView`; chúng được vẽ bằng giao diện native thật của hệ điều hành (không phải WebView). Một code base dùng cho cả hai nền tảng, có thể viết mã riêng khi cần. Cách bắt đầu khuyên dùng là Expo.

import { useState } from 'react';
import { View, Text, Pressable, StyleSheet } from 'react-native';

export default function App() {
  const [dem, setDem] = useState(0);
  return (
    <View style={styles.khung}>
      <Text style={styles.chu}>Đã bấm {dem} lần</Text>
      <Pressable onPress={() => setDem(dem + 1)}><Text>Bấm tôi</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  khung: { flex: 1, alignItems: 'center', justifyContent: 'center' },
  chu: { fontSize: 20 },
});

Kết quả

- Trên điện thoại hiện dòng `Đã bấm 0 lần` ở giữa màn hình và nút `Bấm tôi`
- Mỗi lần chạm vào nút, state đổi và chữ cập nhật `Đã bấm 1 lần`, `Đã bấm 2 lần`...
- Cùng đoạn code chạy được trên iOS và Android

Lưu ý

- Tạo dự án: `npx create-expo-app@latest`
- Không có thẻ HTML hay CSS; kiểu dáng viết bằng object JavaScript (giống flexbox)

`View` là khối bố cục cơ bản của React Native (tương đương `div`), render thành thành phần native thật của hệ điều hành. Mặc định bố cục bằng flexbox với `flexDirection: 'column'` (xếp dọc, khác web mặc định là hàng). Lồng được, nhận `style` (xem StyleSheet), và có các biến thể: `SafeAreaView` (tránh tai thỏ, thanh trạng thái), `ScrollView` (cuộn), `KeyboardAvoidingView`. Đơn vị là điểm độc lập mật độ, không có `px`.

import { View } from 'react-native';

export default function Khung() {
  return (
    <View style={{ flex: 1, padding: 16, backgroundColor: '#eee' }}>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>
        <View style={{ width: 40, height: 40, backgroundColor: 'tomato' }} />
        <View style={{ width: 40, height: 40, backgroundColor: 'steelblue' }} />
      </View>
    </View>
  );
}

Kết quả

- Khung xám phủ toàn màn hình (`flex: 1`), lề trong 16
- Hai ô vuông 40×40 (đỏ cà chua và xanh thép) nằm trên một hàng, đẩy về hai đầu nhờ `space-between`
- Bỏ `flexDirection: 'row'` thì hai ô xếp chồng theo cột

Lưu ý

- `View` không hiển thị chữ trực tiếp; chữ phải nằm trong `Text`
- Dùng `SafeAreaView` (từ `react-native-safe-area-context`) cho phần gốc của màn hình

React Native không có CSS; kiểu dáng là object JavaScript với tên thuộc tính viết camelCase (`backgroundColor`, `fontSize`). `StyleSheet.create({...})` gom các kiểu đặt tên ở cuối tệp để dùng lại và được kiểm tra. Truyền mảng `style={[a, b]}` để gộp (cái sau ghi đè cái trước), thêm điều kiện bằng `cond && kieu`. Bố cục dùng flexbox: `flex`, `flexDirection`, `justifyContent`, `alignItems`, `gap`.

import { View, Text, StyleSheet } from 'react-native';

export default function The({ noiBat }) {
  return (
    <View style={[styles.the, noiBat && styles.noiBat]}>
      <Text style={styles.chu}>Thẻ</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  the: { padding: 12, borderRadius: 8, backgroundColor: '#eee', flexDirection: 'row', gap: 8 },
  noiBat: { backgroundColor: 'gold' },
  chu: { fontSize: 16 },
});

Kết quả

- Thẻ có nền xám nhạt, bo góc 8, padding 12
- Truyền `noiBat` thì kiểu `noiBat` ghi đè nền thành màu vàng
- Không có thừa kế kiểu như CSS: chữ trong `Text` không tự nhận kiểu của `View` cha

Lưu ý

- Giá trị số không kèm đơn vị; phần trăm viết chuỗi `'50%'`
- Dùng `StyleSheet.absoluteFill` để phủ kín phần tử cha

`FlatList` hiển thị danh sách dài hiệu quả bằng cách chỉ vẽ các dòng đang trong màn hình (ảo hóa), thay vì vẽ tất cả như `ScrollView` + `map`. Props chính: `data` (mảng), `renderItem` (nhận `{ item, index }`), `keyExtractor` (khóa duy nhất mỗi dòng), cùng `ListEmptyComponent`, `ListHeaderComponent`, `onEndReached` (tải thêm), `refreshing` + `onRefresh` (kéo để làm mới). Dữ liệu theo nhóm dùng `SectionList`.

import { FlatList, Text, View } from 'react-native';

const data = Array.from({ length: 1000 }, (_, i) => ({ id: String(i), ten: `Mục ${i + 1}` }));

export default function DanhSach() {
  return (
    <FlatList
      data={data}
      keyExtractor={(m) => m.id}
      renderItem={({ item }) => <View style={{ padding: 12 }}><Text>{item.ten}</Text></View>}
      ListEmptyComponent={<Text>Không có dữ liệu</Text>}
    />
  );
}

Kết quả

- Màn hình hiện khoảng 10–15 dòng đầu (`Mục 1`, `Mục 2`...); cuộn xuống thì các dòng mới được vẽ và dòng đã ra khỏi màn hình được tái sử dụng
- Dù có 1000 phần tử, bộ nhớ và thời gian vẽ vẫn thấp
- Nếu `data` rỗng hiện `Không có dữ liệu`

Lưu ý

- Giữ `renderItem` nhẹ và có thể bọc `React.memo`
- `keyExtractor` phải trả chuỗi duy nhất và ổn định

React Navigation quản lý nhiều màn hình trong ứng dụng di động. Các bộ điều hướng chính: Stack (chồng màn hình, có nút Back), Bottom Tabs, Drawer. Bạn bọc ứng dụng bằng `NavigationContainer`, khai báo màn hình trong navigator, rồi chuyển bằng `navigation.navigate('TenMan', { thamSo })`; màn hình đích đọc `route.params`. Với Expo có thể dùng Expo Router (định tuyến theo tệp) dựng trên nó.

import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { Button, Text } from 'react-native';

const Stack = createNativeStackNavigator();

const TrangChu = ({ navigation }) => (
  <Button title="Xem chi tiết" onPress={() => navigation.navigate('ChiTiet', { id: 7 })} />
);
const ChiTiet = ({ route }) => <Text>Sản phẩm {route.params.id}</Text>;

export default function App() {
  return (
    <NavigationContainer>
      <Stack.Navigator>
        <Stack.Screen name="TrangChu" component={TrangChu} options={{ title: 'Trang chủ' }} />
        <Stack.Screen name="ChiTiet" component={ChiTiet} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}

Kết quả

- Màn đầu có thanh tiêu đề `Trang chủ` và nút `Xem chi tiết`
- Bấm nút: màn `ChiTiet` trượt vào hiện `Sản phẩm 7`, thanh tiêu đề có nút Back để quay lại
- Cử chỉ vuốt từ cạnh trái (iOS) cũng quay lại màn trước

Lưu ý

- Truyền ít tham số (id) rồi tải dữ liệu ở màn đích
- Màn hình trong stack vẫn giữ state khi bạn đi tới màn khác

Framework của Google viết ứng dụng iOS, Android, web, desktop từ MỘT code Dart; tự vẽ giao diện bằng engine riêng nên đồng nhất trên mọi nền tảng. Mọi thứ đều là Widget.

void main() => runApp(const MaterialApp(home: TrangChu()));

class TrangChu extends StatelessWidget {
  const TrangChu({super.key});
  @override
  Widget build(BuildContext context) =>
      const Scaffold(body: Center(child: Text('Xin chào Flutter')));
}

StatelessWidget: giao diện chỉ phụ thuộc tham số truyền vào. StatefulWidget: có State riêng thay đổi theo thời gian.

class BoDem extends StatefulWidget {
  const BoDem({super.key});
  @override
  State<BoDem> createState() => _BoDemState();
}

class _BoDemState extends State<BoDem> {
  int dem = 0;
  @override
  Widget build(BuildContext context) => ElevatedButton(
        onPressed: () => setState(() => dem++),
        child: Text('Đã bấm $dem lần'),
      );
}

Báo cho Flutter state đã đổi để build lại widget. State dùng chung nhiều màn hình thì dùng thư viện quản lý state (Provider, Riverpod, Bloc).

setState(() {
  danhSach.add(viecMoi);    // sửa state BÊN TRONG hàm truyền vào
});

Điều hướng giữa các màn hình theo kiểu ngăn xếp: push mở màn hình mới, pop quay lại (go_router cho định tuyến theo URL).

Navigator.push(context, MaterialPageRoute(builder: (_) => ChiTiet(sp: sp)));
Navigator.pop(context, ketQua);   // quay lại, trả kết quả cho màn hình trước

Khai báo biến bằng var (suy luận kiểu), final (gán một lần), const (hằng lúc biên dịch). Kiểu có ? mới được chứa null.

var ten = 'An';            // String
final ngay = DateTime.now();
const pi = 3.14;
String? bietDanh;          // có thể null
print(bietDanh ?? 'chưa có');
print(bietDanh?.length);
int doDai = bietDanh!.length;   // ! khẳng định không null (sai sẽ lỗi khi chạy)

Hàm có tham số vị trí, tham số đặt tên {...} (có thể required), tham số tùy chọn [...] và cú pháp mũi tên => cho hàm một biểu thức.

int cong(int a, int b) => a + b;

void chao({required String ten, String loiChao = 'Xin chào'}) {
  print('$loiChao, $ten');
}
chao(ten: 'An');

Class với constructor rút gọn this.x, named constructor, getter, và kế thừa extends.

class SanPham {
  final String ten;
  final int gia;
  const SanPham(this.ten, this.gia);
  SanPham.mienPhi(this.ten) : gia = 0;          // named constructor
  String get moTa => '$ten: $gia đ';
}

Future là giá trị có trong tương lai (như Promise); async/await viết code bất đồng bộ tuần tự.

Future<List<SanPham>> taiSanPham() async {
  final res = await http.get(Uri.parse('https://api.site.com/sp'));
  if (res.statusCode != 200) throw Exception('Lỗi ${res.statusCode}');
  return (jsonDecode(res.body) as List).map((j) => SanPham.fromJson(j)).toList();
}

Collection của Dart có sẵn map, where (lọc), fold, và cú pháp "collection if/for" trong literal.

final so = [1, 2, 3, 4];
final chan = so.where((x) => x.isEven).toList();
final tong = so.fold(0, (a, b) => a + b);
final diem = {'an': 8, 'binh': 9};
final menu = ['Trang chủ', if (daDangNhap) 'Tài khoản', for (final m in them) m];

Stream phát ra NHIỀU giá trị theo thời gian (sự kiện, dữ liệu realtime); duyệt bằng await for, hoặc hiển thị bằng StreamBuilder trong Flutter.

Stream<int> demNguoc(int n) async* {
  for (var i = n; i > 0; i--) {
    await Future.delayed(const Duration(seconds: 1));
    yield i;
  }
}
await for (final x in demNguoc(3)) print(x);

React Router ánh xạ URL với component trong ứng dụng một trang (SPA): đổi địa chỉ mà không tải lại trang. Bạn khai báo cây route (đường dẫn → component), dùng `<Link>` để chuyển trang, hook `useParams`, `useNavigate`, `useSearchParams` để đọc và điều khiển URL, và `<Outlet>` để lồng route con vào bố cục chung. Từ bản 6.4 có chế độ data router với `loader` và `action` để tải và ghi dữ liệu theo route; bản 7 gộp thêm khả năng làm framework (như Remix).

import { createBrowserRouter, RouterProvider, Link } from 'react-router-dom';

const router = createBrowserRouter([
  { path: '/', element: <Link to="/gioi-thieu">Giới thiệu</Link> },
  { path: '/gioi-thieu', element: <h1>Trang giới thiệu</h1> },
  { path: '*', element: <h1>Không tìm thấy</h1> },
]);

export default function App() {
  return <RouterProvider router={router} />;
}

Kết quả

- Vào `/` thấy liên kết `Giới thiệu`; bấm vào thì URL đổi thành `/gioi-thieu` và hiện `Trang giới thiệu` mà không tải lại trang
- Vào đường dẫn lạ như `/abc` rơi vào route `*` và hiện `Không tìm thấy`

Lưu ý

- Máy chủ phải trả `index.html` cho mọi đường dẫn để tải lại trang vẫn chạy (fallback SPA)
- Cài bằng `npm i react-router-dom` (hoặc `react-router` ở bản 7)

`<Link to="/duong-dan">` render thẻ `<a>` thật nhưng chặn tải lại trang: chỉ đổi URL và để Router vẽ route mới. `to` nhận chuỗi hoặc object `{ pathname, search, hash }`; đường dẫn tương đối tính từ route hiện tại. Có các prop `replace` (thay mục lịch sử hiện tại), `state` (gửi dữ liệu kèm lần chuyển trang, đọc bằng `useLocation().state`), `reloadDocument`. Dùng `<a href>` thường cho liên kết ra trang ngoài.

import { Link } from 'react-router-dom';

function Menu({ id }) {
  return (
    <nav>
      <Link to="/">Trang chủ</Link>
      <Link to={`/san-pham/${id}?tab=danh-gia`} state={{ tu: 'menu' }}>Xem sản phẩm</Link>
      <Link to="/dang-nhap" replace>Đăng nhập</Link>
    </nav>
  );
}

Kết quả

- Bấm `Xem sản phẩm` với `id = 5`: URL đổi thành `/san-pham/5?tab=danh-gia`, không tải lại trang, và trang đích đọc được `{ tu: 'menu' }` qua `useLocation().state`
- Bấm `Đăng nhập`: thay mục lịch sử hiện tại nên nút Back không quay về trang trước đó
- Thẻ được render là `<a href="/">...` (hỗ trợ mở tab mới bằng chuột giữa)

Lưu ý

- Không dùng `<a href>` cho liên kết nội bộ vì tải lại cả trang
- Để đánh dấu mục menu hiện tại dùng `<NavLink>`

`useNavigate()` trả về hàm `navigate` để chuyển trang bằng code, thường sau khi đăng nhập thành công hoặc gửi biểu mẫu. `navigate('/duong-dan')` thêm một mục lịch sử; `navigate('/x', { replace: true })` thay mục hiện tại để nút Back không quay lại; `navigate(-1)` lùi một bước. Với chuyển trang ngay khi render, dùng `<Navigate to="..." />`.

import { useNavigate } from 'react-router-dom';

function DangNhap() {
  const navigate = useNavigate();
  async function gui(e) {
    e.preventDefault();
    await fetch('/api/dang-nhap', { method: 'POST' });
    navigate('/bang-dieu-khien', { replace: true });
  }
  return (
    <form onSubmit={gui}>
      <button>Đăng nhập</button>
      <button type="button" onClick={() => navigate(-1)}>Quay lại</button>
    </form>
  );
}

Kết quả

- Gửi biểu mẫu xong: URL đổi sang `/bang-dieu-khien`, và vì `replace: true` nên nút Back không quay về trang đăng nhập
- Nút `Quay lại` đưa người dùng về trang trước trong lịch sử

Lưu ý

- Chỉ gọi `navigate` trong sự kiện hoặc effect, không gọi trong thân render
- Nếu chỉ cần liên kết, ưu tiên `<Link>` vì tốt hơn cho khả năng truy cập

Route có thể chứa đoạn động như `/san-pham/:id`. Hook `useParams()` trả về object các tham số khớp, ví dụ `{ id: '42' }`; giá trị luôn là chuỗi. Dùng nó để tải đúng dữ liệu cho trang chi tiết. Phần sau dấu `?` của URL (truy vấn) lấy bằng `useSearchParams()`.

import { useParams, useSearchParams } from 'react-router-dom';

// route: { path: '/san-pham/:id', element: <ChiTiet /> }
function ChiTiet() {
  const { id } = useParams();
  const [qs] = useSearchParams();
  return <p>Sản phẩm {id}, tab: {qs.get('tab') ?? 'mac-dinh'}</p>;
}

Kết quả

- Vào `/san-pham/42?tab=danh-gia` hiện `Sản phẩm 42, tab: danh-gia`
- Vào `/san-pham/7` hiện `Sản phẩm 7, tab: mac-dinh`
- `id` là chuỗi `'42'`; cần `Number(id)` nếu muốn so sánh số

Lưu ý

- Tham số động không tồn tại sẽ không có trong object; luôn kiểm tra dữ liệu tải được
- Với TypeScript, kiểu của `useParams()` là `Readonly<Params<string>>`

Route có thể lồng nhau: route cha dựng bố cục chung (đầu trang, menu), route con là nội dung thay đổi. `<Outlet />` đặt trong component cha chỉ chỗ route con khớp sẽ được hiển thị. Nhờ vậy header và sidebar giữ nguyên khi chuyển giữa các trang con, trạng thái của chúng không bị mất.

import { Outlet, Link, createBrowserRouter } from 'react-router-dom';

function BoCuc() {
  return (
    <>
      <header><Link to="/">Trang chủ</Link> | <Link to="/ho-so">Hồ sơ</Link></header>
      <main><Outlet /></main>
    </>
  );
}

export const router = createBrowserRouter([
  {
    path: '/',
    element: <BoCuc />,
    children: [
      { index: true, element: <h1>Chào mừng</h1> },
      { path: 'ho-so', element: <h1>Hồ sơ của bạn</h1> },
    ],
  },
]);

Kết quả

- Vào `/`: header cùng `Chào mừng` ở vị trí `<Outlet />`
- Bấm `Hồ sơ`: header giữ nguyên, phần `<main>` đổi thành `Hồ sơ của bạn`
- `index: true` là route con mặc định khi URL khớp đúng đường dẫn của cha

Lưu ý

- Route con có `path` tương đối so với cha (không có dấu `/` ở đầu)
- Route bố cục không có `path` vẫn dùng được để bọc nhóm route

`loader` là hàm khai báo trên route trong data router (`createBrowserRouter`), chạy TRƯỚC khi route được vẽ để tải dữ liệu; kết quả đọc trong component bằng `useLoaderData()`. Nhận `{ params, request }` (đọc tham số đường dẫn và truy vấn). Khác `useEffect` + `fetch` (vẽ trước, tải sau, thấy trạng thái trống), loader tải song song cho các route lồng nhau, tránh thác nước yêu cầu. Ném `Response` hoặc lỗi để hiện `errorElement`; trả `redirect('/dang-nhap')` để chuyển hướng.

import { createBrowserRouter, useLoaderData } from 'react-router-dom';

async function loaderNguoi({ params }) {
  const r = await fetch(`/api/nguoi/${params.id}`);
  if (!r.ok) throw new Response('Không thấy', { status: 404 });
  return r.json();
}

function Nguoi() {
  const nguoi = useLoaderData();
  return <h1>{nguoi.ten}</h1>;
}

export const router = createBrowserRouter([
  { path: '/nguoi/:id', element: <Nguoi />, loader: loaderNguoi, errorElement: <p>Có lỗi</p> },
]);

Kết quả

- Vào `/nguoi/3`: loader gọi `/api/nguoi/3` TRƯỚC, rồi `Nguoi` render sẵn với dữ liệu (không có trạng thái "đang tải" rỗng)
- Nếu API trả 404, loader ném `Response`, router hiện `errorElement` (`Có lỗi`) thay cho trang
- Chuyển từ `/nguoi/3` sang `/nguoi/4` làm loader chạy lại với `id = 4`

Lưu ý

- Với bộ nhớ đệm và làm mới nền, kết hợp loader với TanStack Query
- Loader chỉ chạy ở phía client trong chế độ SPA

TanStack Query (trước đây React Query) quản lý "state từ server": tải dữ liệu, lưu đệm, làm mới nền, loại bỏ yêu cầu trùng, thử lại khi lỗi, phân trang và cập nhật lạc quan. Bạn khai báo truy vấn gồm khóa (`queryKey`) và hàm tải (`queryFn`); thư viện trả về `data`, `isPending`, `error` và lo phần còn lại. Nó thay thế phần lớn code `useEffect` + `useState` + `fetch` thủ công, và không buộc bạn gom dữ liệu server vào Redux. Có bản cho React, Vue, Svelte, Solid, Angular.

import { QueryClient, QueryClientProvider, useQuery } from '@tanstack/react-query';

const queryClient = new QueryClient();

function DanhSach() {
  const { data, isPending, error } = useQuery({
    queryKey: ['viec'],
    queryFn: () => fetch('/api/viec').then((r) => r.json()),
  });
  if (isPending) return <p>Đang tải...</p>;
  if (error) return <p>Lỗi: {error.message}</p>;
  return <ul>{data.map((v) => <li key={v.id}>{v.ten}</li>)}</ul>;
}

export default () => (
  <QueryClientProvider client={queryClient}>
    <DanhSach />
  </QueryClientProvider>
);

Kết quả

- Hiện `Đang tải...`, sau đó danh sách công việc khi API trả về
- Mount `DanhSach` ở hai nơi cùng lúc chỉ gửi một request nhờ bộ nhớ đệm theo khóa `['viec']`
- Chuyển tab rồi quay lại, dữ liệu được tải lại ở nền (refetch on window focus)

Lưu ý

- Phân biệt state server (dùng thư viện này) với state giao diện (dùng useState/Zustand)
- Bọc ứng dụng bằng một `QueryClientProvider` duy nhất

`useQuery({ queryKey, queryFn, ...tuyChon })` đăng ký một truy vấn. Kết quả có `data`, `isPending` (chưa có dữ liệu), `isFetching` (đang tải nền), `error`, `refetch`. Tùy chọn hay dùng: `staleTime` (bao lâu dữ liệu còn "mới", mặc định 0), `gcTime` (bao lâu giữ cache khi không ai dùng), `enabled: false` (hoãn chạy cho đến khi đủ điều kiện, ví dụ chờ có `id`), `retry`, `select` (biến đổi dữ liệu). Khóa truy vấn là mảng chứa mọi biến mà `queryFn` phụ thuộc.

import { useQuery } from '@tanstack/react-query';

function HoSo({ id }) {
  const { data, isPending, isFetching } = useQuery({
    queryKey: ['nguoi', id],
    queryFn: () => fetch(`/api/nguoi/${id}`).then((r) => r.json()),
    enabled: !!id,
    staleTime: 60_000,
  });
  if (isPending) return <p>Đang tải...</p>;
  return <h1>{data.ten} {isFetching && '(đang làm mới)'}</h1>;
}

Kết quả

- Lần đầu với `id = 1`: `Đang tải...` rồi `An` (tên người dùng)
- Chuyển sang `id = 2`: khóa `['nguoi', 2]` là truy vấn mới, tải riêng; quay lại `id = 1` thì lấy ngay từ cache
- Trong 60 giây `staleTime`, mount lại không gọi API nữa; sau đó hiện dữ liệu cũ kèm `(đang làm mới)` trong khi tải nền
- `id` rỗng thì `enabled: false` và không gửi request

Lưu ý

- Đưa mọi biến vào `queryKey` để cache đúng và tự tải lại khi biến đổi
- `queryFn` phải ném lỗi (hoặc trả Promise bị từ chối) khi HTTP lỗi: `fetch` không tự làm điều này

`useMutation({ mutationFn })` dùng cho thao tác ghi. Khác `useQuery`, nó không chạy tự động mà bạn gọi `mutate(bienSo)`. Có các callback `onSuccess`, `onError`, `onSettled` và trạng thái `isPending`, `error`. Mẫu thường gặp: sau khi ghi thành công, làm hỏng (`invalidateQueries`) truy vấn liên quan để dữ liệu hiển thị được tải lại. Cập nhật lạc quan: sửa cache ngay ở `onMutate`, hoàn tác ở `onError`.

import { useMutation, useQueryClient } from '@tanstack/react-query';

function ThemViec() {
  const qc = useQueryClient();
  const them = useMutation({
    mutationFn: (ten) =>
      fetch('/api/viec', { method: 'POST', body: JSON.stringify({ ten }) }).then((r) => r.json()),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['viec'] }),
  });
  return (
    <button disabled={them.isPending} onClick={() => them.mutate('Học Query')}>
      {them.isPending ? 'Đang lưu...' : 'Thêm việc'}
    </button>
  );
}

Kết quả

- Bấm nút: hiện `Đang lưu...` và nút bị vô hiệu cho đến khi POST xong
- `onSuccess` làm hỏng khóa `['viec']`, nên mọi `useQuery(['viec'])` tự tải lại và danh sách có thêm `Học Query`
- Nếu POST lỗi, `them.error` có thông báo và `onSuccess` không chạy

Lưu ý

- Dùng `mutateAsync` nếu muốn `await` kết quả trong code
- Với cập nhật lạc quan nhớ lưu bản cũ để hoàn tác khi lỗi

`queryKey` là mảng định danh một mục trong cache, ví dụ `['nguoi', id, { tab }]`; so sánh theo nội dung nên thứ tự phần tử quan trọng nhưng thứ tự khóa trong object thì không. `queryClient.invalidateQueries({ queryKey: ['nguoi'] })` đánh dấu mọi truy vấn có khóa bắt đầu bằng `['nguoi']` là cũ và tải lại những truy vấn đang hiển thị. `setQueryData` ghi thẳng vào cache, `removeQueries` xóa, `cancelQueries` hủy yêu cầu đang chạy.

import { useQueryClient } from '@tanstack/react-query';

function CongCu() {
  const qc = useQueryClient();
  return (
    <>
      <button onClick={() => qc.invalidateQueries({ queryKey: ['nguoi'] })}>Làm mới mọi người</button>
      <button onClick={() => qc.setQueryData(['nguoi', 1], { id: 1, ten: 'An (đã sửa)' })}>Sửa cache</button>
      <button onClick={() => qc.removeQueries({ queryKey: ['nguoi', 2] })}>Xóa cache người 2</button>
    </>
  );
}

Kết quả

- Nút 1 tải lại `['nguoi', 1]`, `['nguoi', 2]`... mọi khóa bắt đầu bằng `nguoi` mà đang có component dùng
- Nút 2 thay ngay dữ liệu người 1 trong giao diện thành `An (đã sửa)` không cần gọi API
- Nút 3 xóa cache người 2; lần sau dùng sẽ tải mới từ đầu

Lưu ý

- Tổ chức khóa theo thứ bậc từ chung đến riêng để làm hỏng theo nhóm dễ
- Dùng hàm tạo khóa (query key factory) để tránh gõ nhầm chuỗi

`app.get(duongDan, handler)` đăng ký hàm xử lý cho yêu cầu GET (đọc dữ liệu). Đường dẫn có thể chứa tham số `:id` (đọc từ `req.params`), ký tự `*` hoặc biểu thức chính quy. Handler nhận `(req, res)` và phải kết thúc yêu cầu bằng `res.send/json/status().end`. Route khớp theo thứ tự khai báo; route đầu tiên khớp và đã trả lời sẽ thắng, nên đặt route cụ thể trước route có tham số. Cũng có `app.put`, `app.patch`, `app.delete` cho các phương thức khác.

const sach = [{ id: 1, ten: 'JavaScript' }];

app.get('/sach', (req, res) => res.json(sach));

app.get('/sach/:id', (req, res) => {
  const s = sach.find((x) => x.id === Number(req.params.id));
  if (!s) return res.status(404).json({ loi: 'không tìm thấy' });
  res.json(s);
});

Kết quả

- `GET /sach` trả `[{"id":1,"ten":"JavaScript"}]`
- `GET /sach/1` trả `{"id":1,"ten":"JavaScript"}`
- `GET /sach/9` trả mã 404 với `{"loi":"không tìm thấy"}`

Lưu ý

- `req.params.id` luôn là chuỗi; ép kiểu trước khi so sánh
- Dùng `return res...` khi kết thúc sớm để không chạy tiếp phần dưới

`req` (request) mô tả yêu cầu đến: `req.params` (đoạn `:id` của đường dẫn), `req.query` (phần sau dấu `?`, đã phân tích thành object), `req.body` (cần middleware đọc body), `req.headers` (tiêu đề, khóa viết thường), `req.get('Ten-Header')`, `req.method`, `req.path`, `req.originalUrl`, `req.ip`, `req.cookies` (cần `cookie-parser`). Mọi giá trị trong `params` và `query` là chuỗi (hoặc mảng chuỗi nếu khóa lặp).

app.get('/tim/:loai', (req, res) => {
  const { loai } = req.params;
  const { q = '', trang = '1' } = req.query;
  res.json({
    loai,
    tuKhoa: q,
    trang: Number(trang),
    phuongThuc: req.method,
    coUserAgent: Boolean(req.get('user-agent')),
  });
});

Kết quả

- `GET /tim/sach?q=node&trang=2` trả `{"loai":"sach","tuKhoa":"node","trang":2,"phuongThuc":"GET","coUserAgent":true}`
- `GET /tim/but` trả `{"loai":"but","tuKhoa":"","trang":1,...}` nhờ giá trị mặc định
- `GET /tim/sach?tag=a&tag=b` làm `req.query.tag` là mảng `['a', 'b']`

Lưu ý

- Luôn ép kiểu giá trị lấy từ `params` và `query`
- Không tin dữ liệu từ `req`; kiểm tra bằng thư viện schema

Middleware là hàm `(req, res, next)` chạy theo thứ tự khai báo cho các yêu cầu khớp. Nó có thể đọc hoặc sửa `req`/`res`, kết thúc yêu cầu bằng cách trả lời, hoặc gọi `next()` để chuyển cho middleware kế tiếp. `app.use(fn)` áp dụng cho mọi đường dẫn, `app.use('/api', fn)` chỉ cho tiền tố đó. Có sẵn `express.json()`, `express.urlencoded()`, `express.static()`; thư viện ngoài như `morgan` (log), `cors`, `helmet`. Thứ tự rất quan trọng.

app.use((req, res, next) => {
  req.batDau = Date.now();
  console.log(req.method, req.url);
  next();
});

app.use(express.json());

app.get('/xin-chao', (req, res) => {
  res.json({ msg: 'chào', ms: Date.now() - req.batDau });
});

Kết quả

- Mỗi yêu cầu in dòng log, ví dụ `GET /xin-chao`, trước khi vào route
- `GET /xin-chao` trả `{"msg":"chào","ms":0}` (số mili giây xử lý)
- Quên gọi `next()` thì yêu cầu bị treo vì không ai trả lời

Lưu ý

- Khai báo middleware dùng chung (json, cors, log) trước các route
- Middleware có 4 tham số `(err, req, res, next)` là middleware xử lý lỗi

`express.Router()` tạo "ứng dụng thu nhỏ" gồm các route và middleware riêng, sau đó gắn vào ứng dụng chính dưới một tiền tố bằng `app.use('/sach', router)`. Dùng để chia API theo tài nguyên (người dùng, sách, đơn hàng) thành các tệp riêng. Router có thể có middleware chỉ áp dụng cho nhóm đó (như kiểm tra đăng nhập) và `router.route('/').get(...).post(...)` gom nhiều phương thức một đường dẫn.

// routes/sach.js
import { Router } from 'express';
const router = Router();

router.get('/', (req, res) => res.json([{ id: 1 }]));
router.get('/:id', (req, res) => res.json({ id: Number(req.params.id) }));

export default router;

// app.js
import sachRouter from './routes/sach.js';
app.use('/api/sach', sachRouter);

Kết quả

- `GET /api/sach` trả `[{"id":1}]`
- `GET /api/sach/5` trả `{"id":5}`
- Trong router, đường dẫn viết tương đối so với tiền tố `/api/sach`

Lưu ý

- Mỗi tài nguyên một router, đặt trong thư mục `routes/`
- Dùng `Router({ mergeParams: true })` khi router con cần tham số của router cha

Middleware xử lý lỗi có bốn tham số `(err, req, res, next)` và phải khai báo SAU mọi route. Lỗi đồng bộ ném trong handler, hoặc lỗi bạn chuyển bằng `next(err)`, sẽ nhảy tới nó. Express 5 cũng tự chuyển lỗi/từ chối Promise từ handler `async`; Express 4 cần `try/catch` rồi `next(err)`. Dùng nó để trả lỗi JSON thống nhất và ghi log; thêm một middleware 404 cuối cùng cho đường dẫn không khớp.

app.get('/loi', (req, res) => {
  throw new Error('có sự cố');
});

app.use((req, res) => {
  res.status(404).json({ loi: 'không tìm thấy đường dẫn' });
});

app.use((err, req, res, next) => {
  console.error(err.message);
  res.status(err.status ?? 500).json({ loi: err.message });
});

Kết quả

- `GET /loi` in `có sự cố` trên console và trả mã 500 với `{"loi":"có sự cố"}`
- `GET /abc` (không có route) trả mã 404 với `{"loi":"không tìm thấy đường dẫn"}`
- Không lộ stack trace cho người dùng

Lưu ý

- Trong môi trường production đừng trả `err.stack` ra ngoài
- Đặt `err.status` (hoặc dùng `http-errors`) để điều khiển mã trả về

`express.static('thu-muc')` là middleware phục vụ các tệp trong thư mục như một máy chủ tệp tĩnh: đường dẫn tương ứng cấu trúc thư mục, tự đặt `Content-Type`, `ETag`, `Last-Modified`. Có thể gắn dưới tiền tố (`app.use('/tai-nguyen', ...)`) và cấu hình `maxAge` để trình duyệt lưu đệm, `index` (trang mặc định). Thích hợp phục vụ bản build của ứng dụng React/Vue cùng API trên một cổng.

import path from 'node:path';

app.use(express.static('public', { maxAge: '1d' }));
app.use('/tai-nguyen', express.static(path.join(process.cwd(), 'uploads')));

app.get('*', (req, res) => {
  res.sendFile(path.resolve('public', 'index.html'));
});

Kết quả

- `GET /style.css` trả tệp `public/style.css` với `Content-Type: text/css` và `Cache-Control: public, max-age=86400`
- `GET /tai-nguyen/anh.png` trả `uploads/anh.png`
- Mọi đường dẫn khác trả `index.html` (hữu ích cho SPA có định tuyến phía client)

Lưu ý

- Đừng đặt thư mục chứa mã nguồn hay bí mật làm thư mục tĩnh
- Đặt route `*` fallback sau API để không nuốt chúng

