Giới hạn những class nào được kế thừa (Java 17): switch trên kiểu sealed biết đã xét hết trường hợp.

sealed interface Hinh permits Tron, ChuNhat {}
record Tron(double r) implements Hinh {}
record ChuNhat(double dai, double rong) implements Hinh {}

double dienTich(Hinh h) {
    return switch (h) {
        case Tron t -> Math.PI * t.r() * t.r();
        case ChuNhat c -> c.dai() * c.rong();
    };   // không cần default
}

