Hàm trong impl: có self là method (gọi x.ham()), không có self là hàm liên kết (gọi Kieu::ham(), như constructor new).

impl HinhChuNhat {
    fn new(r: f64, c: f64) -> Self { Self { rong: r, cao: c } }   // HinhChuNhat::new
    fn dien_tich(&self) -> f64 { self.rong * self.cao }            // chỉ đọc
    fn phong_to(&mut self, k: f64) { self.rong *= k; self.cao *= k; }
    fn tieu_thu(self) -> (f64, f64) { (self.rong, self.cao) }      // lấy quyền sở hữu
}

