enum LoiApp { KhongThay(u32), Io(std::io::Error) }
impl std::fmt::Display for LoiApp {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self { LoiApp::KhongThay(id) => write!(f, "không thấy {id}"), LoiApp::Io(e) => write!(f, "io: {e}") }
