function sloppyGrade() {
  mark = 10;
  return mark;
}

function strictGrade() {
  'use strict';
  try {
    exam = 10;
  } catch (e) {
    console.log(e.name);
    console.log(e.message);
  }
}

console.log(sloppyGrade());
strictGrade();

Kết quả

sloppyGrade() → 10
e.name → 'ReferenceError'
e.message → 'exam is not defined'

Strict mode thay đổi gì

Biến chưa khai báo: gán vào sẽ ném `ReferenceError`, không còn tự tạo biến toàn cục
`this` trong hàm thường: là `undefined`, không phải đối tượng toàn cục
Tên tham số trùng nhau, `with`, số bát phân `010`: đều là lỗi cú pháp
Gán vào thuộc tính chỉ đọc hoặc đã đóng băng: ném `TypeError` thay vì bị bỏ qua

Lưu ý

- Chuỗi `'use strict'` chỉ có tác dụng khi nằm ở dòng đầu tiên của file hoặc của hàm
- Code bundle bằng công cụ hiện đại (Vite, webpack) hầu hết đã là ES Module nên tự ở strict mode

Dấu chấm phẩy kết thúc câu lệnh là tùy chọn vì cơ chế ASI (Automatic Semicolon Insertion) tự chèn chúng khi xuống dòng. Phần lớn thời gian việc này vô hại, nhưng có vài chỗ nguy hiểm: `return` xuống dòng ngay sau từ khóa sẽ trả về `undefined`, và dòng bắt đầu bằng `(`, `[` hoặc dấu backtick bị nối vào dòng trước. Dù theo phong cách nào, hãy dùng Prettier hoặc ESLint để thống nhất.

function getScore() {
  return
  9;
}
console.log(getScore());

const math = 8
const literature = 7
console.log(math + literature)

function total() {
  return (
    8 + 9
  );
}
console.log(total());

Kết quả

getScore() → undefined
math + literature → 15
total() → 17

Lưu ý

- Với phong cách không dùng `;`, hãy thêm `;` đầu dòng nếu dòng bắt đầu bằng `(`, `[` hoặc backtick
- Đặt giá trị trả về cùng dòng với `return`, hoặc bọc trong ngoặc như ví dụ cuối
- `throw`, `break`, `continue` cũng không được xuống dòng ngay sau từ khóa

Vòng lặp sự kiện (event loop) là cơ chế điều phối code bất đồng bộ trên một luồng: nó chạy hết code đang trên call stack, rồi chạy HẾT hàng đợi microtask (callback của Promise, `queueMicrotask`, `await`), rồi lấy một macrotask (`setTimeout`, sự kiện giao diện, I/O) để chạy, rồi lại xả microtask và cứ thế. Hệ quả là: mọi microtask luôn chạy trước macrotask kế tiếp, và `setTimeout(fn, 0)` chỉ chạy sau khi code đồng bộ và microtask xong. Trình duyệt vẽ lại giao diện giữa các macrotask.

console.log('1. đồng bộ');
setTimeout(() => console.log('8. macrotask: setTimeout 0'), 0);
Promise.resolve().then(() => console.log('3. microtask: then'));
queueMicrotask(() => console.log('4. microtask: queueMicrotask'));
(async () => {
  console.log('2. async chạy đồng bộ đến await');
  await null;
  console.log('5. phần sau await là microtask');
})();
console.log('2b. đồng bộ kết thúc');
Promise.resolve()
  .then(() => {
    console.log('6. then lồng 1');
    return Promise.resolve();
  })
  .then(() => console.log('7. then lồng 2'));
setTimeout(() => console.log('9. timeout 5ms'), 5);

Kết quả

1. đồng bộ
2. async chạy đồng bộ đến await
2b. đồng bộ kết thúc
3. microtask: then
4. microtask: queueMicrotask
5. phần sau await là microtask
6. then lồng 1
7. then lồng 2
8. macrotask: setTimeout 0
9. timeout 5ms

Lưu ý

- Vòng lặp microtask vô hạn (microtask sinh microtask mãi) làm treo cả trang vì macrotask không bao giờ được chạy
- Trong Node.js còn có `process.nextTick` (chạy trước microtask của Promise) và `setImmediate` (sau pha I/O)
- `setTimeout(fn, 0)` thực tế bị trễ tối thiểu vài mili giây

`setTimeout(ham, ms, ...doiSo)` chạy hàm một lần sau ít nhất `ms` mili giây; `setInterval(ham, ms)` chạy lặp lại mỗi `ms`. Cả hai trả về một id (trong trình duyệt là số, trong Node.js là object `Timeout`) dùng với `clearTimeout`/`clearInterval` để hủy. Thời gian chỉ là tối thiểu vì hàm phải chờ đến lượt trong event loop; bộ hẹn giờ lệch dần với code nặng. Dùng `requestAnimationFrame` thay cho `setInterval` với hoạt ảnh.

setTimeout(() => console.log('tiết 2 sau 20ms'), 20);
setTimeout(() => console.log('tiết 1 sau 10ms'), 10);
setTimeout((a, b) => console.log('đối số:', a, b), 0, 'An', 'Bình');
const cancelled = setTimeout(() => console.log('không bao giờ in'), 15);
clearTimeout(cancelled);
let count = 0;
const bell = setInterval(() => {
  count++;
  console.log(`chuông ${count}`);
  if (count === 3) clearInterval(bell);
}, 8);
const sleep = (ms) => new Promise((done) => setTimeout(done, ms));
(async () => {
  await sleep(40);
  console.log('đã chờ 40ms bằng await');
})();
const schedule = () => setTimeout(() => console.log('timeout trong callback'), 0);
schedule();

Kết quả

đối số: An Bình
timeout trong callback
chuông 1
tiết 1 sau 10ms
tiết 2 sau 20ms
chuông 2
chuông 3
đã chờ 40ms bằng await

Lưu ý

- Hủy bộ hẹn giờ khi không còn cần (ví dụ khi component bị gỡ) để tránh rò rỉ và lỗi
- `setInterval` không đợi lần trước chạy xong; với tác vụ bất đồng bộ nên dùng `setTimeout` đệ quy
- Trình duyệt giới hạn bộ hẹn giờ ở tab nền (thường tối thiểu 1 giây)

Promise không thể hủy trực tiếp; chuẩn cách hủy tác vụ bất đồng bộ là `AbortController`. Tạo controller, truyền `controller.signal` cho tác vụ (như `fetch(url, { signal })`), gọi `controller.abort()` để báo dừng; tác vụ nhận tín hiệu sẽ từ chối với `AbortError`. `AbortSignal.timeout(ms)` tạo sẵn tín hiệu tự hủy sau thời gian chỉ định, còn `AbortSignal.any([...])` kết hợp nhiều tín hiệu. Tự viết hàm hỗ trợ hủy bằng cách lắng nghe sự kiện `abort` của signal.

const wait = (ms, signal) =>
  new Promise((done, reject) => {
    const t = setTimeout(done, ms, 'nộp bài xong');
    signal?.addEventListener('abort', () => {
      clearTimeout(t);
      reject(signal.reason);
    });
  });
const ac = new AbortController();
wait(1000, ac.signal).then(console.log, (e) => console.log('bị hủy:', e.name));
setTimeout(() => ac.abort(), 10);
console.log(ac.signal.aborted);
wait(500, AbortSignal.timeout(10)).catch((e) => console.log('hết giờ:', e.name));
const ac2 = new AbortController();
ac2.abort(new Error('lý do riêng'));
console.log(ac2.signal.aborted, ac2.signal.reason.message);
wait(5, new AbortController().signal).then(console.log);

Kết quả

ac.signal.aborted → false
ac2.signal.aborted, ac2.signal.reason.message → true 'lý do riêng'
nộp bài xong
bị hủy: AbortError
hết giờ: TimeoutError

Lưu ý

- Hủy chỉ có tác dụng nếu tác vụ lắng nghe signal; `fetch`, `addEventListener`, `timers/promises` đều hỗ trợ
- `AbortError` là lỗi thường gặp nên cần phân biệt khi xử lý lỗi: `if (e.name === 'AbortError') return`
- Trong React, hủy yêu cầu trong hàm dọn dẹp của `useEffect` để tránh cập nhật state sau khi component bị gỡ

Hai hệ module cùng tồn tại. ES Module (ESM): chuẩn ngôn ngữ, cú pháp `import`/`export`, phân tích tĩnh (công cụ biết trước phụ thuộc nên tối ưu và loại code thừa được), tải bất đồng bộ, hoạt động ở trình duyệt và Node.js. CommonJS (CJS): hệ cũ của Node.js, dùng `require()` và `module.exports`, thực thi đồng bộ, giá trị được sao chép chứ không là liên kết sống. Node.js chọn hệ theo đuôi tệp (`.mjs` là ESM, `.cjs` là CJS) hoặc trường `"type"` trong `package.json`. Code mới nên dùng ESM.

// ESM (.mjs hoặc "type": "module")
import { readFile } from 'node:fs/promises';
import chao from './chao.js';
export const phienBan = '1.0';

// CommonJS (.cjs hoặc mặc định)
const { readFileSync } = require('node:fs');
const chaoCJS = require('./chao.cjs');
module.exports = { phienBan: '1.0' };

// dùng CJS từ ESM và ngược lại
import cjs from './cu.cjs';
const esm = await import('./moi.mjs');
console.log(typeof require, typeof module);

Kết quả

- Trong ESM: `typeof require` và `typeof module` đều in `undefined` (không có sẵn); thay bằng `import.meta` và `createRequire`
- Trong CJS: cả hai là `function` và `object`
- ESM nhập được CJS (nhận `module.exports` làm export mặc định); CJS nạp ESM phải dùng `import()` bất đồng bộ
- `import` ở đầu tệp được nâng và chạy trước; `require` chạy đúng tại dòng gọi

Lưu ý

- Không có `__dirname` và `__filename` trong ESM; dùng `import.meta.url`, hoặc `import.meta.dirname` (Node.js 20.11 trở lên)
- Thư viện nên cung cấp cả hai dạng qua trường `exports` của `package.json`
- Node.js mới (22 trở lên) cho phép `require()` nạp ESM đồng bộ trong nhiều trường hợp

`import(duongDan)` là hàm cú pháp (không phải hàm thường) nạp module theo yêu cầu lúc chạy và trả về Promise cho object namespace của module (có các export có tên và `default`). Khác `import` tĩnh ở đầu tệp: có thể đặt trong điều kiện, hàm, sự kiện, và đường dẫn có thể tính toán. Dùng để tách bundle (code splitting) và tải lười: chỉ tải trang quản trị khi người dùng vào đó, tải thư viện biểu đồ khi bấm nút. Bundler tự tách thành tệp riêng.

async function xemBieuDo() {
  const { ve, mac_dinh } = await import('./bieu-do.js');
  ve(document.getElementById('khung'));
  return typeof mac_dinh;
}
document.getElementById('nut').addEventListener('click', xemBieuDo);

const ngonNgu = 'vi';
const goi = await import(`./i18n/${ngonNgu}.js`);
console.log(Object.keys(goi));
import('./khong-co.js').catch((e) => console.log(e.name));
if (cauHinh.coAdmin) {
  const admin = await import('./admin.js');
  admin.khoiTao();
}

Kết quả

- Chỉ khi bấm nút, trình duyệt mới tải `bieu-do.js` (tab Network cho thấy yêu cầu mới lúc đó)
- `Object.keys(goi)` in danh sách export của tệp `vi.js`, ví dụ `['chao', 'default']`
- Tệp không tồn tại làm Promise bị từ chối: in `TypeError` (trình duyệt) hoặc `Error` (Node.js)
- Mô-đun `admin.js` chỉ được nạp khi điều kiện đúng

Lưu ý

- `import()` dùng được cả trong script thường và CommonJS, nên là cầu nối để nạp ESM từ CJS
- Mỗi module chỉ chạy một lần: các lần `import()` sau trả lại kết quả đã có

`import.meta` là object chứa thông tin về module hiện tại, chỉ dùng được trong ES Module. Thuộc tính chính `import.meta.url` là URL của tệp module (dạng `file://` trong Node.js, `https://` trong trình duyệt). Dùng để dựng đường dẫn tương đối tới tài nguyên: `new URL('./du-lieu.json', import.meta.url)`. Node.js 20.11 trở lên có thêm `import.meta.dirname` và `import.meta.filename` thay cho `__dirname` và `__filename` của CommonJS. Công cụ build như Vite thêm `import.meta.env`.

console.log(import.meta.url);
const duongDanJson = new URL('./cau-hinh.json', import.meta.url);
console.log(duongDanJson.pathname.endsWith('cau-hinh.json'));
import { fileURLToPath } from 'node:url';
import path from 'node:path';
const dirname = path.dirname(fileURLToPath(import.meta.url));
console.log(dirname === import.meta.dirname);
console.log(import.meta.env?.MODE);
console.log(typeof import.meta);

Kết quả

- `import.meta.url` in `file:///home/an/app/src/main.js` (Node.js) hoặc `https://example.com/assets/main.js` (trình duyệt)
- Dựng URL tới `cau-hinh.json` cạnh tệp hiện tại: in `true`
- Hai cách tính thư mục tương đương nhau: in `true`
- Dưới Vite, `import.meta.env.MODE` in `development` hoặc `production`; ngoài Vite in `undefined`
- `typeof import.meta` in `object`

Lưu ý

- Dùng `import.meta` ở tệp CommonJS gây `SyntaxError`
- Trong trình duyệt, đường dẫn tương đối của `fetch` tính theo URL trang, không phải theo module; dùng `new URL(..., import.meta.url)`

Phiên bản theo ngữ nghĩa có dạng `MAJOR.MINOR.PATCH`: tăng PATCH khi sửa lỗi tương thích, MINOR khi thêm tính năng tương thích ngược, MAJOR khi có thay đổi phá vỡ tương thích. Trong `package.json`, dấu `^1.2.3` cho phép cập nhật MINOR và PATCH (đến trước `2.0.0`), `~1.2.3` chỉ cho phép PATCH (đến trước `1.3.0`), phiên bản trần `1.2.3` ghim chính xác, `*` hoặc `latest` cho bản mới nhất. Với phiên bản `0.x`, `^0.2.3` chỉ tới trước `0.3.0` vì 0.x coi là chưa ổn định. Thư viện `semver` tính toán các quy tắc này.

import semver from 'semver';

console.log(semver.satisfies('1.5.2', '^1.2.3'));
console.log(semver.satisfies('2.0.0', '^1.2.3'));
console.log(semver.satisfies('1.2.9', '~1.2.3'));
console.log(semver.satisfies('1.3.0', '~1.2.3'));
console.log(semver.satisfies('0.2.9', '^0.2.3'));
console.log(semver.satisfies('0.3.0', '^0.2.3'));
console.log(semver.gt('1.10.0', '1.9.0'), '1.10.0' > '1.9.0');
console.log(semver.inc('1.2.3', 'minor'));
console.log(semver.maxSatisfying(['1.2.0', '1.4.5', '2.1.0'], '^1.0.0'));

Kết quả

- `^1.2.3` chấp nhận `1.5.2`: in `true`, nhưng không chấp nhận `2.0.0`: in `false`
- `~1.2.3` chấp nhận `1.2.9`: `true`, không chấp nhận `1.3.0`: `false`
- Với `0.x`: `^0.2.3` chấp nhận `0.2.9` (`true`) nhưng không chấp nhận `0.3.0` (`false`)
- So sánh phiên bản đúng: `semver.gt('1.10.0', '1.9.0')` in `true`, trong khi so chuỗi `'1.10.0' > '1.9.0'` in `false`
- `semver.inc('1.2.3', 'minor')` in `1.3.0`
- `maxSatisfying` chọn phiên bản cao nhất trong khoảng `^1.0.0`: in `1.4.5`

Lưu ý

- Lệnh `npm version patch|minor|major` tăng phiên bản trong `package.json` và tạo thẻ git
- Không phải gói nào cũng tuân thủ semver; đọc ghi chú phát hành trước khi nâng MAJOR

`package-lock.json` ghi lại phiên bản CHÍNH XÁC của mọi gói đã cài (kể cả phụ thuộc gián tiếp) cùng mã băm toàn vẹn, nên mọi người và máy chủ CI cài ra đúng cùng một cây thư viện, kể cả khi `package.json` chỉ ghi khoảng `^1.2.3`. Tệp được npm tạo và cập nhật tự động khi cài hoặc gỡ gói; KHÔNG sửa tay. Phải đưa vào kho mã nguồn. `npm ci` đọc nó để cài đúng. Mỗi trình quản lý có tệp khóa riêng: `yarn.lock`, `pnpm-lock.yaml`, `bun.lock`; chỉ dùng một loại trong một dự án.

{
  "name": "ung-dung",
  "lockfileVersion": 3,
  "packages": {
    "": { "dependencies": { "express": "^4.19.0" } },
    "node_modules/express": {
      "version": "4.19.2",
      "resolved": "https://registry.npmjs.org/express/-/express-4.19.2.tgz",
      "integrity": "sha512-5T6nhjsT..."
    },
    "node_modules/body-parser": { "version": "1.20.2", "integrity": "sha512-..." }
  }
}

Kết quả

- `package.json` yêu cầu `^4.19.0` nhưng khóa ghim `4.19.2`: `npm ci` luôn cài đúng `4.19.2`
- Khi có bản `4.19.3` mới, `npm install` vẫn giữ `4.19.2` cho đến khi bạn chạy `npm update`
- Mã băm `integrity` bảo đảm tệp tải về không bị thay đổi
- Mỗi gói gián tiếp (như `body-parser`) cũng có phiên bản được ghim

Lưu ý

- Xung đột khi gộp nhánh: xóa tệp khóa rồi `npm install` lại, hoặc chấp nhận một bên rồi chạy `npm install`
- Thư viện (gói xuất bản) không phát hành lockfile cho người dùng; chỉ ứng dụng mới cần nó

DevTools là bộ công cụ gỡ lỗi tích hợp trong trình duyệt (mở bằng F12 hoặc Ctrl+Shift+I). Các tab chính: Elements (xem và sửa HTML, CSS trực tiếp), Console (chạy JavaScript và xem log), Sources (gỡ lỗi bằng điểm dừng), Network (theo dõi yêu cầu mạng), Performance (ghi và phân tích hiệu năng), Memory (tìm rò rỉ bộ nhớ), Application (lưu trữ, cookie, Service Worker), Lighthouse (chấm điểm chất lượng trang). Firefox và Safari có bộ công cụ tương tự.

function tinhTong(ds) {
  let tong = 0;
  debugger;
  for (const x of ds) tong += x.gia * x.sl;
  return tong;
}
console.log(tinhTong([{ gia: 10, sl: 2 }, { gia: 5, sl: 3 }]));
console.table([{ ten: 'An', diem: 8 }, { ten: 'Bình', diem: 6 }]);
console.time('tinh');
tinhTong([]);
console.timeEnd('tinh');

Kết quả

- Khi DevTools đang mở, câu lệnh `debugger` dừng chương trình ở dòng đó: xem biến `ds`, `tong` ở khung Scope và bước từng dòng (F10) hoặc vào hàm (F11)
- Sau khi tiếp tục chạy (F8), Console in `35`
- `console.table` hiện bảng hai hàng, `console.timeEnd` in thời gian dạng `tinh: 0.02ms`
- Khi DevTools đóng, `debugger` không có tác dụng

Lưu ý

- Xóa `debugger` và `console.log` thừa trước khi triển khai
- Trong Console, `$0` là phần tử đang chọn ở Elements, `$_` là kết quả biểu thức trước, `copy(obj)` chép vào bảng nhớ tạm

Điểm bắt đầu là fun main(); file .main.kts chạy như script.

fun main(args: Array<String>) {
    val ten = args.firstOrNull() ?: "bạn"
    println("Xin chào $ten")
}

Các hàm biến đổi collection hay dùng ngoài map / filter.

don.sumOf { it.tong }
users.associateBy { it.id }             // Map<Id, User>
val (vip, thuong) = users.partition { it.vip }
ds.chunked(100); ds.windowed(3)
a.zip(b) { x, y -> x + y }
khach.flatMap { it.don }
users.sortedWith(compareBy({ it.tuoi }, { it.ten }))
ds.distinctBy { it.email }; ds.maxByOrNull { it.diem }

Hàm nhận / trả hàm; lambda cuối có thể viết ra ngoài ngoặc; tham số duy nhất tên là it.

fun lap(n: Int, viec: (Int) -> Unit) { for (i in 0 until n) viec(i) }
lap(3) { println("lần $it") }
val binhPhuong: (Int) -> Int = { x -> x * x }
ds.filter { it > 0 }.map(::binhPhuongHam)

Constructor chính khai báo ngay trên tên class; init chạy khi tạo object.

class TaiKhoan(val chu: String, private var soDu: Long = 0) {
    init { require(soDu >= 0) { "số dư âm" } }
    fun nap(tien: Long) { soDu += tien }
    constructor(chu: String, soDuChuoi: String) : this(chu, soDuChuoi.toLong())
}

Class mặc định là final; thêm open để cho kế thừa, override để ghi đè.

open class DongVat(val ten: String) { open fun keu() = "..." }
class Meo(ten: String) : DongVat(ten) { override fun keu() = "Meo" }
abstract class Hinh { abstract fun dienTich(): Double }

Interface có method trừu tượng và method có sẵn thân; class cài nhiều interface.

interface ThanhToan {
    fun tra(tien: Long): Boolean
    fun ten(): String = this::class.simpleName ?: "?"
}
class Momo : ThanhToan { override fun tra(tien: Long) = true }

