Coroutine con thuộc về scope cha: cha đợi con, con lỗi thì hủy cả nhóm (supervisorScope thì không).

suspend fun taiTrang() = coroutineScope {
    val u = async { api.user() }
    val d = async { api.don() }
    Trang(u.await(), d.await())         // một cái lỗi -> cái kia bị hủy
}
val job = scope.launch { ... }
job.cancel()
withTimeout(5_000) { taiTrang() }

