Hàm / kiểu generic với ràng buộc protocol; some (kiểu cụ thể ẩn) và any (hộp chứa kiểu bất kỳ).

func lonNhat<T: Comparable>(_ a: T, _ b: T) -> T { a > b ? a : b }
