struct là kiểu giá trị (gán là sao chép, được ưu tiên), class là kiểu tham chiếu (dùng chung một object, có kế thừa).

struct Diem { var x = 0; mutating func dich() { x += 1 } }
var a = Diem(); var b = a; b.x = 5      // a.x vẫn 0
final class BoDem { var n = 0 }
let c = BoDem(); let d = c; d.n = 5      // c.n cũng 5

Mô tả khả năng bằng protocol, cài mặc định trong extension, struct / enum / class đều cài được.

protocol CoTen { var ten: String { get } }
extension CoTen { func chao() -> String { "Chào \(ten)" } }
struct User: CoTen, Codable, Hashable { let ten: String }
User(ten: "An").chao()

Class kế thừa một class khác; init phải gán mọi thuộc tính; override để ghi đè; final chặn kế thừa.

class DongVat {
    let ten: String
    init(ten: String) { self.ten = ten }
    func keu() -> String { "..." }
}
final class Meo: DongVat {
    override func keu() -> String { "Meo" }
    convenience init() { self.init(ten: "Mướp") }
}

