Iterable là thứ duyệt được bằng for-each; tự cài Iterable để class của bạn dùng được trong for.

class DaySo implements Iterable<Integer> {
    private final int n;
    DaySo(int n) { this.n = n; }
    public Iterator<Integer> iterator() {
        return new Iterator<>() {
            int i = 0;
            public boolean hasNext() { return i < n; }
            public Integer next() { return i++; }
        };
    }
}
for (int x : new DaySo(3)) System.out.println(x);

