class Bus<E extends Record<string, unknown>> {
  private h: { [K in keyof E]?: ((d: E[K]) => void)[] } = {};
  on<K extends keyof E>(k: K, f: (d: E[K]) => void) { (this.h[k] ??= []).push(f); }
